window.VOCAB_TERMS = window.VOCAB_TERMS || {};
window.VOCAB_TERMS["arch"] = {"arch--api":{"definition":"날씨 기능을 앱에 넣으려고 관측 데이터를 모으고 예측 알고리즘을 만들면 몇 달이 걸린다. 날씨 API를 부르면 그 기능을 그대로 빌려 쓴다. 안쪽이 어떻게 생겼는지는 몰라도 된다.","name":"Application :: 프로그램\nProgramming :: 짜기\nInterface :: 맞닿는 창구\n= 붙여 읽으면 \"프로그램을 짤 때 맞닿는 창구\". 이름과 넘길 값만 알면 안쪽은 몰라도 된다","analogy":"식당 메뉴판. 주방에 들어가 요리하는 대신 메뉴판에 적힌 이름을 대면 음식이 나온다. 주방 설비가 바뀌어도 메뉴판이 그대로면 손님은 아무것도 안 바꿔도 된다.","example":"쇼핑 앱 안에 지도가 그대로 뜨는 것은 그 앱이 지도를 만든 게 아니라 창구로 빌려 온 것이다.","tryit":"브라우저 주소창에 `https://api.github.com/users/octocat` 를 쳐 보라. 사람이 아니라 프로그램이 읽으라고 만든 답이 그대로 보인다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"웹 API는 대개 HTTP로 오간다. 주소로 무엇을 다룰지 정하고, 메서드로 무엇을 할지 정한다.\n\n```\nGET    /users/123     123번 사용자를 가져온다\nPOST   /users         새 사용자를 만든다\nDELETE /users/123     123번 사용자를 지운다\n```\n\n같은 주소에 메서드만 바꿔 보내면 다른 일이 일어난다. 이렇게 주소를 자원 이름으로 쓰는 방식이 [[REST]]다. 응답은 보통 [[JSON]]으로 온다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **지도 붙이기** — 지도 API에 좌표를 보내면 지도 조각을 돌려준다. 지도 데이터를 직접 갖지 않아도 화면에 지도가 뜬다.\n- **결제** — 카드 정보는 결제사 쪽으로 바로 보내고 우리 서버는 결과만 받는다. 민감한 값을 우리가 들고 있지 않아도 된다.\n- **사내 서비스 사이** — 주문 서비스가 재고 서비스의 API를 부른다. 재고 쪽이 데이터베이스를 바꿔도 주문 쪽은 그대로 돈다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **API는 웹에서만 쓰는 말이다** — 아니다. 라이브러리가 열어둔 함수도 API고, 운영체제가 프로그램에 열어주는 창구도 API다. 웹 API가 흔해서 그렇게 보일 뿐이다.\n- **API를 붙이면 그 기능이 내 서버로 들어온다** — 들어오지 않는다. 계산은 여전히 상대 서버에서 일어나고, 그쪽이 멈추면 내 화면의 그 부분도 같이 멈춘다.\n- **주소만 알면 아무나 부를 수 있다** — 대개 키가 있어야 한다. 주소는 창구 위치일 뿐이고 통과 여부는 키와 권한이 정한다."}],"figure":"```도해\n흐름: 앱에 날씨를 붙이면 무슨 순서로 오가나\n내 앱 :: \"서울 날씨 줘\" 라고 요청을 보낸다\nAPI :: 정해진 형식인지 확인하고 안쪽에 넘긴다\n날씨 서버 :: 관측값을 찾아 결과를 만든다\nAPI :: 약속한 형식으로 포장해서 돌려준다\n< 내 앱 :: 받은 값에서 온도만 꺼내 화면에 쓴다\n= 안쪽을 몰라도 창구 쓰는 법만 알면 된다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 남이 만든 기능을 쓰려면 어떻게 해야 하나\nAPI 없이 || API 로\n날씨 기능 :: 직접 다 만든다 || 불러 쓴다\n상대의 변경 :: 같이 깨진다 || 창구는 그대로\n연동 방식 :: 서비스마다 제각각 || 정해진 규칙\n= 창구를 정해두면 안쪽이 바뀌어도 쓰는 쪽이 안 흔들린다\n```\n\n기능을 하나 붙일 때마다 처음부터 만들면 시간이 아무리 많아도 모자란다. 지도, 결제, 번역, 인증은 이미 잘 만들어진 것이 있고 그걸 부르는 편이 낫다.\n\n혼자 만든 코드 안에서도 마찬가지다. 함수 이름과 넘길 값만 정해두면, 그 함수를 나중에 통째로 다시 짜도 부르는 쪽 코드는 손댈 필요가 없다. API가 하는 일은 결국 이 경계를 그어두는 것이다."},"recap":"**\"남의 기능을 이름만 대고 빌려 쓰는 그 창구\"** 라고 읽으면 된다. 부르는 쪽은 안쪽 구현을 몰라도 되고, 만드는 쪽은 창구만 지키면 안을 마음대로 바꿀 수 있다.","kid":"식당에서 주방에 들어가 요리하지 않고 메뉴판에 적힌 이름만 대면 음식이 나오지? 앱도 그래. 지도를 직접 그리는 대신 지도 만드는 집에 이름을 대면, 그 집이 그려서 보내준 지도가 네 화면에 붙어.","check":[{"q":"날씨가 나오던 화면이 갑자기 비었다면 어디를 먼저 의심해야 하나","at":"흔한 오해"},{"q":"상대 서비스가 내부 계산 방식을 고쳤는데 내 코드를 안 바꿔도 되는 이유는","at":"해결하는 문제"},{"q":"같은 `/users/123` 주소로 보낸 두 요청이 서로 다른 일을 한다. 무엇이 그것을 정하나","at":"작동 원리"}],"myths":[{"wrong":"API는 웹에서만 쓰는 말이다","right":"아니다. 라이브러리가 열어둔 함수도 API고, 운영체제가 프로그램에 열어주는 창구도 API다. 웹 API가 흔해서 그렇게 보일 뿐이다."},{"wrong":"API를 붙이면 그 기능이 내 서버로 들어온다","right":"들어오지 않는다. 계산은 여전히 상대 서버에서 일어나고, 그쪽이 멈추면 내 화면의 그 부분도 같이 멈춘다."},{"wrong":"주소만 알면 아무나 부를 수 있다","right":"대개 키가 있어야 한다. 주소는 창구 위치일 뿐이고 통과 여부는 키와 권한이 정한다."}],"cases":[{"label":"지도 붙이기","note":"지도 API에 좌표를 보내면 지도 조각을 돌려준다. 지도 데이터를 직접 갖지 않아도 화면에 지도가 뜬다."},{"label":"결제","note":"카드 정보는 결제사 쪽으로 바로 보내고 우리 서버는 결과만 받는다. 민감한 값을 우리가 들고 있지 않아도 된다."},{"label":"사내 서비스 사이","note":"주문 서비스가 재고 서비스의 API를 부른다. 재고 쪽이 데이터베이스를 바꿔도 주문 쪽은 그대로 돈다."}],"dia":{"shape":"흐름","title":"앱에 날씨를 붙이면 무슨 순서로 오가나","rows":[{"who":"내 앱","what":"\"서울 날씨 줘\" 라고 요청을 보낸다"},{"who":"API","what":"정해진 형식인지 확인하고 안쪽에 넘긴다"},{"who":"날씨 서버","what":"관측값을 찾아 결과를 만든다"},{"who":"API","what":"약속한 형식으로 포장해서 돌려준다"},{"who":"내 앱","what":"받은 값에서 온도만 꺼내 화면에 쓴다","back":true}],"sum":"안쪽을 몰라도 창구 쓰는 법만 알면 된다"}},"arch--api-gateway":{"definition":"뒤에 서비스가 열 개든 스무 개든 밖에서는 주소 하나만 보인다. 인증, 요청량 제한, 로그처럼 모든 서비스가 똑같이 해야 하는 일을 이 문에서 한 번에 처리한다.","name":"API :: 기능을 빌려 쓰는 창구\nGateway :: 드나드는 관문\n= 붙여 읽으면 \"창구들 앞에 놓인 하나의 관문\". 뒤에 몇 곳이 있든 밖에서는 문 하나만 보인다","analogy":"회사 로비의 안내 데스크. 방문객은 로비 하나만 알면 되고, 신분 확인과 출입증 발급은 여기서 한 번만 한다. 각 층 사무실이 저마다 검문소를 둘 필요가 없다.","example":"앱을 오래 켜두면 어느 메뉴를 눌러도 똑같이 로그인 화면으로 튕기는 것이 이 문에서 걸러진 결과다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"게이트웨이가 맡는 일은 대체로 정해져 있다.\n\n| 하는 일 | 내용 |\n|---|---|\n| 라우팅 | 경로를 보고 어느 서비스로 보낼지 정한다 |\n| 인증·인가 | 토큰을 확인하고 권한을 본다 |\n| 요청량 제한 | 한 사용자가 너무 많이 부르는 것을 막는다 |\n| 응답 조합 | 여러 서비스 결과를 하나로 합친다 |\n| 로그·추적 | 요청 하나가 어디를 거쳤는지 기록한다 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **모바일 앱 전용 응답** — 앱에는 가벼운 형태로, 웹에는 자세한 형태로 같은 데이터를 다르게 내려준다.\n- **버전 관리** — `/v1`은 옛 서비스로, `/v2`는 새 서비스로 보내면서 클라이언트를 천천히 옮긴다.\n- **외부 공개** — 내부 서비스는 그대로 두고 게이트웨이에서만 공개 규칙을 정한다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **게이트웨이가 [[Load Balancer]]와 같은 것이다** — 분산기는 같은 서버 여럿에 요청을 나눈다. 게이트웨이는 서로 다른 서비스로 보내면서 인증과 조합까지 한다.\n- **게이트웨이에 비즈니스 로직을 넣어도 된다** — 넣기 시작하면 여기가 다시 모놀리스가 된다. 문을 만들려다 건물을 지은 셈이 된다.\n- **한 번 두면 장애가 줄어든다** — 모든 요청이 지나는 지점이라 여기가 죽으면 전부 죽는다. 이중화가 필수다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **여기가 단일 장애점이다.** 이중으로 띄우고 헬스체크를 건다.\n- **지연이 한 겹 늘어난다.** 요청마다 홉이 하나 추가되므로 게이트웨이 자체가 느리면 전부 느려진다."}],"figure":"```도해\n흐름: 요청 하나가 게이트웨이를 지나며 무슨 일을 겪나\n클라이언트 :: `/api/orders` 로 요청한다\n게이트웨이 :: 토큰이 유효한지 확인한다\n게이트웨이 :: 이 사용자가 한도를 넘지 않았는지 본다\n게이트웨이 :: 주문 서비스로 넘긴다\n주문 서비스 :: 자기 일만 한다. 인증은 이미 끝났다\n< 게이트웨이 :: 응답을 받아 로그를 남기고 돌려준다\n= 서비스마다 하던 공통 작업을 문 앞에서 한 번만 한다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 서비스가 스무 개일 때 무엇이 달라지나\n게이트웨이 없이 || 게이트웨이로\n인증 코드 :: 스무 벌 || 한 벌\n주소 :: 스무 개를 안다 || 하나만 안다\n정책 변경 :: 스무 곳 배포 || 한 곳만\n= 같은 일을 여러 번 하지 않게 만드는 것이 이 장치의 전부다\n```\n\n서비스를 잘게 나누면 각 서비스는 단순해지지만, 공통으로 해야 하는 일이 서비스 수만큼 복제된다. 토큰 검증 로직이 스무 벌 생기고, 그중 한 곳만 업데이트를 놓쳐도 구멍이 된다.\n\n클라이언트 쪽도 복잡해진다. 화면 하나를 그리려고 서비스 세 곳을 각각 호출하고 결과를 합쳐야 한다. 게이트웨이가 그 조합을 대신 맡으면 클라이언트는 한 번만 부르면 된다."},"compose":{"label":"무엇으로 되어 있나","head":"🧱 구성","body":"```도해\n층: 게이트웨이는 무엇 위에 무엇을 얹은 것인가\n정책 :: 토큰 확인, 횟수 세기, 응답 합치기. 이 겹이 게이트웨이를 게이트웨이로 만든다\n라우팅 :: 경로를 보고 어느 서비스로 넘길지 고른다\n프록시 :: 밖에서 온 요청을 뒤 대신 받아주는 자리\n= 게이트웨이라는 새 물건이 있는 게 아니라, 대신 받아주는 자리에 정책이 한 겹 얹힌 것이다\n```"},"recap":"**\"여럿 앞에 하나만 세운 그 문\"** 이라고 읽으면 된다. 뒤에 서비스가 몇이든 밖에서는 주소 하나만 보이고, 인증·요청량 제한·로그 같은 공통 작업은 이 문에서 한 번만 한다. 중복을 없애는 대신 모든 요청이 지나는 지점이 하나 생기므로, 그 지점을 얼마나 튼튼하게 두느냐가 관건이다.","kid":"큰 건물에서 층마다 지키는 사람이 이름을 물어보면 번거롭지? 그래서 일 층 로비 한 곳에서만 확인하고 출입증을 줘. 그러면 위층 사무실들은 물어보는 일을 아예 안 해도 되고, 너도 로비 한 곳만 알면 돼.","check":[{"q":"서비스 스무 곳에 토큰 검증 코드를 따로 두면 왜 구멍이 생기나","at":"해결하는 문제"},{"q":"게이트웨이에 주문 계산 로직을 넣으면 무엇이 문제가 되나","at":"흔한 오해"},{"q":"게이트웨이를 붙였는데 전체 응답이 느려졌다면 어디를 봐야 하나","at":"주의사항"}],"myths":[{"wrong":"게이트웨이가 [[Load Balancer]]와 같은 것이다","right":"분산기는 같은 서버 여럿에 요청을 나눈다. 게이트웨이는 서로 다른 서비스로 보내면서 인증과 조합까지 한다."},{"wrong":"게이트웨이에 비즈니스 로직을 넣어도 된다","right":"넣기 시작하면 여기가 다시 모놀리스가 된다. 문을 만들려다 건물을 지은 셈이 된다."},{"wrong":"한 번 두면 장애가 줄어든다","right":"모든 요청이 지나는 지점이라 여기가 죽으면 전부 죽는다. 이중화가 필수다."}],"cases":[{"label":"모바일 앱 전용 응답","note":"앱에는 가벼운 형태로, 웹에는 자세한 형태로 같은 데이터를 다르게 내려준다."},{"label":"버전 관리","note":"`/v1`은 옛 서비스로, `/v2`는 새 서비스로 보내면서 클라이언트를 천천히 옮긴다."},{"label":"외부 공개","note":"내부 서비스는 그대로 두고 게이트웨이에서만 공개 규칙을 정한다."}],"dia":{"shape":"흐름","title":"요청 하나가 게이트웨이를 지나며 무슨 일을 겪나","rows":[{"who":"클라이언트","what":"`/api/orders` 로 요청한다"},{"who":"게이트웨이","what":"토큰이 유효한지 확인한다"},{"who":"게이트웨이","what":"이 사용자가 한도를 넘지 않았는지 본다"},{"who":"게이트웨이","what":"주문 서비스로 넘긴다"},{"who":"주문 서비스","what":"자기 일만 한다. 인증은 이미 끝났다"},{"who":"게이트웨이","what":"응답을 받아 로그를 남기고 돌려준다","back":true}],"sum":"서비스마다 하던 공통 작업을 문 앞에서 한 번만 한다"}},"arch--api-2":{"definition":"`localhost` 는 그 컴퓨터 안에서만 통하는 주소다. 다른 사람이 부르게 하려면 공인 IP 가 있는 자리에 코드를 올리고, 이름과 암호화와 인증을 차례로 얹어야 한다.","name":"API :: 기능을 빌려 쓰는 창구\n외부 :: 내 컴퓨터 바깥\n공개 :: 누구나 닿게 열어둠\n= 붙여 읽으면 \"그 창구를 내 컴퓨터 바깥에 열어두는 일\". 여는 순간 지켜야 할 것이 따라 붙는다","analogy":"집에서 만든 음식은 가족만 먹는다. 손님을 받으려면 가게 자리를 얻고 간판을 달고 위생 검사를 받아야 한다.","example":"처음 여는 앱인데 이미 쓰던 계정으로 로그인되는 것이 그쪽이 자기 API 를 밖에 열어둔 덕이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n층: 공개하는 방법은 어디까지 갈 수 있나\n터널링 :: ngrok 이 임시 주소를 내준다. 끄면 회수된다\n클라우드 :: 공인 IP 를 받은 서버에 코드를 올린다\n도메인 :: DNS 에 이름을 등록하고 인증서를 붙인다\n관문 :: API Gateway 가 키와 호출 제한과 로그를 맡는다\n= 위는 몇 분이면 되고, 아래로 갈수록 준비가 늘지만 오래 간다\n```\n\nngrok 은 로컬 포트와 인터넷을 잇는 터널을 만든다. 설치하고 한 줄만 치면 `https://...` 로 시작하는 주소가 생기지만, 끄면 그 주소는 회수된다. 시연과 잠깐의 공유용이다.\n\n계속 떠 있어야 하면 클라우드에 인스턴스를 만들고 공인 IP 를 받는다. IP 를 그대로 알려주는 대신 도메인을 등록하고, Let's Encrypt 나 클라우드가 주는 인증서로 HTTPS 를 건다. 마지막으로 API Gateway 를 앞에 두면 클라이언트마다 키를 발급하고 호출 횟수를 세는 일을 코드 밖에서 처리할 수 있다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교","body":"| | localhost | ngrok | 클라우드 서버 |\n|---|---|---|---|\n| 외부 접근 | 안 됨 | 임시 주소 | 계속 유지 |\n| 도메인 | 필요 없음 | 필요 없음 | 등록해야 함 |\n| HTTPS | 필요 없음 | 자동 | 인증서 설치 |\n| 어디에 쓰나 | 개발 중 | 시연, 테스트 | 실제 서비스 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **팀 리뷰** — 만든 API 를 리더가 확인해야 할 때 ngrok 주소를 띄워 그 자리에서 눌러보게 한다.\n- **테스트 환경** — 클라우드에 인스턴스를 하나 두고 `test-api` 같은 도메인을 붙여 내부 인원이 계속 쓰게 한다.\n- **외부 고객 연동** — API Gateway 를 앞에 두고 고객사마다 키를 발급한 뒤, 키별로 분당 호출 수를 정해둔다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **서버에 올리고 주소만 알려주면 끝이다** — 인증을 안 걸면 주소를 아는 누구나 데이터를 가져간다. 공개는 시작이고 그다음이 인증과 제한이다.\n- **ngrok 주소를 그대로 서비스에 쓰면 된다** — 끄고 켤 때마다 주소가 바뀐다. 문서나 앱에 박아두면 다음 날 전부 끊긴다.\n- **HTTPS 는 있으면 좋은 것이다** — 브라우저가 HTTP 요청을 막는다. 인증 정보가 평문으로 오가는 것도 문제라 선택 사항이 아니다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **공개 전에 열려 있는 포트를 확인한다.** 데이터베이스 포트까지 같이 열려 있는 사고가 흔하다.\n- **키 없이 부를 수 있는 경로가 남았는지 본다.** 인증을 붙여도 한 곳이 뚫려 있으면 나머지가 무의미하다."}],"figure":"```도해\n흐름: 로컬에서 만든 API 를 남이 부르려면 무엇이 필요하나\n내 PC :: localhost 는 이 컴퓨터 안에서만 통한다\n서버 :: 공인 IP 가 있는 자리에 코드를 올린다\n도메인 :: IP 대신 이름으로 찾아오게 한다\n인증서 :: HTTPS 로 오가는 내용을 가린다\n관문 :: 키를 확인하고 호출 횟수를 센다\n외부 사용자 :: 이제 주소만 알면 부를 수 있다\n= 코드를 다 짜도 이 다섯 자리를 지나야 남이 쓸 수 있다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 로컬에만 있는 API 는 무엇을 못 하나\n공개 전 || 공개 후\n접근 범위 :: 내 컴퓨터만 || 어디서나\n전달 방법 :: 파일로 넘김 || 주소로 호출\n내 PC 를 끄면 :: 바로 끊긴다 || 계속 떠 있다\n= 코드가 도는 것과 남이 쓸 수 있는 것은 다른 문제다\n```\n\nAPI 를 다 만들어도 팀원이 그 주소를 열면 아무것도 뜨지 않는다. `127.0.0.1` 은 \"이 컴퓨터\"를 가리키는 주소라, 각자의 컴퓨터에서 각자의 컴퓨터를 가리킬 뿐이다.\n\n외부 공개는 그 주소를 바깥에서 닿을 수 있는 것으로 바꾸는 작업이다. 주소가 생기면 그다음 문제가 따라온다. 누가 부르는지 확인해야 하고, 오가는 내용을 가려야 하고, 한 사람이 초당 수백 번 부르는 것을 막아야 한다."},"recap":"**\"내 컴퓨터 밖에서도 닿게 만드는 그 일\"** 이라고 읽으면 된다. 터널링은 몇 분이면 되지만 임시고, 계속 쓸 것이라면 서버와 도메인과 인증서와 관문을 차례로 붙여야 한다. 주소가 생긴 순간부터 인증과 호출 제한이 같이 필요해진다.","kid":"집에서 만든 음식은 식구들만 먹지? 그걸 손님한테도 팔려면 가게 자리를 얻고 간판을 달고 위생 검사도 받아야 해. 그러고 나면 아무나 문을 밀고 들어오니까, 이번엔 누굴 받고 한 사람이 몇 그릇까지 시킬 수 있는지도 정해 둬야 해.","check":[{"q":"팀원에게 `localhost:3000` 주소를 알려줬는데 접속이 안 된다. 왜 그런가","at":"해결하는 문제"},{"q":"시연용으로 만든 ngrok 주소를 문서에 적어두면 며칠 뒤 무엇이 문제가 되나","at":"흔한 오해"},{"q":"한 사용자가 초당 수백 번 API 를 부르고 있다. 코드를 고치지 않고 어디서 막나","at":"실제 사례"}],"myths":[{"wrong":"서버에 올리고 주소만 알려주면 끝이다","right":"인증을 안 걸면 주소를 아는 누구나 데이터를 가져간다. 공개는 시작이고 그다음이 인증과 제한이다."},{"wrong":"ngrok 주소를 그대로 서비스에 쓰면 된다","right":"끄고 켤 때마다 주소가 바뀐다. 문서나 앱에 박아두면 다음 날 전부 끊긴다."},{"wrong":"HTTPS 는 있으면 좋은 것이다","right":"브라우저가 HTTP 요청을 막는다. 인증 정보가 평문으로 오가는 것도 문제라 선택 사항이 아니다."}],"cases":[{"label":"팀 리뷰","note":"만든 API 를 리더가 확인해야 할 때 ngrok 주소를 띄워 그 자리에서 눌러보게 한다."},{"label":"테스트 환경","note":"클라우드에 인스턴스를 하나 두고 `test-api` 같은 도메인을 붙여 내부 인원이 계속 쓰게 한다."},{"label":"외부 고객 연동","note":"API Gateway 를 앞에 두고 고객사마다 키를 발급한 뒤, 키별로 분당 호출 수를 정해둔다."}],"dia":{"shape":"흐름","title":"로컬에서 만든 API 를 남이 부르려면 무엇이 필요하나","rows":[{"who":"내 PC","what":"localhost 는 이 컴퓨터 안에서만 통한다"},{"who":"서버","what":"공인 IP 가 있는 자리에 코드를 올린다"},{"who":"도메인","what":"IP 대신 이름으로 찾아오게 한다"},{"who":"인증서","what":"HTTPS 로 오가는 내용을 가린다"},{"who":"관문","what":"키를 확인하고 호출 횟수를 센다"},{"who":"외부 사용자","what":"이제 주소만 알면 부를 수 있다"}],"sum":"코드를 다 짜도 이 다섯 자리를 지나야 남이 쓸 수 있다"}},"arch--aws-bedrock":{"definition":"모델을 직접 돌리려면 GPU 서버를 사고 모델을 설치하고 사용량에 맞춰 늘렸다 줄였다 해야 한다. Bedrock은 그 일을 AWS가 맡고, 쓰는 쪽은 요청을 보내고 응답을 받는 일만 한다.","name":"= Bedrock 은 흙을 파 내려가면 나오는 단단한 기반암이다. 위에 무엇을 얹든 받쳐 주는 바닥이라는 뜻으로 붙은 이름이다","analogy":"여러 브랜드를 함께 파는 대리점. 제품마다 본사를 찾아가지 않고 한 창구에서 고른다.","example":"AWS 요금 청구서 한 장에 여러 회사 모델의 사용량이 나란히 찍혀 나오는 자리다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"호출은 `modelId`로 모델을 지정하고 메시지를 넘기는 형태다.\n\n```python\nimport boto3\n\nbedrock = boto3.client('bedrock-runtime')\n\nresponse = bedrock.invoke_model(\n    modelId='anthropic.claude-3-sonnet-20240229-v1:0',\n    body={\n        \"messages\": [{\"role\": \"user\", \"content\": \"안녕하세요\"}],\n        \"max_tokens\": 1000\n    }\n)\n```\n\n모델을 바꾸려면 `modelId` 문자열을 바꾼다. 호출하는 코드의 모양은 그대로다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교","body":"| 항목 | Bedrock | 모델 회사 API 직접 호출 |\n|---|---|---|\n| 제공사 | AWS | 모델을 만든 회사 |\n| 모델 | Claude, Llama 등 여러 곳 | 그 회사 모델만 |\n| 통신 경로 | VPC 안에 둘 수 있다 | 인터넷을 통해 나간다 |\n| 계정 | 쓰던 AWS 계정 그대로 | 따로 만든다 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **사내 문서를 다루는 기능** — 통신이 VPC 안에서 끝나도록 잡으면 문서가 인터넷으로 나가지 않는다.\n- **모델 갈아타며 시험하기** — 응답이 마음에 안 들 때 `modelId`만 바꿔서 같은 코드로 다른 모델을 시험한다.\n- **이미 AWS를 쓰는 서비스** — 별도 연동 없이 같은 계정과 권한 안에서 모델을 부른다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **Bedrock이 만든 모델을 쓰는 것이다** — Bedrock은 모델을 만들지 않는다. Claude나 Llama처럼 다른 곳이 만든 모델을 AWS 안에서 부를 수 있게 모아둔 창구다.\n- **관리형이니 모델도 알아서 골라준다** — 어느 모델을 쓸지는 부르는 쪽이 `modelId`로 지정한다. 대신해주는 건 서버와 확장이지 선택이 아니다.\n- **내 서버 안에서 모델이 도는 것이다** — 모델은 AWS가 관리하는 쪽에서 돈다. 통신이 밖으로 나가지 않게 경로를 잡을 수는 있지만 모델이 내 서버에 설치되는 건 아니다."}],"figure":"```도해\n흐름: 내 코드가 모델을 부를 때 어디를 거치나\n내 코드 :: 질문과 함께 요청을 보낸다\nBedrock :: `modelId` 로 어느 모델인지 고른다\n모델 :: AWS 안에서 실행되고 답을 만든다\n< Bedrock :: 같은 형식으로 응답을 돌려준다\n= 다른 모델로 갈아타도 바뀌는 건 이름 한 줄이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: LLM 을 직접 돌리려면 무엇이 필요한가\n직접 운영 || Bedrock 으로\n시작 준비 :: GPU 서버부터 || API 호출부터\n모델 교체 :: 새로 설치한다 || 이름만 바꾼다\n네트워크 :: 직접 구성한다 || VPC 안에서\n= 모델을 굴리는 일을 넘기고 부르는 일만 남긴다\n```\n\n모델 하나를 직접 서비스에 올리려면 GPU 서버를 마련하고, 모델을 내려받아 설치하고, 요청이 몰릴 때 서버를 늘리는 장치까지 붙여야 한다. 모델을 바꾸고 싶으면 그 과정을 처음부터 다시 한다.\n\nBedrock은 그 자리를 API 호출로 바꾼다. 서버도 설치도 확장도 AWS 쪽에 있고, 쓰는 쪽에 남는 것은 어느 모델을 부를지 정하는 일이다."},"recap":"**\"여러 회사 모델을 한 창구에서 고르는 그 자리\"** 라고 읽으면 된다. 서버와 설치와 확장을 넘기는 대신, 어느 모델을 쓸지 고르는 일은 그대로 남는다. 통신을 VPC 안에 둘 수 있어서 데이터를 밖으로 내보내지 않는 구성이 가능하다.","kid":"여러 회사 물건을 한꺼번에 갖다 놓고 파는 큰 가게가 있지? 회사마다 찾아다니지 않고 거기서 골라 사면 돼. 마음에 안 들면 다른 회사 것으로 바꿔 달라고만 하면 되고, 창고에 쌓아 두는 일은 그 가게가 알아서 해.","check":[{"q":"쓰던 모델을 다른 모델로 바꾸려면 코드에서 무엇을 고쳐야 하나","at":"작동 원리"},{"q":"사내 문서를 다루는 기능에서 Bedrock을 고르는 이유는 무엇인가","at":"실제 사례"},{"q":"관리형 서비스인데도 여전히 쓰는 쪽이 정해야 하는 것은 무엇인가","at":"흔한 오해"}],"myths":[{"wrong":"Bedrock이 만든 모델을 쓰는 것이다","right":"Bedrock은 모델을 만들지 않는다. Claude나 Llama처럼 다른 곳이 만든 모델을 AWS 안에서 부를 수 있게 모아둔 창구다."},{"wrong":"관리형이니 모델도 알아서 골라준다","right":"어느 모델을 쓸지는 부르는 쪽이 `modelId`로 지정한다. 대신해주는 건 서버와 확장이지 선택이 아니다."},{"wrong":"내 서버 안에서 모델이 도는 것이다","right":"모델은 AWS가 관리하는 쪽에서 돈다. 통신이 밖으로 나가지 않게 경로를 잡을 수는 있지만 모델이 내 서버에 설치되는 건 아니다."}],"cases":[{"label":"사내 문서를 다루는 기능","note":"통신이 VPC 안에서 끝나도록 잡으면 문서가 인터넷으로 나가지 않는다."},{"label":"모델 갈아타며 시험하기","note":"응답이 마음에 안 들 때 `modelId`만 바꿔서 같은 코드로 다른 모델을 시험한다."},{"label":"이미 AWS를 쓰는 서비스","note":"별도 연동 없이 같은 계정과 권한 안에서 모델을 부른다."}],"dia":{"shape":"흐름","title":"내 코드가 모델을 부를 때 어디를 거치나","rows":[{"who":"내 코드","what":"질문과 함께 요청을 보낸다"},{"who":"Bedrock","what":"`modelId` 로 어느 모델인지 고른다"},{"who":"모델","what":"AWS 안에서 실행되고 답을 만든다"},{"who":"Bedrock","what":"같은 형식으로 응답을 돌려준다","back":true}],"sum":"다른 모델로 갈아타도 바뀌는 건 이름 한 줄이다"}},"arch--active-active-vs-active-passive":{"definition":"AWS 재해 복구 백서는 이 갈림을 전략의 축으로 놓는다. 대기 쪽(active/passive)은 한 곳만 사람을 받고 다른 곳은 복구용으로 놀리다가 장애 전환 때 깨어나고, 둘 다 쪽(multi-site active/active)은 깔아 둔 모든 곳이 동시에 받는다. 애저 Well-Architected 문서도 같은 두 이름으로 이 선택을 적는다.","name":"Active :: 지금 일하고 있는\nPassive :: 서 있기만 하는\n= 둘 다 앞은 Active 다. 뒤 낱말이 짝의 상태를 말한다 — 짝도 일하나, 짝은 서 있나","analogy":"같은 가게를 두 곳에 내되 두 곳 다 손님을 받을지, 한 곳만 열고 다른 곳은 불만 켜 둔 채 비워 둘지의 차이다.","example":"장애 공지에 \"전환에 30분 걸립니다\" 가 붙는 날과, 공지도 없이 그냥 되던 날의 차이가 여기서 갈린다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n흐름: 어느 쪽이 사람을 받을지 누가 정하나\n사람 :: 같은 이름 하나로 들어온다\n앞단 :: 건강 검사로 살아 있는 곳을 안다\n우선순위 :: 대기 방식이면 1번 지역만 쓴다\n지연·가중치 :: 둘 다 방식이면 나눠 보낸다\n전환 :: 1번이 죽으면 2번으로 이름을 돌린다\n= 갈림은 뒤쪽 설비가 아니라 앞단의 보내기 규칙에서 시작된다\n```\n\n뒤에 판을 두 벌 깔아 두는 것만으로는 아무것도 안 갈린다. 갈리는 자리는 앞단이다. 대기 방식은 우선순위 방식으로 보내 1번만 쓰다가 죽으면 2번으로 돌리고, 둘 다 방식은 지연이나 가중치로 나눠 보낸다. AWS 백서는 이 전환을 데이터 평면 기능(건강 검사에 물린 이름 전환)으로 하라고 적는다 — 설정을 바꾸는 제어 평면은 장애 중에 같이 아플 수 있어서다.\n\n자동으로 넘길지 손으로 누를지도 정해야 한다. 백서는 자동 전환을 조심해서 쓰라고 적는다. 되살아나는 시간과 잃는 데이터가 아무리 작아도 0 은 아니라서, 잘못 울린 경보 하나로 멀쩡한 곳을 버리면 그 손해를 공짜로 떠안는다. 그래서 누르는 것은 사람이 하되 누른 뒤 절차는 전부 자동으로 만들어 두는 쪽을 권한다.\n\n둘 다 굴리면 새 숙제가 하나 생긴다. 읽기는 가까운 쪽에서 받으면 되지만 쓰기는 양쪽에서 들어온다. 백서는 세 갈래를 든다 — 쓰기를 한 곳으로 몰거나(write global), 가까운 쪽에서 받고 나중에 맞추거나(write local), 키로 나눠 아예 충돌이 안 생기게 하거나(write partitioned)."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 같은 갈림 안에서도 넷으로 갈린다","body":"| 짜임 | 여벌 쪽이 평소에 하는 일 | 무엇을 내주나 |\n|---|---|---|\n| **둘 다 · 제 몫만** | 제 지역 몫만큼만 켜 두고 받는다 | 싸다. 한쪽이 죽으면 남은 쪽이 버겁다 |\n| **둘 다 · 넉넉히** | 남의 몫까지 감당할 만큼 켜 두고 받는다 | 가장 안 끊긴다. 가장 비싸다 |\n| **대기 · 웜 스페어** | 가장 작게 켜 둔 채 짐은 안 받는다 | 대기 쪽에선 가장 빨리 깨어난다 |\n| **대기 · 콜드 스페어** | 크기는 다 잡아 두고 전부 꺼 둔다 | 가장 싸다. 켜는 시간이 든다 |\n\n애저 문서는 여기에 숫자로 함정 하나를 짚어 둔다. 두 곳에 나눠 보내 각각 60%씩 쓰고 있었다면, 한 곳이 죽는 순간 남은 곳은 120%를 감당해야 한다. 그럴 수 있는 대는 없다. 그래서 \"둘 다 굴린다\" 는 말은 곧 **평소에 얼마를 놀릴지 정한다**는 말이다. 놀릴 몫을 안 정해 두면 여벌은 있는데 여벌이 죽는 날 남은 쪽도 같이 무너진다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **지역 장애 대비** — 두 지역에 같은 판을 깔고 앞단이 건강 검사로 죽은 지역을 목록에서 뺀다. 쓰는 사람은 이름 하나만 계속 친다.\n- **놀릴 몫 정하기** — 두 곳에 나눠 받되 각 곳을 제 몫보다 넉넉히 켜 둔다. 한 곳이 죽는 날 남은 곳이 두 곳 몫을 받아도 버티게 하려고 평소에 미리 내는 값이다.\n- **쓰기를 어디서 받을지** — 둘 다 굴릴 때는 읽기를 가까운 쪽에서 받고, 쓰기는 한 곳으로 몰거나 키로 나눠 충돌을 피한다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **둘 다 굴리는 쪽이 항상 낫다** — 두 벌 값이 늘 나가고, 양쪽에서 동시에 쓴 것을 맞추는 일이 새로 생긴다. AWS 백서도 이 방식을 가장 비싸고 가장 복잡한 쪽으로 적는다.\n- **대기 쪽은 그냥 꺼져 있는 것이다** — 얼마나 켜 두느냐가 등급을 가른다. 가장 작게 켜 둔 웜 스페어와 크기만 잡아 두고 다 꺼 둔 콜드 스페어는 깨어나는 시간이 다르고, 전부 켜 두고도 사람은 안 받는 핫 스탠바이까지 전부 대기 쪽이다.\n- **자동으로 넘기게 해 두면 안심이다** — 잘못 울린 경보 하나로 멀쩡한 곳을 버리게 된다. 그래서 백서는 누르는 것은 사람이 하되 그 뒤 절차를 자동으로 두라고 적는다."}],"figure":"```도해\n대조: 같은 판을 두 곳에 깔면 무엇이 갈리나\nActive-Active |=| Active-Passive\n평소에 :: 양쪽이 나눠 받는다 || 한쪽만 받는다\n한쪽이 죽으면 :: 전환할 것이 없다 || 전환을 해야 한다\n드는 값 :: 두 벌 값이 다 든다 || 노는 만큼 싸다\n= 같이 굴리면 비싸고 안 끊기고, 세워 두면 싸고 깨우는 데 시간이 든다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 여벌을 세워만 두면 무엇이 남나\n세워 둔다 || 같이 받는다\n사고가 났을 때 :: 넘기는 절차가 남는다 || 넘길 것이 없다\n그 절차 :: 그날 처음 눌러 본다 || 매일 쓰고 있다\n쓰기가 들어오는 곳 :: 한 곳뿐이라 안 부딪친다 || 두 곳이라 부딪친다\n= 세워 두면 전환이라는 숙제가 남고, 같이 굴리면 전환이 사라지는 대신 충돌이 온다\n```\n\n한 곳만 받게 두면 그 곳이 죽는 날 반드시 해야 할 일이 하나 남는다 — 사람을 다른 곳으로 넘기는 일이다. 문제는 그 절차가 평소에 한 번도 안 쓰이는 절차라는 점이다. 정말 써야 하는 날이 그 절차를 처음 눌러 보는 날이 된다. AWS 백서가 이 전략은 정기적으로 재고 시험해 봐야 믿고 쓸 수 있다고 못 박는 이유가 이것이다.\n\n둘 다 받게 두면 그 절차 자체가 사라진다. 백서는 액티브/액티브에는 페일오버라는 것이 아예 없다고 적는다 — 한 지역이 죽어도 남은 지역은 이미 하던 일을 계속할 뿐이다. 대신 새 숙제가 온다. 양쪽이 동시에 쓰기를 받으니 같은 것을 서로 다르게 고치는 날이 오고, 그 충돌을 어떻게 없앨지가 설계의 중심이 된다. **전환을 없애는 값이 충돌이다.**"},"recap":"**\"여벌을 같이 굴릴까, 세워 뒀다 깨울까\"** 라고 읽으면 된다. 세워 두면 값이 싸고 깨우는 데 시간이 걸리고, 같이 굴리면 전환이라는 절차 자체가 사라지는 대신 두 벌 값과 쓰기 충돌을 떠안는다. 그러니 물어야 할 것은 어느 쪽이 좋으냐가 아니라 몇 분까지 멈춰도 되느냐다.","kid":"같은 가게를 두 곳에 내면, 한 곳이 문을 닫아도 손님은 다른 곳으로 그냥 가면 돼. 대신 두 곳 다 열어 두려면 사람도 물건도 두 배로 드니까, 한 곳은 불만 켜 놓고 비워 두기도 해. 그러면 돈은 덜 드는데, 갑자기 손님이 몰려오면 그 가게 문 열고 준비하는 동안 다들 기다려야 해.","check":[{"q":"같은 판을 두 지역에 깔아만 두면 왜 아직 아무것도 안 갈리나","at":"작동 원리"},{"q":"두 곳이 나눠 받고 있었는데 한 곳이 죽자 남은 곳까지 무너지는 이유는","at":"비교"},{"q":"자동으로 넘기게 해 두면 왜 오히려 손해를 볼 수 있나","at":"흔한 오해"}],"myths":[{"wrong":"둘 다 굴리는 쪽이 항상 낫다","right":"두 벌 값이 늘 나가고, 양쪽에서 동시에 쓴 것을 맞추는 일이 새로 생긴다. AWS 백서도 이 방식을 가장 비싸고 가장 복잡한 쪽으로 적는다."},{"wrong":"대기 쪽은 그냥 꺼져 있는 것이다","right":"얼마나 켜 두느냐가 등급을 가른다. 가장 작게 켜 둔 웜 스페어와 크기만 잡아 두고 다 꺼 둔 콜드 스페어는 깨어나는 시간이 다르고, 전부 켜 두고도 사람은 안 받는 핫 스탠바이까지 전부 대기 쪽이다."},{"wrong":"자동으로 넘기게 해 두면 안심이다","right":"잘못 울린 경보 하나로 멀쩡한 곳을 버리게 된다. 그래서 백서는 누르는 것은 사람이 하되 그 뒤 절차를 자동으로 두라고 적는다."}],"cases":[{"label":"지역 장애 대비","note":"두 지역에 같은 판을 깔고 앞단이 건강 검사로 죽은 지역을 목록에서 뺀다. 쓰는 사람은 이름 하나만 계속 친다."},{"label":"놀릴 몫 정하기","note":"두 곳에 나눠 받되 각 곳을 제 몫보다 넉넉히 켜 둔다. 한 곳이 죽는 날 남은 곳이 두 곳 몫을 받아도 버티게 하려고 평소에 미리 내는 값이다."},{"label":"쓰기를 어디서 받을지","note":"둘 다 굴릴 때는 읽기를 가까운 쪽에서 받고, 쓰기는 한 곳으로 몰거나 키로 나눠 충돌을 피한다."}],"dia":{"shape":"대조","title":"같은 판을 두 곳에 깔면 무엇이 갈리나","rows":[{"who":"","what":"Active-Active || Active-Passive","left":"Active-Active","right":"Active-Passive","even":true},{"who":"평소에","what":"양쪽이 나눠 받는다 || 한쪽만 받는다","left":"양쪽이 나눠 받는다","right":"한쪽만 받는다"},{"who":"한쪽이 죽으면","what":"전환할 것이 없다 || 전환을 해야 한다","left":"전환할 것이 없다","right":"전환을 해야 한다"},{"who":"드는 값","what":"두 벌 값이 다 든다 || 노는 만큼 싸다","left":"두 벌 값이 다 든다","right":"노는 만큼 싸다"}],"sum":"같이 굴리면 비싸고 안 끊기고, 세워 두면 싸고 깨우는 데 시간이 든다"}},"arch--auto-scaling":{"definition":"서버를 몇 대 둘지는 원래 사람이 미리 정하는 값이었다. 오토 스케일링은 그 값을 정하는 대신, 무엇을 보고 늘리고 줄일지를 정해둔다.","name":"Auto :: 사람 손 없이\nScaling :: 규모를 늘리고 줄임\n= 붙여 읽으면 \"규모를 사람 손 없이 늘리고 줄이기\". 정해두는 것이 대수가 아니라 대수를 정하는 기준이다","analogy":"회전문 대신 놀이공원 매표소. 줄이 길어지면 창구를 더 열고, 한산해지면 다시 닫는다.","example":"티켓 예매가 열리자마자 몇 분 먹통이다가 슬슬 풀리는 것이 대수가 뒤늦게 따라붙은 모습이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"늘리고 줄이는 기준은 크게 세 가지로 정한다. 지표를 정해두고 그 값을 유지하도록 맡기는 방식, 구간마다 몇 대를 더할지 직접 적는 방식, 시각을 정해두고 그때 대수를 바꾸는 방식이다.\n\n세 가지 모두 최소와 최대 대수 안에서만 움직인다. 최소는 아무리 한산해도 남겨둘 대수이고, 최대는 지표가 잘못됐을 때 요금이 새는 것을 막는 울타리다.\n\n서버를 하나 추가한 뒤에는 잠시 판단을 멈춘다. 새 서버가 부하를 나눠 받기 전에 다시 지표를 보면 여전히 높게 나와서 계속 추가하게 되기 때문이다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 수평 확장 vs 수직 확장","body":"| | 수평 확장 | 수직 확장 |\n|---|---|---|\n| 늘리는 것 | 서버 대수 | 서버 한 대의 사양 |\n| 한계 | 앞단에서 나눠줄 수 있는 만큼 | 살 수 있는 가장 큰 사양까지 |\n| 중단 | 없이 가능 | 대개 재시작이 필요 |\n| 조건 | 서버가 상태를 안 들고 있어야 편하다 | 상태를 들고 있어도 된다 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **행사 트래픽** — 판매 시작 시각에 접속이 몰리면 대수를 늘렸다가 끝나면 되돌린다.\n- **업무 시간** — 평일 낮에만 쓰이는 사내 시스템은 시각을 정해 늘리고 줄인다.\n- **서버 교체** — 헬스체크에 실패한 서버를 빼고 같은 설정으로 새로 띄운다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **오토 스케일링을 켜면 서비스가 안 죽는다** — 늘어나는 건 서버 대수지 병목이 아니다. DB 한 곳이 막혀 있으면 서버를 열 대로 늘려도 똑같이 막힌다.\n- **접속이 몰리는 순간 바로 늘어난다** — 지표를 모으고 서버가 뜨고 헬스체크를 통과하기까지 시간이 걸린다. 급증이 그보다 빠르면 늦는다.\n- **대수가 줄면 비용도 알아서 준다** — 최대 대수를 크게 열어두면 잘못된 지표에도 그만큼 늘어난다. 요금 상한은 최대 대수로 잡는 것이다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **줄일 때 진행 중인 요청을 확인한다.** 종료 신호를 받고 곧바로 꺼지면 처리 중이던 요청이 끊긴다. 새 요청만 막고 하던 일을 끝낸 뒤 내려가야 한다.\n- **헬스체크가 부실하면 늘려도 소용없다.** 포트만 열려 있으면 정상으로 보는 검사는 DB 가 끊긴 서버에도 요청을 보낸다."}],"figure":"```도해\n흐름: 접속이 몰리면 서버는 어떻게 늘어나나\n감시 :: CPU 사용률을 짧은 주기로 지켜본다\n감시 :: 정해둔 기준을 넘긴 상태가 이어진다\n그룹 :: 같은 설정으로 서버를 더 띄운다\n분산기 :: 헬스체크를 통과한 서버부터 요청을 준다\n그룹 :: 부하가 내려가면 서버를 하나씩 뺀다\n@ 감시 :: 다시 지켜본다. 최소 대수 아래로는 안 내린다\n= 사람이 보고 있지 않아도 대수가 부하를 따라간다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 서버 대수를 고정해두면 어떤 일이 생기나\n고정 대수 || 자동 조절\n평상시 :: 남는 서버가 논다 || 최소 대수만\n급증할 때 :: 대수가 모자란다 || 자동으로 늘린다\n대응 속도 :: 사람이 붙어야 한다 || 분 단위로 반응\n= 대수를 정해두는 대신 대수를 정하는 기준을 정해둔다\n```\n\n고정 대수는 두 방향으로 틀린다. 최대 부하에 맞춰 잡으면 평소에 대부분이 놀고, 평소에 맞춰 잡으면 몰리는 날 버티지 못한다. 어느 쪽으로 맞춰도 하루 중 대부분은 틀린 값이다.\n\n수동으로 늘리는 것도 답이 되기 어렵다. 부하를 알아채고 서버를 띄우고 준비될 때까지 걸리는 시간 동안 이미 응답이 밀린다. 오토 스케일링은 그 판단과 실행을 규칙으로 미리 적어두는 것이다."},"recap":"**\"줄이 길면 창구를 더 여는 그 규칙\"** 이라고 읽으면 된다. 정해둔 지표를 보고 서버 대수를 자동으로 늘리고 줄인다. 대수 대신 기준을 정해두는 것이라, 기준이 병목과 어긋나 있으면 늘려도 나아지지 않는다.","kid":"놀이공원 매표소에 줄이 길어지면 옆 창구를 하나 더 열지? 한산해지면 도로 닫고. 사람이 지켜보다 여는 게 아니라 \"줄이 이만큼 길어지면 하나 더 연다\" 고 미리 정해 두면, 밤중에 갑자기 몰려도 저절로 그렇게 돼.","check":[{"q":"접속이 열 배로 뛴 직후 몇 분간 여전히 느린 이유는","at":"흔한 오해"},{"q":"서버를 줄이는 순간 처리 중이던 요청은 어떻게 되나","at":"주의사항"},{"q":"지표가 아직 높은데도 서버를 곧바로 더 안 띄우는 구간이 있다. 왜 그런가","at":"작동 원리"}],"myths":[{"wrong":"오토 스케일링을 켜면 서비스가 안 죽는다","right":"늘어나는 건 서버 대수지 병목이 아니다. DB 한 곳이 막혀 있으면 서버를 열 대로 늘려도 똑같이 막힌다."},{"wrong":"접속이 몰리는 순간 바로 늘어난다","right":"지표를 모으고 서버가 뜨고 헬스체크를 통과하기까지 시간이 걸린다. 급증이 그보다 빠르면 늦는다."},{"wrong":"대수가 줄면 비용도 알아서 준다","right":"최대 대수를 크게 열어두면 잘못된 지표에도 그만큼 늘어난다. 요금 상한은 최대 대수로 잡는 것이다."}],"cases":[{"label":"행사 트래픽","note":"판매 시작 시각에 접속이 몰리면 대수를 늘렸다가 끝나면 되돌린다."},{"label":"업무 시간","note":"평일 낮에만 쓰이는 사내 시스템은 시각을 정해 늘리고 줄인다."},{"label":"서버 교체","note":"헬스체크에 실패한 서버를 빼고 같은 설정으로 새로 띄운다."}],"dia":{"shape":"흐름","title":"접속이 몰리면 서버는 어떻게 늘어나나","rows":[{"who":"감시","what":"CPU 사용률을 짧은 주기로 지켜본다"},{"who":"감시","what":"정해둔 기준을 넘긴 상태가 이어진다"},{"who":"그룹","what":"같은 설정으로 서버를 더 띄운다"},{"who":"분산기","what":"헬스체크를 통과한 서버부터 요청을 준다"},{"who":"그룹","what":"부하가 내려가면 서버를 하나씩 뺀다"}],"sum":"사람이 보고 있지 않아도 대수가 부하를 따라간다","loop":{"who":"감시","what":"다시 지켜본다. 최소 대수 아래로는 안 내린다"}}},"arch--bff":{"definition":"폰 앱과 데스크톱 화면은 화면 크기도, 성능도, 한 번에 보여줄 수 있는 양도 다르다. 그런데 뒤쪽이 하나면 그 서로 다른 요구가 한 곳에 몰려 부딪친다. BFF는 그 부딪침을 화면별 층 하나로 흡수하는 자리다.","name":"Backend :: 뒤에서 일하는 쪽\nfor :: ~만을 위한\nFrontend :: 눈에 보이는 화면\n= 붙여 읽으면 \"그 화면 하나만을 위한 뒤쪽\". 이름이 곧 이 층의 범위다","analogy":"손님마다 따로 싸 주는 도시락. 같은 주방에서 만들지만 아이 것은 양을 줄이고 반찬을 골라 담는다.","example":"같은 서비스인데 폰에서는 목록이 한 화면씩 오고 웹에서는 여러 화면이 한꺼번에 오는 그 차이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n흐름: 폰 화면 하나를 열면 무엇이 순서대로 일어나나\n화면 :: 자기 전용 뒤쪽 한 곳에만 요청을 보낸다\n전용 뒤쪽 :: 주문·재고·추천을 한꺼번에 부른다\n업무 서비스 :: 각자 자기 것만 돌려준다\n전용 뒤쪽 :: 폰에 쓸 것만 골라 하나로 합친다\n< 화면 :: 받은 그대로 그린다. 더 부를 곳이 없다\n= 여러 번 오갈 일을 뒤쪽 한 자리로 옮겨서 화면은 한 번만 부른다\n```\n\n화면은 업무 서비스의 주소를 하나도 모른다. 아는 것은 자기 전용 뒤쪽 하나뿐이다. 화면이 셋을 직접 부르면 느린 회선에서 왕복이 세 번 일어나고, 그 셋을 합치는 코드가 앱 안에 들어가 앱을 새로 받아야 고칠 수 있게 된다. 뒤쪽에서 합치면 왕복은 한 번이고, 고칠 때는 뒤쪽만 다시 배포한다.\n\n한 서비스가 답을 못 줄 때 무엇을 내놓을지도 이 층이 정한다. 추천이 죽었을 때 그 칸만 비운 응답을 내려보낼지 요청 전체를 실패로 칠지는 화면마다 다르고, 그 판단을 화면별로 따로 둘 수 있는 것이 뒤쪽을 나눠 둔 값이다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: BFF · API 게이트웨이 · GraphQL","body":"| 무엇 | 무엇을 맡나 | 몇 개 두나 |\n|---|---|---|\n| **BFF** | 그 화면 하나에만 해당하는 다듬기 | 화면 종류만큼 |\n| **API 게이트웨이** | 인가·기록·캐시·라우팅 같은 공통 일 | 대개 하나 |\n| **GraphQL** | 화면이 필요한 것만 골라 물어보게 하기 | 대개 하나 |\n\n세 자리가 겹쳐 보이지만 맡는 것이 다르다. 공통 일을 BFF에 넣으면 화면 수만큼 같은 코드를 복사하게 되고, 화면별 다듬기를 게이트웨이에 넣으면 다시 공용 병목이 된다. Azure 문서는 앞쪽에서 필요한 것만 골라 가져가는 방식을 이미 쓰고 있다면 BFF 층이 값을 못 할 수도 있다고 적고, 게이트웨이와 마이크로서비스 조합만으로 충분한 경우도 있다고 덧붙인다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **폰과 데스크톱** — 폰 쪽은 대역폭을 아끼려고 한 화면씩 내려주고, 데스크톱 쪽은 여러 화면을 한 번에 모아 내려준다.\n- **여러 곳의 값 모으기** — 앞쪽이 서비스 여럿을 각각 부르는 대신 전용 뒤쪽이 모아서 한 번에 내려준다. 오가는 횟수와 양이 줄어든다.\n- **화면에 열어 줄 수 없는 API** — 밖에 공개하지 않은 내부 API를 전용 뒤쪽이 대신 부른다. 화면은 그 주소도 열쇠도 갖지 않는다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **앞쪽이 둘이면 뒤쪽도 둘로 나누는 게 맞다** — 아니다. Azure 문서는 여러 화면이 같거나 비슷한 것만 물어보는 경우, 그리고 화면이 하나뿐인 경우에는 이 패턴이 맞지 않는다고 적는다. 나누는 순간 서비스 하나가 늘고, 그만큼 배포·유지·보안을 따로 감당한다.\n- **BFF에 인가랑 요청량 제한도 같이 넣으면 편하다** — BFF는 그 화면의 사용자 경험에 딸린 일만 맡는 자리다. 공통으로 걸릴 일은 따로 빼서 관문에 두라고 문서가 적는다.\n- **여러 화면이 BFF 하나를 같이 쓰면 중복이 준다** — 줄기는 하지만 그 하나가 다시 서로 다른 요구를 받는 자리가 된다. AWS 문서는 BFF가 자기 경계 안에서만 돌아야 하고 다른 경계와 공유되어서는 안 된다고 못 박는다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **한 번 더 건너간다.** 화면이 업무 서비스를 직접 부르지 않고 전용 뒤쪽을 거치므로 지연이 붙는다. 층을 하나 세울 때마다 응답 목표를 다시 잰다.\n- **코드가 겹치는 것은 이 패턴이 치르는 값이다.** 화면마다 비슷한 코드를 또 쓰게 된다. 그 중복과 화면에 딱 맞는 응답 중 무엇이 더 값진지 저울에 올려 정한다.\n- **몇 개까지 둘지 비용으로 정한다.** 뒤쪽 하나가 늘 때마다 수명 주기와 배포, 유지, 보안이 한 벌 더 생긴다. 화면 수가 아니라 감당할 수 있는 운영량이 상한이다."}],"figure":"```도해\n층: 화면과 업무 서비스 사이에 무엇이 끼어 있나\n화면 :: 폰 앱과 데스크톱처럼 요구가 다른 앞쪽들\n공용 관문 :: 인가·기록·요청량 제한 같은 공통 일을 맡는다\n전용 뒤쪽 :: 화면 종류마다 하나씩. 그 화면에 맞게만 다듬는다\n업무 서비스 :: 주문·결제·재고. 어느 화면인지 모른다\n= 화면마다 다른 요구를 전용 층에서 받아내고, 아래 업무 서비스는 그대로 둔다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 앞쪽이 여럿인데 뒤쪽이 하나면 무슨 일이 생기나\n공용 뒤쪽 하나 || 화면마다 하나\n요구가 부딪치면 :: 서로 조율해야 || 각자 정한다\n배포 :: 남을 기다린다 || 팀이 알아서 낸다\n폰에 맞추기 :: 다 같이 받는다 || 그 화면만 바꾼다\n= 앞쪽이 여럿이면 공용 뒤쪽 하나가 병목이 된다. 그 병목을 화면 수만큼 쪼갠 것이다\n```\n\n뒤쪽 하나가 여러 앞쪽의 요구를 동시에 받으면 고칠 일이 잦아지고, 그 하나를 고치려고 줄을 서게 된다. 한 앞쪽 팀이 요청한 변경을 다른 앞쪽 팀들과 맞춰 본 뒤에야 넣을 수 있고, 호환을 지키느라 손을 못 대는 자리가 늘어난다. 뒤쪽을 따로 관리하는 팀이 있으면 그 사이가 더 벌어진다.\n\nBFF는 그 층을 화면 수만큼 나눠 놓는다. 앞쪽 팀이 자기 뒤쪽을 직접 들고 있으면 언어도, 낼 시점도, 무엇을 먼저 할지도 스스로 정한다. 각 뒤쪽이 작아지므로 다루기도 쉬워진다."},"recap":"**\"그 화면 하나만 챙기는 전용 뒤쪽\"** 이라고 읽으면 된다. 공용 뒤쪽 하나가 여러 앞쪽의 요구에 눌려 병목이 될 때, 그 층을 화면 종류만큼 쪼개 앞쪽 팀에게 넘기는 방법이다. 화면들이 서로 다른 것을 요구할 때만 값을 하고, 비슷한 것만 물어본다면 뒤쪽 개수만 늘어난다.","kid":"급식실 한 곳에서 밥을 만들어도 1학년 도시락은 양을 줄이고 반찬을 골라 담아 주지? 그러면 1학년이 반찬을 바꿔 달라고 해도 6학년 도시락은 그대로야. 대신 도시락 종류가 늘어날수록 싸는 사람은 더 바빠져.","check":[{"q":"게이트웨이만으로 충분한 경우와 전용 뒤쪽이 필요한 경우는 무엇이 다른가","at":"비교"},{"q":"화면마다 뒤쪽을 나누면 코드가 겹치는데 그 중복을 왜 감수하나","at":"주의사항"},{"q":"앞쪽 팀이 자기 배포 시점을 스스로 정할 수 있게 되는 이유는 무엇인가","at":"해결하는 문제"}],"myths":[{"wrong":"앞쪽이 둘이면 뒤쪽도 둘로 나누는 게 맞다","right":"아니다. Azure 문서는 여러 화면이 같거나 비슷한 것만 물어보는 경우, 그리고 화면이 하나뿐인 경우에는 이 패턴이 맞지 않는다고 적는다. 나누는 순간 서비스 하나가 늘고, 그만큼 배포·유지·보안을 따로 감당한다."},{"wrong":"BFF에 인가랑 요청량 제한도 같이 넣으면 편하다","right":"BFF는 그 화면의 사용자 경험에 딸린 일만 맡는 자리다. 공통으로 걸릴 일은 따로 빼서 관문에 두라고 문서가 적는다."},{"wrong":"여러 화면이 BFF 하나를 같이 쓰면 중복이 준다","right":"줄기는 하지만 그 하나가 다시 서로 다른 요구를 받는 자리가 된다. AWS 문서는 BFF가 자기 경계 안에서만 돌아야 하고 다른 경계와 공유되어서는 안 된다고 못 박는다."}],"cases":[{"label":"폰과 데스크톱","note":"폰 쪽은 대역폭을 아끼려고 한 화면씩 내려주고, 데스크톱 쪽은 여러 화면을 한 번에 모아 내려준다."},{"label":"여러 곳의 값 모으기","note":"앞쪽이 서비스 여럿을 각각 부르는 대신 전용 뒤쪽이 모아서 한 번에 내려준다. 오가는 횟수와 양이 줄어든다."},{"label":"화면에 열어 줄 수 없는 API","note":"밖에 공개하지 않은 내부 API를 전용 뒤쪽이 대신 부른다. 화면은 그 주소도 열쇠도 갖지 않는다."}],"dia":{"shape":"층","title":"화면과 업무 서비스 사이에 무엇이 끼어 있나","rows":[{"who":"화면","what":"폰 앱과 데스크톱처럼 요구가 다른 앞쪽들"},{"who":"공용 관문","what":"인가·기록·요청량 제한 같은 공통 일을 맡는다"},{"who":"전용 뒤쪽","what":"화면 종류마다 하나씩. 그 화면에 맞게만 다듬는다"},{"who":"업무 서비스","what":"주문·결제·재고. 어느 화면인지 모른다"}],"sum":"화면마다 다른 요구를 전용 층에서 받아내고, 아래 업무 서비스는 그대로 둔다"}},"arch--back-pressure":{"definition":"표준 문서는 이 일을 \"원래 출처의 흐름을 사슬이 처리할 수 있는 속도에 맞추는 일\" 이라고 적는다. 사슬의 어느 한 칸이 아직 덩어리를 못 받으면 그 사실이 뒤로 거슬러 올라가고, 결국 맨 앞의 출처가 그만 빨리 만들라는 말을 듣는다.","name":"Back :: 뒤로\nPressure :: 미는 힘\n= 붙여 읽으면 \"뒤로 미는 힘\". 앞으로만 흐르던 것이 거꾸로 밀어 보내는 쪽의 속도를 정한다","analogy":"설거지할 때 헹구는 사람이 밀리면 씻는 사람이 잠깐 손을 멈추는 것.","example":"큰 파일을 옮기는 중에 진행 막대가 멈춘 듯 서 있는 순간이다. 받는 쪽이 삼킬 때까지 보내는 쪽이 기다리는 중이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"재는 방법은 단순하다. 줄에 쌓인 덩어리의 크기를 다 더해서 정해둔 선(high water mark)과 견준다. 그 선에서 쌓인 양을 뺀 값이 \"지금 더 받아도 되는 양\" 이고, 만드는 쪽은 그 값을 보고 속도를 조절한다.\n\nNode.js 스트림에서는 그 순간이 눈에 보인다. 쌓인 양이 선을 넘거나 쓰기 줄이 바쁘면 `.write()` 가 `false` 를 돌려준다. 기본 선은 16KB다. `false` 를 받으면 배압이 걸린 것이고, 읽어 오던 쪽이 멈춰 선다. 줄이 비면 `drain` 이 울리고 다시 흐른다. 안내서가 정한 규칙은 한 줄이다 — **`false` 를 받은 다음에는 `drain` 을 기다린다.**\n\n거슬러 올라가는 신호라는 점이 중요하다. 한 칸만 늦추는 것이 아니라 사슬 맨 앞까지 전해져야 쌓이는 자리가 안 생긴다. 중간 어딘가에 상한 없는 줄이 하나 끼어 있으면 그 줄이 신호를 삼키고, 배압은 거기서 끊긴다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 넘칠 때 고를 수 있는 세 가지","body":"| 대응 | 무엇을 하나 | 언제 고르나 |\n|---|---|---|\n| **늦추기 (배압)** | 보내는 쪽을 멈춰 세운다 | 보내는 쪽이 기다려도 되는 일. 파일 옮기기, 야간 일괄 처리 |\n| **쌓아두기 (큐)** | 남는 양을 줄에 받아 둔다 | 봉우리가 잠깐이고 평균은 소화되는 일 |\n| **버리기 (부하 덜기)** | 넘치는 요청을 곧바로 거절한다 | 사람이 화면 앞에서 기다리는 일 |\n\n셋은 서로 배타적이지 않다. 줄로 봉우리를 받되 줄이 계속 자라면 배압으로 늦추고, 사람을 기다리게 할 수 없는 앞쪽에서는 버린다. 다만 **배압만으로는 과부하가 사라지지 않는다.** 거슬러 올라간 느림은 결국 맨 앞의 사람에게 닿기 때문이다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **스트림으로 파일 옮기기** — 쓰기가 `false` 를 돌려주면 더 쓰지 않고 `drain` 을 기다린다. 이걸 어기면 메모리가 열 배 넘게 뛴다.\n- **여러 칸을 이어 붙인 사슬** — 중간 한 칸이 느려지면 그 사실이 사슬을 거슬러 맨 앞 출처까지 전해지고, 출처가 만드는 속도를 스스로 낮춘다.\n- **큐가 자라기만 할 때** — 생산 속도가 소비 속도를 넘으면 큐 깊이가 계속 자라고 지연도 같이 는다. 소비자를 늘려도 안 따라잡히면 생산자 쪽에서 일을 덜어낸다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **버퍼를 크게 잡으면 배압은 필요 없다** — 버퍼는 터지는 시각을 미룰 뿐이다. 평균 생산 속도가 소비 속도를 넘으면 줄은 계속 자라고, 그동안 지연도 같이 자란다. 구글 SRE 책이 대기줄을 일꾼 수의 절반 이하로 짧게 두라고 적는 이유다.\n- **배압이 걸리면 장애다** — 설계대로 도는 정상 상태다. 느려졌다는 사실이 제때 앞으로 전해진 것이고, 그 신호를 지우면 다음에 오는 것은 쓰러짐이다.\n- **막히면 무조건 배압을 걸면 된다** — 사람이 화면 앞에서 기다리는 자리에서는 늦추기가 그냥 지연이 된다. 그럴 땐 빨리 거절하거나 품질을 낮춰 답하는 편이 낫다."}],"figure":"```도해\n흐름: 받는 쪽이 느릴 때 보내는 쪽은 어떻게 아나\n보내는 쪽 :: 처리할 것을 줄에 밀어 넣는다\n줄 :: 쌓인 양이 정해둔 선을 넘는다\n받는 쪽 :: 한 번에 삼킬 수 있는 양이 정해져 있다\n< 신호 :: \"그만\" 이 보내는 쪽까지 거슬러 올라간다\n@ 보내는 쪽 :: 멈췄다가 줄이 비면 그 자리에서 이어 보낸다\n= 받는 쪽의 속도가 거꾸로 올라와 보내는 쪽의 속도를 정한다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 느린 쪽에 계속 밀어 넣으면 무슨 일이 생기나\n막지 않으면 || 배압으로\n쌓이는 곳 :: 줄이 계속 자란다 || 정해둔 선에서 선다\n메모리 :: 한없이 먹는다 || 예측이 된다\n망가지는 때 :: 한꺼번에 쓰러진다 || 미리 느려진다\n= 넘칠 때까지 두느냐, 넘치기 전에 늦추느냐의 차이다\n```\n\n보내는 쪽이 빠르고 받는 쪽이 느리면 그 차이는 어딘가에 쌓인다. 쌓이는 자리에 상한이 없으면 줄은 끝까지 자라고, 자라는 동안 지연도 같이 자란다. Node.js 공식 안내서가 같은 일을 배압 있을 때와 없을 때로 재 보는데, 메모리가 90MB 안팎에서 1.5GB 로 열 배 넘게 뛴다. 쓰러지기 전까지는 아무 경고도 없다.\n\n배압은 그 차이를 쌓지 않고 **앞으로 되돌려 보낸다.** 느리다는 사실이 제때 보내는 쪽에 닿으면, 보내는 쪽은 더 만들지 않고 기다린다. 애저 문서도 같은 말을 큐 쪽에서 한다 — 평균 생산 속도가 소비 속도를 넘으면 큐는 계속 자라고 지연이 늘어나니, 큐 깊이를 보고 소비자를 안전한 범위에서 늘리거나 생산자 쪽에서 일을 덜어내라고 적는다."},"recap":"**\"뒤에서 앞으로 거슬러 올라가는 그 브레이크\"** 라고 읽으면 된다. 받는 쪽의 속도를 보내는 쪽에 전해서, 차이가 어딘가에 쌓이는 대신 만드는 속도 자체를 줄인다. 다만 늦추기는 셋 중 하나일 뿐이라, 사람이 앞에서 기다리는 자리에서는 쌓아두기나 버리기와 함께 정해야 한다.","kid":"설거지할 때 씻는 사람이 빠르고 헹구는 사람이 느리면 그릇이 산더미가 되지? 그래서 헹구는 쪽이 밀리면 \"잠깐만\" 하고 말해 주고, 씻는 쪽이 손을 멈춰. 헹군 게 치워지면 다시 씻기 시작해.","check":[{"q":"버퍼를 키우기만 해서는 왜 문제가 미뤄지기만 하나","at":"흔한 오해"},{"q":"보내는 쪽은 받는 쪽이 느려졌다는 것을 어떻게 알게 되나","at":"그림"},{"q":"사람이 화면 앞에서 기다리는 요청에 왜 늦추기가 답이 아닌가","at":"비교"}],"myths":[{"wrong":"버퍼를 크게 잡으면 배압은 필요 없다","right":"버퍼는 터지는 시각을 미룰 뿐이다. 평균 생산 속도가 소비 속도를 넘으면 줄은 계속 자라고, 그동안 지연도 같이 자란다. 구글 SRE 책이 대기줄을 일꾼 수의 절반 이하로 짧게 두라고 적는 이유다."},{"wrong":"배압이 걸리면 장애다","right":"설계대로 도는 정상 상태다. 느려졌다는 사실이 제때 앞으로 전해진 것이고, 그 신호를 지우면 다음에 오는 것은 쓰러짐이다."},{"wrong":"막히면 무조건 배압을 걸면 된다","right":"사람이 화면 앞에서 기다리는 자리에서는 늦추기가 그냥 지연이 된다. 그럴 땐 빨리 거절하거나 품질을 낮춰 답하는 편이 낫다."}],"cases":[{"label":"스트림으로 파일 옮기기","note":"쓰기가 `false` 를 돌려주면 더 쓰지 않고 `drain` 을 기다린다. 이걸 어기면 메모리가 열 배 넘게 뛴다."},{"label":"여러 칸을 이어 붙인 사슬","note":"중간 한 칸이 느려지면 그 사실이 사슬을 거슬러 맨 앞 출처까지 전해지고, 출처가 만드는 속도를 스스로 낮춘다."},{"label":"큐가 자라기만 할 때","note":"생산 속도가 소비 속도를 넘으면 큐 깊이가 계속 자라고 지연도 같이 는다. 소비자를 늘려도 안 따라잡히면 생산자 쪽에서 일을 덜어낸다."}],"dia":{"shape":"흐름","title":"받는 쪽이 느릴 때 보내는 쪽은 어떻게 아나","rows":[{"who":"보내는 쪽","what":"처리할 것을 줄에 밀어 넣는다"},{"who":"줄","what":"쌓인 양이 정해둔 선을 넘는다"},{"who":"받는 쪽","what":"한 번에 삼킬 수 있는 양이 정해져 있다"},{"who":"신호","what":"\"그만\" 이 보내는 쪽까지 거슬러 올라간다","back":true}],"sum":"받는 쪽의 속도가 거꾸로 올라와 보내는 쪽의 속도를 정한다","loop":{"who":"보내는 쪽","what":"멈췄다가 줄이 비면 그 자리에서 이어 보낸다"}}},"arch--bulkhead":{"definition":"애저 문서는 이 패턴을 \"요소들을 여러 묶음으로 나눠, 하나가 죽어도 나머지는 계속 돌게 하는 것\" 으로 적고 셀 기반 아키텍처라는 다른 이름도 같이 붙인다. AWS 문서는 같은 이야기를 숫자로 말한다 — 열 칸으로 나눠 백 건을 처리하고 있었다면, 한 칸이 죽어도 요청의 90%는 아무 일 없이 지나간다.","name":"= 배 안을 칸칸이 막아 세운 벽에서 온 이름이다. 한 칸에 물이 새도 그 칸만 차고 배는 안 가라앉는다","analogy":"한 칸이 뚫려도 그 칸만 물이 차고 배는 계속 뜨게 하는, 배 안의 칸막이 벽.","example":"한 고객사의 요청이 폭주해서 아무 상관 없는 다른 고객사까지 같이 느려졌던 그 장애다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n층: 벽을 어디까지 세울 수 있나\n연결 풀 :: 부르는 쪽이 상대마다 따로 쥔다. 코드 안에서 끝난다\n스레드 풀 :: 기능마다 일꾼을 갈라 둔다. 하나가 막혀도 나머지가 돈다\n컨테이너·가상 머신 :: 계산 자원과 상한을 아예 따로 준다\n셀 :: 고객을 나눠 담은 통째 사본. 앞의 배분기만 공유한다\n= 아래로 갈수록 확실히 갈라지고, 그만큼 자원과 손이 더 든다\n```\n\n위의 둘은 부르는 쪽이 스스로 거는 벽이다. 애저 문서는 프로세스·스레드 풀·세마포어(한 번에 몇이나 들어갈지 세어 막는 장치)를 쓰라고 적고, 컨테이너는 격리 정도와 부담이 균형을 이루는 자리라고 덧붙인다.\n\n맨 아래의 셀은 성격이 다르다. 고객 번호처럼 요청마다 들어 있는 값을 열쇠로 삼아 요청을 칸으로 보내고, 칸끼리는 상태도 부품도 나눠 갖지 않는다. 칸을 넘나드는 호출이 생기는 순간 그 칸들은 다시 이어지고, 벽은 그만큼 얇아진다. 칸끼리 공유하는 유일한 부품이 앞단의 배분기라, 그 배분기만은 다른 규칙으로 다뤄야 한다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **상대마다 연결 풀 분리** — 외부 결제사가 응답을 멈춰도 마르는 것은 그쪽 풀뿐이고, 배송사 호출은 평소대로 나간다.\n- **셀로 나눈 고객** — 열 칸으로 나눠 두면 한 칸이 통째로 죽어도 요청의 90%는 아무 일 없이 처리된다.\n- **컨테이너로 상한 걸기** — 서비스마다 계산 자원과 상한을 따로 준다. 하나가 폭주해도 같은 기계 위의 다른 서비스는 제 몫을 그대로 쓴다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **벽은 많이 세울수록 좋다** — 칸을 나누면 남는 자리를 서로 못 빌려 쓴다. 자원을 덜 효율적으로 쓰는 것이 받아들여지지 않는 곳이면 이 패턴은 맞지 않는다.\n- **벽을 세우면 고장이 안 난다** — 고장은 그대로 난다. 그 칸 안에서만 나게 만드는 것이 전부다.\n- **서킷 브레이커가 있으면 격벽은 필요 없다** — 하는 일이 다르다. 브레이커는 죽은 곳을 그만 부르는 것이고, 격벽은 부르다 물린 자원이 남의 자원까지 먹지 못하게 미리 갈라 두는 것이다. 공식 문서도 둘을 같이 쓰라고 적는다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **칸을 무한정 키우지 않는다.** 최대 크기를 부하 시험으로 찾아 정해 두고, 그 위로는 칸을 하나 더 만들어 늘린다.\n- **모든 칸에 한꺼번에 배포하지 않는다.** 나쁜 배포 하나가 벽을 넘어가는 가장 흔한 길이다. 칸을 나눠 차례로 올린다.\n- **앞단 배분기는 단순하게 둔다.** 칸끼리 공유하는 유일한 부품이라, 여기에 업무 규칙이 들어가면 벽 전체가 같이 위태로워진다.\n- **플랫폼이 주는 상한을 먼저 쓴다.** 요청량 제한이나 자원 상한 같은 장치는 이미 있다. 애저 문서는 그걸 애플리케이션 코드로 다시 만들지 말라고 적는다."}],"figure":"```도해\n대조: 고장 하나가 어디까지 번지나\n칸을 안 나누면 || 칸칸이 나누면\n자원 :: 다 같이 쓴다 || 각자 제 칸만\n한 곳이 죽으면 :: 전부 멈춘다 || 그 칸만 멈춘다\n멀쩡한 몫 :: 없다 || 열 칸이면 아홉\n= 자원을 미리 갈라 두면 고장이 그 칸을 넘어가지 못한다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 남의 사고가 왜 나에게까지 건너오나\n몫을 안 가르면 || 몫을 갈라 두면\n느린 상대 :: 연결 풀이 마른다 || 그쪽 몫만 마른다\n다른 상대 :: 멀쩡한데 못 부른다 || 평소대로 부른다\n옆 손님 :: 같이 못 쓴다 || 평소대로 쓴다\n= 같이 쓰는 자원이 남의 사고가 나에게 건너오는 다리가 된다\n```\n\n고장은 두 방향으로 번진다. 부르는 쪽에서는 응답 없는 상대를 기다리는 연결이 하나씩 묶이다가 연결 풀이 말라버리고, 그러면 멀쩡한 다른 상대까지 못 부르게 된다. 받는 쪽에서는 한 고객이 쏟아낸 요청이 자원을 다 먹어서 다른 고객이 그 기능을 못 쓰게 된다. 애저 문서는 이 패턴이 부르는 쪽과 받는 쪽 둘 다를 연쇄 장애에서 떼어 놓는다고 적는다.\n\n격벽은 고장을 막지 않는다. **번질 길을 미리 끊어 둘 뿐이다.** 상대마다 연결 풀을 따로 주면 마르는 것은 그 풀 하나고, 고객을 칸으로 나눠 두면 소진되는 것은 그 칸의 몫뿐이다."},"recap":"**\"고장을 한 칸에 가두려고 미리 그어 둔 그 선\"** 이라고 읽으면 된다. 연결 풀 하나를 나누는 일부터 고객을 통째 사본으로 갈라 담는 셀까지 같은 생각이고, 아래로 갈수록 확실해지는 대신 자원과 손이 더 든다. 대가는 낭비다 — 남는 자리를 서로 못 빌려 쓰는 것을 받아들일 수 없으면 고르지 않는다.","kid":"큰 배 안은 방마다 벽으로 딱딱 나뉘어 있어. 어느 방에 구멍이 나서 물이 들어와도 그 방만 차고 옆방은 멀쩡해서 배가 안 가라앉아. 아예 안 새게 하는 게 아니라, 새더라도 한 방만 새게 미리 막아 두는 거야.","check":[{"q":"손님 하나가 몰아쳤을 뿐인데 다른 손님까지 못 쓰게 되는 이유는","at":"해결하는 문제"},{"q":"벽을 세울 자리가 여러 곳인데 아래로 갈수록 무엇이 늘어나나","at":"작동 원리"},{"q":"자원을 아껴 써야 하는 곳에 이 패턴이 안 맞는 이유는","at":"흔한 오해"}],"myths":[{"wrong":"벽은 많이 세울수록 좋다","right":"칸을 나누면 남는 자리를 서로 못 빌려 쓴다. 자원을 덜 효율적으로 쓰는 것이 받아들여지지 않는 곳이면 이 패턴은 맞지 않는다."},{"wrong":"벽을 세우면 고장이 안 난다","right":"고장은 그대로 난다. 그 칸 안에서만 나게 만드는 것이 전부다."},{"wrong":"서킷 브레이커가 있으면 격벽은 필요 없다","right":"하는 일이 다르다. 브레이커는 죽은 곳을 그만 부르는 것이고, 격벽은 부르다 물린 자원이 남의 자원까지 먹지 못하게 미리 갈라 두는 것이다. 공식 문서도 둘을 같이 쓰라고 적는다."}],"cases":[{"label":"상대마다 연결 풀 분리","note":"외부 결제사가 응답을 멈춰도 마르는 것은 그쪽 풀뿐이고, 배송사 호출은 평소대로 나간다."},{"label":"셀로 나눈 고객","note":"열 칸으로 나눠 두면 한 칸이 통째로 죽어도 요청의 90%는 아무 일 없이 처리된다."},{"label":"컨테이너로 상한 걸기","note":"서비스마다 계산 자원과 상한을 따로 준다. 하나가 폭주해도 같은 기계 위의 다른 서비스는 제 몫을 그대로 쓴다."}],"dia":{"shape":"대조","title":"고장 하나가 어디까지 번지나","rows":[{"who":"","what":"칸을 안 나누면 || 칸칸이 나누면","left":"칸을 안 나누면","right":"칸칸이 나누면"},{"who":"자원","what":"다 같이 쓴다 || 각자 제 칸만","left":"다 같이 쓴다","right":"각자 제 칸만"},{"who":"한 곳이 죽으면","what":"전부 멈춘다 || 그 칸만 멈춘다","left":"전부 멈춘다","right":"그 칸만 멈춘다"},{"who":"멀쩡한 몫","what":"없다 || 열 칸이면 아홉","left":"없다","right":"열 칸이면 아홉"}],"sum":"자원을 미리 갈라 두면 고장이 그 칸을 넘어가지 못한다"}},"arch--cqrs":{"definition":"한 모델이 둘을 다 감당하면 한쪽에 맞출 때마다 다른 쪽이 손해를 본다. 쓰기는 업무 규칙을 따지느라 무거워야 하고, 읽기는 화면에 낼 모양 그대로 가벼워야 한다. 두 요구가 원래 다르다는 것을 인정하고 모델을 갈라 놓은 것이 이 패턴이다.","name":"Command :: 바꾸라는 지시\nQuery :: 물어보는 일\nResponsibility :: 맡은 몫\nSegregation :: 갈라 놓기\n= 붙여 읽으면 \"바꾸는 일과 묻는 일의 몫을 갈라 놓기\". 한국어로는 명령 질의 책임 분리라고 읽는다","analogy":"주문서는 주방으로 들어가고 손님은 사진까지 박아 둔 메뉴판만 보는 식당.","example":"리뷰를 올리면 \"등록되었습니다\" 는 곧바로 뜨는데 상품 페이지의 별점 평균은 몇 초 뒤에야 바뀌는 그 순간이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n층: 가르는 깊이를 어디까지 밀 수 있나\n모델만 가르기 :: 저장소는 하나. 읽기 로직과 쓰기 로직만 나눈다\n저장소까지 가르기 :: 읽기 전용 복제본이나 다른 종류의 저장소를 둔다\n원본까지 가르기 :: 사건 기록이 원본이 되고 조회용 표는 거기서 만든다\n= 아래로 갈수록 얻는 것도 크고 감당할 것도 크다. 필요한 깊이까지만 내려간다\n```\n\n가장 얕은 단계는 저장소 하나를 그대로 두고 모델만 나누는 것이다. 쓰기 모델은 검증과 업무 규칙을 담고, 읽기 모델은 업무 규칙 없이 화면에 넘길 자료 묶음만 만든다. 여기까지만 해도 책임이 갈라져서 두 쪽 코드가 서로를 방해하지 않는다.\n\n한 단계 내려가면 저장소를 따로 둔다. 그러면 읽기와 쓰기를 각자의 부하에 맞춰 늘릴 수 있고, 한쪽은 문서 저장소 다른 쪽은 관계형처럼 종류를 달리 고를 수도 있다. 대신 둘을 맞춰 주어야 한다. 흔한 방법은 쓰기 쪽이 바뀔 때마다 사건을 발행하고 읽기 쪽이 그걸 받아 자기 표를 고치는 것이다.\n\n가장 깊은 단계가 [[Event Sourcing]]과 붙인 형태다. 사건 기록 자체가 쓰기 모델이자 유일한 원본이 되고, 조회용 표는 그 사건을 재생해 만든 결과가 된다. 표를 새로 만들거나 모양을 바꾸고 싶으면 과거 사건을 다시 재생하면 된다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **읽기 쪽만 늘리기** — 조회가 쓰기보다 열 배쯤 많은 화면에서는 읽기 모델만 여러 대로 늘리고 쓰기 모델은 적은 수로 둔다.\n- **화면에 맞춘 표** — 조인을 여러 번 해야 나오는 목록을 미리 한 줄로 만들어 두고, 조회는 그 표만 읽는다.\n- **팀을 나눠 붙이기** — 복잡한 업무 규칙은 쓰기 쪽 팀이 맡고, 화면과 조회는 읽기 쪽 팀이 따로 만든다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **CQRS를 쓰면 어떤 시스템이든 더 낫다** — 업무 규칙이 단순하고 CRUD 화면으로 충분한 곳에서는 모델만 둘로 늘어난다. Microsoft 문서도 그런 자리에는 이 패턴이 맞지 않는다고 적는다.\n- **저장소를 두 개 써야 CQRS다** — 아니다. 저장소 하나를 그대로 두고 읽기 모델과 쓰기 모델만 나누는 것이 이 패턴의 기본 단계다.\n- **CQRS는 곧 이벤트 소싱이다** — 자주 같이 쓸 뿐 다른 패턴이다. 메시징조차 필수가 아니고, 둘을 합치면 설계 난도가 한 단계 더 올라간다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **읽는 값은 잠깐 옛것이다.** 저장소를 가르는 순간 조회 쪽은 최신 변경을 바로 보여주지 못한다. 사용자가 낡은 값을 보고 행동하는 경우를 어떻게 다룰지 미리 정해야 한다.\n- **원본을 고치는 일과 소식을 보내는 일은 한 묶음이 아니다.** Microsoft 문서는 메시지 브로커와 데이터베이스를 하나의 분산 트랜잭션으로 묶을 수 없는 것이 보통이라 적고, 상태 변경과 사건을 함께 확정하는 아웃박스와 같은 소식을 두 번 받아도 결과가 같은 소비자를 쓰라고 권한다.\n- **도구가 대신 만들어 주지 않는다.** 스키마에서 코드를 뽑아 주던 O/RM 방식이 여기서는 통하지 않아서, 두 모델 사이를 잇는 로직을 직접 써야 한다."}],"figure":"```도해\n대조: 바꾸는 일과 묻는 일을 갈라 놓으면 각자 무엇을 하나\n쓰기 모델 |=| 읽기 모델\n받는 것 :: \"예약해\" 라는 지시 || \"목록 줘\" 라는 질문\n하는 일 :: 규칙을 따져 고친다 || 만들어 둔 표를 읽는다\n맞춘 곳 :: 업무 규칙 || 화면 모양\n= 한 모델이 둘을 겸하지 않는다. 바꾸는 쪽과 묻는 쪽을 갈라 각자에 맞춘다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 읽기와 쓰기가 한 모델을 같이 쓰면 무엇이 걸리나\n한 모델로 || 두 모델로\n구조 :: 한쪽에 맞추면 손해 || 각자에 맞춘다\n확장 :: 같이 늘려야 한다 || 따로 늘린다\n잠금 :: 같은 줄을 두고 다툰다 || 다툴 일이 준다\n= 두 일은 요구가 다르다. 한 모델은 그 차이를 담지 못한다\n```\n\n읽기와 쓰기는 성능과 확장 요구가 서로 다른데, 전통적인 CRUD 구조는 그 비대칭을 반영하지 않는다. Microsoft 문서는 그래서 생기는 것으로 넷을 든다 — 갱신에만 필요한 항목까지 조회가 떠안는 표현의 불일치, 같은 자료를 동시에 건드릴 때의 잠금 다툼, 복잡한 질의가 저장소에 얹는 부하, 그리고 하나의 개체가 읽기와 쓰기를 겸할 때 어려워지는 권한 관리다.\n\nCQRS는 그 둘을 갈라서 각자 다르게 손보게 한다. 조회가 쓰기보다 열 배쯤 많은 화면이라면 읽기 쪽만 늘리면 되고, 조회용 표는 조인 없이 바로 읽히는 모양으로 따로 만들어 둘 수 있다. 반대로 업무 규칙이 단순하고 CRUD 화면으로 충분한 곳이라면, Microsoft 문서도 이 패턴이 맞지 않는다고 적는다."},"recap":"**\"바꾸는 길과 묻는 길을 따로 낸 설계\"** 라고 읽으면 된다. 저장소를 하나 둔 채 모델만 가르는 것부터 저장소와 원본까지 가르는 것까지 깊이가 여러 단계이고, 깊이 내려갈수록 얻는 것도 감당할 것도 커진다. 값이 잠깐 어긋나는 것을 받아들일 수 있고 읽기와 쓰기의 요구가 실제로 다를 때만 고른다.","kid":"식당에서 주문서는 주방으로 들어가지? 그런데 너는 주방을 들여다보는 게 아니라 사진 붙은 메뉴판만 보고 고르잖아. 그래서 주방에서 재료가 다 떨어져도, 누가 메뉴판을 바꿔 붙이기 전까지는 그 사진이 그대로 걸려 있어.","check":[{"q":"읽기 쪽만 서버를 열 배로 늘릴 수 있는 이유는 무엇인가","at":"해결하는 문제"},{"q":"리뷰를 올리자마자 평균 별점이 안 바뀌는 일이 왜 생기나","at":"주의사항"},{"q":"저장소를 하나만 쓰면서도 이 패턴을 썼다고 할 수 있나","at":"작동 원리"}],"myths":[{"wrong":"CQRS를 쓰면 어떤 시스템이든 더 낫다","right":"업무 규칙이 단순하고 CRUD 화면으로 충분한 곳에서는 모델만 둘로 늘어난다. Microsoft 문서도 그런 자리에는 이 패턴이 맞지 않는다고 적는다."},{"wrong":"저장소를 두 개 써야 CQRS다","right":"아니다. 저장소 하나를 그대로 두고 읽기 모델과 쓰기 모델만 나누는 것이 이 패턴의 기본 단계다."},{"wrong":"CQRS는 곧 이벤트 소싱이다","right":"자주 같이 쓸 뿐 다른 패턴이다. 메시징조차 필수가 아니고, 둘을 합치면 설계 난도가 한 단계 더 올라간다."}],"cases":[{"label":"읽기 쪽만 늘리기","note":"조회가 쓰기보다 열 배쯤 많은 화면에서는 읽기 모델만 여러 대로 늘리고 쓰기 모델은 적은 수로 둔다."},{"label":"화면에 맞춘 표","note":"조인을 여러 번 해야 나오는 목록을 미리 한 줄로 만들어 두고, 조회는 그 표만 읽는다."},{"label":"팀을 나눠 붙이기","note":"복잡한 업무 규칙은 쓰기 쪽 팀이 맡고, 화면과 조회는 읽기 쪽 팀이 따로 만든다."}],"dia":{"shape":"대조","title":"바꾸는 일과 묻는 일을 갈라 놓으면 각자 무엇을 하나","rows":[{"who":"","what":"쓰기 모델 || 읽기 모델","left":"쓰기 모델","right":"읽기 모델","even":true},{"who":"받는 것","what":"\"예약해\" 라는 지시 || \"목록 줘\" 라는 질문","left":"\"예약해\" 라는 지시","right":"\"목록 줘\" 라는 질문"},{"who":"하는 일","what":"규칙을 따져 고친다 || 만들어 둔 표를 읽는다","left":"규칙을 따져 고친다","right":"만들어 둔 표를 읽는다"},{"who":"맞춘 곳","what":"업무 규칙 || 화면 모양","left":"업무 규칙","right":"화면 모양"}],"sum":"한 모델이 둘을 겸하지 않는다. 바꾸는 쪽과 묻는 쪽을 갈라 각자에 맞춘다"}},"arch--cache-aside-vs-write-through":{"definition":"캐시에 둔 사본은 원본과 어긋나기 마련이다. 애저 문서는 그래서 \"캐시를 얼마나 최신으로 둘지\" 를 앱이 전략으로 정해 두어야 한다고 적는다. 이 갈림이 그 전략의 첫 번째 갈래고, AWS 문서는 앞쪽 방식을 지연 적재(lazy loading)라는 이름으로 설명한다.","name":"Cache :: 가까이 둔 사본\nAside :: 비켜서\nWrite :: 쓰기\nThrough :: 지나서\n= \"캐시를 비켜서\" 는 읽다 없을 때 원본에 다녀와 채우고, \"지나서 쓰기\" 는 쓸 때 원본까지 한 번에 쓴다","analogy":"밥상의 작은 반찬통에 부엌 큰 통의 반찬을 언제 덜어 오느냐 — 먹고 싶을 때 그때그때냐, 새로 담글 때마다 미리냐.","example":"상품 이름을 고쳤는데 목록에는 한동안 옛 이름이 그대로 떠 있던 그 순간이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n흐름: 캐시를 비켜 읽는 쪽은 한 번 읽을 때 무엇을 하나\n앱 :: 먼저 캐시에 그 값이 있냐고 묻는다\n캐시 :: 있으면 그대로 준다. 여기서 끝난다\n원본 :: 없으면 앱이 원본에서 읽어 온다\n앱 :: 읽어 온 값을 캐시에 넣어 둔다\n< 앱 :: 값을 돌려준다. 뒷사람은 첫 줄에서 끝난다\n= 캐시가 스스로 채우는 게 아니라 없을 때 앱이 채워 넣는 것이다\n```\n\n쓸 때의 순서는 원본이 먼저다. 원본을 고치고 그다음 캐시의 그 항목을 지운다. 다음에 누가 읽으면 없으니까 새 값이 그때 담긴다. 지우는 대신 새 값으로 덮어쓰지 않는 까닭은, 거의 같은 때에 두 번 고쳤을 때 어느 쪽 값이 나중에 캐시에 닿을지 정해져 있지 않기 때문이다. 지워 두면 다음 읽기가 원본에서 가장 최신 값을 가져온다.\n\n쓰며 채우는 쪽은 이 순서가 아예 없다. 쓰기 한 번에 캐시와 원본을 함께 쓰고 둘 다 끝나야 성공으로 친다. 대신 쓰기마다 두 곳을 다녀오므로 쓰기가 느려지고, 캐시가 안 열리는 동안에는 쓰기 자체가 막힐 수 있다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 둘 중 무엇을 고르나","body":"| 보는 자리 | Cache Aside (읽다 채우기) | Write Through (쓰며 채우기) |\n|---|---|---|\n| **캐시에 없는 값** | 세 번 오간다 — 캐시·원본·다시 캐시 | 쓴 적 없으면 여전히 없다 |\n| **쓴 직후 읽기** | 잠깐 옛값이 보일 수 있다 | 곧바로 새 값이 보인다 |\n| **새로 띄운 노드** | 없는 값마다 원본에 다녀오며 스스로 채워진다 | 다시 쓸 때까지 비어 있다 |\n| **캐시 낭비** | 요청된 값만 담긴다 | 안 읽을 값까지 담긴다 |\n| **고르는 자리** | 무엇이 읽힐지 모를 때 | 고친 사람이 곧바로 다시 보는 화면 |\n\n**둘은 배타적이지 않다.** AWS 문서가 권하는 조합은 쓰며 채우되 만료 시간을 함께 거는 것이다. 그러면 빈 노드는 읽다 채워지고, 안 읽는 값은 시간이 지나 걷힌다. 기본은 읽다 채우기로 두고, 쓴 직후 바로 읽는 화면에만 쓰며 채우기를 얹는 것이 대개 안전한 순서다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **상품 상세 화면** — 처음 열릴 때 원본에서 읽어 담고 그다음부터는 캐시가 답한다. 아무도 안 여는 상품은 담기지도 않는다.\n- **고쳐서 바로 보여주는 화면** — 수정 버튼을 누른 사람이 그 값을 곧바로 다시 읽는다면, 쓸 때 캐시까지 같이 채운다.\n- **둘을 겹쳐 쓰기** — 쓰며 채우되 만료 시간을 함께 건다. 빈 노드는 읽다 채워지고, 안 읽는 값은 시간이 지나면 걷힌다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **쓰며 채우는 쪽이 언제나 낫다** — 대부분의 값은 한 번도 안 읽힌다. 쓸 때마다 담으면 안 읽을 값이 캐시를 차지하고, 새로 띄운 노드는 다시 쓸 때까지 비어 있다.\n- **고칠 때 캐시부터 지우면 된다** — 순서가 반대다. 원본을 먼저 고치고 그다음 캐시를 지운다. 캐시를 먼저 지우면 그 틈에 누가 읽어 가서 옛값을 도로 담아 놓는다.\n- **캐시를 붙이면 어차피 빨라진다** — 대부분의 요청이 캐시에서 안 맞으면 캐시를 확인하고 채우는 비용만 더 든다. 그럴 때는 캐시를 빼는 편이 낫다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **만료 시간을 접근 주기에 맞춘다.** 너무 짧으면 원본에 계속 다녀오고, 너무 길면 옛값이 오래 남는다. 캐시는 자주 읽히고 잘 안 바뀌는 값에 가장 잘 듣는다.\n- **비싼 값은 따로 정한다.** 캐시가 가득 차면 대개 가장 오래 안 쓴 것부터 버린다. 꺼내오기 비싼 값은 전체 정책 말고 그 값만의 정책을 준다.\n- **민감한 값은 담지 않는다.** 여럿이 함께 쓰는 캐시라면 더 그렇다. 그런 값은 원본에서 바로 읽는다."}],"figure":"```도해\n대조: 캐시를 언제 채우느냐로 무엇이 갈리나\n캐시 비켜 읽기 |=| 지나서 쓰기\n채우는 때 :: 읽다 없을 때 || 쓸 때마다\n쓴 직후 읽기 :: 잠깐 옛값 || 곧바로 새값\n안 읽는 값 :: 안 담긴다 || 그래도 담긴다\n= 읽다 채우면 안 쓰는 값이 안 쌓이고, 쓰며 채우면 옛값이 안 남는다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 전략을 안 정해 두면 캐시는 어떻게 되나\n정하지 않으면 || 정해 두면\n옛값 :: 언제 지울지 모른다 || 지우는 때가 있다\n새로 띄운 기계 :: 텅 빈 채로 받는다 || 채울 길이 정해진다\n자리 :: 안 읽는 값이 쌓인다 || 만료로 걷어낸다\n= 어긋남을 없앨 수는 없고, 어디로 몰지 정하는 것이 전략이다\n```\n\n캐시를 붙이면 빨라진다. 대신 같은 값이 두 군데에 있게 되고, 그 둘은 반드시 어긋난다. 어긋남은 세 자리에서 나온다 — 원본을 고친 직후, 캐시가 가득 차서 무언가를 버릴 때, 캐시를 담은 기계(노드)를 새로 띄워 캐시가 텅 비었을 때.\n\n이 갈림은 그 어긋남을 **어느 쪽으로 몰지** 고르는 일이다. 읽다 채우면 안 읽는 값이 안 쌓이고 빈 노드도 스스로 채워지지만, 쓴 직후에 잠깐 옛값이 보인다. 쓰며 채우면 옛값이 안 남지만, 한 번도 안 읽힐 값까지 캐시를 차지하고 새 노드는 다시 쓸 때까지 비어 있다."},"recap":"**\"읽다 채울까 쓰며 채울까의 갈림\"** 이라고 읽으면 된다. 읽다 채우면 안 읽는 값이 안 쌓이고 빈 노드가 스스로 차는 대신 쓴 직후에 잠깐 옛값이 보이고, 쓰며 채우면 그 반대다. 둘 중 하나를 고르는 문제로 보지 말고, 기본을 읽다 채우기로 두고 만료 시간을 건 뒤 곧바로 다시 읽는 화면에만 쓰며 채우기를 얹는다.","kid":"밥상에는 작은 반찬통을 놓고 큰 통은 부엌에 두지? 먹고 싶을 때만 큰 통에서 덜어 오면 아무도 안 먹는 반찬은 아예 안 담기는 대신, 방금 담근 김치가 작은 통에는 아직 없을 수 있어. 담글 때마다 미리 덜어 두면 늘 새것이지만 안 먹을 반찬까지 자리를 차지해.","check":[{"q":"상품 이름을 고쳤는데 목록에 옛 이름이 남아 있는 이유는","at":"그림"},{"q":"캐시를 먼저 지우고 원본을 고치면 무슨 일이 생기나","at":"흔한 오해"},{"q":"새로 띄운 캐시가 텅 비었을 때 어느 쪽이 스스로 채워지나","at":"비교"}],"myths":[{"wrong":"쓰며 채우는 쪽이 언제나 낫다","right":"대부분의 값은 한 번도 안 읽힌다. 쓸 때마다 담으면 안 읽을 값이 캐시를 차지하고, 새로 띄운 노드는 다시 쓸 때까지 비어 있다."},{"wrong":"고칠 때 캐시부터 지우면 된다","right":"순서가 반대다. 원본을 먼저 고치고 그다음 캐시를 지운다. 캐시를 먼저 지우면 그 틈에 누가 읽어 가서 옛값을 도로 담아 놓는다."},{"wrong":"캐시를 붙이면 어차피 빨라진다","right":"대부분의 요청이 캐시에서 안 맞으면 캐시를 확인하고 채우는 비용만 더 든다. 그럴 때는 캐시를 빼는 편이 낫다."}],"cases":[{"label":"상품 상세 화면","note":"처음 열릴 때 원본에서 읽어 담고 그다음부터는 캐시가 답한다. 아무도 안 여는 상품은 담기지도 않는다."},{"label":"고쳐서 바로 보여주는 화면","note":"수정 버튼을 누른 사람이 그 값을 곧바로 다시 읽는다면, 쓸 때 캐시까지 같이 채운다."},{"label":"둘을 겹쳐 쓰기","note":"쓰며 채우되 만료 시간을 함께 건다. 빈 노드는 읽다 채워지고, 안 읽는 값은 시간이 지나면 걷힌다."}],"dia":{"shape":"대조","title":"캐시를 언제 채우느냐로 무엇이 갈리나","rows":[{"who":"","what":"캐시 비켜 읽기 || 지나서 쓰기","left":"캐시 비켜 읽기","right":"지나서 쓰기","even":true},{"who":"채우는 때","what":"읽다 없을 때 || 쓸 때마다","left":"읽다 없을 때","right":"쓸 때마다"},{"who":"쓴 직후 읽기","what":"잠깐 옛값 || 곧바로 새값","left":"잠깐 옛값","right":"곧바로 새값"},{"who":"안 읽는 값","what":"안 담긴다 || 그래도 담긴다","left":"안 담긴다","right":"그래도 담긴다"}],"sum":"읽다 채우면 안 쓰는 값이 안 쌓이고, 쓰며 채우면 옛값이 안 남는다"}},"arch--caching":{"definition":"같은 질문에 같은 답이 나온다면 두 번째부터는 답을 만들 필요가 없다. 만들어둔 답을 빠른 곳에 놓아두고 꺼내 쓰는 것이 캐싱이다.","name":"= Cache 는 프랑스어 cacher(감추다)에서 온 말로, 나중에 쓰려고 가까이 감춰 둔 곳간을 뜻한다. 멀리 가지 않고 감춰 둔 데서 바로 꺼내 쓴다는 뜻이 그대로 남았다","analogy":"자주 보는 책은 도서관에 반납하지 않고 책상 위에 둔다.","example":"뒤로 가기를 눌렀을 때 페이지가 다시 뜨지 않고 곧바로 나타나는 것이 이것이 일한 결과다.","tryit":"아무 사이트나 열었다가 다른 곳으로 갔다 뒤로 가기를 눌러 보라. 처음보다 빨리 뜨는 건 그림과 글을 다시 받지 않고 컴퓨터에 남겨 둔 것을 쓰기 때문이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"넣고 빼는 방식은 보통 셋 중 하나다. 읽을 때 없으면 그때 채우는 방식이 가장 흔하고, 쓸 때 DB 와 캐시에 같이 넣는 방식은 옛 값이 남을 일이 적다. 캐시에 먼저 쓰고 DB 에는 나중에 몰아 넣는 방식은 가장 빠르지만 그 사이에 죽으면 쓴 값을 잃는다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **로그인 세션** — 요청마다 DB 를 보지 않고 캐시에서 세션을 꺼내 확인한다.\n- **목록 화면** — 인기 상품처럼 모두에게 같은 목록은 한 번 만들어 잠시 재사용한다.\n- **외부 API 응답** — 환율처럼 자주 안 바뀌는 값을 받아두고 정해진 시간 동안 그대로 쓴다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **캐시를 붙이면 무조건 빨라진다** — 같은 값을 다시 안 부르는 데이터라면 미스만 쌓인다. DB 조회 앞에 캐시 조회가 얹혀서 오히려 느려진다.\n- **캐시에 있는 값은 최신 값이다** — 원본이 바뀌어도 캐시는 모른다. 만료되거나 지워질 때까지 옛 값을 그대로 준다.\n- **캐시도 데이터 저장소다** — 언제 사라져도 되는 사본이다. 캐시에만 있는 값은 서버가 재시작되면 없어진다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **사람마다 다른 값은 키를 나눈다.** 사용자 구분 없이 키를 잡으면 A 가 담은 장바구니가 B 에게 나간다.\n- **만료를 한 시각에 몰지 않는다.** 캐시가 한꺼번에 비면 그 순간 모든 요청이 DB 로 쏟아진다."}],"figure":"```도해\n흐름: 같은 값을 두 번째로 부르면 무엇이 달라지나\n앱 :: 캐시에 있는지 먼저 본다\n캐시 :: 없다. 이것을 미스라고 부른다\nDB :: 앱이 대신 물어본다. 여기가 느린 구간이다\n앱 :: 받은 값을 캐시에 넣어둔다\n@ 다음 요청 :: 처음부터 다시. 이번엔 캐시에서 끝난다\n= 첫 사람만 DB 까지 가고 나머지는 캐시에서 돌아온다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 같은 값을 매번 DB 에서 읽으면 어떻게 되나\n캐시 없이 || 캐시로\n같은 조회 :: 매번 DB 까지 || 두 번째는 생략\nDB 부하 :: 요청 수만큼 || 미스일 때만\n응답 시간 :: 밀리초 단위 || 마이크로초 단위\n= 값이 안 바뀌는 동안에는 같은 일을 두 번 하지 않는다\n```\n\n공지사항이나 상품 정보처럼 잘 바뀌지 않는 값도 조회할 때마다 DB 까지 간다. 사용자가 천 명이면 같은 질의가 천 번 나가고, DB 는 매번 같은 답을 만들어 돌려준다. 느린 것도 문제지만 DB 가 먼저 한계에 닿는다.\n\n캐싱은 이 반복을 없앤다. 처음 한 번만 DB 에서 읽고 이후에는 메모리에서 꺼내니, 응답이 빨라지는 동시에 DB 가 받는 요청 수 자체가 줄어든다."},"compose":{"label":"무엇으로 되어 있나","head":"🧱 구성","body":"```도해\n층: 데이터를 찾으러 어디까지 내려가나\nCPU 캐시 :: 프로세서 안. 나노초 단위\n앱 메모리 :: 같은 프로세스 안. 서버마다 따로 갖는다\n분산 캐시 :: 별도 서버. 여러 앱이 같은 값을 본다\nDB :: 원본. 여기까지 내려오는 비율을 낮추는 게 목표다\n= 위에서 끝날수록 빠르고, 아래로 갈수록 여러 곳이 같은 값을 본다\n```"},"recap":"**\"한 번 간 길을 두 번 가지 않게 두는 그 사본\"** 이라고 읽으면 된다. 자주 쓰는 값을 빠른 곳에 두고 다시 쓰니 응답 시간과 원본 부하가 함께 줄어든다. 대가로 원본과 어긋난 값이 잠시 남으며, 언제 지울지를 정하는 일이 캐싱의 어려운 부분이다.","kid":"자주 보는 책을 볼 때마다 도서관까지 걸어갔다 오면 힘들지? 그래서 책상 위에 두고 봐. 대신 도서관 책이 새것으로 바뀌어도 네 책상 위 책은 옛날 그대로라, 언제 다시 빌려 올지를 미리 정해 둬야 해.","check":[{"q":"상품 값을 고쳤는데 화면에는 옛 값이 계속 보인다면 무엇 때문인가","at":"흔한 오해"},{"q":"사용자마다 다른 장바구니를 캐시할 때 무엇을 조심해야 하나","at":"주의사항"},{"q":"서버를 두 대로 늘렸더니 같은 값을 물어도 서버마다 다르게 답한다. 캐시를 어디에 둔 것인가","at":"구성"}],"myths":[{"wrong":"캐시를 붙이면 무조건 빨라진다","right":"같은 값을 다시 안 부르는 데이터라면 미스만 쌓인다. DB 조회 앞에 캐시 조회가 얹혀서 오히려 느려진다."},{"wrong":"캐시에 있는 값은 최신 값이다","right":"원본이 바뀌어도 캐시는 모른다. 만료되거나 지워질 때까지 옛 값을 그대로 준다."},{"wrong":"캐시도 데이터 저장소다","right":"언제 사라져도 되는 사본이다. 캐시에만 있는 값은 서버가 재시작되면 없어진다."}],"cases":[{"label":"로그인 세션","note":"요청마다 DB 를 보지 않고 캐시에서 세션을 꺼내 확인한다."},{"label":"목록 화면","note":"인기 상품처럼 모두에게 같은 목록은 한 번 만들어 잠시 재사용한다."},{"label":"외부 API 응답","note":"환율처럼 자주 안 바뀌는 값을 받아두고 정해진 시간 동안 그대로 쓴다."}],"dia":{"shape":"흐름","title":"같은 값을 두 번째로 부르면 무엇이 달라지나","rows":[{"who":"앱","what":"캐시에 있는지 먼저 본다"},{"who":"캐시","what":"없다. 이것을 미스라고 부른다"},{"who":"DB","what":"앱이 대신 물어본다. 여기가 느린 구간이다"},{"who":"앱","what":"받은 값을 캐시에 넣어둔다"}],"sum":"첫 사람만 DB 까지 가고 나머지는 캐시에서 돌아온다","loop":{"who":"다음 요청","what":"처음부터 다시. 이번엔 캐시에서 끝난다"}}},"arch--circuit-breaker":{"definition":"응답이 없는 서비스를 계속 부르면 기다리는 요청이 쌓이고, 결국 부르는 쪽까지 같이 죽는다. 그래서 실패가 일정 횟수를 넘으면 아예 부르지 않고 즉시 실패로 처리한다.","name":"Circuit :: 전기가 도는 한 바퀴\nBreaker :: 끊는 장치\n= 붙여 읽으면 \"도는 길을 끊는 장치\". 집 두꺼비집의 이름을 그대로 가져다 썼다","analogy":"집의 두꺼비집. 전선에 문제가 생기면 알아서 내려가서 집 전체가 타는 걸 막는다. 고쳤다고 확신하기 전에 한 번 올려보고, 또 튀면 다시 내린다.","example":"앱 화면에서 한 칸만 불러오지 못했다고 뜨고 나머지는 멀쩡히 도는 그 상태다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"상태가 셋이고, 그 셋을 돌아가며 오간다.\n\n- **닫힘** — 평소. 호출을 그냥 통과시키고 실패 횟수만 센다.\n- **열림** — 실패가 한도를 넘은 상태. 부르지 않고 즉시 실패로 답한다.\n- **반열림** — 열린 지 일정 시간이 지나면 한 건만 시험 삼아 통과시킨다. 성공하면 닫히고 또 실패하면 다시 열린다.\n\n반열림이 있어서, 회복됐는지 확인하려고 한꺼번에 폭주시키지 않아도 된다. 한 건으로 물어보고 그 답에 따라 닫거나 다시 연다.\n\n열림 상태에서 무엇을 돌려줄지 정해두는 것이 중요하다. 캐시에 있던 옛 값을 주거나, 기본값을 주거나, 사용자에게 솔직하게 알리거나. 이 대비책을 폴백이라고 한다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **추천 목록** — 추천 서비스가 죽으면 인기 상품 목록으로 대체한다. 화면은 계속 뜬다.\n- **외부 API** — 환율 API가 응답하지 않으면 마지막으로 받은 환율을 그대로 쓰고 표시만 바꾼다.\n- **부분 장애 표시** — 결제만 막히면 \"결제 점검 중\"으로 안내하고 장바구니는 계속 쓰게 둔다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **차단기가 장애를 고쳐준다** — 고치지 않는다. 번지는 것을 막을 뿐이고, 고장 난 서비스는 여전히 고장 나 있다.\n- **재시도를 하면 차단기는 필요 없다** — 반대다. 재시도만 하면 죽어가는 서비스에 부하를 더 얹어 더 빨리 죽인다. 재시도와 차단기는 같이 써야 한다.\n- **열림 상태는 오류다** — 설계대로 동작하는 정상 상태다. 오류로 취급해 알람을 끄면 정작 볼 신호를 잃는다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **폴백을 정해두지 않으면 절반만 쓴 것이다.** 열렸을 때 무엇을 돌려줄지가 사용자 경험을 정한다.\n- **한도를 너무 낮게 잡지 않는다.** 일시적인 지연에도 열려버리면 멀쩡한 기능이 자주 막힌다."}],"figure":"```도해\n흐름: 결제 서비스가 죽으면 주문 서비스는 무엇을 하나\n주문 서비스 :: 결제 서비스를 부른다. 응답이 없다\n차단기 :: 실패를 센다. 다섯 번째다\n차단기 :: 열린다. 이제부터 부르지 않는다\n주문 서비스 :: 즉시 \"결제 잠시 불가\" 로 답한다\n차단기 :: 30초 뒤 한 번만 시험 삼아 통과시킨다\n@ 차단기 :: 성공하면 닫고, 또 실패하면 다시 연다\n= 죽은 곳을 계속 두드리지 않는 것이 무너짐을 막는다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 아래 서비스 하나가 느려지면 어떻게 되나\n차단기 없이 || 차단기로\n대기 요청 :: 계속 쌓인다 || 즉시 실패 처리\n스레드 :: 전부 붙잡힌다 || 풀려 있다\n결과 :: 부르는 쪽도 죽음 || 그 기능만 막힘\n= 한 곳의 고장이 옆으로 번지지 않게 벽을 세우는 것이다\n```\n\n서비스 하나가 죽는 것보다 무서운 건 그 죽음이 번지는 것이다. 결제 서비스가 응답하지 않으면 주문 서비스의 스레드가 하나씩 거기 붙잡히고, 몇 분 안에 주문 서비스도 새 요청을 못 받는다. 주문이 멈추면 그 위의 화면 서비스도 멈춘다.\n\n차단기는 그 사슬을 끊는다. 결제가 안 되는 것과 사이트 전체가 안 되는 것은 전혀 다른 사고다."},"recap":"**\"번지기 전에 스스로 내려가는 그 두꺼비집\"** 이라고 읽으면 된다. 실패가 거듭되는 호출을 잠시 끊어 고장이 옆으로 번지는 것을 막는다. 닫힘, 열림, 반열림 세 상태를 오가며, 열렸을 때 무엇을 돌려줄지 정해두어야 제 값을 한다.","kid":"집에서 어느 방 전기가 잘못되면 두꺼비집이 탁 내려가지? 그 방만 껌껌해지고 나머지 방은 그대로 불이 켜져 있어. 좀 있다 한 번 올려 봤다가 또 툭 튀면 도로 내려 두는 거야.","check":[{"q":"결제 서비스 하나가 느려졌는데 사이트 전체가 멈추는 이유는","at":"해결하는 문제"},{"q":"재시도만 넣으면 왜 상황이 더 나빠지나","at":"흔한 오해"},{"q":"반열림 상태가 없으면 회복 확인을 어떻게 해야 하고, 그게 왜 위험한가","at":"작동 원리"}],"myths":[{"wrong":"차단기가 장애를 고쳐준다","right":"고치지 않는다. 번지는 것을 막을 뿐이고, 고장 난 서비스는 여전히 고장 나 있다."},{"wrong":"재시도를 하면 차단기는 필요 없다","right":"반대다. 재시도만 하면 죽어가는 서비스에 부하를 더 얹어 더 빨리 죽인다. 재시도와 차단기는 같이 써야 한다."},{"wrong":"열림 상태는 오류다","right":"설계대로 동작하는 정상 상태다. 오류로 취급해 알람을 끄면 정작 볼 신호를 잃는다."}],"cases":[{"label":"추천 목록","note":"추천 서비스가 죽으면 인기 상품 목록으로 대체한다. 화면은 계속 뜬다."},{"label":"외부 API","note":"환율 API가 응답하지 않으면 마지막으로 받은 환율을 그대로 쓰고 표시만 바꾼다."},{"label":"부분 장애 표시","note":"결제만 막히면 \"결제 점검 중\"으로 안내하고 장바구니는 계속 쓰게 둔다."}],"dia":{"shape":"흐름","title":"결제 서비스가 죽으면 주문 서비스는 무엇을 하나","rows":[{"who":"주문 서비스","what":"결제 서비스를 부른다. 응답이 없다"},{"who":"차단기","what":"실패를 센다. 다섯 번째다"},{"who":"차단기","what":"열린다. 이제부터 부르지 않는다"},{"who":"주문 서비스","what":"즉시 \"결제 잠시 불가\" 로 답한다"},{"who":"차단기","what":"30초 뒤 한 번만 시험 삼아 통과시킨다"}],"sum":"죽은 곳을 계속 두드리지 않는 것이 무너짐을 막는다","loop":{"who":"차단기","what":"성공하면 닫고, 또 실패하면 다시 연다"}}},"arch--clean-architecture":{"definition":"같은 구조가 이름을 여럿 달고 있다. 2005년의 헥사고날 아키텍처(육각형), 포트와 어댑터, 어니언 아키텍처(양파), 그리고 클린 아키텍처가 전부 같은 원리를 가리킨다. 공통점 하나는 **의존 방향을 뒤집는다**는 것이다.","name":"Clean :: 섞이지 않은\nArchitecture :: 짜임새\n= 붙여 읽으면 \"섞이지 않은 짜임새\". 업무 규칙 안에 기술 이야기가 섞여 들지 않는다는 뜻이다","analogy":"벽에 붙은 콘센트. 구멍 모양만 정해 두면 선풍기를 빼고 난로를 꽂아도 벽은 한 군데도 안 뜯는다.","example":"규칙 하나를 시험하려는데 진짜 DB 가 떠 있어야만 해서 한참 기다렸던 그 순간이다.","tryit":"지금 만드는 프로젝트에서 업무 규칙이 든 파일이 저장소 라이브러리를 직접 불러오는 줄이 있는지 찾아보라. 있으면 방향이 아직 안 뒤집힌 것이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"바깥과 만나는 자리를 **포트**로 열어 둔다. 포트는 기술을 가리지 않는 창구라, 누가 구현하든 상관하지 않는다. AWS 문서는 이것을 USB 포트에 빗댄다 — 어댑터만 맞으면 어떤 기기든 붙는다. 실제로 붙는 쪽이 **어댑터**다. 어댑터는 포트에 꽂혀 자료를 받거나 건네고, 그 기술에 맞게 모양을 바꿔 준다.\n\n포트도 두 갈래다. 안쪽은 들어오는 명령과 조회를 포트로 받고, 바깥 자원이 필요하면 역시 포트로 요청을 내보낸다. 한 포트에 어댑터를 여럿 꽂아도 포트와 안쪽은 그대로다. REST 어댑터가 붙어 있는 포트에 GraphQL 어댑터를 하나 더 꽂아도 기존 것은 아무 영향을 안 받는다.\n\n컴파일 시점과 실행 시점을 갈라 보는 것이 요령이다. 컴파일할 때 화면 쪽은 안쪽 인터페이스만 알고 인프라의 구체 타입은 모른다. 다만 실행할 때는 그 구체 타입이 있어야 하므로 시작 지점에서 인터페이스와 구현을 이어 준다. 그 이어 주는 한 자리를 조립 지점(composition root)이라 부른다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 언제 이 구조를 들이나","body":"```도해\n대조: 이 구조를 들일지 무엇으로 정하나\n들일 만한 곳 |=| 다시 따져 볼 곳\n바깥 붙는 곳 :: 여럿이고 바뀐다 || 하나로 고정이다\n업무 규칙 :: 두껍다 || 화면과 저장뿐\n어댑터 값 :: 유지비를 넘는다 || 층만 하나 는다\n= 바깥이 여럿이거나 앞으로 바뀔 때만 어댑터 값이 유지비를 넘는다\n```\n\nAWS 문서는 이 판단을 아주 또렷하게 적어 둔다. 구조를 꽂았다 뺐다 할 수 있게 만드는 어댑터 코드는 **입력원과 출력처가 여럿이거나 앞으로 바뀔 때만** 정당하다. 그렇지 않으면 어댑터는 그냥 관리할 층이 하나 더 생긴 것이고, 유지 부담만 는다. 포트와 어댑터가 층을 하나 더하니 지연이 늘 수도 있다고도 적는다.\n\n반대로 들일 만한 자리도 문서에 나열되어 있다. 완전히 시험 가능한 부품으로 떼어내고 싶을 때, 여러 종류의 클라이언트가 같은 업무 규칙을 쓸 때, 화면과 저장소가 주기적으로 기술을 갈아탈 때, 입력과 출력이 여럿이라 로직을 손볼수록 코드가 복잡해지고 늘리기 어려워질 때다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **저장소 갈아 끼우기** — 자체 DB 에서 다른 저장소로 옮길 때, 같은 인터페이스를 구현한 새 어댑터만 끼우고 업무 규칙은 건드리지 않는다.\n- **인프라 없이 시험하기** — 안쪽이 인프라를 안 부르니 가짜 구현을 넣고 규칙만 따로 돌린다. 환경을 통째로 띄울 일이 없다.\n- **입구가 여럿일 때** — 같은 업무 규칙을 REST 어댑터와 GraphQL 어댑터가 나란히 부른다. 포트와 안쪽은 그대로다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **클린 아키텍처를 쓰면 언제나 낫다** — AWS 문서는 어댑터 값이 유지비를 넘을 때만 정당하다고 적는다. 입출력이 하나로 고정된 작은 부품에서는 관리할 층만 하나 늘어난다.\n- **폴더를 도메인·응용·인프라로 나누면 그게 클린이다** — 이름이 아니라 의존 방향이 정한다. 안쪽 코드가 저장소 라이브러리를 직접 부르는 순간 그건 그냥 N층이다.\n- **이건 마이크로서비스용 구조다** — Microsoft 문서는 이 구조를 자잘하지 않은 **모놀리스**를 짜는 가장 알맞은 방식으로 적는다. 한 덩어리 안에서도 방향은 뒤집을 수 있다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **조립 지점 한 곳은 예외다.** 실행 시점에 구현을 이어 주려면 시작 코드가 인프라를 참조해야 한다. Microsoft 문서는 이 참조를 조립 지점 한 자리로만 제한하라고 적는다.\n- **층을 하나 더 두면 지연이 는다.** AWS 문서가 포트와 어댑터의 대가로 명시하는 항목이다. 응답 시간이 빡빡한 자리에서는 이 값을 재고 들어간다.\n- **어설픈 분리는 안 하느니만 못하다.** 같은 문서가 업무 규칙과 인프라를 가르는 일을 조심히 다루면 큰 이득이지만 그러지 못하면 문제가 더 풀기 어려워진다고 적는다."}],"figure":"```도해\n층: 의존은 어느 쪽으로만 흐르나\nUI 와 인프라 :: 화면·저장소·메일·바깥 호출. 안쪽이 정한 약속을 구현한다\n도메인 서비스 :: 업무 일을 엮는다. 안쪽 인터페이스만 쓴다\n개체와 인터페이스 :: 업무 규칙 그 자체와 약속. 아무 데도 안 기댄다\n= 바깥은 안쪽을 알고 안쪽은 바깥을 모른다. 그래서 바깥만 갈아 끼울 수 있다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 층을 위에서 아래로 쌓으면 무엇이 막히나\n전통 N층 || 클린\n의존 방향 :: 위에서 아래로 || 전부 안쪽으로\n업무 규칙 :: 저장소에 매인다 || 혼자 선다\n단위 시험 :: DB 를 띄워야 || 그냥 돌린다\n= 방향 하나를 뒤집으면 업무 규칙이 기술보다 오래 산다\n```\n\n전통적인 N층 구조에서 화면은 업무 층에 기대고, 업무 층은 자료 접근 층에 기댄다. Microsoft 문서는 이 배치의 단점을 한 문장으로 적는다 — 앱에서 가장 중요한 로직을 담은 업무 층이 자료 접근의 구현 세부와 데이터베이스의 존재에 매달리게 된다. 그래서 업무 규칙을 시험하려면 시험용 DB 부터 띄워야 한다.\n\n클린 아키텍처는 업무 모델을 한가운데 두고 그 의존을 **뒤집는다.** 인터페이스를 안쪽에서 정의하고 바깥이 그것을 구현하게 만드는 방식이다. 그러면 저장소를 자체 DB 에서 다른 것으로 바꾸는 일이 같은 인터페이스를 구현한 새 구현체를 끼우는 일로 줄고, 시험은 가짜 구현을 넣어 인프라 없이 돌아간다."},"recap":"**\"업무 규칙을 한가운데 두고 기술을 바깥에 꽂는 구조\"** 라고 읽으면 된다. 판단의 기준은 하나다. 바깥에 붙는 것이 여럿이거나 앞으로 바뀔 때만 어댑터를 만드는 값이 유지비를 넘는다.","kid":"벽에 있는 구멍은 안 바뀌지? 그래서 선풍기를 빼고 난로를 꽂아도 벽은 하나도 안 뜯어. 자주 바뀌는 건 꽂았다 뺐다 하게 두고 잘 안 바뀌는 건 벽 쪽에 붙여 둔 거야.","check":[{"q":"저장소를 다른 것으로 바꾸는데 업무 규칙 파일을 안 고쳐도 되는 까닭은 무엇인가","at":"그림"},{"q":"입출력이 하나로 고정된 작은 부품에 이 구조를 들이면 무엇이 손해인가","at":"비교"},{"q":"컴파일할 때는 몰랐던 구현체가 실행할 때는 어떻게 이어지나","at":"작동 원리"}],"myths":[{"wrong":"클린 아키텍처를 쓰면 언제나 낫다","right":"AWS 문서는 어댑터 값이 유지비를 넘을 때만 정당하다고 적는다. 입출력이 하나로 고정된 작은 부품에서는 관리할 층만 하나 늘어난다."},{"wrong":"폴더를 도메인·응용·인프라로 나누면 그게 클린이다","right":"이름이 아니라 의존 방향이 정한다. 안쪽 코드가 저장소 라이브러리를 직접 부르는 순간 그건 그냥 N층이다."},{"wrong":"이건 마이크로서비스용 구조다","right":"Microsoft 문서는 이 구조를 자잘하지 않은 **모놀리스**를 짜는 가장 알맞은 방식으로 적는다. 한 덩어리 안에서도 방향은 뒤집을 수 있다."}],"cases":[{"label":"저장소 갈아 끼우기","note":"자체 DB 에서 다른 저장소로 옮길 때, 같은 인터페이스를 구현한 새 어댑터만 끼우고 업무 규칙은 건드리지 않는다."},{"label":"인프라 없이 시험하기","note":"안쪽이 인프라를 안 부르니 가짜 구현을 넣고 규칙만 따로 돌린다. 환경을 통째로 띄울 일이 없다."},{"label":"입구가 여럿일 때","note":"같은 업무 규칙을 REST 어댑터와 GraphQL 어댑터가 나란히 부른다. 포트와 안쪽은 그대로다."}],"dia":{"shape":"층","title":"의존은 어느 쪽으로만 흐르나","rows":[{"who":"UI 와 인프라","what":"화면·저장소·메일·바깥 호출. 안쪽이 정한 약속을 구현한다"},{"who":"도메인 서비스","what":"업무 일을 엮는다. 안쪽 인터페이스만 쓴다"},{"who":"개체와 인터페이스","what":"업무 규칙 그 자체와 약속. 아무 데도 안 기댄다"}],"sum":"바깥은 안쪽을 알고 안쪽은 바깥을 모른다. 그래서 바깥만 갈아 끼울 수 있다"}},"arch--consistent-hashing":{"definition":"서버 개수로 나눈 나머지를 쓰면 서버 하나만 늘어도 거의 모든 키의 담당이 바뀐다. 이 방식은 서버와 키를 같은 원 위에 올려두고 시계 방향으로 담당을 정한다.","name":"Consistent :: 흔들리지 않는\nHashing :: 숫자로 바꿔 자리 정하기\n= 붙여 읽으면 \"자리를 흔들리지 않게 정하기\". 서버가 드나들어도 대부분의 키가 제자리에 남는다","analogy":"원형으로 늘어선 우편함. 새 우편함을 하나 끼워 넣어도 자리를 옮기는 건 그 앞 구간의 편지뿐이고 나머지는 그대로다.","example":"서버를 한 대 늘렸는데 아무도 로그아웃되지 않고 쓰던 그대로인 것이 자리를 덜 흔든 결과다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"원 위에 서버를 하나씩만 올리면 위치가 우연히 몰려서 담당 구간이 고르지 않다. 한 서버가 절반을 맡고 다른 서버는 거의 놀게 된다.\n\n그래서 서버 하나를 여러 개의 이름으로 원 위에 흩어 놓는다. 이렇게 복제한 점들을 가상 노드라고 한다. 개수를 늘릴수록 구간이 고르게 나뉘고, 서버가 빠질 때 그 몫도 남은 서버들에 골고루 흩어진다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교","body":"| | 나머지 연산 | Consistent Hashing |\n|---|---|---|\n| 담당 정하기 | 키를 서버 수로 나눈 나머지 | 원 위에서 시계 방향 |\n| 서버 추가 시 | 거의 모든 키가 이동 | 한 구간만 이동 |\n| 구현 | 한 줄 | 링과 가상 노드가 필요 |\n| 맞는 상황 | 서버 수가 고정된 곳 | 서버가 드나드는 곳 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **캐시 서버 증설** — 서버를 늘리면서 기존 캐시 대부분을 살려서, 증설 직후 원본이 몰매를 맞는 일을 피한다.\n- **분산 데이터베이스** — 어느 노드가 어느 키 구간을 맡을지 정하고, 노드를 더할 때 옮길 범위를 계산한다.\n- **노드 장애 대응** — 노드 하나가 빠지면 그 구간만 시계 방향 이웃이 넘겨받고 나머지 배치는 그대로 둔다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **이름처럼 특별한 해시 함수를 쓴다** — 해시 함수는 평범한 것을 쓴다. 달라지는 건 그 값을 서버에 어떻게 대응시키느냐다.\n- **키가 서버마다 고르게 나뉜다** — 원 위 위치가 몰리면 한 서버가 훨씬 넓은 구간을 맡는다. 가상 노드를 여러 개 두는 이유가 그 쏠림을 없애기 위해서다.\n- **서버가 바뀌어도 데이터는 안 옮겨진다** — 안 옮겨지는 게 아니라 적게 옮겨진다. 새로 들어온 서버가 맡을 구간의 키는 이동한다."}],"figure":"```도해\n흐름: 키 하나가 어느 서버로 갈지 어떻게 정해지나\n키 :: 해시를 구해 원 위의 한 점으로 삼는다\n원 :: 서버들도 각자 해시로 원 위에 놓여 있다\n탐색 :: 그 점에서 시계 방향으로 돈다\n탐색 :: 처음 만나는 서버가 담당이 된다\n결과 :: 배치가 그대로면 같은 키는 늘 같은 곳으로\n= 담당을 서버 개수가 아니라 원 위의 위치로 정한다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 서버를 3대에서 4대로 늘리면 캐시는 어떻게 되나\n나머지 연산 || 해시 링\n옮기는 키 :: 거의 전부 || 한 구간만\n캐시 적중 :: 바닥으로 || 대체로 유지\n증설 직후 :: 원본에 몰림 || 평소와 비슷\n= 서버 개수를 나눗셈에 쓰면 개수가 바뀔 때마다 전부 흔들린다\n```\n\n`key % 3` 으로 담당을 정하면 서버가 4대가 되는 순간 나머지 값이 전부 달라진다. 3으로 나눠 0이던 키가 4로 나누면 다른 값이 되고, 그렇게 거의 모든 키가 다른 서버로 옮겨간다. 캐시라면 전부 빈 상태가 되어 원본으로 요청이 한꺼번에 몰린다.\n\nConsistent Hashing은 서버 개수를 계산에 넣지 않는다. 서버도 키도 같은 원 위의 점이라, 서버 하나를 끼워 넣으면 그 서버가 맡게 되는 구간의 키만 움직인다."},"compose":{"label":"무엇으로 되어 있나","head":"🧱 구성","body":"```도해\n층: 일관된 해싱은 무엇 위에 무엇을 얹은 것인가\n가상 노드 :: 서버 하나를 여러 이름으로 흩어 놓은 겹\n서버 :: 실제로 데이터를 들고 있는 대수\n링 :: 해시 값의 끝과 시작을 이어 원으로 본 판\n해시 :: 이름이든 키든 같은 규칙으로 숫자로 바꾸는 계산\n= 서버 개수는 어디에도 들어가지 않는다. 담당을 정하는 것은 이 판 위의 위치뿐이다\n```"},"recap":"**\"하나 끼워 넣어도 앞 구간만 움직이는 그 원\"** 이라고 읽으면 된다. 서버와 키를 같은 원 위에 올려두고 시계 방향으로 담당을 정한다. 서버 개수를 계산에 넣지 않아서, 서버가 드나들어도 움직이는 키가 한 구간으로 묶인다.","kid":"우편함이 동그랗게 빙 둘러 놓여 있고, 편지는 제자리에서 시계 방향으로 걸어가다 처음 만나는 함에 넣기로 했어. 여기에 함을 하나 더 끼워 넣으면 바로 그 앞 구간 편지만 새 함으로 옮겨 가. 나머지 편지는 전부 원래 있던 함에 그대로 남아 있어.","check":[{"q":"캐시 서버를 3대에서 4대로 늘렸더니 원본 부하가 치솟았다면 담당을 어떻게 정하고 있던 것인가","at":"해결하는 문제"},{"q":"가상 노드를 두지 않으면 어떤 문제가 생기나","at":"작동 원리"},{"q":"노드 하나가 빠지면 그 노드가 맡던 키는 어디로 가나","at":"실제 사례"}],"myths":[{"wrong":"이름처럼 특별한 해시 함수를 쓴다","right":"해시 함수는 평범한 것을 쓴다. 달라지는 건 그 값을 서버에 어떻게 대응시키느냐다."},{"wrong":"키가 서버마다 고르게 나뉜다","right":"원 위 위치가 몰리면 한 서버가 훨씬 넓은 구간을 맡는다. 가상 노드를 여러 개 두는 이유가 그 쏠림을 없애기 위해서다."},{"wrong":"서버가 바뀌어도 데이터는 안 옮겨진다","right":"안 옮겨지는 게 아니라 적게 옮겨진다. 새로 들어온 서버가 맡을 구간의 키는 이동한다."}],"cases":[{"label":"캐시 서버 증설","note":"서버를 늘리면서 기존 캐시 대부분을 살려서, 증설 직후 원본이 몰매를 맞는 일을 피한다."},{"label":"분산 데이터베이스","note":"어느 노드가 어느 키 구간을 맡을지 정하고, 노드를 더할 때 옮길 범위를 계산한다."},{"label":"노드 장애 대응","note":"노드 하나가 빠지면 그 구간만 시계 방향 이웃이 넘겨받고 나머지 배치는 그대로 둔다."}],"dia":{"shape":"흐름","title":"키 하나가 어느 서버로 갈지 어떻게 정해지나","rows":[{"who":"키","what":"해시를 구해 원 위의 한 점으로 삼는다"},{"who":"원","what":"서버들도 각자 해시로 원 위에 놓여 있다"},{"who":"탐색","what":"그 점에서 시계 방향으로 돈다"},{"who":"탐색","what":"처음 만나는 서버가 담당이 된다"},{"who":"결과","what":"배치가 그대로면 같은 키는 늘 같은 곳으로"}],"sum":"담당을 서버 개수가 아니라 원 위의 위치로 정한다"}},"arch--ddd":{"definition":"서비스 경계를 어디에 그을지 정하는 기계적인 절차는 없다. Microsoft 의 아키텍처 문서는 이 일을 마이크로서비스의 가장 큰 난제 중 하나로 적고, 자료 접근이나 메시징 같은 가로층이 아니라 업무 능력을 축으로 나누라고 말한다. DDD 는 그 축을 어디서 찾는지에 대한 답이다.","name":"Domain :: 업무가 도는 영역\nDriven :: 그쪽이 이끄는\nDesign :: 설계\n= 붙여 읽으면 \"업무 영역이 이끄는 설계\". 기술이 아니라 업무가 경계를 정한다는 뜻이다","analogy":"교실 팻말. 같은 \"당번\" 이라는 말도 1학년 교실과 6학년 교실에서 하는 일이 달라서, 어느 교실 이야기인지부터 정해야 말이 통한다.","example":"\"주문\" 이라는 낱말 하나를 두고 영업팀과 물류팀이 30분째 서로 다른 이야기를 하고 있던 그 회의다.","tryit":"지금 팀의 회의록에서 같은 낱말이 두 가지 뜻으로 쓰인 자리를 하나만 찾아보라. 거기가 경계선이 지나가는 자리다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n흐름: 업무에서 서비스 경계를 어떻게 끌어내나\n업무 분석 :: 하는 일을 다 늘어놓고 서로 어떻게 얽히는지 그린다\n경계 컨텍스트 :: 한 모델이 통하는 범위로 자른다. 낱말 뜻은 그 안에서만 하나다\n전술 패턴 :: 그 안에 개체·애그리게이트·도메인 서비스를 놓는다\n서비스 식별 :: 그 결과를 서비스 하나하나로 옮긴다\n@ 다시 분석으로 :: 경계는 고정이 아니다. 업무가 자라면 다시 긋는다\n= 서비스를 먼저 정하고 업무를 끼우는 게 아니라, 업무를 갈라 두면 서비스가 따라 나온다\n```\n\nDDD 는 전략과 전술 두 단계로 나뉜다. 전략 단계에서 큰 구조를 정하고, 전술 단계에서 개체·애그리게이트·도메인 서비스 같은 패턴으로 모델 속을 채운다. 앞의 둘이 위 그림의 처음 두 마디이고, 이 순서를 뒤집으면 코드 패턴만 남고 경계는 안 생긴다.\n\n업무를 늘어놓을 때 하위 도메인은 셋으로 갈린다. **핵심**은 경쟁력이 걸린 곳이라 직접 정성껏 만들고, **지원**은 업무에 필요하지만 남과 다를 것이 없는 곳이고, **일반**은 업계가 이미 푼 문제라 기성품을 쓴다. 계정 관리나 콜센터가 대개 일반에 들어간다. 이 분류가 곧 어디에 사람을 넣을지의 답이다.\n\n경계 컨텍스트끼리 만나는 자리는 컨텍스트 맵으로 적어 둔다. 위쪽이 주는 것에 아래쪽이 기대고 둘이 계약을 맞추는 관계, 위쪽이 잘 정의된 창구를 공통 형식으로 열어 두는 관계, 아래쪽이 번역 층을 세워 자기 모델을 지키는 관계, 아예 안 엮고 각자 가는 관계가 있다. 낡은 시스템과 붙을 때 번역 층을 끼우는 이유는 그쪽 자료 모양이 이쪽 모델로 새어 들어오기 때문이다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 언제 이 설계를 들이나","body":"```도해\n대조: 어떤 업무에서 이 설계가 값을 하나\n들일 만한 곳 |=| 다시 따져 볼 곳\n업무 복잡도 :: 규칙이 얽혀 있다 || 화면과 저장뿐\n물어볼 사람 :: 업무 전문가 있다 || 팀 안에 없다\n기존 모듈 경계 :: 업무를 따라 나 있다 || 층으로 얽혀 있다\n= 얽힌 업무와 물어볼 사람, 이미 난 경계가 있을 때 값을 한다\n```\n\nAWS 문서는 하위 도메인으로 쪼개는 방식의 단점을 둘로 적는다. 서비스가 너무 많아져서 찾고 잇는 일이 어려워지는 것, 그리고 업무 하위 도메인을 알아내는 일 자체가 업무 전체를 깊이 알아야 가능하다는 것. 뒤의 것이 더 무섭다 — 물어볼 사람이 없으면 경계는 추측으로 그어지고, 추측으로 그은 경계는 반드시 다시 긋게 된다.\n\n반대로 잘 들어맞는 자리도 분명하다. AWS 문서는 이 방식이 **모듈 사이 경계가 이미 업무를 따라 나 있는 기존 시스템**에 알맞다고 적는다. 그런 경우에는 코드를 크게 다시 쓰지 않고 모듈을 다시 묶기만 해도 서비스가 나온다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **모놀리스 쪼개기** — 모듈 경계가 이미 업무를 따라 나 있으면 크게 다시 쓰지 않고 그대로 떼어내 서비스로 만든다.\n- **어디에 힘을 쓸지 고르기** — 핵심 하위 도메인만 직접 만들고, 계정이나 콜센터 같은 일반 영역은 기성품으로 덮는다.\n- **낡은 시스템과 붙는 자리** — 그쪽 자료 모양이 새 모델로 새어 들어오지 않게 사이에 번역 층을 하나 끼운다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **DDD 를 하면 어떤 프로젝트든 좋아진다** — 공짜로 얻는 것이 아니다. AWS 문서는 하위 도메인을 알아내는 일 자체가 업무 전체를 깊이 알아야 가능하다고 적는다.\n- **DDD 는 개체와 애그리게이트 같은 코드 패턴이다** — 그건 전술 쪽 절반이다. 먼저 오는 것은 업무를 갈라 경계를 긋는 전략 쪽이고, 그걸 건너뛰면 이름만 DDD 인 코드가 남는다.\n- **경계 컨텍스트는 한 번 정하면 끝이다** — Microsoft 문서는 경계 평가를 계속 이어지는 일로 적는다. 앱이 자라면 서비스 하나를 여럿으로 다시 가르게 된다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **팀 구조가 경계를 정하게 두지 마라.** 시스템은 만드는 조직의 소통 구조를 닮는다. 그대로 두면 조직도가 아키텍처가 되므로, 업무 분석으로 경계를 먼저 긋고 팀을 거기에 맞춘다.\n- **한 팀이 서로 무관한 경계를 여럿 안고 있거나, 한 경계를 여러 팀이 나눠 맡고 있으면** 경계와 팀 배치 중 하나가 틀린 것이다. Microsoft 문서는 그럴 때 둘 다 다시 보라고 적는다.\n- **너무 잘게 자르지 마라.** 서비스가 많아질수록 서로 찾고 잇는 비용이 는다. 잘게 자른 값이 그 비용을 넘는지 매번 따진다."}],"figure":"```도해\n층: 업무를 어디까지 좁혀야 서비스 하나가 나오나\n도메인 :: 회사가 하는 일 전체. 배송업이면 배송에 관한 전부\n하위 도메인 :: 핵심·지원·일반으로 갈린다. 어디에 힘을 쓸지 여기서 갈린다\n경계 컨텍스트 :: 한 모델과 한 낱말 뜻이 통하는 범위\n도메인 모델 :: 그 범위 안의 개체와 규칙. 서비스 하나의 속이 된다\n= 큰 업무를 뜻이 안 엇갈리는 범위까지 좁히면, 그 범위 하나가 서비스 하나가 된다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 시스템을 기술로 나누면 무엇이 어긋나나\n기술로 나누면 || 업무로 나누면\n나누는 축 :: 화면·로직·저장 || 배송·정산·계정\n같은 낱말 :: 팀마다 다른 뜻 || 경계 안에서 한 뜻\n기능 하나 추가 :: 세 층을 다 고친다 || 한 곳만 고친다\n= 업무가 경계를 정해야 한 가지 일이 한 자리에 모인다\n```\n\n경계를 대충 그으면 서비스 사이에 숨은 의존이 생기고, 서로 꽉 물려서 따로 배포할 수 없게 된다. Microsoft 문서는 그 상태를 \"구조 없는 설계\" 라고 부른다. 겉으로는 서비스가 여럿인데 하나를 고치면 나머지도 같이 고쳐야 하니, 쪼갠 값은 못 받고 쪼갠 대가만 치른다.\n\n낱말 뜻이 갈리는 것도 같은 뿌리다. 정비 쪽이 말하는 \"드론\" 은 정비 이력과 주행거리와 모델 번호를 안고 있고, 배차 쪽이 말하는 \"드론\" 은 지금 비었는지와 도착 예정 시각뿐이다. 하나의 모델로 둘을 다 담으면 모델은 부풀고, 고칠 때마다 두 팀이 합의해야 한다. DDD 는 같은 사물을 **경계마다 다른 모델로** 두는 것을 허락해서 이 매듭을 푼다."},"recap":"**\"낱말 뜻이 하나로 통하는 범위까지 업무를 좁히는 일\"** 이라고 읽으면 된다. 그 범위가 경계 컨텍스트이고, 경계 하나가 대체로 서비스 하나가 된다. 경계는 한 번 긋고 끝나는 선이 아니라 업무가 자라면 다시 긋는 선이다.","kid":"학교에서 \"당번\" 이라고만 하면 누구 얘긴지 모르지? 1학년 교실 당번이랑 6학년 교실 당번이 하는 일이 다르니까. 그래서 일을 나눌 때는 어느 교실 이야기인지부터 정하고, 그 교실 안에서만 통하는 말로 적어 두는 거야.","check":[{"q":"같은 \"고객\" 이라는 말이 팀마다 다른 뜻으로 쓰이면 무엇이 잘못되나","at":"해결하는 문제"},{"q":"하위 도메인을 핵심·지원·일반으로 갈라 놓으면 무엇을 정할 수 있나","at":"작동 원리"},{"q":"서비스를 너무 잘게 잘랐을 때 새로 생기는 문제는 무엇인가","at":"주의사항"}],"myths":[{"wrong":"DDD 를 하면 어떤 프로젝트든 좋아진다","right":"공짜로 얻는 것이 아니다. AWS 문서는 하위 도메인을 알아내는 일 자체가 업무 전체를 깊이 알아야 가능하다고 적는다."},{"wrong":"DDD 는 개체와 애그리게이트 같은 코드 패턴이다","right":"그건 전술 쪽 절반이다. 먼저 오는 것은 업무를 갈라 경계를 긋는 전략 쪽이고, 그걸 건너뛰면 이름만 DDD 인 코드가 남는다."},{"wrong":"경계 컨텍스트는 한 번 정하면 끝이다","right":"Microsoft 문서는 경계 평가를 계속 이어지는 일로 적는다. 앱이 자라면 서비스 하나를 여럿으로 다시 가르게 된다."}],"cases":[{"label":"모놀리스 쪼개기","note":"모듈 경계가 이미 업무를 따라 나 있으면 크게 다시 쓰지 않고 그대로 떼어내 서비스로 만든다."},{"label":"어디에 힘을 쓸지 고르기","note":"핵심 하위 도메인만 직접 만들고, 계정이나 콜센터 같은 일반 영역은 기성품으로 덮는다."},{"label":"낡은 시스템과 붙는 자리","note":"그쪽 자료 모양이 새 모델로 새어 들어오지 않게 사이에 번역 층을 하나 끼운다."}],"dia":{"shape":"층","title":"업무를 어디까지 좁혀야 서비스 하나가 나오나","rows":[{"who":"도메인","what":"회사가 하는 일 전체. 배송업이면 배송에 관한 전부"},{"who":"하위 도메인","what":"핵심·지원·일반으로 갈린다. 어디에 힘을 쓸지 여기서 갈린다"},{"who":"경계 컨텍스트","what":"한 모델과 한 낱말 뜻이 통하는 범위"},{"who":"도메인 모델","what":"그 범위 안의 개체와 규칙. 서비스 하나의 속이 된다"}],"sum":"큰 업무를 뜻이 안 엇갈리는 범위까지 좁히면, 그 범위 하나가 서비스 하나가 된다"}},"arch--dead-letter-queue":{"definition":"붙이는 방식은 제품마다 다르다. SQS 는 큐를 하나 더 만들어 실패 편지함으로 지정해 두고, 정한 횟수만큼 건네줬는데도 지워지지 않은 메시지를 그리로 옮긴다. 애저 Service Bus 는 아예 큐와 구독마다 하위 큐로 하나씩 달고 나온다 — 만들 필요도 없고 따로 지울 수도 없다. 어느 쪽이든 담기는 것은 실패했다는 기록이 아니라 실패한 일감 자체다. 원본이 통째로 그대로 들어와 앉는다.","name":"Dead :: 더는 못 가는\nLetter :: 편지 한 통\nQueue :: 줄 세워 둔 곳\n= 붙여 읽으면 \"더는 못 가는 편지를 줄 세워 둔 곳\". 이름이 곧 하는 일이다","analogy":"배달도 반송도 안 된 우편물을 버리지 않고 따로 쌓아 두는 우체국 뒷방이다.","example":"결제는 됐는데 영수증 메일만 끝내 안 오던 그 건이 대개 여기 쌓여 있다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"옮겨지는 사유는 한 가지가 아니다. Service Bus 문서는 시스템이 붙이는 사유를 표로 적어 두는데, 사유를 읽는 것이 원인 찾기의 첫 단추다.\n\n| 옮겨지는 사유 | 무슨 일이 있었나 |\n|---|---|\n| **받아 간 횟수 초과** | 정한 횟수만큼 건넸는데 끝내 지워지지 않았다 |\n| **유통기한 만료** | 정해 둔 시간 안에 아무도 처리하지 못했다 |\n| **크기 초과** | 머리말이 한도를 넘었다 |\n| **넘겨주기 한도 초과** | 큐를 타고 넘어간 횟수가 한도(4번)를 넘었다 |\n| **앱이 직접 밀어 넣음** | 형식이 깨진 것을 코드가 스스로 골라 버렸다 |\n\n마지막 줄이 중요하다. 실패 편지함은 횟수를 넘겨야만 채워지는 곳이 아니다. 받아 본 순간 \"이건 몇 번을 줘도 안 된다\" 고 아는 메시지는 앱이 직접 밀어 넣는 편이 낫다. Service Bus 문서는 그때 예외 이름과 스택 추적을 사유 칸에 함께 적어 두라고 권한다 — 나중에 그 칸만 읽고도 무슨 일이었는지 알게 하려는 것이다.\n\n되돌리는 길도 있다. 원인을 고친 뒤 SQS 는 redrive 로, Service Bus 는 포털 탐색기로 실패 줄의 메시지를 원래 줄에 다시 넣는다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **못 먹는 한 통 치우기** — 형식이 깨진 메시지가 줄 앞을 막을 때, 정한 횟수를 넘기면 자동으로 옆줄로 빠져 뒤가 다시 흐른다.\n- **경보 걸기** — 실패 줄의 개수가 0보다 커지는 순간을 경보로 잡는다. 실패가 조용히 쌓이는 것을 막는 가장 싼 방법이다.\n- **고치고 되돌리기** — 원인을 고친 뒤 실패 줄에 쌓인 것을 원래 줄로 되돌려 다시 처리한다. 잃어버린 주문을 되살리는 자리가 여기다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **실패 줄에 들어가면 그 건은 버려진 것이다** — 아니다. 내용도 사유도 그대로 남아 있고, 원인을 고친 뒤 원래 줄로 되돌려 다시 처리할 수 있다.\n- **만들어 두면 알아서 처리된다** — 아무도 안 본다. 개수 경보를 걸어 두지 않으면 실패가 몇 달치 조용히 쌓여 있다가 어느 날 보관 기간이 다해 사라진다.\n- **어느 큐에나 붙이면 좋다** — 순서가 곧 뜻인 줄에 붙이면 한 통이 빠지는 순간 뒤 작업의 전제가 어긋난다. AWS 문서는 영상 편집 지시 목록을 예로 들며 그런 자리에는 쓰지 말라고 적는다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **보관 기간을 원래 줄보다 길게 잡아라.** 표준 큐에서는 처음 줄에 선 시각이 그대로 따라온다. 원래 줄에서 하루를 보낸 메시지는 실패 줄의 나흘 중 사흘만 남는다.\n- **여기서 또 실패시킬 수는 없다.** Service Bus 의 실패 줄은 유통기한을 보지 않고, 여기서 다시 실패 줄로 보내는 일도 안 된다. 사람이 꺼내 가기 전에는 저절로 비워지지 않는다.\n- **횟수를 1로 두지 마라.** 한 번 삐끗한 것과 영영 안 되는 것이 구분되지 않는다. 재시도가 충분히 돌 만큼 넉넉히 잡으라고 AWS 문서가 적는다."}],"figure":"```도해\n흐름: 처리에 자꾸 실패하는 메시지는 어디로 가나\n보내는 쪽 :: 일감 하나를 줄에 넣는다\n원래 줄 :: 받아 갈 쪽에 건네준다\n받는 쪽 :: 처리에 실패해 지우지 못한다\n다시 주기 :: 잠긴 시간이 풀리면 또 건넨다\n실패 줄 :: 정한 횟수를 넘기면 이리로 옮긴다\n= 영원히 다시 주지 않는다. 정한 횟수를 넘기는 순간 옆줄로 치운다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 실패 편지함이 없으면 무슨 일이 생기나\n없으면 || 두면\n못 먹는 한 통 :: 줄 앞을 막는다 || 옆으로 치운다\n뒤에 선 일감 :: 같이 늦어진다 || 그대로 흐른다\n원인 찾기 :: 로그를 뒤진다 || 실물이 남아 있다\n= 실패를 없애는 자리가 아니라, 실패를 한곳에 모아 보이게 하는 자리다\n```\n\n한 통이 처리에 실패하면 큐는 그것을 다시 건넨다. 잠깐 삐끗한 것이면 두 번째나 세 번째에 넘어가지만, 형식이 깨졌다든가 없는 상품을 가리킨다든가 하는 고쳐질 리 없는 원인이면 같은 실패가 영영 되풀이된다. 그 사이 뒤에 선 일감이 함께 밀리고, 순서를 지키는 줄에서는 앞의 한 통이 뒤 전부를 통째로 막는다.\n\n실패 편지함은 그 되풀이를 끊는 자리다. SQS 는 redrive policy 의 `maxReceiveCount` 로, Service Bus 는 최대 배달 횟수(기본값 10)로 몇 번까지 줄지를 정한다. 그 수를 넘긴 메시지는 자동으로 옆줄로 옮겨지고, Service Bus 는 왜 옮겼는지를 메시지에 적어 둔다 — `MaxDeliveryCountExceeded`, `TTLExpiredException` 같은 값이다. 원본은 그대로 남아 있어서 열어 보고 고친 뒤 되돌릴 수 있다."},"recap":"**\"영영 안 되는 편지를 모아 두는 옆줄\"** 이라고 읽으면 된다. 정한 횟수를 넘기면 자동으로 옮겨지지만, 옮겨진 뒤에는 아무 일도 저절로 일어나지 않는다. 그래서 이 줄의 개수에 경보를 걸어 두는 것까지가 이 장치의 나머지 절반이다.","kid":"편지 한 통이 받는 사람이 없어서 배달도 안 되고 돌려보낼 수도 없으면, 우체국은 그걸 계속 들고 다니지 않고 뒷방에 따로 쌓아 둬. 그래야 뒤에 있는 멀쩡한 편지들이 안 밀리고 그날 다 나가. 대신 뒷방을 아무도 안 열어 보면 그 편지는 영영 그 자리에 있어.","check":[{"q":"형식이 깨진 한 통 때문에 뒤에 선 일감이 다 밀리는 이유는","at":"해결하는 문제"},{"q":"실패 줄에 쌓인 메시지가 소리 없이 사라지기도 하는 이유는","at":"주의사항"},{"q":"순서가 곧 뜻인 줄에 이걸 붙이면 왜 위험한가","at":"흔한 오해"}],"myths":[{"wrong":"실패 줄에 들어가면 그 건은 버려진 것이다","right":"아니다. 내용도 사유도 그대로 남아 있고, 원인을 고친 뒤 원래 줄로 되돌려 다시 처리할 수 있다."},{"wrong":"만들어 두면 알아서 처리된다","right":"아무도 안 본다. 개수 경보를 걸어 두지 않으면 실패가 몇 달치 조용히 쌓여 있다가 어느 날 보관 기간이 다해 사라진다."},{"wrong":"어느 큐에나 붙이면 좋다","right":"순서가 곧 뜻인 줄에 붙이면 한 통이 빠지는 순간 뒤 작업의 전제가 어긋난다. AWS 문서는 영상 편집 지시 목록을 예로 들며 그런 자리에는 쓰지 말라고 적는다."}],"cases":[{"label":"못 먹는 한 통 치우기","note":"형식이 깨진 메시지가 줄 앞을 막을 때, 정한 횟수를 넘기면 자동으로 옆줄로 빠져 뒤가 다시 흐른다."},{"label":"경보 걸기","note":"실패 줄의 개수가 0보다 커지는 순간을 경보로 잡는다. 실패가 조용히 쌓이는 것을 막는 가장 싼 방법이다."},{"label":"고치고 되돌리기","note":"원인을 고친 뒤 실패 줄에 쌓인 것을 원래 줄로 되돌려 다시 처리한다. 잃어버린 주문을 되살리는 자리가 여기다."}],"dia":{"shape":"흐름","title":"처리에 자꾸 실패하는 메시지는 어디로 가나","rows":[{"who":"보내는 쪽","what":"일감 하나를 줄에 넣는다"},{"who":"원래 줄","what":"받아 갈 쪽에 건네준다"},{"who":"받는 쪽","what":"처리에 실패해 지우지 못한다"},{"who":"다시 주기","what":"잠긴 시간이 풀리면 또 건넨다"},{"who":"실패 줄","what":"정한 횟수를 넘기면 이리로 옮긴다"}],"sum":"영원히 다시 주지 않는다. 정한 횟수를 넘기는 순간 옆줄로 치운다"}},"arch--distributed-lock":{"definition":"한 기계 안에서 쓰는 잠금은 그 기계 밖을 모른다. 그래서 같은 코드를 두 대에 올리는 순간 잠금은 아무것도 못 막는다. Redis 문서는 분산 락이 지켜야 할 것을 셋으로 줄인다 — 한 순간에 한 쪽만 잡는다(상호 배제), 잡은 쪽이 죽거나 끊겨도 언젠가는 다시 잡을 수 있다(교착 없음), 과반이 살아 있으면 잡고 푸는 일이 된다(장애 감내).","name":"Distributed :: 여러 대에 흩어진\nLock :: 한 번에 하나만\n= 붙여 읽으면 \"흩어져 있어도 한 번에 하나만\". 기계 안의 잠금을 밖으로 꺼낸 것이다","analogy":"수영장 옷장 열쇠. 한 사람이 가져가면 아무도 못 열고, 문 닫을 시간이 되면 저절로 풀린다.","example":"재고가 하나 남은 상품을 두 사람이 동시에 담았는데 둘 다 결제가 끝나 버린 그 순간이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"한 대짜리 저장소로 만든다면 이렇게 된다. `SET 자원이름 무작위값 NX PX 30000` — 키가 없을 때만 만들고(NX), 30초 뒤에 저절로 지워지게 한다(PX). 이 만료 시간이 곧 자동 반납이다. 잡은 쪽이 통째로 죽어도 30초 뒤에는 자물쇠가 풀리므로 자원이 영원히 잠기지 않는다.\n\n값이 무작위여야 하는 이유는 반납 때문이다. 그냥 지우는 명령을 쓰면, 내 작업이 만료 시간을 넘겨 늘어진 사이에 다른 쪽이 새로 건 자물쇠를 내가 지워 버릴 수 있다. 그래서 \"값이 내가 넣은 것과 같을 때만 지운다\" 를 한 덩어리로 실행한다. 자물쇠마다 서명이 붙어 있는 셈이다.\n\n만료 시간은 자동 반납 시간인 동시에 **작업에 주어진 시간**이다. 상호 배제는 잡은 쪽이 그 시간 안에 일을 끝낼 때만 참이다. 시간이 지나면 자물쇠는 내 손을 떠나고, 내가 아직 일하는 중이어도 다른 쪽이 들어온다.\n\n여러 저장소로 흩어 놓는 방식(Redlock)은 여기서 한 걸음 더 간다. 서로 독립인 노드 다섯 대에 같은 열쇠를 동시에 걸어 보고, 과반인 세 대 이상에서 성공했고 걸리는 데 쓴 시간이 만료 시간보다 짧을 때만 잡은 것으로 친다. 실패하면 부분적으로 잡은 것까지 전부 즉시 푼다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교","body":"이 자물쇠를 고르기 전에 물어야 할 것은 하나다. 겹쳐 잡히면 무엇이 틀어지나.\n\n| 걸려 있는 것 | 겹쳐 잡혔을 때 | 어디까지 하나 |\n|---|---|---|\n| **효율** | 같은 일이 두 번 돌 뿐이다 | 저장소 한 대짜리 잠금이면 충분하다 |\n| **정확성** | 돈이나 재고가 되돌릴 수 없이 틀어진다 | 과반 방식을 쓰고 펜싱 토큰까지 둔다 |\n\nRedis 문서가 갈라 놓는 자리도 여기다. 장애 같은 특수한 상황에서 잠깐 둘이 동시에 잡는 일이 괜찮다면 복제 기반의 간단한 방식으로 충분하고, 그게 아니라면 더 조심스러운 방식을 쓰라고 한다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **재고 차감** — 마지막 하나 남은 상품에 두 주문이 동시에 들어와도, 자물쇠를 잡은 쪽만 재고를 깎고 나머지는 품절 응답을 받는다.\n- **주기 작업 한 번만 돌리기** — 여러 대에 올라간 같은 배치가 같은 이름의 자물쇠를 두고 경쟁하고, 잡은 한 대만 실제로 돈다.\n- **리더 뽑기** — Azure 의 리더 선출 예제는 저장소 blob 에 임차를 걸어 분산 뮤텍스를 만든다. 임차를 먼저 얻은 쪽이 대표가 되고, 갱신에 실패하면 임차가 풀려 다음 대표에게 넘어간다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **자물쇠를 잡았으면 일이 끝날 때까지 내 것이다** — 만료 시간이 지나면 내 손을 떠난다. 잡은 프로세스가 살아 있는 동안 계속 잡고 있다고 가정하면 안 된다고 Redis 문서가 못 박는다.\n- **복제본을 하나 붙여 두면 잠금도 안전해진다** — 복제는 비동기다. 주 노드가 쓰기를 넘기기 전에 죽고 복제본이 승격되면, 같은 자원에 두 쪽이 동시에 자물쇠를 잡는다.\n- **여럿이 같은 자원을 건드리면 일단 분산 락을 걸면 된다** — 자물쇠를 파는 쪽이 단일 장애점이 되고, 망이 끊기면 만료 시간만큼 아무도 못 들어간다. 데이터베이스 한 줄만 지키면 되는 일은 그 안의 낙관적·비관적 잠금이 훨씬 가볍다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **만료 시간을 작업 시간보다 넉넉히 잡는다.** 상호 배제는 잡은 쪽이 만료 전에 끝낼 때만 성립한다. 길어질 것 같으면 도중에 만료를 연장하되, 연장 횟수에는 상한을 둔다.\n- **지울 때는 값을 대조해서 지운다.** 그냥 지우면 남이 새로 건 자물쇠를 지운다.\n- **오래 걸리는 작업이면 펜싱 토큰을 붙인다.** 잠금을 잡을 때마다 커지는 번호를 함께 넘겨서, 늦게 깨어난 옛 주인의 쓰기를 받는 쪽에서 거절하게 만든다.\n- **시계에 기대고 있다는 걸 잊지 마라.** 만료는 벽시계로 재므로, 서버 시각이 갑자기 어긋나면 둘이 동시에 잡는 일이 생길 수 있다."}],"figure":"```도해\n흐름: 여러 대가 같은 일에 달려들면 무엇이 걸러지나\n동시 시도 :: 여러 대가 같은 열쇠 이름으로 잠금을 건다\n선착순 :: 없을 때만 만드는 조건이라 딱 한 대만 성공한다\n나머지 :: 실패한 쪽은 잠깐 쉬었다가 다시 시도한다\n작업 :: 성공한 한 대만 공유 자원을 건드린다\n반납 :: 값이 자기 것과 같을 때만 열쇠를 지운다\n@ 다음 차례로 :: 열쇠가 사라지면 기다리던 쪽이 다시 건다\n= 여럿이 달려들어도 안으로 들어가는 것은 언제나 하나뿐이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 기계 한 대 안의 잠금으로는 왜 모자라나\n한 대 안의 잠금 || 분산 락\n잠금이 사는 곳 :: 그 기계 안 || 밖에 하나만\n막는 범위 :: 같은 기계끼리 || 모든 기계 사이\n두 대로 늘리면 :: 둘 다 통과한다 || 하나만 통과한다\n= 잠금이 지켜야 할 것은 기계가 아니라 자원 하나다\n```\n\n한 대로 돌 때는 잠금이 잘 돌아간다. 대를 늘리는 순간 조용히 무너진다. 각 기계가 자기 안에서만 순서를 지키기 때문에, 두 대는 서로를 모른 채 같은 재고를 동시에 깎는다. 코드는 그대로인데 결과만 틀어지니 재현도 어렵다.\n\n분산 락은 잠금을 기계 밖 한 곳으로 옮긴다. 모두가 같은 이름의 열쇠를 같은 곳에 걸러 가고, 거기서 선착순이 갈린다. 지켜야 할 것이 기계가 아니라 자원 하나라는 사실을 자리로 옮겨 놓은 것이다."},"recap":"**\"기계가 달라도 한 번에 하나만 들여보내는 걸쇠\"** 라고 읽으면 된다. 이 걸쇠에는 기한이 붙어 있어서, 잡은 쪽이 그 기한 안에 일을 끝낼 때만 \"하나만 들어간다\" 는 말이 참이 된다. 그래서 고를 때 물어야 할 것은 겹쳐 잡히면 무엇이 틀어지는가 하나다.","kid":"수영장 옷장은 열쇠가 하나뿐이라, 먼저 집은 사람이 다 쓸 때까지 다른 사람은 못 열지? 그리고 그 사람이 열쇠를 안 돌려주고 집에 가 버려도 문 닫을 시간이 되면 아저씨가 열어 주니까, 다음 사람이 쓸 수 있어.","check":[{"q":"자물쇠를 잡은 채로 그 기계가 통째로 죽으면 다음 사람은 어떻게 들어가나","at":"작동 원리"},{"q":"반납할 때 값을 대조하지 않고 그냥 지우면 무엇이 잘못될 수 있나","at":"주의사항"},{"q":"복제본을 하나 더 붙여 두는 것으로는 왜 상호 배제가 안 되나","at":"흔한 오해"}],"myths":[{"wrong":"자물쇠를 잡았으면 일이 끝날 때까지 내 것이다","right":"만료 시간이 지나면 내 손을 떠난다. 잡은 프로세스가 살아 있는 동안 계속 잡고 있다고 가정하면 안 된다고 Redis 문서가 못 박는다."},{"wrong":"복제본을 하나 붙여 두면 잠금도 안전해진다","right":"복제는 비동기다. 주 노드가 쓰기를 넘기기 전에 죽고 복제본이 승격되면, 같은 자원에 두 쪽이 동시에 자물쇠를 잡는다."},{"wrong":"여럿이 같은 자원을 건드리면 일단 분산 락을 걸면 된다","right":"자물쇠를 파는 쪽이 단일 장애점이 되고, 망이 끊기면 만료 시간만큼 아무도 못 들어간다. 데이터베이스 한 줄만 지키면 되는 일은 그 안의 낙관적·비관적 잠금이 훨씬 가볍다."}],"cases":[{"label":"재고 차감","note":"마지막 하나 남은 상품에 두 주문이 동시에 들어와도, 자물쇠를 잡은 쪽만 재고를 깎고 나머지는 품절 응답을 받는다."},{"label":"주기 작업 한 번만 돌리기","note":"여러 대에 올라간 같은 배치가 같은 이름의 자물쇠를 두고 경쟁하고, 잡은 한 대만 실제로 돈다."},{"label":"리더 뽑기","note":"Azure 의 리더 선출 예제는 저장소 blob 에 임차를 걸어 분산 뮤텍스를 만든다. 임차를 먼저 얻은 쪽이 대표가 되고, 갱신에 실패하면 임차가 풀려 다음 대표에게 넘어간다."}],"dia":{"shape":"흐름","title":"여러 대가 같은 일에 달려들면 무엇이 걸러지나","rows":[{"who":"동시 시도","what":"여러 대가 같은 열쇠 이름으로 잠금을 건다"},{"who":"선착순","what":"없을 때만 만드는 조건이라 딱 한 대만 성공한다"},{"who":"나머지","what":"실패한 쪽은 잠깐 쉬었다가 다시 시도한다"},{"who":"작업","what":"성공한 한 대만 공유 자원을 건드린다"},{"who":"반납","what":"값이 자기 것과 같을 때만 열쇠를 지운다"}],"sum":"여럿이 달려들어도 안으로 들어가는 것은 언제나 하나뿐이다","loop":{"who":"다음 차례로","what":"열쇠가 사라지면 기다리던 쪽이 다시 건다"}}},"arch--error-budget":{"definition":"먼저 분기별 SLO(지키기로 정한 목표치)를 정한다. 100% 와 그 목표치 사이에 남는 틈이 그 분기에 쓸 수 있는 \"불안정\" 의 예산이다. Google SRE 책은 이 잔액이 남아 있는 동안에는 새 릴리스를 계속 내보내고, 잔액을 다 쓰면 릴리스를 잠시 멈추고 시험과 개발에 인력을 더 넣는다고 적는다.","name":"Error :: 못 지킨 몫\nBudget :: 미리 떼어 둔 몫\n= 붙여 읽으면 \"실패해도 되는 몫을 미리 떼어 둔 것\". 다 쓰면 더 못 쓴다","analogy":"한 달 용돈. 남아 있는 동안에는 마음대로 쓰고, 바닥나면 다음 달까지 지갑을 닫는다.","example":"새 기능을 내보내려는데 \"이번 달 장애가 많았으니 배포는 다음 주에 하자\" 는 말이 나오는 그 순간이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n흐름: 에러 예산은 한 분기를 어떻게 도나\n목표 정하기 :: 분기 SLO 를 정하고 100% 에서 뺀다\n잔액 재기 :: 실제 가동률을 재서 남은 몫을 본다\n쓰기 :: 잔액이 남아 있으면 새 릴리스를 내보낸다\n깎이기 :: 계획에 없던 장애도 같은 잔액에서 빠진다\n바닥 :: 다 쓰면 릴리스를 멈추고 안정화에 인력을 넣는다\n@ 다음 분기로 :: 예산이 다시 채워지면 처음으로 돌아간다\n= 잔액이 있으면 내보내고 없으면 고친다. 그 판정을 사람이 아니라 숫자가 한다\n```\n\n여기서 놓치기 쉬운 자리는 \"깎이기\" 다. 예산을 깎는 것은 장애만이 아니다. 계획해서 내보낸 릴리스가 만들어 낸 나쁜 응답도 같은 잔액에서 빠진다. 계획한 것과 계획에 없던 것이 한 지갑을 쓴다는 점이 이 장치의 핵심이다 — 그래서 배포를 많이 할수록 사고에 쓸 몫이 줄어들고, 그 계산이 배포 속도를 스스로 조인다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **배포 정책** — 잔액이 남아 있으면 릴리스를 계속 내보내고, 다 쓰면 잠시 멈춘 뒤 시험과 안정화에 사람을 붙인다.\n- **투자 방향 결정** — 실패가 예산 안에 있으면 기능에 투자하고, 예산을 다 먹으면 신뢰성에 투자한다. 이미 목표를 지키고 있는 곳에 안정화 비용을 더 쓰는 일을 막아 준다.\n- **혼돈 공학 실험 범위** — 일부러 장애를 넣어 보는 실험도 남은 예산 안에서만 한다. 잔액이 곧 실험에 쓸 수 있는 크기다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **잔액이 남았으면 안 쓰고 아끼는 게 안전하다** — 남긴 잔액은 저축이 아니라 못 쓴 기회다. 기능을 더 넣거나, 기술 부채를 정리하거나, 운영비를 줄이는 데 쓸 수 있었던 몫이 그냥 없어진 것이다.\n- **예산은 장애가 났을 때만 깎인다** — 계획해서 내보낸 릴리스가 만든 실패도 같은 잔액에서 빠진다. 장애와 배포가 한 지갑을 쓴다.\n- **목표를 높게 걸수록 예산이 빡빡해져서 더 안전하다** — 신뢰성은 한 칸 올릴 때마다 비용이 앞 칸의 100배까지 든다. 사용자가 못 느끼는 자리를 올리려고 기능과 부채 정리를 통째로 내주게 된다."}],"figure":"```도해\n층: 한 달을 100 으로 놓으면 어디까지가 무엇인가\n100% :: 실패가 하나도 없는 달. 실제로는 오지 않는다\nSLO 99.9% :: 여기까지는 지키기로 약속한 선\n남은 0.1% :: 이 틈이 예산이다. 시간으로는 43분\n= 예산은 따로 주어지는 것이 아니라, 100% 에서 목표를 뺀 나머지다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 배포 시점을 정할 때 이 잔액이 있고 없고가 무엇을 바꾸나\n예산 없이 || 예산으로\n두 팀의 목표 :: 서로 반대다 || 하나로 같다\n배포 중단 :: 힘센 쪽이 이긴다 || 잔액이 정한다\n장애 회고 :: 책임을 가린다 || 잔액을 본다\n= 두 팀에게 같은 지갑을 쥐여 주면, 다툴 일이 계산할 일이 된다\n```\n\n기능을 내보내는 쪽은 빨리 내보내고 싶고, 안정을 맡은 쪽은 그만 내보내고 싶다. 목표가 정반대라 회의는 매번 힘겨루기가 된다. 게다가 \"얼마나 안정적이어야 충분한가\" 에 답이 없으니 안정 쪽 요구에는 끝이 없다.\n\n에러 예산은 두 팀에게 같은 숫자 하나를 준다. SRE 책은 이것을 두고, 개발과 운영이 혁신과 신뢰성 사이의 균형점을 함께 찾게 만드는 공통의 유인이라고 적는다. 잔액이 남았으면 내보내고, 바닥났으면 고친다. 판정을 목소리 큰 사람이 아니라 잔액이 한다."},"recap":"**\"실패해도 되는 만큼을 미리 떼어 둔 잔액\"** 이라고 읽으면 된다. 잔액은 계획한 배포와 계획에 없던 장애가 같이 쓰는 한 지갑이고, 바닥나면 다음 일은 배포가 아니라 안정화가 된다. 남기는 것도 잘한 일이 아니다 — 못 쓴 잔액은 넣지 못한 기능이다.","kid":"한 달 용돈이 정해져 있으면 남아 있는 동안에는 사고 싶은 걸 사도 되지만 다 쓰면 다음 달까지 참아야 하지? 실수해도 되는 횟수를 이렇게 미리 정해 두면, 새로 해 봐도 되는 날인지 조심할 날인지를 다투지 않고 알 수 있어.","check":[{"q":"큰 장애가 한 번도 없었는데 잔액을 다 썼다면 그동안 무슨 일이 있었던 건가","at":"작동 원리"},{"q":"잔액이 남았는데도 안 쓰고 아끼면 무엇을 잃나","at":"흔한 오해"},{"q":"두 팀이 배포 시점을 놓고 다투지 않게 되는 이유는 무엇인가","at":"해결하는 문제"}],"myths":[{"wrong":"잔액이 남았으면 안 쓰고 아끼는 게 안전하다","right":"남긴 잔액은 저축이 아니라 못 쓴 기회다. 기능을 더 넣거나, 기술 부채를 정리하거나, 운영비를 줄이는 데 쓸 수 있었던 몫이 그냥 없어진 것이다."},{"wrong":"예산은 장애가 났을 때만 깎인다","right":"계획해서 내보낸 릴리스가 만든 실패도 같은 잔액에서 빠진다. 장애와 배포가 한 지갑을 쓴다."},{"wrong":"목표를 높게 걸수록 예산이 빡빡해져서 더 안전하다","right":"신뢰성은 한 칸 올릴 때마다 비용이 앞 칸의 100배까지 든다. 사용자가 못 느끼는 자리를 올리려고 기능과 부채 정리를 통째로 내주게 된다."}],"cases":[{"label":"배포 정책","note":"잔액이 남아 있으면 릴리스를 계속 내보내고, 다 쓰면 잠시 멈춘 뒤 시험과 안정화에 사람을 붙인다."},{"label":"투자 방향 결정","note":"실패가 예산 안에 있으면 기능에 투자하고, 예산을 다 먹으면 신뢰성에 투자한다. 이미 목표를 지키고 있는 곳에 안정화 비용을 더 쓰는 일을 막아 준다."},{"label":"혼돈 공학 실험 범위","note":"일부러 장애를 넣어 보는 실험도 남은 예산 안에서만 한다. 잔액이 곧 실험에 쓸 수 있는 크기다."}],"dia":{"shape":"층","title":"한 달을 100 으로 놓으면 어디까지가 무엇인가","rows":[{"who":"100%","what":"실패가 하나도 없는 달. 실제로는 오지 않는다"},{"who":"SLO 99.9%","what":"여기까지는 지키기로 약속한 선"},{"who":"남은 0.1%","what":"이 틈이 예산이다. 시간으로는 43분"}],"sum":"예산은 따로 주어지는 것이 아니라, 100% 에서 목표를 뺀 나머지다"}},"arch--event-sourcing":{"definition":"보통은 값을 읽어서 고치고 덮어쓴다. 그러면 남는 것은 결과뿐이고, 거기까지 오는 동안 무슨 일이 있었는지는 따로 기록을 붙이지 않으면 사라진다. 이벤트 소싱은 순서를 뒤집는다. 일어난 일을 덧붙이기만 하는 저장소에 쌓아 두고, 지금 값은 그 기록을 재생해서 만들어 낸다.","name":"Event :: 일어난 일\nSourcing :: 원천으로 삼기\n= 붙여 읽으면 \"일어난 일을 원천으로 삼기\". 지금 값이 아니라 거기까지 온 일들이 원본이다","analogy":"잔액을 고쳐 적지 않고 입금과 출금을 한 줄씩 아래로 붙여 나가는 통장 거래 내역.","example":"주문을 취소해도 주문 기록이 사라지지 않고 '취소됨' 한 줄이 아래에 덧붙는 그 화면이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n흐름: 지금 남은 좌석 수를 어떻게 알아내나\n명령 :: \"두 자리 예약해\" 가 들어온다\n불러오기 :: 그 개체의 사건을 처음부터 읽는다\n재생 :: 차례로 적용해 현재 상태를 만든다\n판단 :: 남은 자리가 있는지 따진다\n붙이기 :: 새 사건을 끝에 덧붙인다\n@ 다음 명령도 :: 읽고 재생해서 판단하기를 되풀이한다\n= 지금 상태는 저장된 것이 아니라, 사건을 되짚어 그때그때 만들어 내는 것이다\n```\n\n사건을 재생해 상태를 되살리는 이 과정을 재수화라고 부른다. 그런데 한 개체의 사건 줄이 길어지면 매번 처음부터 재생하는 값이 비싸진다. 그래서 사건 몇 개마다 그 시점의 상태를 통째로 저장해 두는 스냅숏을 쓴다. 되살릴 때는 가장 최근 스냅숏을 불러오고 그 뒤의 사건만 재생한다. 스냅숏은 최적화일 뿐 원본이 아니어서, 언제든 사건에서 다시 만들어 낼 수 있다.\n\n조회는 다른 길로 간다. 사건을 읽어 재생하는 일은 비싸므로, 화면에 낼 모양대로 미리 만들어 둔 조회용 표를 따로 둔다. 사건 처리기가 새 사건을 받을 때마다 그 표를 고친다.\n\n같은 개체에 두 명령이 동시에 들어오면 둘 다 같은 상태를 보고 판단해 버릴 수 있다. 사건 저장소는 낙관적 동시성 제어로 이를 막는다. 읽은 뒤에 그 줄이 바뀌었으면 덧붙이기를 거절하고, 거절당한 쪽은 다시 읽어 판단한 뒤 재시도한다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **좌석과 잔액** — 남은 수를 고쳐 쓰는 대신 예약과 취소를 쌓아 두고 그 자리에서 세면, 마감 직전에 몰려도 같은 줄을 두고 다투지 않는다.\n- **감사 추적** — 누가 언제 무엇을 바꿨는지가 저장 방식 자체에 남아서, 별도 기록 장치 없이도 되짚고 디버깅할 수 있다.\n- **조회용 표 새로 만들기** — 화면이 바뀌어 다른 모양의 표가 필요해지면, 쌓아 둔 사건을 처음부터 재생해 새 표를 만들어 낸다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **이벤트 소싱을 쓰면 어떤 시스템이든 더 낫다** — Microsoft 문서는 이 패턴을 대가가 큰 복잡한 패턴이라 못 박고, 대부분의 시스템과 시스템의 대부분에는 전통적인 방식으로 충분하다고 적는다. 감사와 되감기가 그 복잡함을 갚아 주는 자리에만 고른다.\n- **메시지 브로커가 곧 사건 저장소다** — 아니다. Microsoft 문서는 둘을 혼동하지 말라고 적는다. 브로커에는 대개 개체별 사건 줄 조회와 낙관적 동시성 제어가 없어서, 사건을 퍼뜨리는 층으로는 좋아도 원본 저장소를 대신하지 못한다.\n- **잘못 들어간 사건은 지우면 된다** — 저장소는 덧붙이기만 한다. 되돌리려면 반대 효과를 내는 보상 사건을 하나 더 붙여야 하고, 버그가 만든 사건도 원본에는 그대로 남는다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **사건은 결과가 아니라 의도로 적어라.** \"남은 좌석이 42가 됨\" 보다 \"두 자리를 예약함\" 이 낫다. 결과만 적은 사건은 뜻 없는 변경 기록이 되고, 나중에 새 조회용 표를 만들 여지도 사라진다.\n- **개인정보와 정면으로 부딪친다.** 지우라는 요구와 지우지 않는 저장 방식이 충돌한다. 개인정보를 사건 밖에 두고 식별자로만 가리키게 하거나, 사람마다 다른 열쇠로 잠가 두고 열쇠를 버리는 방법을 처음부터 설계에 넣는다.\n- **사건의 모양이 바뀔 때를 미리 정하라.** 저장된 사건은 고치지 않으므로, 모르는 항목을 무시하는 읽기·판 번호 붙이기·옛 판을 읽는 순간 새 판으로 올리는 변환 중에서 골라 둔다.\n- **조회 방법이 따로 없다.** 사건을 SQL처럼 두루 뒤지는 표준 수단이 없다. 식별자로 그 줄을 통째로 읽어 재생하는 것이 기본이고, 그래서 조회용 표가 사실상 필수가 된다."}],"figure":"```도해\n대조: 지금 값을 고치는 것과 일어난 일을 쌓는 것은 무엇이 다른가\n덮어쓰기 |=| 쌓아 두기\n저장 :: 지금 값만 남는다 || 있었던 일이 남는다\n과거 :: 물어볼 수 없다 || 그때로 되감는다\n현재 값 :: 바로 읽는다 || 재생해서 만든다\n= 값을 지우고 고치는 대신, 일어난 일을 붙여 두고 지금 값은 거기서 만들어 낸다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 지금 값만 들고 있으면 무엇을 잃나\n현재 값만 || 일어난 일까지\n동시 수정 :: 같은 줄을 잠근다 || 뒤에 붙이면 끝\n지난 일 :: 남아 있지 않다 || 전부 남아 있다\n이유 :: 왜 그리 됐는지 모름 || 의도까지 남는다\n= 지금 값은 결과다. 그 결과에 이른 일들은 적어 두지 않으면 사라진다\n```\n\n값을 덮어쓰는 방식은 대부분의 경우에 간단하고 빠르지만, 부하가 큰 곳에서 두 가지가 걸린다. 하나는 쓰기 다툼이다. 갱신은 읽고 고쳐 쓰는 과정이라 같은 줄에 잠금이 걸리고, 동시에 몰리면 그 자리가 병목이 된다. 다른 하나는 감사다. 덮어쓰는 방식은 최신 값만 남기므로, 따로 기록 장치를 붙이지 않으면 이력이 통째로 사라진다.\n\n이벤트 소싱은 갱신을 없애고 덧붙이기만 남긴다. 잠그고 고칠 것이 없으니 쓰기 처리량이 올라가고, 덧붙이기만 하는 저장소 자체가 감사 기록이 된다. 어느 시점의 상태든 그때까지의 사건을 재생하면 다시 만들어 낼 수 있다."},"recap":"**\"지금 값을 적는 대신 일어난 일을 쌓아 두는 방식\"** 이라고 읽으면 된다. 덧붙이기만 하므로 쓰기 다툼이 줄고 감사 기록이 공짜로 따라오지만, 지금 값을 알려면 재생해야 하고 조회용 표는 늦게 따라온다. 이력과 되감기가 그 복잡함을 갚아 주는 부분에만 골라서 적용한다.","kid":"용돈 기입장 알지? 남은 돈을 지우고 새로 쓰는 게 아니라, 받은 것과 쓴 것을 한 줄씩 아래에 붙여 나가잖아. 지금 얼마 남았는지 궁금하면 그 줄들을 처음부터 죽 더해서 알아내는 거야.","check":[{"q":"마감 직전에 예약이 몰려도 같은 줄을 두고 다투지 않는 이유는 무엇인가","at":"해결하는 문제"},{"q":"사건 줄이 길어지면 지금 상태를 만드는 일이 왜 느려지나","at":"작동 원리"},{"q":"이미 저장된 사건 안에 개인정보가 들어 있으면 어떻게 지우나","at":"주의사항"}],"myths":[{"wrong":"이벤트 소싱을 쓰면 어떤 시스템이든 더 낫다","right":"Microsoft 문서는 이 패턴을 대가가 큰 복잡한 패턴이라 못 박고, 대부분의 시스템과 시스템의 대부분에는 전통적인 방식으로 충분하다고 적는다. 감사와 되감기가 그 복잡함을 갚아 주는 자리에만 고른다."},{"wrong":"메시지 브로커가 곧 사건 저장소다","right":"아니다. Microsoft 문서는 둘을 혼동하지 말라고 적는다. 브로커에는 대개 개체별 사건 줄 조회와 낙관적 동시성 제어가 없어서, 사건을 퍼뜨리는 층으로는 좋아도 원본 저장소를 대신하지 못한다."},{"wrong":"잘못 들어간 사건은 지우면 된다","right":"저장소는 덧붙이기만 한다. 되돌리려면 반대 효과를 내는 보상 사건을 하나 더 붙여야 하고, 버그가 만든 사건도 원본에는 그대로 남는다."}],"cases":[{"label":"좌석과 잔액","note":"남은 수를 고쳐 쓰는 대신 예약과 취소를 쌓아 두고 그 자리에서 세면, 마감 직전에 몰려도 같은 줄을 두고 다투지 않는다."},{"label":"감사 추적","note":"누가 언제 무엇을 바꿨는지가 저장 방식 자체에 남아서, 별도 기록 장치 없이도 되짚고 디버깅할 수 있다."},{"label":"조회용 표 새로 만들기","note":"화면이 바뀌어 다른 모양의 표가 필요해지면, 쌓아 둔 사건을 처음부터 재생해 새 표를 만들어 낸다."}],"dia":{"shape":"대조","title":"지금 값을 고치는 것과 일어난 일을 쌓는 것은 무엇이 다른가","rows":[{"who":"","what":"덮어쓰기 || 쌓아 두기","left":"덮어쓰기","right":"쌓아 두기","even":true},{"who":"저장","what":"지금 값만 남는다 || 있었던 일이 남는다","left":"지금 값만 남는다","right":"있었던 일이 남는다"},{"who":"과거","what":"물어볼 수 없다 || 그때로 되감는다","left":"물어볼 수 없다","right":"그때로 되감는다"},{"who":"현재 값","what":"바로 읽는다 || 재생해서 만든다","left":"바로 읽는다","right":"재생해서 만든다"}],"sum":"값을 지우고 고치는 대신, 일어난 일을 붙여 두고 지금 값은 거기서 만들어 낸다"}},"arch--fault-tolerance":{"definition":"고가용성과 겹쳐 보이지만 재는 것이 다르다. 고가용성은 \"한 해에 몇 분 멈췄나\" 라는 결과를 시간 비율로 재고, 장애 허용성은 \"한 곳이 죽었을 때 그 죽음이 어디까지 번지나\" 라는 설계 성질을 가리킨다. 고장을 없애는 쪽이 아니라 고장을 안고 가는 쪽이다.","name":"Fault :: 고장 난 부품\nTolerance :: 견디는 정도\n= 이어 읽으면 \"고장을 견디는 정도\". 고장을 막는다는 말이 이름에 없다","analogy":"한 칸에 구멍이 나도 그 칸만 물이 차고 배는 계속 뜨는, 칸막이를 세운 배.","example":"영상이 잠깐 흐릿해졌다가 다시 또렷해질 뿐 멈추지는 않던 그 순간이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n흐름: 서버 한 대가 응답을 멈추면 순서대로 무엇이 일어나나\n타임아웃 :: 정한 시간이 지나면 기다리기를 끊는다\n차단기 :: 실패가 쌓이면 그쪽 길을 잠시 닫는다\n칸 :: 묶인 자원이 그 서비스 몫 안에서 끝난다\n대신 답하기 :: 미리 정해 둔 값이나 줄인 화면을 내놓는다\n@ 열어 보기 :: 조금씩 통과시켜 보고 살아났으면 길을 연다\n= 알아채고, 가두고, 대신 답하고, 열어 보는 네 걸음이 한 벌로 온다\n```\n\n첫 걸음이 타임아웃인 데는 까닭이 있다. 죽은 서버는 죽었다고 알려 주지 않는다. 응답이 안 온다는 사실만 있을 뿐이고, 기다리기를 끊지 않으면 그 호출에 쓰인 연결과 스레드가 계속 묶여 있다. 뒤의 세 걸음은 전부 \"이건 실패다\" 라고 판정한 다음에야 시작되므로, 타임아웃이 없거나 지나치게 길면 나머지 장치를 다 갖춰 놔도 아무것도 걸리지 않는다.\n\n돌아가는 길을 여는 방식도 설계의 일부다. 닫아 두기만 하면 상대가 살아난 뒤에도 계속 막혀 있고, 반대로 한 번에 전부 다시 보내면 겨우 일어선 쪽이 그 순간 다시 넘어간다. 그래서 조금만 통과시켜 보고 그것이 성공했을 때 완전히 연다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 고가용성 · 장애 허용성 · 재해 복구","body":"| | 무엇을 약속하나 | 사용자가 겪는 것 | 무엇을 내주나 |\n|---|---|---|---|\n| **고가용성** | 멈춘 시간이 한도 안 | 잠깐 끊겼다 돌아온다 | 두 벌 값과 전환 장치 |\n| **장애 허용성** | 부품이 죽어도 계속 | 못 느끼거나 일부만 못 쓴다 | 자원을 늘 놀리는 값 |\n| **재해 복구** | 정해진 시간 안에 되살림 | 그동안은 못 쓴다 | 예비 자리 유지비 |\n\n셋은 대립하지 않고 층을 이룬다. 장애 허용성이 잘 되어 있으면 정지 시간이 줄어 고가용성 목표가 지켜지고, 그래도 리전 전체가 날아가는 날을 위해 재해 복구가 아래에 깔린다. 어느 것을 말하고 있는지 헷갈릴 때는 \"사용자가 그 사고를 느끼는가\" 를 물으면 갈린다 — 안 느끼면 허용성, 잠깐 느끼면 가용성, 한참 느끼면 재해 복구다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **커넥션 풀 나누기** — 부르는 서비스마다 커넥션 풀을 따로 준다. 한 곳이 응답을 안 해도 그 풀만 마르고 나머지 호출은 계속 나간다.\n- **줄여서 계속 주기** — 추천이 죽으면 인기 목록으로 대신 채운다. 화면 한 칸이 초라해지는 것과 화면 전체가 안 뜨는 것은 다른 사고다.\n- **고객마다 칸 나누기** — 큰 고객 한 곳의 폭주가 다른 고객 몫까지 먹지 못하게 칸을 갈라 둔다. Azure 문서는 이 나눔의 굵기를 고객당 한 칸으로 할지 여럿을 한 칸에 묶을지 정하라고 적는다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **장애 허용성이 있으면 안 멈춘다** — 멈추지 않는 게 아니라 멈춘 자리가 갇히는 것이다. 고장 난 부품은 여전히 고장 나 있고 누군가는 고쳐야 한다.\n- **재시도를 넣으면 견디게 된다** — 재시도만 넣으면 죽어가는 쪽에 부하를 더 얹는다. Google SRE 책은 재시도를 걸 때 무작위를 섞은 지수 백오프를 반드시 쓰라고 적는다. 안 그러면 재시도들이 같은 순간에 몰려 스스로를 증폭시킨다.\n- **칸을 잘게 나눌수록 좋다** — Azure 문서는 자원을 덜 효율적으로 쓰게 되는 것이 받아들여지지 않거나 늘어난 복잡도가 필요하지 않은 곳에는 이 패턴이 맞지 않다고 적는다. 칸마다 자원을 따로 잡아 두는 값이 곧 이 성질의 가격이다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **칸의 경계를 먼저 긋는다.** Azure 문서는 칸을 그 애플리케이션의 업무 요구와 기술 요구에 맞춰 정하라고 적는다. 손에 잡히는 대로 그으면 같이 죽어야 할 것과 따로 살아야 할 것이 뒤섞인다.\n- **부분 실패에 무엇을 돌려줄지 먼저 정한다.** 칸을 나눠 놓고 그 칸이 막혔을 때 줄 것을 안 정하면 절반만 산 것이다.\n- **고장을 넣어 보지 않으면 모른다.** Google SRE 책은 용량 한계까지 부하를 걸어 과부하 상태의 고장 양상까지 시험해 보라고 적는다. 어디서 무너지는지 모르면 견디게 짰다는 말도 짐작일 뿐이다.\n- **플랫폼이 주는 칸막이를 먼저 쓴다.** Azure 문서는 요청량 제한과 자원 한도 같은 장치를 애플리케이션 코드로 다시 만들지 말라고 적는다."}],"figure":"```도해\n층: 부품 하나가 죽어도 전체가 도는 것은 무엇 덕인가\n두 벌로 두기 :: 한 벌이 죽으면 남은 벌이 그대로 받는다\n칸 나누기 :: 한 기능의 고장이 옆 기능의 자원까지 먹지 못한다\n줄여서 답하기 :: 다 못 주면 덜 준다. 아예 안 주지는 않는다\n사람 부르기 :: 여기까지 내려오면 사용자는 이미 장애를 봤다\n= 위에서 걸릴수록 사용자는 아무 일도 없었던 것처럼 쓴다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 한 곳의 고장이 왜 전체 장애가 되나\n견딤 없이 || 견디게 짜서\n자원 :: 죽은 곳에 묶인다 || 칸 안에서 끝난다\n남은 장비 :: 몰려서 같이 죽는다 || 흘릴 만큼만 받는다\n결과 :: 도미노로 번진다 || 한 기능만 줄어든다\n= 무서운 것은 고장이 아니라 고장이 번지는 속도다\n```\n\nGoogle SRE 책은 연쇄 장애를 \"양의 되먹임 때문에 시간이 갈수록 커지는 장애\" 로 적는다. 복제본 하나가 과부하로 죽으면 그만큼의 부하가 남은 복제본으로 넘어가고, 남은 쪽이 죽을 확률이 올라가고, 그렇게 도미노로 전부 넘어간다. 처음 죽은 한 대는 원인이 아니라 도미노의 첫 조각일 뿐이다.\n\n부르는 쪽에서도 같은 일이 벌어진다. Azure 문서는 응답하지 않는 서비스를 계속 부르면 그 호출에 쓰인 자원이 오래 묶이고, 결국 커넥션 풀(밖으로 열어 둘 수 있는 연결을 담아 놓은 통)이 말라서 **그 소비자가 멀쩡한 다른 서비스에도 요청을 못 보내게 된다**고 적는다. 그래서 자원을 서비스마다 따로 떼어 두는 것이 격벽 패턴이다. 배의 격벽에서 이름을 가져왔고, 선체 한 칸이 뚫려도 그 칸만 물이 차서 배가 가라앉지 않는 것과 같다.\n\n칸을 나누는 것과 두 벌로 두는 것은 방향이 다르다. AWS 문서의 계산으로 99.9% 짜리 독립 부품 둘을 나란히 두면 둘 다 죽어야 장애가 되므로 전체는 99.9999% 가 된다. 다만 이 셈은 **둘이 진짜로 따로 죽을 때만** 성립한다. 같은 전원, 같은 배포, 같은 설정 파일을 나눠 쓰는 두 벌은 하나로 죽는다."},"recap":"**\"고장을 없애는 대신 한 칸에 가두는 성질\"** 이라고 읽으면 된다. 무서운 것은 부품 하나의 고장이 아니라 그 고장이 자원을 붙잡고 옆으로 번지는 속도이고, 그래서 두 벌로 두기·칸 나누기·줄여서 답하기가 한 벌로 온다. 대가는 늘 놀려 두는 자원과 늘어난 운영거리이므로, 번져도 괜찮은 곳까지 칸을 파지는 않는다.","kid":"큰 배 안은 방처럼 칸칸이 나뉘어 있는 거 알아? 한 칸에 구멍이 나서 물이 들어와도 그 칸 문만 닫으면 배는 계속 가지. 구멍을 안 나게 하는 게 아니라 구멍 난 자리를 한 칸에 가둬 두는 거야.","check":[{"q":"결제 한 곳만 느려졌는데 사이트 전체가 멈추는 일은 왜 생기나","at":"해결하는 문제"},{"q":"고가용성과 장애 허용성은 사용자가 겪는 것이 어떻게 다른가","at":"비교"},{"q":"칸을 아주 잘게 나누면 무엇을 내주게 되나","at":"흔한 오해"}],"myths":[{"wrong":"장애 허용성이 있으면 안 멈춘다","right":"멈추지 않는 게 아니라 멈춘 자리가 갇히는 것이다. 고장 난 부품은 여전히 고장 나 있고 누군가는 고쳐야 한다."},{"wrong":"재시도를 넣으면 견디게 된다","right":"재시도만 넣으면 죽어가는 쪽에 부하를 더 얹는다. Google SRE 책은 재시도를 걸 때 무작위를 섞은 지수 백오프를 반드시 쓰라고 적는다. 안 그러면 재시도들이 같은 순간에 몰려 스스로를 증폭시킨다."},{"wrong":"칸을 잘게 나눌수록 좋다","right":"Azure 문서는 자원을 덜 효율적으로 쓰게 되는 것이 받아들여지지 않거나 늘어난 복잡도가 필요하지 않은 곳에는 이 패턴이 맞지 않다고 적는다. 칸마다 자원을 따로 잡아 두는 값이 곧 이 성질의 가격이다."}],"cases":[{"label":"커넥션 풀 나누기","note":"부르는 서비스마다 커넥션 풀을 따로 준다. 한 곳이 응답을 안 해도 그 풀만 마르고 나머지 호출은 계속 나간다."},{"label":"줄여서 계속 주기","note":"추천이 죽으면 인기 목록으로 대신 채운다. 화면 한 칸이 초라해지는 것과 화면 전체가 안 뜨는 것은 다른 사고다."},{"label":"고객마다 칸 나누기","note":"큰 고객 한 곳의 폭주가 다른 고객 몫까지 먹지 못하게 칸을 갈라 둔다. Azure 문서는 이 나눔의 굵기를 고객당 한 칸으로 할지 여럿을 한 칸에 묶을지 정하라고 적는다."}],"dia":{"shape":"층","title":"부품 하나가 죽어도 전체가 도는 것은 무엇 덕인가","rows":[{"who":"두 벌로 두기","what":"한 벌이 죽으면 남은 벌이 그대로 받는다"},{"who":"칸 나누기","what":"한 기능의 고장이 옆 기능의 자원까지 먹지 못한다"},{"who":"줄여서 답하기","what":"다 못 주면 덜 준다. 아예 안 주지는 않는다"},{"who":"사람 부르기","what":"여기까지 내려오면 사용자는 이미 장애를 봤다"}],"sum":"위에서 걸릴수록 사용자는 아무 일도 없었던 것처럼 쓴다"}},"arch--high-availability":{"definition":"가용성은 \"쓸 수 있던 시간 ÷ 전체 시간\" 이다. AWS 문서는 이 값을 백분율로 적고, 흔히 나인의 개수로 줄여 부른다 — 99.99% 를 \"포 나인\" 이라고 하는 식이다. 고가용성은 이 숫자를 목표로 걸고, 그 목표를 지키도록 부품을 겹쳐 두는 일이다.","name":"High :: 높은\nAvail :: 쓸 수 있게 되다\n-ability :: 그럴 수 있는 정도\n= 이어 읽으면 \"쓸 수 있는 정도가 높음\". 그 정도를 숫자로 적은 것이 나인의 개수다","analogy":"직원이 아파도 다른 직원이 대신 서기 때문에 손님은 문 닫힌 걸 본 적이 없는 24시간 편의점.","example":"클라우드 계약서에 적힌 \"월 99.9% 보장\" 이라는 한 줄이 바로 이 이야기다.","tryit":"쓰는 메신저나 클라우드의 상태 페이지를 한번 열어 보라. 지난달에 몇 분이나 멈췄는지가 날짜별로 적혀 있다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"가용성을 올리는 길은 둘뿐이다. AWS 문서는 부품의 가용성을 알 수 없을 때 `MTBF ÷ (MTBF + MTTR)` 로 어림잡으라고 적는다. MTBF 는 고장 사이의 평균 시간이고, MTTR 은 고장이 감지된 뒤 되살리는 데 걸리는 평균 시간이다. 고장이 덜 나게 해서 앞의 값을 늘리거나, 되살리는 시간을 줄여서 뒤의 값을 낮추거나 둘 중 하나다.\n\n그래서 고가용성 구성은 세 부품이 한 벌이다. **같은 것을 두 벌 이상 두기**, **죽은 쪽을 알아채는 감시**, **알아채면 자동으로 넘기는 전환**이다. 셋 중 마지막이 빠지면 새벽에 사람이 깨어 손으로 넘기는 시간이 그대로 정지 시간이 된다. 한 번 깨는 데 한 시간이 걸린다면, 99.99% 의 한 해 예산 52분은 그 한 번으로 끝난다.\n\n어디에 두 벌을 둘지도 정해야 한다. 같은 건물 안의 두 대는 정전 하나에 같이 죽으므로 독립이 아니다. 가용 영역을 나누고, 리전까지 나누는 순간부터는 배포·데이터 일관성·지연이 전부 같이 어려워진다. Azure 문서도 다중 리전을 두고 \"위험이 줄어드는 값이 늘어나는 복잡도만큼 값어치가 있는지 판단하라\" 고 적는다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 가용성을 말할 때 쓰는 다섯 낱말","body":"| 낱말 | 무엇인가 | 누가 정하나 |\n|---|---|---|\n| **SLI** | 성공률·지연 같은 실제 측정값 | 기술팀 |\n| **SLO** | 그 측정값이 넘어야 할 목표 | 기술팀과 사업팀이 합의 |\n| **SLA** | 못 지키면 돈을 무는 계약 | 회사와 고객 |\n| **RTO** | 사고 뒤 몇 시간 안에 되살릴지 | 사업팀 |\n| **RPO** | 잃어도 되는 기록이 몇 분치인지 | 사업팀 |\n\nAzure 문서는 SLA 와 SLO 를 반드시 구별하라고 적는다. SLA 는 못 지키면 금전적·법적 결과가 따르는 계약이고, SLO 는 멈춘 시간이 아직 견딜 만한 범위인지 조직이 스스로 재려고 두는 목표다. 둘은 따로 관리해야 하고, 어느 쪽이 더 높은 숫자인지는 그 회사가 무엇을 노리느냐에 따라 갈린다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **가용 영역 나눠 두기** — 같은 구성을 두 영역에 두고 앞에 부하 분산기를 세운다. 한 영역이 통째로 죽어도 남은 영역이 받는다.\n- **무중단 배포** — 한 대씩 빼서 새 버전을 올리고 다시 넣는다. 배포하려고 멈추는 시간이 그해의 가용성 예산을 갉아먹지 않게 하는 일이다.\n- **목표를 정하는 회의** — 99.9% 를 99.99% 로 올릴지 정할 때, 늘어나는 비용과 줄어드는 8시간을 나란히 놓고 고른다. 숫자가 없으면 \"더 안정적으로\" 로 끝난다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **가용성은 높을수록 좋다** — 100% 는 목표가 아니다. Google SRE 책은 100% 가 \"달성할 수 없을 뿐 아니라 사용자가 원하거나 알아채는 것보다 더 높은 신뢰성\" 이라고 적고, 99% 짜리 폰을 쓰는 사용자는 99.99% 와 99.999% 를 구별하지 못한다고 덧붙인다.\n- **부품을 늘리면 가용성이 올라간다** — 나란히 두면 오르고, 줄줄이 엮으면 내려간다. 없으면 못 도는 의존이 하나 늘 때마다 전체 가용성은 곱해져서 내려간다.\n- **제공사 SLA 가 99.99% 니까 우리도 99.99% 다** — Azure 문서는 SLA 가 그 서비스 전체를 보장하지 않는다고 못 박는다. 계약서에 적힌 좁은 동작 하나만 덮고, 캐싱이나 규칙 엔진 같은 기능은 그 밖이다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **목표를 먼저 정하고 설계한다.** 99.9% 면 되는 내부 도구에 다중 리전을 얹으면 복잡도만 사는 셈이다.\n- **높은 가용성은 속도를 먹는다.** AWS 문서는 아주 높은 목표에서는 배포를 더 천천히 해야 해서 새 기능을 내는 일이 느려진다고 적는다. 고를 수 있는 부품의 폭도 좁아진다.\n- **점검 시간도 정지 시간이다.** \"예정된 작업이니 빼자\" 는 계산은 사용자가 겪는 것과 어긋난다."}],"figure":"```도해\n층: 나인이 하나 더 붙으면 무엇이 달라지나\n99% :: 한 해에 3일 15시간까지 멈춰도 된다\n99.9% :: 한 해에 8시간 45분. 내부 도구가 이 근처다\n99.99% :: 한 해에 52분. 사람이 달려와서는 못 지킨다\n99.999% :: 한 해에 5분. 감지도 복구도 전부 기계가 한다\n= 나인 하나마다 허용된 정지 시간이 10분의 1이 된다. 목표는 곧 예산이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 서버 한 대로만 돌리면 무엇이 문제인가\n한 대로 || 여러 대로\n장비 고장 :: 그대로 멈춘다 || 남은 대가 받는다\n점검 재부팅 :: 그때마다 끊긴다 || 한 대씩 돌린다\n정지 시간 :: 예측이 안 된다 || 한도로 관리된다\n= 안 멈추게 하는 게 아니라, 한 곳이 멈춰도 전체는 안 멈추게 하는 것이다\n```\n\n한 대로 돌리는 시스템에는 정지 시간의 상한이 없다. 장비가 죽으면 새 장비를 구해 올리는 데 걸리는 만큼 멈추고, 그 시간이 얼마인지는 사고가 나 봐야 안다. 점검 재부팅처럼 예정된 중단도 그대로 정지 시간이다 — AWS 문서는 계획된 점검을 전체 시간에서 빼는 계산을 권하지 않는다. 사용자는 그 시간에도 쓰려고 하기 때문이다.\n\n같은 것을 두 벌 이상 두고 앞에서 살아 있는 쪽으로만 보내면 상한이 생긴다. 숫자로 보면 방향이 분명하다. AWS 문서의 계산으로, 99.9% 짜리 독립 부품 둘을 나란히 두면 둘 다 죽을 확률만 남아서 99.9999% 가 된다. **반대 방향도 같은 셈법이다.** 없으면 못 도는 의존이 하나 늘 때마다 가용성은 곱해진다 — 99.99% 짜리 셋을 직렬로 엮으면 전체는 99.97% 다."},"recap":"**\"멈춰도 되는 시간을 미리 정해 둔 약속\"** 이라고 읽으면 된다. 나인을 하나 더 붙일 때마다 허용된 정지 시간은 10분의 1이 되고 값은 그만큼 뛴다. 없으면 못 도는 의존이 늘수록 가용성은 곱해져 내려가므로, 목표를 먼저 정하고 그 목표에 맞는 만큼만 겹쳐 둔다.","kid":"동네 가게가 24시간 문을 연다고 써 붙였으면, 아저씨가 아파도 다른 사람이 대신 서서 문은 안 닫히지? 그런데 일 년에 딱 몇 분은 닫아도 된다고 미리 정해 두는 거야. 그 몇 분을 더 줄이려고 하면 사람이 훨씬 많이 필요해져.","check":[{"q":"없으면 못 도는 의존을 하나 더 붙이면 전체 가용성은 어느 쪽으로 움직이나","at":"해결하는 문제"},{"q":"나인을 하나 더 붙이면 한 해에 허용되는 정지 시간이 얼마로 줄어드나","at":"그림"},{"q":"예비 장비를 두고도 새벽에 사람이 깨서 손으로 넘기는 구성은 무엇을 못 지키나","at":"작동 원리"}],"myths":[{"wrong":"가용성은 높을수록 좋다","right":"100% 는 목표가 아니다. Google SRE 책은 100% 가 \"달성할 수 없을 뿐 아니라 사용자가 원하거나 알아채는 것보다 더 높은 신뢰성\" 이라고 적고, 99% 짜리 폰을 쓰는 사용자는 99.99% 와 99.999% 를 구별하지 못한다고 덧붙인다."},{"wrong":"부품을 늘리면 가용성이 올라간다","right":"나란히 두면 오르고, 줄줄이 엮으면 내려간다. 없으면 못 도는 의존이 하나 늘 때마다 전체 가용성은 곱해져서 내려간다."},{"wrong":"제공사 SLA 가 99.99% 니까 우리도 99.99% 다","right":"Azure 문서는 SLA 가 그 서비스 전체를 보장하지 않는다고 못 박는다. 계약서에 적힌 좁은 동작 하나만 덮고, 캐싱이나 규칙 엔진 같은 기능은 그 밖이다."}],"cases":[{"label":"가용 영역 나눠 두기","note":"같은 구성을 두 영역에 두고 앞에 부하 분산기를 세운다. 한 영역이 통째로 죽어도 남은 영역이 받는다."},{"label":"무중단 배포","note":"한 대씩 빼서 새 버전을 올리고 다시 넣는다. 배포하려고 멈추는 시간이 그해의 가용성 예산을 갉아먹지 않게 하는 일이다."},{"label":"목표를 정하는 회의","note":"99.9% 를 99.99% 로 올릴지 정할 때, 늘어나는 비용과 줄어드는 8시간을 나란히 놓고 고른다. 숫자가 없으면 \"더 안정적으로\" 로 끝난다."}],"dia":{"shape":"층","title":"나인이 하나 더 붙으면 무엇이 달라지나","rows":[{"who":"99%","what":"한 해에 3일 15시간까지 멈춰도 된다"},{"who":"99.9%","what":"한 해에 8시간 45분. 내부 도구가 이 근처다"},{"who":"99.99%","what":"한 해에 52분. 사람이 달려와서는 못 지킨다"},{"who":"99.999%","what":"한 해에 5분. 감지도 복구도 전부 기계가 한다"}],"sum":"나인 하나마다 허용된 정지 시간이 10분의 1이 된다. 목표는 곧 예산이다"}},"arch--idempotency":{"definition":"RFC 9110 은 \"같은 요청을 여러 번 보냈을 때 서버에 의도된 효과가 한 번 보냈을 때와 같으면\" 그 메서드를 멱등이라 부르고, `PUT` 과 `DELETE` 와 안전한 메서드들이 여기 든다고 적는다. 분산된 시스템에서 이 성질이 중요한 이유는 하나다 — 멱등한 것만 마음 놓고 다시 보낼 수 있다.","name":"idem :: 같은\npotent :: 힘\n= 이어 읽으면 \"몇 번을 눌러도 같은 힘\". 힘이 같으니 또 눌러도 된다는 뜻이다","analogy":"이미 불이 들어온 엘리베이터 버튼을 열 번 더 눌러도 엘리베이터는 한 번만 온다.","example":"송금 버튼을 눌렀는데 화면이 멈춰서 다시 눌러야 할지 망설였던 그 순간이 멱등이 아닐 때다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n흐름: 같은 요청이 두 번 와도 한 번이 되게 하려면 무엇을 하나\n클라이언트 :: 요청에 표를 하나 붙여 보낸다\n서버 :: 그 표를 본 적 있는지 저장소에서 먼저 찾는다\n서버 :: 처음 보는 표면 자리를 잡아 두고 그다음에 일을 한다\n서버 :: 끝난 결과를 그 표 아래 적어 둔다\n< 두 번째 :: 같은 표가 오면 일은 건너뛰고 적어 둔 결과를 준다\n= 일을 두 번 막는 게 아니라, 표를 먼저 잡아 두 번째를 못 들어오게 한다\n```\n\n순서에서 중요한 자리는 셋째 줄이다. 표를 일이 끝난 뒤에 적으면, 재시도가 첫 요청이 처리되는 동안 도착했을 때 둘 다 \"처음 보는 표\" 가 되어 나란히 실행된다. 그래서 표부터 자리를 잡아 두고 일을 시작한다. 저장소가 같은 표를 두 번 못 넣게 막아 주면, 그 막힘 자체가 두 번째를 걸러 내는 장치가 된다.\n\n붙일 표를 새로 만들지 않아도 되는 자리가 있다. 주문 번호처럼 그 일에 하나뿐인 값이 이미 있으면 그것을 열쇠로 잡는다. 이렇게 얻은 열쇠는 따로 저장하고 지울 것이 늘지 않으므로, 표를 발급하기 전에 이미 있는 값부터 찾아본다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 어떤 연산이 저절로 멱등인가","body":"| 하는 일 | 멱등인가 | 왜 |\n|---|---|---|\n| **조회** (`GET`) | 그렇다 | 상태를 안 바꾼다 |\n| **덮어쓰기** (`PUT`) | 그렇다 | 몇 번을 써도 같은 값이 남는다 |\n| **지우기** (`DELETE`) | 그렇다 | 두 번째는 이미 없는 것을 지운다 |\n| **새로 만들기** (`POST`) | 아니다 | 부를 때마다 하나가 더 생긴다 |\n| **값 더하기** (`+1`) | 아니다 | 부른 횟수가 그대로 결과에 남는다 |\n| **상태 바꾸기** (`승인함`) | 정하기 나름 | 이미 승인된 건을 또 승인하면 어떻게 할지 적어 둬야 한다 |\n\n설계에서 갈리는 자리는 맨 아래 두 줄이다. \"잔액을 5000원으로 맞춰라\" 로 쓸 수 있는 것을 \"5000원을 더해라\" 로 쓰면 재시도가 위험해진다. **표현을 바꾸는 것만으로 멱등을 공짜로 얻는 경우가 많다.**"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **결제 승인** — 응답이 끊겨도 같은 표를 붙여 다시 보내면 승인은 한 건만 남는다. 이 성질이 없으면 재시도를 아예 못 건다.\n- **메시지 소비** — 큐는 대개 \"적어도 한 번\" 을 보장한다. 같은 메시지가 두 번 와도 처리한 id 를 적어 두고 걸러야 결과가 한 번과 같아진다.\n- **설정 적용** — 같은 선언을 열 번 적용해도 결과가 같게 만들어 두면, 도중에 실패한 작업을 처음부터 그냥 다시 돌릴 수 있다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **응답이 안 왔으면 실패한 거니까 다시 보내면 된다** — 이미 처리되고 응답만 유실됐을 수 있다. 보낸 쪽에는 둘을 구별할 방법이 없고, RFC 9110 은 그래서 프록시가 멱등하지 않은 요청을 자동으로 재시도해서는 안 된다고 못 박는다.\n- **멱등이면 두 번째 요청은 아무 일도 안 한다** — 결과가 같다는 뜻이지 아무 일도 안 한다는 뜻이 아니다. RFC 9110 은 서버가 요청마다 따로 기록을 남기거나 이력을 쌓는 것은 멱등과 무관하다고 적는다.\n- **전부 멱등하게 만들어 두면 안전하다** — 멱등이 아닌 것을 멱등하게 만들려면 표와 처리 결과를 저장하고 언제 지울지까지 관리해야 한다. 두 번 일어나도 손해가 없는 일에는 그 저장소가 순수한 낭비다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **응답까지 같아야 하는 것은 아니다.** 두 번째에 첫 결과를 그대로 주든 겹쳤다고 알리든, 남는 상태만 같으면 멱등이다. 무엇을 줄지는 문서에 밝힌다.\n- **기록을 언제 지울지가 곧 재시도 유효기간이다.** 하루만 들고 있으면 이틀 뒤에 온 재시도는 새 요청으로 취급된다.\n- **어디서 재시도가 일어나는지 그림에 그려 둔다.** 앞단, 미들웨어, 라이브러리, 큐가 저마다 몰래 다시 보내면 멱등하지 않은 자리가 조용히 두 번 실행된다."}],"figure":"```도해\n층: 여러 번 해도 결과가 같아지는 것은 어디서 정해지나\n메서드가 정한다 :: 조회·덮어쓰기·지우기는 규격이 이미 멱등이라 적어 뒀다\n연산이 정한다 :: \"5로 맞춰라\" 는 같고 \"5를 더해라\" 는 매번 달라진다\n붙인 표가 정한다 :: 요청마다 표를 달고, 본 적 있는 표면 첫 결과를 다시 준다\n뒤에서 합친다 :: 중복을 찾아 하나로 붙인다. 이미 두 번 일어난 뒤다\n= 위에서 정해질수록 공짜고, 아래로 내려올수록 저장하고 관리할 것이 늘어난다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 응답을 못 받았을 때 다시 보내도 되나\n멱등이 아니면 || 멱등이면\n재시도 :: 두 건 될까 봐 못 함 || 그냥 다시 보낸다\n자동 복구 :: 사람이 확인해야 || 기계가 알아서 한다\n중복 전달 :: 그대로 두 번 처리 || 한 번과 같다\n= 재시도도 자동 복구도 중복 대비도 전부 이 성질 하나에 매달려 있다\n```\n\n보낸 쪽은 **응답이 안 왔다는 사실만으로는 아무것도 알 수 없다.** 요청이 가다가 사라진 것인지, 이미 처리까지 끝났는데 응답만 사라진 것인지 구별할 방법이 없기 때문이다. 다시 보내면 두 번 처리될 수 있고, 안 보내면 아예 빠질 수 있다.\n\n멱등하면 이 갈림길이 없어진다. RFC 9110 은 멱등한 메서드가 특별한 이유가 바로 이것이라고 적는다 — 응답을 읽기 전에 연결이 끊기면 새 연결을 열어 그냥 다시 보내면 된다. 첫 요청이 성공했더라도 의도한 효과는 같기 때문이다. AWS 문서도 재시도와 백오프를 쓸 때 연산이 멱등이어야 하며, 아니면 반쯤 반영된 갱신이 상태를 망칠 수 있다고 적는다. 재시도·자동 복구·\"적어도 한 번\" 전달이 전부 이 성질 위에 서 있다."},"recap":"**\"몇 번을 눌러도 같은 그 성질\"** 이라고 읽으면 된다. 응답이 안 온 요청은 성공인지 실패인지 알 수 없고, 그래서 다시 보내도 되는지는 이 성질 하나가 정한다. 규격이나 표현으로 공짜로 얻어지는 자리가 있고 표를 저장해 사서 써야 하는 자리가 있으니, 두 번 일어나면 손해인 일에만 값을 치른다.","kid":"엘리베이터 버튼에 이미 불이 켜져 있으면 열 번을 더 눌러도 엘리베이터는 한 번만 오지? 몇 번을 눌렀든 똑같으니까 마음 놓고 또 눌러도 돼. 그런데 붕어빵은 시킬 때마다 하나씩 더 나오니까 두 번 말하면 두 개가 돼 버려.","check":[{"q":"보낸 쪽이 성공인지 실패인지 끝내 알 수 없는 경우는 왜 생기나","at":"해결하는 문제"},{"q":"값을 5로 맞추는 것과 5를 더하는 것은 무엇이 다른가","at":"비교"},{"q":"모든 일을 멱등하게 만들어 두는 것이 낭비가 되는 까닭은","at":"흔한 오해"}],"myths":[{"wrong":"응답이 안 왔으면 실패한 거니까 다시 보내면 된다","right":"이미 처리되고 응답만 유실됐을 수 있다. 보낸 쪽에는 둘을 구별할 방법이 없고, RFC 9110 은 그래서 프록시가 멱등하지 않은 요청을 자동으로 재시도해서는 안 된다고 못 박는다."},{"wrong":"멱등이면 두 번째 요청은 아무 일도 안 한다","right":"결과가 같다는 뜻이지 아무 일도 안 한다는 뜻이 아니다. RFC 9110 은 서버가 요청마다 따로 기록을 남기거나 이력을 쌓는 것은 멱등과 무관하다고 적는다."},{"wrong":"전부 멱등하게 만들어 두면 안전하다","right":"멱등이 아닌 것을 멱등하게 만들려면 표와 처리 결과를 저장하고 언제 지울지까지 관리해야 한다. 두 번 일어나도 손해가 없는 일에는 그 저장소가 순수한 낭비다."}],"cases":[{"label":"결제 승인","note":"응답이 끊겨도 같은 표를 붙여 다시 보내면 승인은 한 건만 남는다. 이 성질이 없으면 재시도를 아예 못 건다."},{"label":"메시지 소비","note":"큐는 대개 \"적어도 한 번\" 을 보장한다. 같은 메시지가 두 번 와도 처리한 id 를 적어 두고 걸러야 결과가 한 번과 같아진다."},{"label":"설정 적용","note":"같은 선언을 열 번 적용해도 결과가 같게 만들어 두면, 도중에 실패한 작업을 처음부터 그냥 다시 돌릴 수 있다."}],"dia":{"shape":"층","title":"여러 번 해도 결과가 같아지는 것은 어디서 정해지나","rows":[{"who":"메서드가 정한다","what":"조회·덮어쓰기·지우기는 규격이 이미 멱등이라 적어 뒀다"},{"who":"연산이 정한다","what":"\"5로 맞춰라\" 는 같고 \"5를 더해라\" 는 매번 달라진다"},{"who":"붙인 표가 정한다","what":"요청마다 표를 달고, 본 적 있는 표면 첫 결과를 다시 준다"},{"who":"뒤에서 합친다","what":"중복을 찾아 하나로 붙인다. 이미 두 번 일어난 뒤다"}],"sum":"위에서 정해질수록 공짜고, 아래로 내려올수록 저장하고 관리할 것이 늘어난다"}},"arch--langgraph":{"definition":"질문을 분류하고 자료를 찾고 답을 만들고 검증하는 식으로 단계가 늘어나면 조건문이 겹겹이 쌓여 어디로 흘러가는지 읽기 어려워진다. LangGraph는 그 단계를 노드로, 이동을 엣지로 따로 적게 한다.","name":"Lang :: 말을 다루는 쪽\nGraph :: 점과 선으로 그린 그림\n= 붙여 읽으면 \"말 다루는 일을 점과 선으로 그린 것\". 흐름이 코드가 아니라 그 그림에 적혀 있다","analogy":"지하철 노선도. 역과 이어진 선만 그려두면 어디서 어디로 갈 수 있는지가 그림 하나로 보인다.","example":"AI 챗봇이 답을 내기 전에 자료 찾는 중과 정리하는 중을 차례로 보여주는 그 단계들이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```python\ngraph = StateGraph(State)\ngraph.add_node(\"retrieve\", retrieve_docs)\ngraph.add_node(\"generate\", generate_answer)\ngraph.add_edge(\"retrieve\", \"generate\")\n\nresult = graph.invoke({\"question\": \"RAG가 뭐에요?\"})\n```\n\n상태는 그래프 전체가 함께 쓰는 그릇이다. 각 노드는 상태를 받아 자기 몫을 채워 넣고 다음 노드로 넘긴다. 노드끼리 값을 직접 주고받지 않기 때문에, 순서를 바꾸거나 중간에 하나를 끼워 넣어도 함수를 고칠 일이 적다.\n\n엣지는 고정으로 이을 수도 있고, 상태를 보고 갈래를 고르게 할 수도 있다. 뒤쪽이 있어서 앞 노드로 되돌아가는 흐름을 만들 수 있고, 그래서 반복해서 다듬는 에이전트를 짤 수 있다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **검색 후 답변** — 자료를 찾는 노드와 답을 만드는 노드를 잇고, 찾은 게 부족하면 검색 노드로 되돌린다.\n- **질문 분류** — 첫 노드에서 질문 종류를 가르고, 종류마다 다른 노드로 보낸다.\n- **검증 단계** — 답을 만든 뒤 확인하는 노드를 붙이고, 통과하지 못하면 다시 만들게 한다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **LangGraph가 답을 만들어준다** — 만들지 않는다. 어느 순서로 무엇을 부를지를 관리할 뿐이고, 답은 안에 등록한 함수와 모델이 만든다.\n- **그래프니까 순서가 한 줄로 정해진다** — 상태를 보고 갈래를 고르거나 앞 노드로 되돌아가게 만들 수 있다. 되돌아가는 길이 있어서 에이전트가 된다.\n- **LangChain을 대체하는 것이다** — 대체가 아니다. LangChain 쪽이 상위 프레임워크이고, LangGraph는 그 안에서 흐름을 맡는 자리다."}],"figure":"```도해\n흐름: 질문 하나가 그래프를 어떻게 지나가나\n상태 :: 질문과 중간 결과를 담을 그릇을 만든다\n노드 :: 할 일 하나를 함수로 등록한다\n엣지 :: 이 노드 다음에 어디로 갈지 잇는다\n분기 :: 상태를 보고 갈래를 고르게 한다\n실행 :: 시작 값을 넣으면 끝 노드까지 흘러간다\n@ 되돌림 :: 답이 부족하면 앞 노드로 돌아가 한 바퀴 더\n= 각 노드는 상태를 받아 고쳐 넘긴다. 흐름은 코드가 아니라 그래프에 적혀 있다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 단계가 늘어나면 코드는 어떻게 되나\n조건문으로 || 그래프로\n흐름 파악 :: 코드를 다 읽음 || 그림으로 보임\n단계 추가 :: 분기를 파고듦 || 노드 하나 추가\n중간 상태 :: 변수로 흩어짐 || 한 곳에 모임\n= 흐름을 코드에서 떼어내 따로 적어두면 고칠 자리가 한 곳으로 모인다\n```\n\n에이전트는 대개 한 번에 끝나지 않는다. 질문을 분류하고, 필요하면 자료를 찾고, 답을 만들고, 마음에 안 들면 다시 찾는다. 이걸 조건문으로 짜면 되돌아가는 길이 생길 때마다 중첩이 깊어진다.\n\nLangGraph는 할 일을 노드로 등록하고 이동을 엣지로 잇는다. 무엇을 하는지와 어디로 가는지가 나뉘므로, 단계를 하나 더 붙일 때 기존 함수를 건드리지 않는다."},"recap":"**\"흐름을 코드가 아니라 그림에 적는 그 도구\"** 라고 읽으면 된다. 단계를 노드로 이동을 엣지로 적어 두고 그 그래프대로 실행하니, 단계를 붙이거나 앞으로 되돌리는 길을 만들기 쉽다. 답을 만드는 일 자체는 안에 등록한 함수가 한다.","kid":"지하철 노선도를 보면 어느 역에서 어느 역으로 갈 수 있는지 한눈에 보이지? 할 일을 역처럼 늘어놓고 사이를 선으로 이어 둔 거야. 그래서 가운데에 역을 하나 더 끼워 넣거나, 마음에 안 들면 앞 역으로 되돌아가는 선을 그려 넣는 것도 쉬워.","check":[{"q":"조건문으로 짠 에이전트에 단계를 하나 더 붙일 때 그래프 쪽이 편한 이유는","at":"해결하는 문제"},{"q":"노드끼리 값을 직접 주고받지 않는데 앞 노드의 결과를 어떻게 쓰나","at":"작동 원리"},{"q":"답이 이상하게 나올 때 LangGraph 쪽만 고쳐서는 소용없는 이유는","at":"흔한 오해"}],"myths":[{"wrong":"LangGraph가 답을 만들어준다","right":"만들지 않는다. 어느 순서로 무엇을 부를지를 관리할 뿐이고, 답은 안에 등록한 함수와 모델이 만든다."},{"wrong":"그래프니까 순서가 한 줄로 정해진다","right":"상태를 보고 갈래를 고르거나 앞 노드로 되돌아가게 만들 수 있다. 되돌아가는 길이 있어서 에이전트가 된다."},{"wrong":"LangChain을 대체하는 것이다","right":"대체가 아니다. LangChain 쪽이 상위 프레임워크이고, LangGraph는 그 안에서 흐름을 맡는 자리다."}],"cases":[{"label":"검색 후 답변","note":"자료를 찾는 노드와 답을 만드는 노드를 잇고, 찾은 게 부족하면 검색 노드로 되돌린다."},{"label":"질문 분류","note":"첫 노드에서 질문 종류를 가르고, 종류마다 다른 노드로 보낸다."},{"label":"검증 단계","note":"답을 만든 뒤 확인하는 노드를 붙이고, 통과하지 못하면 다시 만들게 한다."}],"dia":{"shape":"흐름","title":"질문 하나가 그래프를 어떻게 지나가나","rows":[{"who":"상태","what":"질문과 중간 결과를 담을 그릇을 만든다"},{"who":"노드","what":"할 일 하나를 함수로 등록한다"},{"who":"엣지","what":"이 노드 다음에 어디로 갈지 잇는다"},{"who":"분기","what":"상태를 보고 갈래를 고르게 한다"},{"who":"실행","what":"시작 값을 넣으면 끝 노드까지 흘러간다"}],"sum":"각 노드는 상태를 받아 고쳐 넘긴다. 흐름은 코드가 아니라 그래프에 적혀 있다","loop":{"who":"되돌림","what":"답이 부족하면 앞 노드로 돌아가 한 바퀴 더"}}},"arch--latency":{"definition":"한 번에 얼마나 많이 나르느냐가 아니라, 하나가 갔다 오는 데 얼마나 걸리느냐를 잰다. 사용자가 느리다고 말할 때 실제로 가리키는 값이 대개 이것이다.","name":"= Latency 는 \"숨어 있다\" 는 뜻의 라틴어 latere 에서 왔다. 평소엔 안 보이다가 기다리게 될 때만 드러나는 시간이라는 말이다","analogy":"우편과 전화의 차이. 편지는 부치고 며칠을 기다리고, 전화는 말하는 순간 닿는다.","example":"해외 사이트는 링크를 눌러도 한 박자 늦게 반응하는데, 그 한 박자가 여기서 재는 값이다.","tryit":"명령 창을 열고 `ping 8.8.8.8` 을 쳐 보라. 한 번 갔다 오는 데 걸린 시간이 밀리초 단위로 한 줄씩 찍힌다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n층: 어디서 끝날수록 빠른가\n브라우저 캐시 :: 이미 받은 것. 왕복이 없다\n가까운 거점 :: 같은 지역의 서버. 거리를 줄인다\n원본 서버 :: 처리와 조립. 코드가 걸리는 만큼\n데이터베이스 :: 조회. 인덱스가 없으면 여기서 늘어진다\n= 위에서 끝날수록 짧다. 지연을 줄이는 일은 대개 위로 끌어올리는 일이다\n```\n\n지연은 성격이 다른 조각들의 합이다. 회선을 오가는 시간은 거리가 정하고, 처리 시간은 코드와 서버가 정하고, 조회 시간은 데이터 양과 인덱스가 정한다. 어느 조각이 큰지 모르면 엉뚱한 곳을 고치게 된다.\n\n줄이는 방법도 조각마다 다르다. 거리는 사용자 가까운 곳에 복사본을 두어 줄이고, 반복되는 조회는 캐시에 담아 없애고, 서로 상관없는 작업은 순서대로 기다리는 대신 동시에 건다. 인덱스가 없어 전체를 훑는 조회는 인덱스를 붙여야 줄어든다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 응답 시간대별 체감","body":"| 지연 | 느낌 | 예 |\n|---|---|---|\n| 100ms 아래 | 즉각 반응한다 | 로컬 작업 |\n| 300ms 아래 | 빠르다 | 일반적인 API |\n| 1초 아래 | 참을 만하다 | 복잡한 검색 |\n| 1초 넘음 | 느리다고 느낀다 | 이탈이 시작된다 |\n| 3초 넘음 | 대부분 떠난다 | |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **먼 나라 서버** — 지구 반대편 서버를 부르면 회선에서만 왕복 시간이 붙는다. 코드를 고쳐도 이 부분은 줄지 않는다.\n- **같은 조회의 반복** — 매번 DB에서 같은 값을 꺼내면 그때마다 대기가 생긴다. 캐시에 두면 그 왕복이 사라진다.\n- **차례로 기다리기** — 서로 상관없는 조회 세 개를 순서대로 부르면 셋의 합이 되고, 동시에 걸면 가장 느린 하나가 된다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **서버를 좋은 걸로 바꾸면 지연이 준다** — 처리 시간만 준다. 거리 때문에 생기는 왕복이나 순서 때문에 생기는 대기는 그대로 남는다.\n- **평균 응답 시간이 괜찮으면 괜찮은 것이다** — 평균은 느린 쪽을 가린다. 열 명 중 한 명이 3초를 기다려도 평균은 크게 움직이지 않는다.\n- **지연이 낮으면 처리량도 높다** — 다른 값이다. 하나가 빨리 갔다 오는 것과 동시에 여럿을 감당하는 것은 각각 따로 막힌다."}],"figure":"```도해\n흐름: 검색 버튼을 누르고 결과가 뜰 때까지 어디서 시간이 드나\n브라우저 :: 요청을 만들어 보낸다\n회선 :: 서버까지 물리적으로 오간다\n서버 :: 요청을 받아 처리한다\nDB :: 조회하고 결과를 돌려준다\n< 브라우저 :: 받은 것을 화면에 그린다\n= 한 군데가 아니라 각 마디에서 쌓인 합이 사용자가 느끼는 시간이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 응답이 몇 초씩 걸리면 무엇이 달라지나\n느릴 때 || 빠를 때\n사용자 :: 다시 누른다 || 기다린다\n서버 :: 중복 요청 쌓임 || 요청 한 번\n결과 :: 그냥 떠난다 || 계속 쓴다\n= 느린 것은 불편으로 끝나지 않고 부하를 더 만들어낸다\n```\n\n화면이 멈춰 있으면 사람은 기다리다가 버튼을 다시 누른다. 그 순간 서버는 같은 일을 두 번 하게 되고, 느려서 생긴 재요청이 다시 서버를 느리게 만든다.\n\n지연을 재는 이유는 그래서다. 어느 마디에서 시간이 드는지 알아야 줄일 곳을 고를 수 있고, 줄일 수 없는 마디가 어디인지도 그때 드러난다."},"recap":"**\"하나가 갔다 오는 데 걸리는 그 시간\"** 이라고 읽으면 된다. 한 값처럼 보이지만 거리·처리·조회처럼 성격이 다른 조각들의 합이라, 어느 조각이 큰지 재지 않으면 줄일 수 없는 곳을 붙잡고 고치게 된다. 평균만 보면 오래 기다리는 소수가 통계 뒤에 숨는다.","kid":"편지를 부치면 답장이 올 때까지 며칠을 기다리는데, 전화는 말하는 순간 상대가 듣지? 그 기다리는 만큼이 이거야. 멀리 있으면 상대가 아무리 빨리 답해도 오가는 시간은 안 줄어들어서, 화면이 멈춰 있으면 사람들은 단추를 또 누르게 돼.","check":[{"q":"서버 사양을 올렸는데 응답 시간이 그대로라면 어디를 먼저 봐야 하나","at":"작동 원리"},{"q":"사용자는 느리다고 하는데 평균 응답 시간은 정상이라면 무엇을 놓친 것인가","at":"흔한 오해"},{"q":"서로 상관없는 조회 세 개를 차례로 부르면 왜 느려지나","at":"실제 사례"}],"myths":[{"wrong":"서버를 좋은 걸로 바꾸면 지연이 준다","right":"처리 시간만 준다. 거리 때문에 생기는 왕복이나 순서 때문에 생기는 대기는 그대로 남는다."},{"wrong":"평균 응답 시간이 괜찮으면 괜찮은 것이다","right":"평균은 느린 쪽을 가린다. 열 명 중 한 명이 3초를 기다려도 평균은 크게 움직이지 않는다."},{"wrong":"지연이 낮으면 처리량도 높다","right":"다른 값이다. 하나가 빨리 갔다 오는 것과 동시에 여럿을 감당하는 것은 각각 따로 막힌다."}],"cases":[{"label":"먼 나라 서버","note":"지구 반대편 서버를 부르면 회선에서만 왕복 시간이 붙는다. 코드를 고쳐도 이 부분은 줄지 않는다."},{"label":"같은 조회의 반복","note":"매번 DB에서 같은 값을 꺼내면 그때마다 대기가 생긴다. 캐시에 두면 그 왕복이 사라진다."},{"label":"차례로 기다리기","note":"서로 상관없는 조회 세 개를 순서대로 부르면 셋의 합이 되고, 동시에 걸면 가장 느린 하나가 된다."}],"dia":{"shape":"흐름","title":"검색 버튼을 누르고 결과가 뜰 때까지 어디서 시간이 드나","rows":[{"who":"브라우저","what":"요청을 만들어 보낸다"},{"who":"회선","what":"서버까지 물리적으로 오간다"},{"who":"서버","what":"요청을 받아 처리한다"},{"who":"DB","what":"조회하고 결과를 돌려준다"},{"who":"브라우저","what":"받은 것을 화면에 그린다","back":true}],"sum":"한 군데가 아니라 각 마디에서 쌓인 합이 사용자가 느끼는 시간이다"}},"arch--leader-election":{"definition":"수평 확장을 하면 같은 코드가 여러 벌 동시에 돈다. 이들은 전부 대등해서 자연스러운 우두머리가 없다. Azure 아키텍처 문서는 이 상태를 문제로 잡는다 — 서로 부딪히지 않게 하려면 한 대를 조율자로 뽑아야 하고, 둘 이상이 동시에 그 자리를 차지하는 일이 없도록 뽑는 과정 자체를 조심스럽게 다뤄야 한다.","name":"Leader :: 조율하는 한 대\nElection :: 뽑는 절차\n= 붙여 읽으면 \"조율할 한 대를 뽑는 절차\". 똑같은 것들 중 하나만 특별해진다","analogy":"학급에서 반장을 뽑는 일. 모두가 같은 학생이지만 한 명만 자리를 맡고, 그 학생이 결석하면 다시 뽑는다.","example":"새벽 정산 배치를 서버 세 대에 똑같이 올렸더니 정산이 세 번 돌아 버린 그 사고다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"대표 자리를 만드는 것은 **기한이 붙은 잠금**이다. 후보들이 같은 열쇠 하나를 잡으려 들면 저장소가 한 대에게만 성공을 돌려주고, 나머지는 실패를 받고 기다린다. 이 잠금에는 기한이 함께 걸려 있어서, 잡은 대가 아무 말 없이 사라져도 기한이 지나면 저절로 풀린다. 기한이 없으면 죽은 대표가 쥔 잠금이 잠긴 채로 남고, 사람이 들어와 풀어 주기 전까지 아무도 그 일을 못 한다.\n\n그래서 대표에게 일이 하나 더 붙는다. 기한이 끝나기 전에 잠금을 계속 연장하는 것이다. 연장 주기는 기한보다 넉넉히 짧게 잡는다. 한 번 실패해도 다음 기회가 남아 있어야, 잠깐 느려진 것만으로 자리가 넘어가는 일이 안 생긴다.\n\n기한의 길이가 곧 이 방식의 저울이다. 짧게 잡으면 대표가 죽었을 때 빨리 넘어가는 대신 네트워크가 잠시 흔들려도 자리가 바뀌고, 길게 잡으면 자리는 안정되지만 그 길이만큼 아무도 일하지 않는 시간이 생긴다. 대표가 스스로 물러날 때 잠금을 명시적으로 놓아주면 그 공백을 건너뛸 수 있다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교","body":"세 가지 방식이 있고, 각각 다른 것을 내준다.\n\n| 방식 | 어떻게 뽑나 | 무엇을 내주나 |\n|---|---|---|\n| **공유 잠금 경쟁** | 먼저 잡는 쪽이 대표 | 잠금을 파는 외부 서비스가 단일 장애점이 된다 |\n| **합의 알고리즘** | 후보끼리 서로 연락해 정한다 | 후보마다 고유 번호가 있고 서로 확실히 연락이 닿아야 한다 |\n| **전용 코디네이터** | 이 일만 하는 제품에 맡긴다 | 운영할 구성 요소가 하나 늘어난다 |\n\nAzure 문서가 예제로 보여주는 것은 첫 번째다. 저장소 blob 에 임차(lease, 기한이 붙은 독점 쓰기 잠금)를 걸어 분산 뮤텍스를 만들고, 임차를 먼저 얻은 쪽이 대표가 된다. 두 번째는 Raft 나 Bully 같은 알고리즘을 직접 구현하는 길이고, 손으로 구현하면 다듬을 여지가 가장 크다. 세 번째는 Apache ZooKeeper 처럼 이 일을 위해 만들어진 제품에 맡기는 길이다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **주기 작업 중복 방지** — 같은 배치를 여러 대에 올려두고, 대표를 잡은 한 대만 실제로 돌린다. 나머지는 대기하다가 대표가 사라지면 이어받는다.\n- **제어 평면 이중화** — 쿠버네티스는 무리 전체를 지휘하는 부품인 kube-controller-manager 와 kube-scheduler 를 여러 벌 띄우고, 리스(Lease) 객체를 잡은 한 벌만 활성으로 두고 나머지는 대기 상태로 둔다.\n- **쪼갠 계산 합치기** — 큰 계산을 여러 대가 조각내 나눠 돌리고 나면, 다 끝난 조각을 하나로 모을 쪽이 있어야 한다. 대등한 것들 사이에서 그 자리를 맡는 쪽이 대표다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **대표를 뽑아 놨으니 그 대표가 죽어도 알아서 넘어간다** — 넘어가려면 죽었다는 걸 누가 알아채야 한다. 하트비트나 폴링으로 대표를 지켜보지 않으면 아무도 새로 뽑지 않는다.\n- **대표가 살아 있으면 일도 돌아가고 있는 것이다** — 대표가 하던 일이 멈춰 선 채로 임차만 계속 갱신하면, 아무도 자리를 못 뺏고 일도 안 나간다. 살아 있음과 일하고 있음은 다르게 확인해야 한다.\n- **여러 대가 같은 자원을 건드리면 일단 리더를 뽑아야 한다** — 공유 자원 접근만 맞추면 되는 일이라면 낙관적·비관적 잠금이 더 가볍다. 항상 살아 있는 전용 프로세스처럼 자연스러운 대표가 이미 있으면 선출 자체가 필요 없다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **잠금을 파는 쪽이 단일 장애점이 된다.** 그 저장소가 안 열리면 아무도 대표가 못 되고, 시스템 전체가 조율자 없이 남는다.\n- **오토스케일이 대표를 내려버릴 수 있다.** 규모를 줄일 때 하필 대표가 내려가면 선출이 다시 돌고, 그동안 조율 작업은 멈춘다.\n- **대표를 병목으로 만들지 마라.** 대표가 할 일은 아랫일을 조율하는 것이지 일을 혼자 다 하는 것이 아니다.\n- **누가 뽑힐지는 정해지지 않는다.** 선출 결과는 비결정적이라, 특정 대가 대표가 될 것을 전제로 설계하면 안 된다."}],"figure":"```도해\n흐름: 대표는 어떻게 뽑히고 어떻게 바뀌나\n후보들 :: 같은 코드를 돌리는 여러 대가 동시에 자리를 노린다\n자리 잡기 :: 공유 잠금을 먼저 잡은 한 대가 대표가 된다\n일하기 :: 대표만 조율 작업을 돌리고 나머지는 대기한다\n갱신 :: 대표는 만료 전에 잠금을 계속 연장한다\n감지 :: 갱신이 끊기면 잠금이 풀리고 나머지가 알아챈다\n@ 다시 자리 잡기 :: 남은 것들이 달려들어 새 대표를 뽑는다\n= 대표는 임명되는 것이 아니라 잠금을 먼저 잡아서 되고, 놓으면 곧바로 바뀐다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 똑같은 여러 대에 대표를 안 두면 무엇이 벌어지나\n대표 없이 || 대표를 뽑으면\n새벽 배치 :: 대수만큼 돈다 || 한 번만 돈다\n공유 자원 :: 서로 덮어쓴다 || 한 대만 쓴다\n결과 모으기 :: 모을 쪽이 없다 || 대표가 모은다\n= 전부 대등하면 아무도 조율을 안 한다. 한 대만 특별하게 만드는 것이 선출이다\n```\n\n수평 확장은 \"같은 것을 여러 벌 띄운다\" 는 뜻이다. 사용자 요청을 나눠 받는 일에는 이게 딱 맞지만, 하루 한 번만 돌아야 하는 일에는 그대로 재앙이 된다. 세 대에 올린 배치는 세 번 돌고, 병렬로 쪼갠 계산은 다 끝난 뒤에 결과를 모을 쪽이 없다.\n\n선출은 이 문제를 \"누가 조율자인가\" 라는 하나의 물음으로 줄인다. 대등한 것들 사이에 딱 한 자리를 만들고, 그 자리를 누가 갖는지만 정하면 나머지 규칙은 따라온다. 자리를 가진 쪽만 일하고, 나머지는 자리가 빌 때까지 기다린다."},"recap":"**\"똑같은 것들 중 하나만 자리를 잡는 일\"** 이라고 읽으면 된다. 자리는 임명으로 생기는 것이 아니라 잠금을 먼저 잡아서 생기고, 그 잠금을 놓는 순간 자리도 넘어간다. 그러니 이 패턴을 고를 때 볼 것은 뽑는 방법이 아니라, 대표가 조용히 멈춘 것을 얼마나 빨리 알아채는지다.","kid":"모둠 청소를 하는데 아무도 반장이 아니면 다들 같은 칠판만 닦고 창문은 아무도 안 닦지? 그래서 분필을 먼저 집는 사람이 반장을 맡기로 정해 두고, 그 사람이 집에 가 버리면 분필이 바닥에 떨어져서 다음 사람이 집는 거야.","check":[{"q":"배치 작업을 서버 세 대에 똑같이 올렸더니 정산이 세 번 돌았다. 무엇이 빠졌나","at":"해결하는 문제"},{"q":"대표가 살아 있는데도 일이 안 나가고 다른 대는 끼어들지도 못하는 상황은 왜 생기나","at":"흔한 오해"},{"q":"잠금을 파는 저장소가 잠깐 안 열리면 시스템 전체는 어떻게 되나","at":"주의사항"}],"myths":[{"wrong":"대표를 뽑아 놨으니 그 대표가 죽어도 알아서 넘어간다","right":"넘어가려면 죽었다는 걸 누가 알아채야 한다. 하트비트나 폴링으로 대표를 지켜보지 않으면 아무도 새로 뽑지 않는다."},{"wrong":"대표가 살아 있으면 일도 돌아가고 있는 것이다","right":"대표가 하던 일이 멈춰 선 채로 임차만 계속 갱신하면, 아무도 자리를 못 뺏고 일도 안 나간다. 살아 있음과 일하고 있음은 다르게 확인해야 한다."},{"wrong":"여러 대가 같은 자원을 건드리면 일단 리더를 뽑아야 한다","right":"공유 자원 접근만 맞추면 되는 일이라면 낙관적·비관적 잠금이 더 가볍다. 항상 살아 있는 전용 프로세스처럼 자연스러운 대표가 이미 있으면 선출 자체가 필요 없다."}],"cases":[{"label":"주기 작업 중복 방지","note":"같은 배치를 여러 대에 올려두고, 대표를 잡은 한 대만 실제로 돌린다. 나머지는 대기하다가 대표가 사라지면 이어받는다."},{"label":"제어 평면 이중화","note":"쿠버네티스는 무리 전체를 지휘하는 부품인 kube-controller-manager 와 kube-scheduler 를 여러 벌 띄우고, 리스(Lease) 객체를 잡은 한 벌만 활성으로 두고 나머지는 대기 상태로 둔다."},{"label":"쪼갠 계산 합치기","note":"큰 계산을 여러 대가 조각내 나눠 돌리고 나면, 다 끝난 조각을 하나로 모을 쪽이 있어야 한다. 대등한 것들 사이에서 그 자리를 맡는 쪽이 대표다."}],"dia":{"shape":"흐름","title":"대표는 어떻게 뽑히고 어떻게 바뀌나","rows":[{"who":"후보들","what":"같은 코드를 돌리는 여러 대가 동시에 자리를 노린다"},{"who":"자리 잡기","what":"공유 잠금을 먼저 잡은 한 대가 대표가 된다"},{"who":"일하기","what":"대표만 조율 작업을 돌리고 나머지는 대기한다"},{"who":"갱신","what":"대표는 만료 전에 잠금을 계속 연장한다"},{"who":"감지","what":"갱신이 끊기면 잠금이 풀리고 나머지가 알아챈다"}],"sum":"대표는 임명되는 것이 아니라 잠금을 먼저 잡아서 되고, 놓으면 곧바로 바뀐다","loop":{"who":"다시 자리 잡기","what":"남은 것들이 달려들어 새 대표를 뽑는다"}}},"arch--load-balancing":{"definition":"서버 한 대가 감당할 수 있는 동시 요청 수는 정해져 있다. 그 앞에 나눠주는 장치를 두면 서버를 늘리는 것으로 처리량을 늘릴 수 있고, 한 대가 죽어도 나머지가 받는다.","name":"Load :: 짊어질 짐, 일감\nBalancing :: 고르게 나눔\n= 붙여 읽으면 \"일감을 고르게 나누기\". 한 대에 묶여 있던 일감을 여러 대로 흩는다","analogy":"마트 계산대 앞의 안내 직원. 줄 하나에 다 세우는 대신 비어 있는 계산대로 보낸다.","example":"새로 고칠 때마다 페이지 아래 찍힌 서버 번호가 달라지는 사이트를 본 적이 있다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"밸런서는 뒤에 있는 서버들에 주기적으로 신호를 보내 응답하는지 확인한다. 이 확인이 실패하면 그 서버를 목록에서 빼고, 다시 응답하면 되돌린다. 죽은 서버로 요청이 가지 않는 이유가 이것이다.\n\n살아 있는 서버 중 어디로 보낼지는 규칙이 정한다. 몇 가지가 흔하다.\n\n- **순서대로** — 1번, 2번, 3번, 다시 1번. 아무것도 보지 않아 가장 단순하다.\n- **연결 수** — 지금 붙어 있는 요청이 가장 적은 곳으로 보낸다.\n- **가중치** — 사양이 좋은 서버에 더 많이 보낸다.\n- **주소 해시** — 같은 사용자는 늘 같은 서버로 보낸다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **트래픽 증가 대응** — 접속이 늘면 서버를 몇 대 더 띄워 목록에 넣는다. 코드는 그대로다.\n- **무중단 배포** — 한 대씩 빼서 새 버전으로 바꾸고 되돌린다. 사용자 쪽에서는 끊긴 순간이 없다.\n- **장애 격리** — 서버 한 대가 응답을 멈추면 확인 신호에서 걸러져 목록에서 빠지고, 요청은 나머지로만 간다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **로드 밸런서를 붙이면 서버가 빨라진다** — 한 요청을 처리하는 속도는 그대로다. 늘어나는 것은 동시에 받을 수 있는 요청 수다.\n- **밸런서를 두면 장애가 없어진다** — 밸런서 자체가 죽으면 전부 멈춘다. 그래서 밸런서도 여러 대를 두거나 관리형 서비스를 쓴다.\n- **요청을 똑같이 나눠 주는 게 항상 좋다** — 요청마다 무게가 다르다. 무거운 요청이 한 서버에 몰릴 수 있어서 연결 수를 보고 고르는 규칙을 쓰기도 한다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **세션을 서버 메모리에 두면 깨진다.** 다음 요청이 다른 서버로 가면 로그인이 풀린다. 세션은 공용 저장소에 두는 편이 맞다.\n- **확인 신호를 너무 얕게 만들지 않는다.** 프로세스만 살아 있고 데이터베이스 연결이 끊긴 서버가 계속 요청을 받을 수 있다."}],"figure":"```도해\n흐름: 요청 하나가 어느 서버로 가는지 어떻게 정해지나\n사용자 :: 사이트 주소로 요청을 보낸다\nDNS :: 로드 밸런서의 주소를 알려준다\n밸런서 :: 살아 있는 서버 목록을 본다\n밸런서 :: 정해둔 규칙으로 한 대를 고른다\n서버 3 :: 요청을 처리해서 결과를 만든다\n< 밸런서 :: 결과를 사용자에게 전달한다\n= 사용자는 서버가 몇 대인지 끝내 모른다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 접속이 몰리면 어떻게 되나\n서버 한 대 || 밸런서 뒤에 여러 대\n동시 접속 :: 한 대가 다 받는다 || 나눠서 받는다\n한 대가 죽으면 :: 사이트가 멈춘다 || 나머지가 받는다\n배포 :: 잠깐 끊긴다 || 하나씩 교체\n= 한 대에 묶여 있던 처리량과 생존을 여러 대로 흩는 것이다\n```\n\n서버 한 대로 버티는 구조에서는 그 한 대가 곧 전체 한계다. 사양을 올리는 방법에는 끝이 있고, 올려도 그 한 대가 죽으면 사이트가 통째로 멈춘다.\n\n밸런서를 앞에 두면 서버 대수를 늘려 처리량을 늘릴 수 있다. 배포도 달라진다. 한 대씩 목록에서 빼고 새 버전으로 바꿔 넣으면 사용자 쪽에서는 끊기는 순간이 없다."},"recap":"**\"비어 있는 쪽으로 보내 주는 그 안내\"** 라고 읽으면 된다. 요청을 여러 서버에 나눠 보내 처리량과 생존을 한 대에서 떼어낸다. 한 요청의 처리 속도를 올려주지는 않고, 세션을 어디에 두느냐가 함께 정해져야 한다.","kid":"마트에서 다들 줄 하나에만 서 있으면 답답하지? 그래서 안내하는 사람이 비어 있는 계산대로 한 명씩 보내 줘. 계산하는 속도가 빨라지는 건 아니고, 같은 시간에 계산을 마치고 나가는 사람 수가 늘어나는 거야.","check":[{"q":"서버를 늘렸는데 페이지 하나 여는 시간이 그대로인 이유는","at":"흔한 오해"},{"q":"로그인이 자꾸 풀린다면 무엇이 잘못 놓여 있는 것인가","at":"주의사항"},{"q":"밸런서는 죽은 서버로 요청이 가지 않게 하려고 무엇을 하고 있나","at":"작동 원리"}],"myths":[{"wrong":"로드 밸런서를 붙이면 서버가 빨라진다","right":"한 요청을 처리하는 속도는 그대로다. 늘어나는 것은 동시에 받을 수 있는 요청 수다."},{"wrong":"밸런서를 두면 장애가 없어진다","right":"밸런서 자체가 죽으면 전부 멈춘다. 그래서 밸런서도 여러 대를 두거나 관리형 서비스를 쓴다."},{"wrong":"요청을 똑같이 나눠 주는 게 항상 좋다","right":"요청마다 무게가 다르다. 무거운 요청이 한 서버에 몰릴 수 있어서 연결 수를 보고 고르는 규칙을 쓰기도 한다."}],"cases":[{"label":"트래픽 증가 대응","note":"접속이 늘면 서버를 몇 대 더 띄워 목록에 넣는다. 코드는 그대로다."},{"label":"무중단 배포","note":"한 대씩 빼서 새 버전으로 바꾸고 되돌린다. 사용자 쪽에서는 끊긴 순간이 없다."},{"label":"장애 격리","note":"서버 한 대가 응답을 멈추면 확인 신호에서 걸러져 목록에서 빠지고, 요청은 나머지로만 간다."}],"dia":{"shape":"흐름","title":"요청 하나가 어느 서버로 가는지 어떻게 정해지나","rows":[{"who":"사용자","what":"사이트 주소로 요청을 보낸다"},{"who":"DNS","what":"로드 밸런서의 주소를 알려준다"},{"who":"밸런서","what":"살아 있는 서버 목록을 본다"},{"who":"밸런서","what":"정해둔 규칙으로 한 대를 고른다"},{"who":"서버 3","what":"요청을 처리해서 결과를 만든다"},{"who":"밸런서","what":"결과를 사용자에게 전달한다","back":true}],"sum":"사용자는 서버가 몇 대인지 끝내 모른다"}},"arch--mvc":{"definition":"가르는 목적은 하나다. 화면 쪽 로직은 자주 바뀌고 업무 규칙은 덜 바뀌는데, 둘이 한 덩어리에 있으면 화면을 손볼 때마다 업무 규칙이 든 코드를 고치게 되고 그때마다 다시 시험해야 한다.","name":"Model :: 자료와 업무 규칙\nView :: 보여 주는 쪽\nController :: 입력 받아 고르는 쪽\n= 붙여 읽으면 \"자료·보여주기·고르기\". 이름이 곧 세 덩어리의 목록이다","analogy":"학교 급식실. 조리실이 음식을 만들고, 배식대가 담아 내놓고, 당번이 줄을 세워 누가 언제 받을지 정한다.","example":"장보기 목록 앱에서 담기 단추를 누르면 목록이 바뀌고 화면이 다시 그려지는 그 순간이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"들어온 주소가 먼저 컨트롤러의 동작 하나로 이어진다. 그 동작은 입력을 꺼내 형식이 맞는지 보고, 맞으면 모델을 부른다. 모델은 업무 규칙을 따져 자료를 바꾸고 결과를 돌려준다. 컨트롤러는 그 결과를 보고 어느 뷰를 쓸지 고른 뒤 뷰가 그릴 자료를 넘긴다. 뷰는 넘겨받은 자료로 화면을 만들어 낸다.\n\n화면 고르기가 모델이 아니라 컨트롤러의 몫인 것이 이 순서의 요점이다. 같은 동작이라도 저장에 성공하면 목록으로, 규칙에 걸리면 입력 화면으로 돌아가야 한다. 그 갈림을 모델에 넣는 순간 모델이 화면 이름을 알게 되고, 화면 없이 규칙만 시험하던 이득이 거기서 끝난다.\n\n방향은 한쪽으로만 나 있다. 컨트롤러와 뷰는 모델을 부르지만 모델은 그 둘을 부르지 않고, 뷰는 넘겨받은 자료를 읽기만 하고 바꾸지 않는다. 자료가 바뀌었으면 그것은 이미 모델 안에서 끝난 일이고, 뷰는 바뀐 결과를 받아 다시 그릴 뿐이다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 셋으로 가르는 것만으로 어디까지 가나","body":"```도해\n대조: 셋으로 가르는 것만으로 언제까지 버티나\n폴더 셋으로 |=| 층까지 가를 때\n프로젝트 크기 :: 작고 단순하다 || 커지고 얽힌다\n업무 규칙 자리 :: 모델 폴더에 || 안쪽 프로젝트에\n드는 값 :: 지금이 싸다 || 나중이 싸다\n= 셋으로 가르는 것은 화면 쪽 정리다. 커지면 층을 한 번 더 갈라야 한다\n```\n\n작은 앱은 프로젝트 하나에 모델·뷰·컨트롤러 폴더를 두는 것만으로 충분하다. Microsoft 문서도 한 덩어리로 올리는 이 방식이 사내용이나 규모가 작은 공개 앱에 아주 잘 맞는다고 적는다.\n\n문제는 자랄 때 온다. 같은 문서는 프로젝트가 커지면 화면 관심사가 여러 폴더로 흩어지고, 업무 규칙이 모델 폴더와 서비스 폴더 사이에 널리고, 어느 폴더가 어느 폴더에 기대야 하는지 알 길이 없어진다고 적는다. 그 상태를 스파게티 코드로 가는 길이라 부른다. 그때 필요한 것은 MVC 를 더 잘 지키는 것이 아니라 **층을 한 번 더 가르는 것**이다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **주소 하나 처리하기** — 들어온 주소가 컨트롤러의 동작 하나로 이어지고, 그 동작이 모델을 부른 뒤 어떤 뷰를 쓸지 고른다.\n- **화면 개편** — 같은 모델 위에 뷰 파일만 갈아 끼우면 새 화면이 올라간다. 규칙은 손대지 않는다.\n- **같은 규칙 두 얼굴** — 같은 모델을 두고 사람이 볼 화면과 기계가 읽을 응답을 나란히 낸다. 컨트롤러가 어느 쪽으로 낼지만 고른다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **폴더를 셋으로 나눠 두면 그 자체로 잘 정리된 구조다** — Microsoft 문서는 규모가 커지면 화면 관심사가 여러 폴더로 흩어지고 업무 규칙이 모델과 서비스 사이에 널려 스파게티 코드로 간다고 적는다. 셋으로 가르는 것은 시작이지 끝이 아니다.\n- **컨트롤러가 화면을 그린다** — 아니다. 컨트롤러는 어느 뷰를 쓸지 고르고 필요한 자료를 넘길 뿐이다. 그리는 일은 뷰가 한다.\n- **모델은 자료를 담는 그릇이다** — 모델은 앱의 상태와 업무 규칙을 함께 담는다. 규칙을 컨트롤러에 두면 컨트롤러가 부풀고, 그러면 갈라 둔 값이 사라진다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **컨트롤러를 두껍게 만들지 마라.** Microsoft 문서는 컨트롤러가 책임을 너무 많이 지지 않게 하고, 업무 규칙은 도메인 모델 쪽으로 밀어내라고 적는다.\n- **뷰에 로직을 넣지 마라.** 같은 문서는 뷰 안의 로직을 최소로 두고 그마저도 보여주는 일에 관한 것만 남기라고 적는다. 뷰에서 계산이 길어지면 그건 모델이 할 일이다.\n- **방향이 뒤집히지 않게 지켜라.** 모델이 뷰나 컨트롤러를 알기 시작하면 화면 없이 규칙만 시험할 수 없게 된다. 갈라 둔 이득이 거기서 끝난다."}],"figure":"```도해\n흐름: 단추 하나를 누르면 셋 중 누가 먼저 움직이나\n사용자 :: 단추를 누른다\n컨트롤러 :: 그 입력이 닿는 첫 자리. 무엇을 할지 고른다\n모델 :: 자료를 바꾸고 업무 규칙을 따진다\n뷰 :: 컨트롤러가 고른 화면이 바뀐 자료를 그린다\n< 사용자 :: 새로 그려진 화면을 본다\n= 입력은 컨트롤러로 들어가 모델을 거쳐 뷰로 나온다. 모델은 나머지 둘을 모른다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 화면과 업무 규칙을 한 덩어리로 두면 무엇이 터지나\n안 가르면 || 셋으로 가르면\n단추 색만 바꿔도 :: 규칙까지 다시 본다 || 뷰만 고친다\n시험 :: 화면을 띄워야 || 모델만 돌린다\n나눠 맡기 :: 한 파일에서 겹친다 || 셋으로 갈린다\n= 자주 바뀌는 화면과 덜 바뀌는 규칙을 갈라 둔 것이다\n```\n\nMicrosoft 문서는 이유를 이렇게 적는다. 화면 로직은 업무 로직보다 자주 바뀐다. 둘이 한 객체에 섞여 있으면 화면을 조금 바꿀 때마다 업무 로직이 든 객체를 고쳐야 하고, 그래서 오류가 끼어들고 업무 로직을 매번 다시 시험하게 된다.\n\n방향이 한쪽으로만 나 있는 것도 이 절의 답이다. 뷰와 컨트롤러는 모델에 기대지만 모델은 뷰와 컨트롤러를 모른다. 그래서 모델은 화면 없이 따로 만들고 따로 시험할 수 있다. 하나만 하는 조각이 짜고 고치고 시험하기 쉬우니, 앱이 복잡해져도 감당이 된다."},"recap":"**\"입력·규칙·화면을 셋으로 갈라 둔 그 짜임새\"** 라고 읽으면 된다. 뷰와 컨트롤러는 모델을 알지만 모델은 둘을 모르고, 그 한 방향 덕에 규칙만 따로 시험된다. 앱이 커져 폴더 셋으로 감당이 안 되면 MVC 를 조이는 게 아니라 층을 한 번 더 가른다.","kid":"급식실을 떠올려 봐. 조리실은 음식을 만들고, 배식대는 그걸 담아 내놓고, 당번은 줄을 세워 누가 언제 받을지 정하지? 담는 접시를 바꾼다고 조리법까지 다시 쓰지는 않잖아.","check":[{"q":"단추 색 하나 바꾸는 일에 업무 규칙을 다시 시험하게 되는 까닭은 무엇인가","at":"해결하는 문제"},{"q":"컨트롤러에 업무 규칙을 계속 쌓으면 나중에 무엇이 어려워지나","at":"주의사항"},{"q":"폴더를 셋으로 나눠 두고도 프로젝트가 엉키기 시작하는 때는 언제인가","at":"비교"}],"myths":[{"wrong":"폴더를 셋으로 나눠 두면 그 자체로 잘 정리된 구조다","right":"Microsoft 문서는 규모가 커지면 화면 관심사가 여러 폴더로 흩어지고 업무 규칙이 모델과 서비스 사이에 널려 스파게티 코드로 간다고 적는다. 셋으로 가르는 것은 시작이지 끝이 아니다."},{"wrong":"컨트롤러가 화면을 그린다","right":"아니다. 컨트롤러는 어느 뷰를 쓸지 고르고 필요한 자료를 넘길 뿐이다. 그리는 일은 뷰가 한다."},{"wrong":"모델은 자료를 담는 그릇이다","right":"모델은 앱의 상태와 업무 규칙을 함께 담는다. 규칙을 컨트롤러에 두면 컨트롤러가 부풀고, 그러면 갈라 둔 값이 사라진다."}],"cases":[{"label":"주소 하나 처리하기","note":"들어온 주소가 컨트롤러의 동작 하나로 이어지고, 그 동작이 모델을 부른 뒤 어떤 뷰를 쓸지 고른다."},{"label":"화면 개편","note":"같은 모델 위에 뷰 파일만 갈아 끼우면 새 화면이 올라간다. 규칙은 손대지 않는다."},{"label":"같은 규칙 두 얼굴","note":"같은 모델을 두고 사람이 볼 화면과 기계가 읽을 응답을 나란히 낸다. 컨트롤러가 어느 쪽으로 낼지만 고른다."}],"dia":{"shape":"흐름","title":"단추 하나를 누르면 셋 중 누가 먼저 움직이나","rows":[{"who":"사용자","what":"단추를 누른다"},{"who":"컨트롤러","what":"그 입력이 닿는 첫 자리. 무엇을 할지 고른다"},{"who":"모델","what":"자료를 바꾸고 업무 규칙을 따진다"},{"who":"뷰","what":"컨트롤러가 고른 화면이 바뀐 자료를 그린다"},{"who":"사용자","what":"새로 그려진 화면을 본다","back":true}],"sum":"입력은 컨트롤러로 들어가 모델을 거쳐 뷰로 나온다. 모델은 나머지 둘을 모른다"}},"arch--message-queue":{"definition":"보내는 쪽은 줄에 넣고 바로 돌아온다. 받는 쪽은 자기 속도로 하나씩 꺼내 처리한다. 둘이 같은 시각에 살아 있지 않아도 된다.","name":"Message :: 남겨 둔 할 일 한 건\nQueue :: 차례를 기다리는 줄\n= 붙여 읽으면 \"할 일이 차례를 기다리는 줄\". 넣는 쪽과 꺼내는 쪽이 같은 시각에 살아 있지 않아도 된다","analogy":"음식점 주방의 주문서 꽂이. 홀 직원은 주문서를 꽂고 바로 다음 손님을 받는다. 주방은 꽂힌 순서대로 만든다. 주방이 바쁘다고 홀이 멈추지는 않는다.","example":"가입 완료 화면은 바로 떴는데 인증 메일은 몇 분 뒤에 도착하는 것이 줄에서 기다린 흔적이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"메시지를 넣는 쪽을 프로듀서, 꺼내 처리하는 쪽을 컨슈머라고 한다. 컨슈머를 여러 개 띄우면 줄이 그만큼 빨리 줄어든다.\n\n```도해\n흐름: 메시지 하나가 어디를 지나나\n프로듀서 :: 할 일을 만들어 큐에 넣는다\n큐 :: 순서대로 쌓아둔다. 여기가 완충 지대\n컨슈머 :: 하나씩 꺼내 처리한다\n< 컨슈머 :: 성공했다고 큐에 알려야 그때 지워진다\n= 확인이 오기 전까지 지우지 않는 덕에 컨슈머가 죽어도 일이 사라지지 않는다\n```\n\n처리에 실패한 메시지를 몇 번 재시도한 뒤에도 안 되면 따로 모아두는 곳을 둔다. 이걸 데드레터 큐라고 하고, 여기에 쌓인 것을 보는 게 운영의 절반이다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **알림 발송** — 이메일, 푸시, 문자를 큐에 넣고 워커가 처리한다. 실패하면 재시도한다.\n- **이미지 변환** — 업로드는 즉시 끝내고 썸네일 생성은 큐로 넘긴다.\n- **주문 처리** — 결제 완료 메시지를 큐에 넣으면 재고, 배송, 정산이 각자 꺼내 처리한다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **큐를 쓰면 빨라진다** — 전체 처리 시간은 그대로거나 오히려 길다. 짧아지는 건 사용자가 기다리는 시간뿐이다.\n- **순서가 항상 지켜진다** — 컨슈머를 여러 개 띄우면 처리 순서가 섞인다. 순서가 중요하면 키를 정해 같은 줄로 몰아야 한다.\n- **한 번만 처리된다** — 대부분의 큐는 \"최소 한 번\"을 보장한다. 같은 메시지가 두 번 올 수 있으니 두 번 처리해도 결과가 같게 만들어야 한다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **중복 처리를 대비한다.** 결제 메시지를 두 번 받아 두 번 결제하는 사고가 여기서 나온다. 처리한 메시지 ID를 기록해 걸러낸다.\n- **데드레터 큐를 본다.** 아무도 안 보면 실패한 일들이 조용히 쌓인다."}],"figure":"```도해\n흐름: 회원가입 뒤 메일 발송이 어떻게 분리되나\n사용자 :: 가입 버튼을 누른다\n가입 서비스 :: DB에 저장하고 \"메일 보내라\" 를 큐에 넣는다\n사용자 :: 가입 완료 화면을 즉시 본다\n메일 워커 :: 큐에서 하나 꺼낸다\n메일 워커 :: 메일을 보낸다. 3초 걸려도 상관없다\n= 사용자를 기다리게 하는 일과 아닌 일을 갈라놓는 것이 핵심이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 무거운 일을 그 자리에서 처리하면 어떻게 되나\n큐 없이 || 큐로\n응답 시간 :: 메일 시간까지 포함 || 저장만 하고 끝\n메일 서버 장애 :: 가입도 실패 || 가입은 성공\n갑작스런 몰림 :: 서버가 무너진다 || 줄이 길어질 뿐\n= 급한 일과 나중에 해도 되는 일을 갈라놓으면 둘 다 살아남는다\n```\n\n가입 처리 안에서 메일까지 보내면, 사용자는 메일이 나갈 때까지 화면 앞에서 기다린다. 메일 서버가 잠시 응답하지 않으면 가입 자체가 실패한다. 가입과 메일은 원래 함께 성공하거나 함께 실패할 이유가 없는 일이다.\n\n큐를 두면 가입은 저장까지만 책임지고 끝난다. 메일은 나중에 처리되고, 실패하면 다시 시도하면 된다. 트래픽이 몰려도 큐가 길어질 뿐 서버가 무너지지 않는다."},"recap":"**\"넣어두고 먼저 가는 그 줄\"** 이라고 읽으면 된다. 할 일을 줄에 넣어 보내는 쪽과 처리하는 쪽을 떼어놓는다. 사용자 응답은 빨라지고 장애는 번지지 않지만, 순서와 중복은 직접 챙겨야 한다.","kid":"음식점에서 홀 직원이 주문서를 주방에 꽂아 두고 바로 다음 손님을 받으러 가지? 주방이 아무리 바빠도 홀은 안 멈춰. 대신 음식은 꽂힌 순서가 올 때까지 기다렸다 나오니까, 자리에는 금방 앉아도 먹는 건 좀 뒤야.","check":[{"q":"큐를 넣었는데 전체 처리 시간이 안 줄었다면 정상인가","at":"흔한 오해"},{"q":"결제 메시지가 두 번 도착하면 무슨 일이 벌어지고, 어떻게 막나","at":"주의사항"},{"q":"컨슈머가 처리 도중 죽으면 그 메시지는 어떻게 되나","at":"작동 원리"}],"myths":[{"wrong":"큐를 쓰면 빨라진다","right":"전체 처리 시간은 그대로거나 오히려 길다. 짧아지는 건 사용자가 기다리는 시간뿐이다."},{"wrong":"순서가 항상 지켜진다","right":"컨슈머를 여러 개 띄우면 처리 순서가 섞인다. 순서가 중요하면 키를 정해 같은 줄로 몰아야 한다."},{"wrong":"한 번만 처리된다","right":"대부분의 큐는 \"최소 한 번\"을 보장한다. 같은 메시지가 두 번 올 수 있으니 두 번 처리해도 결과가 같게 만들어야 한다."}],"cases":[{"label":"알림 발송","note":"이메일, 푸시, 문자를 큐에 넣고 워커가 처리한다. 실패하면 재시도한다."},{"label":"이미지 변환","note":"업로드는 즉시 끝내고 썸네일 생성은 큐로 넘긴다."},{"label":"주문 처리","note":"결제 완료 메시지를 큐에 넣으면 재고, 배송, 정산이 각자 꺼내 처리한다."}],"dia":{"shape":"흐름","title":"회원가입 뒤 메일 발송이 어떻게 분리되나","rows":[{"who":"사용자","what":"가입 버튼을 누른다"},{"who":"가입 서비스","what":"DB에 저장하고 \"메일 보내라\" 를 큐에 넣는다"},{"who":"사용자","what":"가입 완료 화면을 즉시 본다"},{"who":"메일 워커","what":"큐에서 하나 꺼낸다"},{"who":"메일 워커","what":"메일을 보낸다. 3초 걸려도 상관없다"}],"sum":"사용자를 기다리게 하는 일과 아닌 일을 갈라놓는 것이 핵심이다"}},"arch--multi-tier-architecture":{"definition":"애저 아키텍처 센터는 이 짜임을 두 낱말로 갈라 설명한다. 계층(layer)은 책임을 나누는 선이고, 티어(tier)는 실제로 다른 기계에서 도는 경계다. AWS 백서는 가장 흔한 꼴로 세 층을 든다 — 사람이 직접 만지는 화면 층(presentation), 누른 것을 규칙대로 처리하는 논리 층(logic), 결과를 남기는 저장 층(data).","name":"Multi :: 여럿\nTier :: 따로 놓인 한 켜\nArchitecture :: 짜임새\n= 붙여 읽으면 \"여러 켜로 짠 구조\". 켜와 켜 사이의 선이 곧 기계와 기계 사이의 선이다","analogy":"음식점의 홀·주방·창고 — 손님은 홀에서만 말하고, 창고에는 주방을 거쳐야만 닿는다.","example":"로그인 화면은 멀쩡히 뜨는데 누르면 \"잠시 후 다시 시도해 주세요\" 만 나오던 날, 앞 층은 살아 있고 뒤 층이 죽은 것이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n대조: 위층이 아래층을 건너뛰어 불러도 되나\n닫힌 층 |=| 열린 층\n부를 수 있는 곳 :: 바로 아래만 || 아래 아무 층\n갈아 끼우기 :: 한 층씩 안전 || 얽힌 데가 는다\n거쳐 가는 값 :: 전달만 하는 층 || 없다\n= 닫으면 의존이 줄고 거쳐 가는 값이 늘고, 열면 그 반대다\n```\n\n계층과 티어는 다른 축이다. 한 티어에 여러 계층을 올려도 되고, 계층마다 티어를 따로 둬도 된다. 티어로 가르면 확장성과 회복력이 오르는 대신 그 사이가 망이라 지연이 붙는다 — 애저 문서가 티어를 나눌 때 반드시 함께 적는 맞바꿈이다.\n\n부르는 규칙에도 두 갈래가 있다. 닫힌 계층은 바로 아래 계층만 부를 수 있고, 열린 계층은 아래 아무 층이나 부를 수 있다. 닫으면 의존이 정리되는 대신 받은 것을 그대로 넘기기만 하는 층이 생기고, 열면 그 헛걸음은 없어지지만 얽힌 데가 늘어 나중에 한 층을 갈아 끼우기 어려워진다. 티어끼리도 같은 갈래가 있다 — 이웃을 하나씩 거치는 엄격한 쪽과 건너뛸 수 있는 느슨한 쪽이다.\n\n곧바로 부르는 대신 메시지 줄을 사이에 두면 층 사이가 느슨해진다. 애저 문서가 이 짜임의 모범 사례에 \"티어를 떼어 놓으려면 비동기 메시징을 쓰라\" 를 올려 두는 이유가 이것이다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 계층과 티어는 무엇이 다른가","body":"| | 계층 (layer) | 티어 (tier) |\n|---|---|---|\n| **무엇을 가르나** | 책임 | 기계 |\n| **어디서 갈리나** | 코드 안 | 망 위 |\n| **가르면 드는 값** | 없다 | 부를 때마다 지연 |\n| **가르면 얻는 것** | 의존이 정리된다 | 따로 늘리고 따로 막는다 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **서브넷으로 층 가르기** — 층마다 다른 서브넷에 두고 저장 층은 처리 층에서 온 것만 받게 막는다. 층 경계가 곧 방화벽 경계가 된다.\n- **붐비는 층만 늘리기** — 화면 층 앞에 부하 분산기를 두고 그 층만 여러 대로 불린다. 저장 층은 그대로 둔다.\n- **옛 앱 그대로 옮기기** — 이미 층으로 갈라진 사내 앱은 손을 거의 안 대고 클라우드로 옮길 수 있다. 애저 문서가 이 짜임을 권하는 대표 상황이다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **층을 나눴으니 마이크로서비스다** — 아니다. 층으로 갈라도 배포는 여전히 한 덩어리인 경우가 많고, 애저 문서는 이 짜임의 약점으로 기능을 따로 배포하지 못하는 점을 든다.\n- **층은 많을수록 좋다** — 받은 것을 그대로 아래로 넘기기만 하는 층은 지연과 코드만 늘린다. 애저 문서가 이 짜임의 첫 번째 함정으로 적는 것이 바로 그런 중간 층이다.\n- **계층과 티어는 같은 말이다** — 계층은 코드 안의 책임 경계고 티어는 다른 기계라는 경계다. 한 기계에 세 계층을 다 올리면 계층은 셋인데 티어는 하나다."}],"figure":"```도해\n층: 여러 층 구조는 무엇을 무엇 위에 올린 것인가\n화면 층 :: 사람이 직접 보고 누르는 자리\n처리 층 :: 누른 것을 규칙에 맞게 처리한다\n저장 층 :: 결과를 오래 남겨 두는 자리\n= 위는 사람에 가깝고 아래는 자료에 가깝다. 위층은 아래층을 부르지만 그 반대는 없다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 층을 안 가르면 무엇이 달라지나\n한 덩어리 || 층으로 갈라\n바꿀 때 :: 전부 다시 올린다 || 그 층만 손댄다\n늘릴 때 :: 통째로 늘린다 || 붐비는 층만\n막을 때 :: 다 같은 자리다 || 층마다 막는다\n= 층은 기능을 나누는 선이 아니라, 따로 바꾸고 따로 늘리고 따로 막는 경계다\n```\n\n한 덩어리로 두면 화면 글자 하나를 고쳐도 저장까지 통째로 다시 올려야 한다. 화면만 붐비는 날에도 전부를 함께 늘려야 하고, 바깥에서 들어온 것이 곧바로 저장까지 닿는다. 셋이 다른 요구를 갖는데 경계가 하나뿐이라서 생기는 일이다.\n\n층을 가르면 이 셋이 각각 제 경계를 얻는다. 애저 문서는 티어마다 제 서브넷에 두고 서브넷을 보안 경계로 쓰라고 적고, 저장 층은 처리 층에서 온 것만 받게 하라고 적는다. AWS 백서도 이 짜임의 값어치를 \"따로 개발하고 따로 관리하고 따로 늘릴 수 있게 하는 틀\" 로 적는다. **층은 기능의 분류가 아니라 경계의 개수다.**"},"recap":"**\"화면·처리·저장을 따로 세운 켜\"** 라고 읽으면 된다. 켜를 가르는 값은 부를 때마다 붙는 지연이고, 얻는 것은 따로 바꾸고 따로 늘리고 따로 막을 수 있는 경계다. 그러니 층을 하나 더 세울 때는 그 층이 무슨 경계를 새로 주는지부터 물어야 한다.","kid":"음식점에 가면 손님은 홀에만 있고, 요리는 주방에서 하고, 재료는 창고에 쌓아 두지? 이렇게 갈라 두면 홀만 넓히거나 주방만 고칠 수 있고, 손님이 창고에 함부로 들어가는 일도 없어. 다 한방에 몰아 두면 의자 하나 옮기려 해도 가게 문을 통째로 닫아야 해.","check":[{"q":"화면만 붐비는 날에도 전부를 함께 늘려야 했던 이유는","at":"해결하는 문제"},{"q":"층을 하나 더 세웠는데 느려지기만 하는 경우는 왜 생기나","at":"흔한 오해"},{"q":"층이 셋인데 기계는 한 대일 수도 있는 이유는","at":"비교"}],"myths":[{"wrong":"층을 나눴으니 마이크로서비스다","right":"아니다. 층으로 갈라도 배포는 여전히 한 덩어리인 경우가 많고, 애저 문서는 이 짜임의 약점으로 기능을 따로 배포하지 못하는 점을 든다."},{"wrong":"층은 많을수록 좋다","right":"받은 것을 그대로 아래로 넘기기만 하는 층은 지연과 코드만 늘린다. 애저 문서가 이 짜임의 첫 번째 함정으로 적는 것이 바로 그런 중간 층이다."},{"wrong":"계층과 티어는 같은 말이다","right":"계층은 코드 안의 책임 경계고 티어는 다른 기계라는 경계다. 한 기계에 세 계층을 다 올리면 계층은 셋인데 티어는 하나다."}],"cases":[{"label":"서브넷으로 층 가르기","note":"층마다 다른 서브넷에 두고 저장 층은 처리 층에서 온 것만 받게 막는다. 층 경계가 곧 방화벽 경계가 된다."},{"label":"붐비는 층만 늘리기","note":"화면 층 앞에 부하 분산기를 두고 그 층만 여러 대로 불린다. 저장 층은 그대로 둔다."},{"label":"옛 앱 그대로 옮기기","note":"이미 층으로 갈라진 사내 앱은 손을 거의 안 대고 클라우드로 옮길 수 있다. 애저 문서가 이 짜임을 권하는 대표 상황이다."}],"dia":{"shape":"층","title":"여러 층 구조는 무엇을 무엇 위에 올린 것인가","rows":[{"who":"화면 층","what":"사람이 직접 보고 누르는 자리"},{"who":"처리 층","what":"누른 것을 규칙에 맞게 처리한다"},{"who":"저장 층","what":"결과를 오래 남겨 두는 자리"}],"sum":"위는 사람에 가깝고 아래는 자료에 가깝다. 위층은 아래층을 부르지만 그 반대는 없다"}},"arch--pipeline":{"definition":"앞 단계의 결과가 뒤 단계의 입력이 된다. 단계마다 맡은 일이 하나씩이라 어디서 멈췄는지 바로 보이고, 멈춘 자리부터 다시 돌릴 수 있다.","name":"Pipe :: 흘려보내는 관\nline :: 죽 이어 놓은 줄\n= 붙여 읽으면 \"죽 이어 놓은 관\". 앞자리가 내놓은 것이 다음 자리로 그대로 흘러 들어간다","analogy":"공장 컨베이어 벨트. 한 사람이 완제품을 만들지 않고, 각 자리가 자기 몫만 하고 다음으로 넘긴다.","example":"올린 영상이 한동안 저화질로만 보이다가 고화질이 뒤늦게 열리는 것이 단계가 차례로 도는 모습이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"단계 사이에는 지켜야 할 것이 하나 있다. 앞 단계가 내놓는 형태와 뒤 단계가 받는 형태가 맞아야 한다. 이 약속이 지켜지면 중간에 단계를 끼워 넣거나 빼도 나머지는 그대로 돈다.\n\n실행하는 방법은 여러 가지다. 함수를 정해진 순서로 부르는 것도 파이프라인이고, CI/CD 도구에 build, test, deploy 를 적어두고 도구가 순서와 실패 처리를 맡게 하는 것도 파이프라인이다. 앞의 결과를 뒤가 받는다는 뼈대는 같다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **CI/CD** — 커밋이 올라오면 빌드, 테스트, 배포가 차례로 돈다. 테스트에서 멈추면 배포는 시작조차 하지 않는다.\n- **데이터 처리** — 수집, 정제, 변환, 저장을 나눠 두고 매일 정해진 시각에 돌린다. 변환에서 실패하면 그 단계부터 다시 돌린다.\n- **이미지 업로드** — 올린 파일을 검사하고, 크기를 줄이고, 저장소에 넣고, 주소를 DB에 적는 순서로 흘려보낸다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **파이프라인으로 바꾸면 빨라진다** — 단계를 나눈다고 총 작업량이 줄지는 않는다. 얻는 것은 멈춘 자리를 알고 거기서부터 다시 돌릴 수 있다는 것이다.\n- **단계는 잘게 나눌수록 좋다** — 단계마다 넘기고 받는 비용이 붙는다. 같이 실패하고 같이 다시 돌려야 하는 일은 한 단계에 두는 편이 낫다.\n- **파이프라인은 CI/CD 를 가리키는 말이다** — CI/CD 가 파이프라인을 쓰는 한 가지 경우일 뿐이다. 데이터 처리나 이미지 변환에도 같은 구조가 쓰인다."}],"figure":"```도해\n흐름: 원본 데이터가 저장되기까지 무엇을 거치나\n수집 :: 여기저기서 원본 데이터를 가져온다\n정제 :: 빠진 값과 중복을 걷어낸다\n변환 :: 쓰기 좋은 형태로 바꾼다\n집계 :: 필요한 단위로 묶어 계산한다\n저장 :: 결과를 목적지에 넣는다\n재실행 :: 실패한 단계부터만 다시 돌린다\n= 나뉘어 있으니 어디서 멈췄는지와 어디부터 다시 할지를 알 수 있다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 전부 한 스크립트에 적어두면 무엇이 달라지나\n한 덩어리로 || 파이프라인으로\n실패했을 때 :: 처음부터 다시 || 그 단계부터\n멈춘 자리 :: 로그를 뒤진다 || 단계가 표시됨\n한 곳만 수정 :: 전체를 건드림 || 그 단계만\n= 나누는 값은 속도가 아니라 되돌릴 수 있다는 것이다\n```\n\n데이터를 받아 정제하고 변환해서 저장하는 일을 스크립트 하나에 다 적으면, 세 시간짜리 작업이 마지막 저장에서 실패했을 때 처음부터 다시 돌려야 한다. 어디가 문제였는지도 로그를 처음부터 읽어야 안다.\n\n파이프라인은 그 일을 끊어놓는다. 단계마다 성공과 실패가 따로 기록되므로 실패한 곳부터 다시 돌릴 수 있고, 정제 방식만 바꾸고 싶을 때 그 단계만 손대면 된다."},"recap":"**\"앞이 내놓은 것을 뒤가 받는 그 줄\"** 이라고 읽으면 된다. 나누는 이유는 속도가 아니라 어디서 멈췄는지 알고 거기서부터 다시 돌리기 위해서다. 단계 사이에 주고받는 형태만 맞으면 중간을 갈아 끼울 수 있다.","kid":"공장에서는 한 사람이 물건을 처음부터 끝까지 다 만들지 않고, 벨트를 따라 자리마다 자기 몫만 하고 다음 자리로 넘기지? 그러면 어느 자리에서 잘못됐는지 딱 보여. 그 자리부터 다시 하면 되니까 처음부터 도로 만들지 않아도 돼.","check":[{"q":"세 시간짜리 작업이 마지막 단계에서 실패했다. 파이프라인이면 무엇이 달라지나","at":"해결하는 문제"},{"q":"단계를 무조건 잘게 나누면 왜 손해가 생기나","at":"흔한 오해"},{"q":"중간 단계 하나를 갈아 끼워도 나머지가 그대로 도는 조건은","at":"작동 원리"}],"myths":[{"wrong":"파이프라인으로 바꾸면 빨라진다","right":"단계를 나눈다고 총 작업량이 줄지는 않는다. 얻는 것은 멈춘 자리를 알고 거기서부터 다시 돌릴 수 있다는 것이다."},{"wrong":"단계는 잘게 나눌수록 좋다","right":"단계마다 넘기고 받는 비용이 붙는다. 같이 실패하고 같이 다시 돌려야 하는 일은 한 단계에 두는 편이 낫다."},{"wrong":"파이프라인은 CI/CD 를 가리키는 말이다","right":"CI/CD 가 파이프라인을 쓰는 한 가지 경우일 뿐이다. 데이터 처리나 이미지 변환에도 같은 구조가 쓰인다."}],"cases":[{"label":"CI/CD","note":"커밋이 올라오면 빌드, 테스트, 배포가 차례로 돈다. 테스트에서 멈추면 배포는 시작조차 하지 않는다."},{"label":"데이터 처리","note":"수집, 정제, 변환, 저장을 나눠 두고 매일 정해진 시각에 돌린다. 변환에서 실패하면 그 단계부터 다시 돌린다."},{"label":"이미지 업로드","note":"올린 파일을 검사하고, 크기를 줄이고, 저장소에 넣고, 주소를 DB에 적는 순서로 흘려보낸다."}],"dia":{"shape":"흐름","title":"원본 데이터가 저장되기까지 무엇을 거치나","rows":[{"who":"수집","what":"여기저기서 원본 데이터를 가져온다"},{"who":"정제","what":"빠진 값과 중복을 걷어낸다"},{"who":"변환","what":"쓰기 좋은 형태로 바꾼다"},{"who":"집계","what":"필요한 단위로 묶어 계산한다"},{"who":"저장","what":"결과를 목적지에 넣는다"},{"who":"재실행","what":"실패한 단계부터만 다시 돌린다"}],"sum":"나뉘어 있으니 어디서 멈췄는지와 어디부터 다시 할지를 알 수 있다"}},"arch--pub-sub":{"definition":"보내는 쪽은 누가 받는지 모른다. 받는 쪽은 누가 보냈는지 모른다. 둘 사이에 주제만 있고, 그래서 받는 쪽을 추가해도 보내는 쪽 코드는 그대로다.","name":"Publish :: 널리 펴서 알림\nSubscribe :: 받아 보겠다고 적어 둠\n= 붙여 읽으면 \"알리는 쪽과 받아 보겠다 적어 둔 쪽\". 둘 사이에 주제만 있고 서로는 모른다","analogy":"잡지 구독. 출판사는 구독자 명단을 신경 쓰지 않고 발행만 한다. 새 구독자가 늘어도 인쇄 방식은 바뀌지 않고, 구독을 끊어도 출판사는 하던 일을 계속한다.","example":"주문 한 번에 문자와 앱 알림과 메일이 제각기 도착하는 것이 소식 하나를 여럿이 받아간 모양이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"[[Message Queue]]와 자주 헷갈리는데, 메시지 하나를 몇 곳이 받느냐가 다르다.\n\n| | 큐 | Pub/Sub |\n|---|---|---|\n| 한 메시지를 | 한 곳이 가져간다 | 구독한 곳 전부가 받는다 |\n| 목적 | 일을 나눠서 처리 | 소식을 퍼뜨리기 |\n| 예 | 이미지 변환 작업 | 주문 완료 알림 |\n\n구독자가 잠시 죽었을 때 그동안의 소식을 나중에 받을지, 그냥 놓칠지도 정해야 한다. 놓치면 안 되는 소식이면 구독자마다 별도의 저장 공간을 두는 방식을 쓴다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **이벤트 기반 아키텍처** — 상태가 바뀔 때마다 소식을 발행하고 각 서비스가 알아서 반응한다.\n- **실시간 화면 갱신** — 서버가 변경 사항을 발행하면 접속 중인 브라우저들이 각자 받아 화면을 고친다.\n- **로그 수집** — 여러 서비스가 같은 주제로 로그를 발행하고, 저장용과 분석용이 각각 구독한다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **Pub/Sub과 큐는 같은 것이다** — 큐는 한 메시지를 한 곳이 가져가고, Pub/Sub은 구독한 전부가 받는다. 일을 나누려는데 Pub/Sub을 쓰면 같은 일이 세 번 처리된다.\n- **발행하면 무조건 전달된다** — 구독자가 죽어 있으면 놓칠 수 있다. 놓치면 안 되는 소식은 저장 방식을 따로 정해야 한다.\n- **결합이 완전히 사라진다** — 주제 이름과 메시지 모양에 여전히 묶여 있다. 메시지 구조를 바꾸면 구독자가 전부 깨진다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **메시지 모양을 함부로 바꾸지 않는다.** 구독자가 누구인지 모르기 때문에 무엇이 깨지는지도 모른다. 필드는 더하기만 하고 빼지 않는 쪽이 안전하다.\n- **흐름을 추적하기 어렵다.** 요청 하나가 어디까지 퍼졌는지 보려면 추적 ID를 메시지에 넣고 끝까지 따라가야 한다."}],"figure":"```도해\n흐름: 주문 하나가 여러 서비스에 어떻게 퍼지나\n주문 서비스 :: \"주문 완료\" 를 주제에 발행한다\n주제 :: 이 주제를 구독한 곳 모두에게 복사해 보낸다\n구독자들 :: 재고·배송·알림이 저마다 받는다. 순서도 없고 서로 모른다\n새 구독자 :: 나중에 붙어도 주제만 구독하면 끝난다\n= 구독자를 하나 더 붙여도 주문 서비스는 고칠 게 없다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 주문 완료를 세 곳에 알려야 할 때 무엇이 달라지나\n직접 호출 || Pub/Sub\n새 기능 추가 :: 주문 코드 수정 || 구독만 추가\n한 곳 장애 :: 주문도 실패 || 그곳만 밀린다\n아는 대상 :: 세 곳을 다 안다 || 주제만 안다\n= 보내는 쪽이 받는 쪽을 모르게 만드는 것이 이 방식의 전부다\n```\n\n주문이 끝났을 때 재고, 배송, 알림을 차례로 부르면 주문 코드가 그 셋을 전부 알게 된다. 나중에 정산 서비스가 생기면 주문 코드를 또 고쳐야 하고, 셋 중 하나가 죽으면 주문 자체가 실패한다.\n\n발행-구독으로 바꾸면 주문은 \"주문이 끝났다\"는 사실만 알린다. 누가 그 소식으로 무엇을 하든 주문이 알 바가 아니다. 새 서비스는 구독만 시작하면 된다."},"recap":"**\"누가 받는지 모른 채 내놓는 그 소식\"** 이라고 읽으면 된다. 소식을 주제에 발행하면 구독한 쪽들이 각자 받아 간다. 보내는 쪽과 받는 쪽이 서로를 몰라도 되지만, 그 대가로 무엇이 어디까지 갔는지 추적하기 어려워진다.","kid":"잡지 만드는 곳은 누가 사 볼지 하나하나 세지 않고 그냥 찍어 내지? 보고 싶은 사람이 받아 보겠다고 적어 두면 그때부터 집으로 와. 그래서 보는 사람이 하나 늘어도 잡지 만드는 쪽은 아무것도 안 바꿔도 돼.","check":[{"q":"이미지 변환 작업을 Pub/Sub으로 돌리면 무엇이 잘못되나","at":"흔한 오해"},{"q":"정산 서비스를 새로 붙일 때 주문 서비스를 고쳐야 하나","at":"해결하는 문제"},{"q":"메시지에 필드를 하나 빼면 왜 위험한가","at":"주의사항"}],"myths":[{"wrong":"Pub/Sub과 큐는 같은 것이다","right":"큐는 한 메시지를 한 곳이 가져가고, Pub/Sub은 구독한 전부가 받는다. 일을 나누려는데 Pub/Sub을 쓰면 같은 일이 세 번 처리된다."},{"wrong":"발행하면 무조건 전달된다","right":"구독자가 죽어 있으면 놓칠 수 있다. 놓치면 안 되는 소식은 저장 방식을 따로 정해야 한다."},{"wrong":"결합이 완전히 사라진다","right":"주제 이름과 메시지 모양에 여전히 묶여 있다. 메시지 구조를 바꾸면 구독자가 전부 깨진다."}],"cases":[{"label":"이벤트 기반 아키텍처","note":"상태가 바뀔 때마다 소식을 발행하고 각 서비스가 알아서 반응한다."},{"label":"실시간 화면 갱신","note":"서버가 변경 사항을 발행하면 접속 중인 브라우저들이 각자 받아 화면을 고친다."},{"label":"로그 수집","note":"여러 서비스가 같은 주제로 로그를 발행하고, 저장용과 분석용이 각각 구독한다."}],"dia":{"shape":"흐름","title":"주문 하나가 여러 서비스에 어떻게 퍼지나","rows":[{"who":"주문 서비스","what":"\"주문 완료\" 를 주제에 발행한다"},{"who":"주제","what":"이 주제를 구독한 곳 모두에게 복사해 보낸다"},{"who":"구독자들","what":"재고·배송·알림이 저마다 받는다. 순서도 없고 서로 모른다"},{"who":"새 구독자","what":"나중에 붙어도 주제만 구독하면 끝난다"}],"sum":"구독자를 하나 더 붙여도 주문 서비스는 고칠 게 없다"}},"arch--rate-limiting":{"definition":"한 사용자가 1분에 60번까지만 부를 수 있게 정해두면, 61번째부터는 처리하지 않고 거절한다. 서버를 지키는 가장 싸고 확실한 방법이다.","name":"Rate :: 정해진 동안의 횟수\nLimiting :: 상한을 두어 막음\n= 붙여 읽으면 \"정해진 동안의 횟수에 상한 두기\". 총 몇 번이 아니라 얼마 동안 몇 번인지를 잰다","analogy":"놀이공원의 1인당 탑승 제한. 한 사람이 계속 타면 뒤에 선 사람들이 영원히 못 탄다. 제한은 특정인을 막으려는 게 아니라 줄이 돌아가게 하려는 것이다.","example":"인증번호 재전송 단추가 잠긴 채 60초를 세고 있는 그 화면이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"세는 방식이 몇 가지 있다.\n\n| 방식 | 어떻게 세나 | 특징 |\n|---|---|---|\n| 고정 창 | 1분 단위로 끊어서 센다 | 단순하지만 경계에서 두 배가 몰린다 |\n| 슬라이딩 창 | 지금부터 1분 전까지를 센다 | 고르지만 계산이 무겁다 |\n| 토큰 버킷 | 토큰을 채워두고 쓸 때마다 뺀다 | 순간적인 몰림을 허용한다 |\n\n거절할 때는 `429` 상태 코드와 함께 `Retry-After` 헤더로 언제 다시 오면 되는지 알려준다. 그래야 클라이언트가 무작정 재시도하지 않는다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **공개 API 등급** — 무료는 시간당 100번, 유료는 10,000번처럼 요금제와 묶는다.\n- **로그인 보호** — 같은 계정에 실패가 다섯 번 쌓이면 잠시 막는다.\n- **문자 인증 발송** — 한 번호에 하루 몇 건으로 제한한다. 비용이 실제로 나가는 기능이라 안 막으면 그대로 요금이 된다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **제한을 걸면 사용자가 불편해진다** — 제한이 없을 때 모두가 느려지는 쪽이 훨씬 불편하다. 잘 잡은 한도는 정상 사용자에게 닿지 않는다.\n- **IP 단위로 막으면 충분하다** — 회사나 학교는 수백 명이 한 IP를 쓴다. 계정이나 API 키 단위로 세는 게 정확하다.\n- **`429`는 서버 오류다** — 서버는 멀쩡하다. 의도대로 거절한 것이라 재시도하면 통과한다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **서버가 여러 대면 횟수도 같이 세야 한다.** 서버마다 따로 세면 서버 수만큼 한도가 늘어난다. Redis 같은 공용 저장소에 센다.\n- **`Retry-After`를 빼먹지 않는다.** 언제 다시 오라는 말이 없으면 클라이언트가 바로 다시 두드린다."}],"figure":"```도해\n흐름: 한도를 넘은 요청은 어떻게 처리되나\n사용자 :: 1분 사이에 61번째 요청을 보낸다\n제한기 :: 이 사용자의 이번 분 횟수를 센다\n제한기 :: 60을 넘었다\n제한기 :: `429 Too Many Requests` 로 거절한다\n< 사용자 :: 얼마 뒤 다시 오라는 안내를 받는다\n= 서버가 무너지는 대신 요청 하나가 거절되는 쪽을 고르는 것이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 제한이 없으면 무슨 일이 생기나\n제한 없이 || 제한으로\n한 사용자 폭주 :: 전체가 느려진다 || 그 사람만 막힌다\n비밀번호 대입 :: 무한정 시도 || 몇 번 뒤 차단\n서버 비용 :: 예측 불가 || 상한이 생긴다\n= 최악의 사용자 한 명이 전체 품질을 정하지 못하게 만든다\n```\n\n공개된 API에는 반드시 잘못 쓰는 쪽이 생긴다. 반복문 안에서 실수로 초당 수천 번 부르는 경우가 대부분이고, 일부러 부하를 거는 경우도 있다. 제한이 없으면 그 한 명 때문에 나머지 전원이 느려진다.\n\n보안 측면도 크다. 로그인 요청에 제한이 없으면 비밀번호를 무한정 대입할 수 있다. 다섯 번으로 막으면 그 공격 자체가 성립하지 않는다."},"recap":"**\"한 사람이 얼마 동안 몇 번까지인지 정해 둔 그 상한\"** 이라고 읽으면 된다. 서버를 지키고 무차별 대입을 막으며, 거절할 때는 언제 다시 오면 되는지 함께 알려주어야 한다.","kid":"놀이공원에서 한 사람이 같은 기구만 계속 타면 뒤에 선 애들은 영영 못 타지? 그래서 한 사람당 몇 번까지만 타게 정해 둬. 그 수를 넘겨서 또 오면 지금은 안 된다고 하고, 얼마 있다 다시 오라고 알려 줘.","check":[{"q":"서버를 세 대로 늘렸더니 실제 한도가 세 배가 됐다면 왜 그런가","at":"주의사항"},{"q":"회사 사무실에서 일부 사용자만 막힌다면 무엇을 기준으로 세고 있을 가능성이 큰가","at":"흔한 오해"},{"q":"`429`를 받은 클라이언트가 곧바로 다시 요청하게 만드는 실수는 무엇인가","at":"작동 원리"}],"myths":[{"wrong":"제한을 걸면 사용자가 불편해진다","right":"제한이 없을 때 모두가 느려지는 쪽이 훨씬 불편하다. 잘 잡은 한도는 정상 사용자에게 닿지 않는다."},{"wrong":"IP 단위로 막으면 충분하다","right":"회사나 학교는 수백 명이 한 IP를 쓴다. 계정이나 API 키 단위로 세는 게 정확하다."},{"wrong":"`429`는 서버 오류다","right":"서버는 멀쩡하다. 의도대로 거절한 것이라 재시도하면 통과한다."}],"cases":[{"label":"공개 API 등급","note":"무료는 시간당 100번, 유료는 10,000번처럼 요금제와 묶는다."},{"label":"로그인 보호","note":"같은 계정에 실패가 다섯 번 쌓이면 잠시 막는다."},{"label":"문자 인증 발송","note":"한 번호에 하루 몇 건으로 제한한다. 비용이 실제로 나가는 기능이라 안 막으면 그대로 요금이 된다."}],"dia":{"shape":"흐름","title":"한도를 넘은 요청은 어떻게 처리되나","rows":[{"who":"사용자","what":"1분 사이에 61번째 요청을 보낸다"},{"who":"제한기","what":"이 사용자의 이번 분 횟수를 센다"},{"who":"제한기","what":"60을 넘었다"},{"who":"제한기","what":"`429 Too Many Requests` 로 거절한다"},{"who":"사용자","what":"얼마 뒤 다시 오라는 안내를 받는다","back":true}],"sum":"서버가 무너지는 대신 요청 하나가 거절되는 쪽을 고르는 것이다"}},"arch--retry-exponential-backoff":{"definition":"클라우드에서 나는 실패의 상당수는 잠깐 났다 스스로 낫는 것들이다 — 순간 끊긴 연결, 잠시 바쁜 상대, 요청량을 넘겨 돌아온 거절. 애저 문서는 이런 실패를 \"일시적 결함\" 이라 부르고, 적당히 기다렸다 같은 일을 다시 하면 대개 성공한다고 적는다.","name":"Retry :: 다시 걸기\nExponential :: 갑절씩 커지는\nBackoff :: 물러나 기다리기\n= 붙여 읽으면 \"물러나 기다리는 시간을 갑절씩 늘리며 다시 걸기\". 이름이 곧 규칙이다","analogy":"통화 중인 친구에게 1분 뒤, 2분 뒤, 4분 뒤로 간격을 늘려 가며 다시 거는 일.","example":"\"일시적인 오류입니다. 다시 시도해 주세요\" 를 눌렀더니 두 번째에는 그냥 되던 그 순간이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"기다림을 어떻게 늘릴지는 그림이 말했다. 남은 것은 셋이다 — 무엇을 다시 걸지, 두 번 걸려도 괜찮은지, 어디까지 걸지.\n\n**무엇을 다시 걸지**가 먼저다. 요청량 초과 거절이나 순간 끊김은 다시 걸 값어치가 있지만, 업무 규칙이 틀려서 난 오류는 백 번 걸어도 같은 답이 온다. AWS 문서는 원인을 알 수 있는 오래 갈 고장이면 재시도 대신 서킷 브레이커로 빨리 실패하는 편이 낫다고 적는다.\n\n**멱등한가**가 그다음이다. 상대가 요청을 제대로 처리하고 응답만 못 보냈을 수 있다. 그때 다시 건 요청은 같은 일을 두 번 하게 만든다. 애저 문서와 AWS 문서가 모두 같은 말을 한다 — 재시도를 걸 연산은 멱등해야 하고, 아니면 부분 갱신이 상태를 망가뜨린다.\n\n**어디까지 걸지**는 호출 하나가 아니라 프로세스 단위로 조인다. 구글 SRE 책은 프로세스마다 재시도 예산을 두라고 적는다. 분당 60번까지만 다시 걸게 하고 예산을 넘기면 다시 걸지 않고 곧바로 실패로 답하는 식이다. 예산이 없으면 재시도는 부하가 커질수록 같이 커진다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **요청량 초과 거절** — 429 가 돌아오면 곧바로 다시 걸지 않고 간격을 늘려 가며 다시 건다. 상대가 스스로를 지키려고 거절한 것이기 때문이다.\n- **워크플로 설정** — 재시도 세 번에 배수 1.5 로 잡으면 3초, 4.5초, 6.75초 뒤에 다시 걸고 그래도 실패하면 그 일을 실패로 끝낸다.\n- **재시도 예산** — 한 프로세스에서 분당 60번까지만 다시 걸게 하고, 예산을 넘기면 다시 걸지 않고 곧바로 실패로 답한다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **일단 재시도를 넣으면 안정성이 올라간다** — 잠깐 나는 실패에만 그렇다. 오래 갈 고장이나 업무 규칙이 틀려서 난 오류에 다시 걸면 시간과 자원만 쓰고 같은 답을 받는다.\n- **재시도는 계층마다 넣어 두면 든든하다** — 겹치면 곱해진다. 구글 SRE 책은 층마다 네 번씩 세 겹이면 사용자의 한 번 누름이 맨 아래에서 64번의 시도가 된다고 적는다.\n- **어디서든 다시 걸어 보는 편이 낫다** — 사람이 화면 앞에서 기다리는 자리에서는 짧게 몇 번만 걸고 빨리 실패하는 편이 낫다. 기다리는 동안 화면은 멈춰 있다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **한 층에서만 건다.** 계층마다 재시도를 걸면 곱해진다. 아래층은 빨리 실패하고 그 이유를 위로 올려서, 정책은 한 층에서만 정하게 둔다.\n- **기다림이 길어지는 값을 치른다.** 갑절씩 늘린 만큼 답을 받는 시각도 뒤로 밀린다. AWS 문서는 백오프가 최종 사용자의 대기 시간을 늘린다고 적는다.\n- **잦은 재시도는 규모 문제의 신호다.** 상대가 늘 바쁘다면 재시도를 늘릴 게 아니라 상대를 늘려야 한다."}],"figure":"```도해\n흐름: 호출이 실패했을 때 언제 다시 거나\n호출 :: 상대를 부른다. 실패가 돌아온다\n판정 :: 잠깐 나는 실패인가, 오래 갈 실패인가\n대기 :: 1초, 2초, 4초로 기다림을 갑절씩 늘린다\n흔들기 :: 거기에 무작위를 섞어 시각을 흩는다\n@ 다시 호출로 :: 성공하면 끝, 정해둔 횟수를 넘기면 실패로 답한다\n= 다시 거는 것만으로는 모자라고, 언제 거느냐를 같이 정해야 한다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 실패하자마자 곧바로 다시 걸면 어떻게 되나\n간격 없이 || 갑절씩 늘려서\n바쁜 상대 :: 부하가 더 얹힌다 || 숨 돌릴 틈이 난다\n재시도 물결 :: 다 같은 시각에 || 시각이 흩어진다\n회복 :: 더 늦어진다 || 대개 스스로 푼다\n= 다시 거는 일이 상대를 죽이지 않게 하는 것이 이 규칙의 절반이다\n```\n\n잠깐 나는 실패를 그대로 사용자에게 내보내면 멀쩡한 요청이 실패로 끝난다. 그래서 다시 건다. 문제는 다시 거는 방식이다. 애저 문서는 간격이 거의 없고 횟수만 많은 재시도가 한계에 걸려 있는 상대를 더 나쁘게 만든다고 적는다. 실패한 호출들이 하나같이 같은 간격으로 다시 걸리면, 그 다시 걸기가 같은 시각에 몰려 물결이 된다.\n\n지수 백오프는 기다림을 갑절씩 늘려 부하를 흩고, 무작위(지터)는 시각을 흩는다. 구글 SRE 책은 \"재시도를 잡을 때는 **언제나** 무작위를 섞은 지수 백오프를 쓰라\" 고 적는다. 지터가 없으면 작은 흔들림 하나가 재시도 물결을 같은 시각에 정렬시키고, 그 물결이 스스로를 키운다."},"recap":"**\"다시 걸되 갈수록 늦게, 남과 다른 시각에\"** 라고 읽으면 된다. 잠깐 나는 실패만 골라 다시 걸고, 기다림을 갑절씩 늘려 상대에게 숨 돌릴 틈을 주고, 무작위를 섞어 다시 걸기가 한 시각에 몰리지 않게 한다. 층마다 겹쳐 걸지 않는 것과 멱등한 연산에만 거는 것, 이 둘을 안 지키면 재시도는 고장을 키우는 쪽이 된다.","kid":"친구한테 전화했는데 통화 중이면 바로 또 걸지는 않지? 1분 있다가, 그래도 안 되면 2분, 그다음엔 4분, 이렇게 점점 더 오래 기다렸다 걸어. 다들 똑같이 1분 뒤에 걸면 또 한꺼번에 몰리니까 저마다 조금씩 다르게 기다리는 거야.","check":[{"q":"재시도를 계층마다 넣으면 왜 상황이 더 나빠지나","at":"흔한 오해"},{"q":"기다리는 시간에 무작위를 안 섞으면 무슨 일이 생기나","at":"해결하는 문제"},{"q":"응답만 못 받은 요청을 다시 걸기 전에 무엇을 확인해야 하나","at":"작동 원리"}],"myths":[{"wrong":"일단 재시도를 넣으면 안정성이 올라간다","right":"잠깐 나는 실패에만 그렇다. 오래 갈 고장이나 업무 규칙이 틀려서 난 오류에 다시 걸면 시간과 자원만 쓰고 같은 답을 받는다."},{"wrong":"재시도는 계층마다 넣어 두면 든든하다","right":"겹치면 곱해진다. 구글 SRE 책은 층마다 네 번씩 세 겹이면 사용자의 한 번 누름이 맨 아래에서 64번의 시도가 된다고 적는다."},{"wrong":"어디서든 다시 걸어 보는 편이 낫다","right":"사람이 화면 앞에서 기다리는 자리에서는 짧게 몇 번만 걸고 빨리 실패하는 편이 낫다. 기다리는 동안 화면은 멈춰 있다."}],"cases":[{"label":"요청량 초과 거절","note":"429 가 돌아오면 곧바로 다시 걸지 않고 간격을 늘려 가며 다시 건다. 상대가 스스로를 지키려고 거절한 것이기 때문이다."},{"label":"워크플로 설정","note":"재시도 세 번에 배수 1.5 로 잡으면 3초, 4.5초, 6.75초 뒤에 다시 걸고 그래도 실패하면 그 일을 실패로 끝낸다."},{"label":"재시도 예산","note":"한 프로세스에서 분당 60번까지만 다시 걸게 하고, 예산을 넘기면 다시 걸지 않고 곧바로 실패로 답한다."}],"dia":{"shape":"흐름","title":"호출이 실패했을 때 언제 다시 거나","rows":[{"who":"호출","what":"상대를 부른다. 실패가 돌아온다"},{"who":"판정","what":"잠깐 나는 실패인가, 오래 갈 실패인가"},{"who":"대기","what":"1초, 2초, 4초로 기다림을 갑절씩 늘린다"},{"who":"흔들기","what":"거기에 무작위를 섞어 시각을 흩는다"}],"sum":"다시 거는 것만으로는 모자라고, 언제 거느냐를 같이 정해야 한다","loop":{"who":"다시 호출로","what":"성공하면 끝, 정해둔 횟수를 넘기면 실패로 답한다"}}},"arch--sla-slo-sli":{"definition":"Google SRE 책이 이 순서로 정의한다. SLI 는 서비스의 한 측면을 재는 정량 지표이고, SLO 는 그 지표에 건 목표값이나 범위이며, SLA 는 그 목표를 지키거나 못 지켰을 때의 대가가 적힌 계약이다. 둘을 가르는 물음은 하나다 — \"못 지키면 무슨 일이 벌어지나\". 명시된 대가가 없으면 그건 SLA 가 아니라 SLO 다.","name":"Service Level :: 서비스의 수준\nIndicator :: 재는 눈금\nObjective :: 우리가 건 목표\nAgreement :: 대가가 적힌 계약\n= 앞 두 낱말은 셋이 똑같고 마지막 낱말만 다르다. 재는 것, 거는 것, 물어주는 것","analogy":"택배 회사의 도착 기록. 몇 시에 왔는지 적는 장부가 눈금이고, \"이틀 안에\" 가 목표고, 늦으면 배송비를 돌려주겠다는 문구가 계약이다.","example":"클라우드 요금제 페이지 맨 아래에 작은 글씨로 \"월 99.99% 가용성\" 이라고 적힌 그 줄이다.","tryit":"쓰고 있는 클라우드의 SLA 문서를 열어 보라. \"가용\" 을 무엇으로 판정하는지 정의한 문장이 따로 적혀 있다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"SLI 는 대개 비율이다. 좋은 사건을 전체 사건으로 나눈다. 예를 들어 \"1초 안에 끝난 요청 수 ÷ 전체 요청 수\" 가 지연 SLI 다. 평균이 아니라 백분위로 본다. 대부분의 지표는 평균보다 분포로 보는 편이 맞다 — 평균은 느린 소수를 가려 버린다.\n\n여러 구성요소를 엮으면 SLO 는 곱해진다. Azure Well-Architected 문서는 합성 SLO 를 기여 요소들의 곱으로 계산한다고 적는다. 99.95% 짜리 구성요소 넷을 직렬로 엮으면 전체는 99.8% 로 내려간다. 그래서 목표를 올리는 일은 대개 한 구성요소를 잘 만드는 일이 아니라, 직렬로 엮인 개수를 줄이거나 이중화로 갈라 놓는 일이 된다.\n\n클라우드가 게시한 SLA 를 그대로 자기 SLO 로 삼으면 안 된다. 같은 문서는 SLA 가 제품 전체를 보장하지 않는다고 못 박는다. Azure Front Door 의 99.99% 는 성공한 GET 요청이라는 좁은 조건에 걸린 수치이고, 캐싱이나 규칙 엔진은 그 조건 밖이다. 계약서에 명시되지 않은 부분은 플랫폼의 최선 노력으로 보아야 한다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **클라우드 서비스를 고를 때** — 게시된 퍼센트보다 적용 범위를 먼저 읽는다. 무엇을 \"가용\" 으로 세는지, 무엇이 계약 밖인지가 그 숫자의 진짜 값이다.\n- **의존 서비스를 엮을 때** — 각 구성요소의 조정된 목표치를 곱해 합성 SLO 를 낸다. 직렬로 길어질수록 전체가 내려가므로, 어디를 이중화할지가 이 계산에서 나온다.\n- **지표 개수를 정할 때** — 지표를 너무 많이 두면 정작 중요한 지표에 주의를 못 준다. 너무 적으면 시스템의 큰 동작이 안 보인 채로 남는다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **목표는 높을수록 좋으니 99.999% 로 걸자** — 신뢰성은 한 칸 올릴 때마다 비용이 앞 칸의 100배까지 든다. 사용자가 못 느끼는 개선에 기능과 기술 부채 정리에 쓸 돈을 넣는 셈이 된다.\n- **SLO 만 지키면 SLA 는 알아서 지켜진다** — SLA 에는 적용 범위가 따로 있다. 계약서에 안 적힌 기능은 최선 노력일 뿐이라, SLO 를 다 지키고도 사용자가 겪는 고장은 남을 수 있다.\n- **SLA 랑 SLO 는 부르는 이름만 다르다** — \"못 지키면 무슨 일이 벌어지나\" 를 물어 보면 갈린다. 대가가 없으면 SLO 고, 요금 크레딧처럼 오가는 것이 있으면 SLA 다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **목표를 넘겨 잘하는 것도 문제다.** 사용자는 말로 약속한 수준이 아니라 실제로 겪은 수준에 기대어 자기 시스템을 만든다. 계속 99.99% 를 내주면 그게 새 기준이 된다.\n- **측정 창을 먼저 정한다.** 같은 숫자도 5분 창과 24시간 창에서 다르게 나온다. 창은 놀고 있는 시간이 아니라 실제 활동이 담기도록 잡는다.\n- **지표는 사용자가 겪는 것으로 고른다.** 서버 사용률은 우리 사정이고, 성공률과 응답 시간은 사용자 사정이다. SLO 는 뒤쪽으로 세운다."}],"figure":"```도해\n층: 세 글자는 무엇 위에 무엇이 얹힌 것인가\nSLA :: 어기면 요금 크레딧을 돌려주는 계약. 법무와 재무가 정한다\nSLO :: 아래 눈금에 건 목표치. 엔지니어가 지키는 선이다\nSLI :: 좋은 요청을 전체 요청으로 나눈 값. 실제로 재는 눈금 하나\n= 아래가 없으면 위는 말뿐이다. 눈금이 있어야 목표가 서고, 목표가 있어야 계약이 선다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: \"안정적인가\" 를 세 글자로 쪼개면 무엇이 달라지나\n한 마디로 물으면 || 세 글자로 물으면\n판정 :: 사람마다 다르다 || 숫자 하나로 난다\n책임 :: 서로 미룬다 || 칸마다 주인이 있다\n투자 멈출 곳 :: 끝이 없다 || 목표에서 멈춘다\n= 눈금이 없으면 \"안정\" 은 의견이고, 눈금이 생기면 판정이 된다\n```\n\n\"우리 서비스는 안정적입니까\" 라는 물음에는 답이 없다. 누구는 죽지 않는 것을 안정이라 부르고 누구는 3초 안에 응답이 오는 것을 안정이라 부른다. 판정 기준이 사람마다 다르면 장애 회고는 매번 책임 다툼이 된다.\n\n세 글자는 그 물음을 셋으로 쪼갠다. 무엇을 재는가(SLI), 얼마까지 허용하는가(SLO), 어기면 무엇을 무는가(SLA). 쪼개면 숫자가 붙는다. 99.9% 는 한 달에 43분, 99.99% 는 4분 남짓이다. 이 한 자리 차이가 설계도 전체를 바꾼다."},"recap":"**\"재는 눈금 · 건 목표 · 무는 계약\"** 이라고 읽으면 된다. 눈금이 없으면 목표는 의견이고, 목표가 없으면 계약은 계산 없이 적은 숫자다. 바깥 계약을 안쪽 목표보다 느슨하게 걸어 두면, 목표를 놓친 순간과 계약을 어기는 순간 사이에 손쓸 시간이 남는다.","kid":"택배가 몇 시에 왔는지 매일 적어 두면, \"이틀 안에는 오게 하자\" 는 약속을 지켰는지 말다툼 없이 알 수 있어. 그리고 늦은 날이 몇 번을 넘으면 배송비를 돌려주기로 미리 적어 두는 거야.","check":[{"q":"멀쩡한 구성요소 넷을 이어 붙였는데 전체 목표치가 넷 중 어느 것보다도 낮아지는 이유는 무엇인가","at":"작동 원리"},{"q":"클라우드 문서에 99.99% 라고 적혀 있는데도 그 숫자를 그대로 못 믿는 이유는 무엇인가","at":"흔한 오해"},{"q":"목표보다 잘해 주는 것이 왜 손해가 될 수 있나","at":"주의사항"}],"myths":[{"wrong":"목표는 높을수록 좋으니 99.999% 로 걸자","right":"신뢰성은 한 칸 올릴 때마다 비용이 앞 칸의 100배까지 든다. 사용자가 못 느끼는 개선에 기능과 기술 부채 정리에 쓸 돈을 넣는 셈이 된다."},{"wrong":"SLO 만 지키면 SLA 는 알아서 지켜진다","right":"SLA 에는 적용 범위가 따로 있다. 계약서에 안 적힌 기능은 최선 노력일 뿐이라, SLO 를 다 지키고도 사용자가 겪는 고장은 남을 수 있다."},{"wrong":"SLA 랑 SLO 는 부르는 이름만 다르다","right":"\"못 지키면 무슨 일이 벌어지나\" 를 물어 보면 갈린다. 대가가 없으면 SLO 고, 요금 크레딧처럼 오가는 것이 있으면 SLA 다."}],"cases":[{"label":"클라우드 서비스를 고를 때","note":"게시된 퍼센트보다 적용 범위를 먼저 읽는다. 무엇을 \"가용\" 으로 세는지, 무엇이 계약 밖인지가 그 숫자의 진짜 값이다."},{"label":"의존 서비스를 엮을 때","note":"각 구성요소의 조정된 목표치를 곱해 합성 SLO 를 낸다. 직렬로 길어질수록 전체가 내려가므로, 어디를 이중화할지가 이 계산에서 나온다."},{"label":"지표 개수를 정할 때","note":"지표를 너무 많이 두면 정작 중요한 지표에 주의를 못 준다. 너무 적으면 시스템의 큰 동작이 안 보인 채로 남는다."}],"dia":{"shape":"층","title":"세 글자는 무엇 위에 무엇이 얹힌 것인가","rows":[{"who":"SLA","what":"어기면 요금 크레딧을 돌려주는 계약. 법무와 재무가 정한다"},{"who":"SLO","what":"아래 눈금에 건 목표치. 엔지니어가 지키는 선이다"},{"who":"SLI","what":"좋은 요청을 전체 요청으로 나눈 값. 실제로 재는 눈금 하나"}],"sum":"아래가 없으면 위는 말뿐이다. 눈금이 있어야 목표가 서고, 목표가 있어야 계약이 선다"}},"arch--saga":{"definition":"한 서비스 안에서는 데이터베이스가 전부 아니면 전무를 보장한다. 그런데 서비스마다 저장소를 따로 들면 그 보장이 경계를 넘지 못한다. 사가는 큰 거래를 각자의 저장소 안에서 끝나는 작은 거래로 쪼개고, 하나가 실패하면 앞서 끝난 단계를 되돌리는 보상 거래를 차례로 실행한다.","name":"Saga :: 길게 이어지는 이야기\n= 한 번에 끝나는 거래가 아니라 여러 장으로 이어지는 이야기처럼 다루라는 이름이다","analogy":"기차표와 잘 곳과 자전거를 따로 잡다가 하나가 안 되면 앞서 잡은 것을 하나씩 도로 취소하는 여행 준비.","example":"주문이 됐다고 떴는데 잠시 뒤 \"재고가 없어 취소되었습니다\" 문자가 오는 그 경우다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"한 단계가 도는 방식은 늘 같다. 자기 저장소 안에서 거래를 하나 끝내고, 다음 단계를 부를 소식을 내보낸다. 이 둘이 갈라지면 사가는 그 자리에서 멈춘다. 저장은 됐는데 소식이 안 나가면 아무도 다음을 이어받지 않고, 소식만 나가고 저장이 안 됐으면 있지도 않은 결과 위에서 다음 단계가 돈다. 그래서 내보낼 소식을 같은 거래 안에서 자기 저장소의 한 자리에 함께 적어 두고, 적힌 것을 따로 읽어 내보내는 방식을 쓴다.\n\n실패는 앞으로 알리지 않고 뒤로 되돌린다. 어느 단계가 못 하겠다고 하면 그 앞까지 끝난 단계들이 **역순으로** 보상 거래를 실행한다. 순서를 뒤집는 까닭은 뒤 단계가 앞 단계의 결과 위에 서 있기 때문이다. 주문을 무효로 적고 나서 결제를 푸는 순서로 가면, 결제를 푸는 동안 근거가 될 주문이 이미 사라진 상태가 된다.\n\n어디까지 갔는지는 누군가 적어 두어야 안다. 조율자를 두는 방식은 그 자리가 사가마다 어느 단계에 있는지를 상태로 들고 있고, 조율자가 없는 방식은 각 서비스가 자기가 받은 소식과 낸 소식으로 그 자취를 남긴다. 이 기록이 없으면 되돌리기를 시작할 지점도, 멈춰 선 사가를 찾아낼 방법도 없다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 코레오그래피와 오케스트레이션","body":"사가를 잇는 방법은 둘이다. 코레오그래피는 가운데 지휘자 없이 각 서비스가 사건을 발행하고 그 사건이 다음 서비스를 부르는 방식이고, 오케스트레이션은 가운데에 둔 조율자가 누가 무엇을 할지 지시하고 상태를 들고 있는 방식이다.\n\n```도해\n대조: 코레오그래피와 오케스트레이션 중 무엇을 고르나\n코레오그래피 |=| 오케스트레이션\n지휘 :: 지휘자가 없다 || 가운데가 시킨다\n단계 추가 :: 흐름이 헷갈린다 || 한 곳만 고친다\n고장점 :: 한 곳에 안 몰린다 || 그 한 곳이 문제\n= 참여자가 적고 흐름이 단순하면 코레오그래피, 복잡해지면 오케스트레이션이다\n```\n\n코레오그래피는 서비스 수가 적고 조율 로직이 필요 없는 단순한 흐름에 맞다. 대신 단계를 더할수록 누가 어떤 명령에 반응하는지 추적하기 어려워지고, 참여자끼리 서로의 사건을 소비하다 순환 의존이 생길 위험이 있다. 통합 테스트를 하려면 서비스를 전부 띄워야 한다.\n\n오케스트레이션은 흐름이 복잡하거나 서비스를 계속 더할 때 낫다. 조율자가 순서를 쥐고 있어 순환 의존이 생기지 않고 책임 구분이 또렷해진다. 대신 조율 로직을 따로 구현해야 하고, 그 조율자가 전체 흐름을 쥔 고장점이 된다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **주문 처리** — 주문·결제·재고·배송을 단계로 잇고, 재고에서 막히면 결제와 주문을 거꾸로 취소한다.\n- **오래 걸리는 일** — 한 단계가 몇 분씩 걸리는 흐름에서 다른 서비스를 붙잡아 두지 않으려고 잠금 대신 보상을 쓴다.\n- **여러 팀이 나눠 가진 흐름** — 팀마다 서비스와 저장소가 다를 때, 공통 저장소를 만들지 않고도 하나의 업무 흐름을 잇는다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **사가가 롤백을 해 준다** — 되돌아가지 않는다. 각 단계는 이미 자기 저장소에 확정해 버렸고, 사가가 하는 일은 반대 효과를 내는 거래를 하나 더 실행하는 것이다.\n- **분산 거래는 무조건 사가로 해야 한다** — Microsoft 문서는 단계가 서로 꽉 물려 있거나 앞선 참여자에게까지 보상이 거슬러 올라가야 하거나 순환 의존이 있으면 맞지 않는다고 적는다. 위험이 큰 갱신은 분산 트랜잭션으로, 낮은 갱신은 사가로 나눠 쓰라고도 적는다.\n- **보상 거래만 만들어 두면 값은 안전하다** — 서비스 사이에는 격리가 없다. 사가가 도는 중간 상태를 다른 사가가 읽어 가서 갱신 유실이나 더티 리드가 생기고, 보상 거래 자체가 실패할 수도 있다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **되돌릴 수 없는 지점을 먼저 찾아라.** 메일 발송이나 외부 결제 확정처럼 취소가 안 되는 단계가 분기점이다. 그 앞은 보상으로 되감고, 그 뒤는 성공할 때까지 재시도하도록 나눠 설계한다.\n- **같은 단계를 두 번 받아도 결과가 같아야 한다.** 메시지는 다시 올 수 있다. 재시도 구간의 단계는 여러 번 실행해도 결과가 달라지지 않게 만든다.\n- **어디까지 갔는지 보이게 하라.** Microsoft 문서는 참여 서비스가 늘수록 사가를 디버깅하기 어려워진다고 적고, 흐름을 지켜보고 뒤쫓는 일을 빼놓을 수 없는 일로 든다. 어느 단계까지 갔는지 남겨 두지 않으면 장애가 났을 때 손댈 데를 못 찾는다."}],"figure":"```도해\n흐름: 한 단계가 실패하면 앞 단계는 어떻게 되나\n주문 :: 주문을 만들고 다음 단계로 넘긴다\n결제 :: 돈을 잡고 다음 단계로 넘긴다\n재고 :: 물건이 없다. 실패를 앞으로 알린다\n< 결제 :: 그 소식을 받고 잡았던 돈을 푼다\n< 주문 :: 만들어 둔 주문을 무효로 적는다\n= 한꺼번에 되돌릴 장치가 없으니, 되돌리는 일을 단계마다 따로 만들어 둔다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 중간에 실패했는데 되돌릴 장치가 없으면 어떻게 되나\n보상 없이 || 보상 단계로\n결제만 성공 :: 돈만 빠진 채 끝 || 도로 풀어 준다\n재고만 차감 :: 안 팔릴 물건이 묶임 || 다시 풀어 준다\n수습 :: 사람이 손으로 || 정해진 대로 자동\n= 여러 저장소를 한 번에 되돌릴 수 없으니, 되돌리는 일을 미리 적어 둔다\n```\n\n서비스마다 저장소를 따로 두는 구성에는 이유가 있다. 각자 자기 자료를 감싸고, 자기에게 맞는 저장소 종류를 고르고, 따로 늘리고, 한쪽 고장이 옆으로 안 번진다. 대신 서비스를 넘나드는 정합성이 어려워진다. Microsoft 문서는 여러 저장소가 독립적으로 관리되는 곳에는 데이터베이스가 주던 보장이 그대로 적용되지 않는다고 적는다.\n\n사가는 그 자리를 메운다. 각 단계는 자기 저장소 안에서 원자적으로 끝내고 사건이나 메시지로 다음 단계를 부른다. 중간에 실패하면 앞 단계들이 반대 효과를 내는 보상 거래를 실행해 되감는다. 대가는 분명하다. 이미 확정된 것을 되돌리는 코드를 사람이 직접 설계해야 하고, 되감기는 도중에는 값이 어긋난 채로 보인다."},"recap":"**\"되돌리는 일까지 미리 적어 둔 여러 단계 거래\"** 라고 읽으면 된다. 각 단계는 자기 저장소 안에서만 확정하고, 실패하면 앞 단계가 반대 거래로 되감는다. 잠금을 오래 쥐지 않는 대신 되감는 코드와 어긋난 중간 상태를 내가 떠안는 거래다.","kid":"여행 갈 때 기차표부터 끊고, 잘 곳을 잡고, 자전거도 빌려 두잖아. 그런데 자전거 가게가 문을 닫아서 못 빌리게 됐대. 그러면 앞에서 잡아 둔 잘 곳이랑 기차표를 하나씩 도로 취소해야 해.","check":[{"q":"결제까지 끝난 주문이 몇 초 뒤에 취소 문자로 돌아오는 이유는 무엇인가","at":"그림"},{"q":"단계가 열 개로 늘어난 흐름에 새 단계를 끼울 때 어느 쪽이 유리하고 왜 그런가","at":"비교"},{"q":"보상 거래를 빠짐없이 만들어 두었는데도 값이 어긋나는 일이 왜 생기나","at":"흔한 오해"}],"myths":[{"wrong":"사가가 롤백을 해 준다","right":"되돌아가지 않는다. 각 단계는 이미 자기 저장소에 확정해 버렸고, 사가가 하는 일은 반대 효과를 내는 거래를 하나 더 실행하는 것이다."},{"wrong":"분산 거래는 무조건 사가로 해야 한다","right":"Microsoft 문서는 단계가 서로 꽉 물려 있거나 앞선 참여자에게까지 보상이 거슬러 올라가야 하거나 순환 의존이 있으면 맞지 않는다고 적는다. 위험이 큰 갱신은 분산 트랜잭션으로, 낮은 갱신은 사가로 나눠 쓰라고도 적는다."},{"wrong":"보상 거래만 만들어 두면 값은 안전하다","right":"서비스 사이에는 격리가 없다. 사가가 도는 중간 상태를 다른 사가가 읽어 가서 갱신 유실이나 더티 리드가 생기고, 보상 거래 자체가 실패할 수도 있다."}],"cases":[{"label":"주문 처리","note":"주문·결제·재고·배송을 단계로 잇고, 재고에서 막히면 결제와 주문을 거꾸로 취소한다."},{"label":"오래 걸리는 일","note":"한 단계가 몇 분씩 걸리는 흐름에서 다른 서비스를 붙잡아 두지 않으려고 잠금 대신 보상을 쓴다."},{"label":"여러 팀이 나눠 가진 흐름","note":"팀마다 서비스와 저장소가 다를 때, 공통 저장소를 만들지 않고도 하나의 업무 흐름을 잇는다."}],"dia":{"shape":"흐름","title":"한 단계가 실패하면 앞 단계는 어떻게 되나","rows":[{"who":"주문","what":"주문을 만들고 다음 단계로 넘긴다"},{"who":"결제","what":"돈을 잡고 다음 단계로 넘긴다"},{"who":"재고","what":"물건이 없다. 실패를 앞으로 알린다"},{"who":"결제","what":"그 소식을 받고 잡았던 돈을 푼다","back":true},{"who":"주문","what":"만들어 둔 주문을 무효로 적는다","back":true}],"sum":"한꺼번에 되돌릴 장치가 없으니, 되돌리는 일을 단계마다 따로 만들어 둔다"}},"arch--scalability":{"definition":"늘리는 쪽만이 아니라 줄이는 쪽도 함께 세는 것이 요점이다. Google Cloud 문서는 확장성을 \"자원을 더하거나 빼서 여러 크기의 일을 감당하는 능력\" 으로 적고, 그 덕에 놀고 있는 자원을 걷어내 값을 줄일 수 있다고 덧붙인다.","name":"Scale :: 크기를 조절하다\n-ability :: 그럴 수 있는 성질\n= 이어 읽으면 \"크기를 조절할 수 있음\". 크게만이 아니라 작게도 조절한다는 말이다","analogy":"손님이 몰리면 계산대를 더 열고 한산해지면 도로 닫는 마트.","example":"공연 예매가 열리는 그 1분 동안 사이트가 먹통이 되던 장면이 확장성이 모자란 자리다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"자동 확장은 세 부품이다. 지표를 재는 감시, 임계값과 견줘 늘릴지 줄일지 정하는 판단, 실제로 대수를 바꾸는 실행. Azure 문서는 이 실행 부품을 일감 코드와 떼어 놓으라고 적는다 — 놀고 있거나 이미 짓눌린 코드가 자기 확장을 책임질 수는 없기 때문이다.\n\n**즉시가 아니라는 점이 설계를 가른다.** 판단은 순간값이 아니라 일정 구간의 평균으로 하고, 새 인스턴스가 떠서 자리 잡을 시간도 기다린다. Azure 문서는 가상 머신 계열의 기본 집계 구간이 45분이라고 적는다. 그래서 갑작스러운 폭주는 확장으로 못 받는다 — 자원이 준비될 즈음이면 이미 지나가 있다. 같은 문서가 그럴 때는 확장 대신 요청량 제한을 걸라고 권한다.\n\n무엇으로 잴지도 고른다. 사용률 대신 대기 줄의 길이를 보는 편이 나은 자리가 많고, 더 나은 것은 메시지가 들어와서 처리가 끝나기까지 걸린 시간이다. 줄에 5만 건이 쌓여 있어도 그 시간이 업무가 견딜 만하면 늘릴 이유가 없고, 500건뿐이어도 그 시간이 약속을 넘으면 늘려야 한다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **예매 오픈 전에 미리 올리기** — 몰릴 시각을 아는 일에는 예정 규칙으로 대수를 먼저 올려 둔다. 반응형 규칙만 믿으면 인스턴스가 뜨는 사이에 첫 몇 분을 통째로 날린다.\n- **새벽에 줄이기** — 한산한 시간에는 최소 대수로 내린다. 확장성이 돈을 버는 자리는 늘리는 쪽보다 줄이는 쪽인 경우가 많다.\n- **대기 줄로 재기** — 처리 대기 줄의 길이나 가장 오래 기다린 건의 대기 시간을 기준으로 삼는다. 앞단 사용률만 보면 정작 밀리는 뒷단을 못 본다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **장비를 늘리면 그만큼 빨라진다** — 늘어난 대수가 성능이 되려면 일을 나눠 받을 수 있어야 한다. 한 대에만 상태가 붙어 있으면 새 대수는 놀고, 뒤의 공용 저장소가 병목이면 앞단만 늘어난다.\n- **자동 확장을 켜 두면 몰려도 괜찮다** — 즉시가 아니다. 지표가 쌓이고 인스턴스가 뜨는 동안 몰림은 이미 지나간다. Azure 문서도 갑작스러운 폭주에는 확장보다 요청량 제한이 낫다고 적는다.\n- **수평 확장이 항상 낫다** — 상태를 들고 있는 저장소를 수평으로 늘리려면 쪼개기와 재분배가 따라온다. 한 대를 키워 2~3년을 벌 수 있으면 그쪽이 더 싼 답일 때가 많다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **위 한도를 반드시 정한다.** 끝없이 늘어나는 규칙은 장애를 청구서로 바꿔 놓을 뿐이다.\n- **늘리는 규칙과 줄이는 규칙을 쌍으로 만든다.** Azure 문서는 한쪽만 두면 한 방향으로만 가서 최대치나 최소치에 붙어 버린다고 적는다.\n- **두 임계값 사이를 벌린다.** 붙어 있으면 늘렸다 줄였다만 반복하는 플래핑이 생긴다. 세 대에서 한 대를 빼면 남은 대의 부하가 다시 임계값을 넘기 때문이다.\n- **규칙을 한 번 짜고 두지 않는다.** AWS 문서는 사람이 손으로 용량을 어림하는 것과, 바뀌는 업무 요구·트래픽 양상에 맞춰 고쳐지지 않는 확장 규칙을 대표적인 안티패턴으로 든다."}],"figure":"```도해\n대조: 일이 늘고 줄 때 자원은 어떻게 맞추나\n수직 확장 |=| 수평 확장\n늘릴 때 :: 한 대를 키운다 || 대수를 늘린다\n줄일 때 :: 도로 작게 잡는다 || 몇 대를 끈다\n그동안 :: 대개 재배포 || 안 멈춘다\n한계 :: 장비 최대치 || 설계가 정한다\n= 일의 양에 맞춰 자원을 더하고 빼는 길이 둘이고, 방향이 다르다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 손님이 갑자기 열 배로 오면 어떻게 되나\n고정 용량으로 || 늘릴 수 있게\n평소 :: 놀리는 장비 값 || 필요한 만큼만\n몰릴 때 :: 응답이 멈춘다 || 대수를 늘린다\n빠진 뒤 :: 그대로 돈이 샌다 || 도로 줄인다\n= 최대치에 맞춰 미리 사 두는 대신, 그때그때 맞추는 것이다\n```\n\n용량을 고정하면 실패가 두 방향으로 난다. 최대치에 맞춰 사 두면 평소에는 그 장비를 놀리면서 값을 내고, 평소에 맞춰 사 두면 몰리는 날 응답이 멈춘다. 어느 쪽을 골라도 틀리는 이유는 일의 양이 시간에 따라 변하는데 자원만 고정이기 때문이다.\n\n확장성은 그 둘을 시간축에서 떼어 놓는다. 다만 **공짜로 얻어지는 성질이 아니다.** Azure 문서는 대수를 늘려서 성능을 얻으려면 시스템이 처음부터 수평 확장이 되게 설계되어 있어야 한다고 적는다 — 특정 인스턴스(같은 프로그램을 돌리는 한 대)에만 상태가 붙어 있으면 안 되고, 같은 사용자의 연속 요청이 늘 같은 대로 간다고 가정해서도 안 된다. Google Cloud 문서도 자동 확장을 쓸 때 인스턴스가 예고 없이 만들어지고 없어지므로 무상태 설계가 특히 중요하다고 적는다."},"recap":"**\"일의 양을 따라 자원이 늘었다 줄었다 하는 성질\"** 이라고 읽으면 된다. 대수를 늘려서 성능을 얻으려면 상태가 한 대에 붙어 있지 않아야 하고, 그 설계 비용이 확장성의 진짜 값이다. 자동 확장은 즉시가 아니라서 갑작스러운 폭주는 확장이 아니라 요청량 제한으로 받는다.","kid":"마트에 손님이 갑자기 몰리면 줄이 길어지지? 그때 계산대를 몇 개 더 열고, 손님이 빠지면 도로 닫아. 하루 종일 스무 개를 다 열어 놓고 아저씨들을 놀리는 것보다, 그때그때 늘렸다 줄였다 하는 편이 나은 거야.","check":[{"q":"대수를 두 배로 늘렸는데 응답 시간이 그대로인 일은 왜 생기나","at":"흔한 오해"},{"q":"늘리는 규칙만 만들고 줄이는 규칙을 안 만들면 무슨 일이 생기나","at":"주의사항"},{"q":"한 대를 키우는 쪽과 대수를 늘리는 쪽은 무엇이 다른가","at":"그림"}],"myths":[{"wrong":"장비를 늘리면 그만큼 빨라진다","right":"늘어난 대수가 성능이 되려면 일을 나눠 받을 수 있어야 한다. 한 대에만 상태가 붙어 있으면 새 대수는 놀고, 뒤의 공용 저장소가 병목이면 앞단만 늘어난다."},{"wrong":"자동 확장을 켜 두면 몰려도 괜찮다","right":"즉시가 아니다. 지표가 쌓이고 인스턴스가 뜨는 동안 몰림은 이미 지나간다. Azure 문서도 갑작스러운 폭주에는 확장보다 요청량 제한이 낫다고 적는다."},{"wrong":"수평 확장이 항상 낫다","right":"상태를 들고 있는 저장소를 수평으로 늘리려면 쪼개기와 재분배가 따라온다. 한 대를 키워 2~3년을 벌 수 있으면 그쪽이 더 싼 답일 때가 많다."}],"cases":[{"label":"예매 오픈 전에 미리 올리기","note":"몰릴 시각을 아는 일에는 예정 규칙으로 대수를 먼저 올려 둔다. 반응형 규칙만 믿으면 인스턴스가 뜨는 사이에 첫 몇 분을 통째로 날린다."},{"label":"새벽에 줄이기","note":"한산한 시간에는 최소 대수로 내린다. 확장성이 돈을 버는 자리는 늘리는 쪽보다 줄이는 쪽인 경우가 많다."},{"label":"대기 줄로 재기","note":"처리 대기 줄의 길이나 가장 오래 기다린 건의 대기 시간을 기준으로 삼는다. 앞단 사용률만 보면 정작 밀리는 뒷단을 못 본다."}],"dia":{"shape":"대조","title":"일이 늘고 줄 때 자원은 어떻게 맞추나","rows":[{"who":"","what":"수직 확장 || 수평 확장","left":"수직 확장","right":"수평 확장","even":true},{"who":"늘릴 때","what":"한 대를 키운다 || 대수를 늘린다","left":"한 대를 키운다","right":"대수를 늘린다"},{"who":"줄일 때","what":"도로 작게 잡는다 || 몇 대를 끈다","left":"도로 작게 잡는다","right":"몇 대를 끈다"},{"who":"그동안","what":"대개 재배포 || 안 멈춘다","left":"대개 재배포","right":"안 멈춘다"},{"who":"한계","what":"장비 최대치 || 설계가 정한다","left":"장비 최대치","right":"설계가 정한다"}],"sum":"일의 양에 맞춰 자원을 더하고 빼는 길이 둘이고, 방향이 다르다"}},"arch--service-discovery":{"definition":"서비스를 여러 개로 나누고 컨테이너로 띄우면 주소가 계속 바뀐다. 재시작할 때마다 IP가 달라지고 대수도 늘었다 줄었다 하는데, 부르는 쪽 코드에 주소를 박아두면 그때마다 끊긴다.","name":"Service :: 제 몫 하는 한 가지 일\nDiscovery :: 어디 있는지 찾아냄\n= 붙여 읽으면 \"그 일이 지금 어디 있는지 찾아내기\". 부르는 쪽이 아는 것은 주소가 아니라 이름뿐이다","analogy":"회사 내선 안내판. 자리가 바뀌어도 안내판만 고쳐두면 이름만 알고 찾아갈 수 있다.","example":"서버 대수가 밤새 늘었다 줄었다 했는데 부르는 쪽 설정에 적힌 주소는 그대로다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"레지스트리가 맡는 일은 넷이다.\n\n- **등록** — 서비스가 뜰 때 이름과 주소를 올린다.\n- **헬스체크** — 10초마다 살아 있는지 물어본다.\n- **조회** — 이름을 주면 지금 쓸 수 있는 주소를 돌려준다.\n- **해지** — 답이 없거나 내려가면 명단에서 뺀다.\n\n명단이 실제와 어긋나면 없느니만 못하다. 헬스체크와 해지가 그걸 막는 자리다.\n\n누가 레지스트리에 묻느냐로 두 가지가 갈린다. 부르는 쪽이 직접 물어 주소를 받아 호출하는 방식은 구조가 단순한 대신 서비스마다 그 코드를 넣어야 한다. 앞에 로드 밸런서를 세워 대신 묻게 하면 부르는 쪽은 아무것도 몰라도 되지만 그 장비가 하나 더 필요하다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **대수 늘리기** — 부하가 늘어 인스턴스가 세 대 더 떠도 각자 등록하니 부르는 쪽은 고칠 게 없다.\n- **배포** — 새 버전을 띄워 등록한 뒤 옛 인스턴스를 명단에서 빼면 요청이 그쪽으로 옮겨간다.\n- **장애 격리** — 헬스체크에 답하지 않는 인스턴스는 명단에서 빠져 요청을 받지 않는다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **디스커버리가 부하도 나눠준다** — 어디 있는지 알려주는 데까지가 일이다. 받은 주소가 여럿일 때 어디로 보낼지 고르는 것은 로드 밸런싱이고, 붙어 다닐 뿐 같은 일은 아니다.\n- **한 번 등록해두면 명단은 알아서 맞는다** — 서버가 갑자기 죽으면 스스로 해지하지 못한다. 레지스트리가 주기적으로 물어보고 답이 없는 것을 빼기 때문에 명단이 실제와 맞는 것이다.\n- **서비스가 몇 개 안 되면 안 써도 된다** — 개수가 아니라 주소가 바뀌느냐의 문제다. 컨테이너는 재시작할 때마다 주소가 달라져서 서비스가 둘이어도 필요해진다."}],"figure":"```도해\n흐름: 주소가 계속 바뀌는 서비스를 어떻게 찾아 부르나\n결제 :: 뜨자마자 이름과 주소를 등록한다\n레지스트리 :: 주기적으로 살아 있는지 물어 명단을 고친다\n주문 :: 부르기 전에 \"결제 어디 있나\" 를 묻는다\n< 레지스트리 :: 살아 있는 주소를 돌려준다. 주문은 그리로 부른다\n= 부르는 쪽이 아는 것은 주소가 아니라 이름뿐이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 주소를 코드에 박아두면 어떻게 되나\n주소를 박아두면 || 등록해서 찾으면\n재시작 :: 연결이 끊긴다 || 새 주소로 간다\n대수 늘리기 :: 설정을 다 고친다 || 등록만 하면 끝\n죽은 서버 :: 그대로 부른다 || 명단에서 빠진다\n= 주소가 자주 바뀌는 곳에서는 이름으로 부르게 만들어야 한다\n```\n\n주문 서비스가 결제 서비스를 `192.168.1.100:8080`으로 부르고 있었다면, 결제 서비스를 재시작해 IP가 바뀌는 순간 호출이 실패한다. 대수를 늘릴 때도 부르는 쪽 설정을 전부 찾아 고쳐야 한다.\n\n레지스트리를 두면 이 일이 없어진다. 서비스는 뜰 때 자기 이름과 주소를 올리고, 부르는 쪽은 이름으로 물어 지금 쓸 수 있는 주소를 받는다."},"recap":"**\"주소 말고 이름으로 부르게 해 주는 그 명단\"** 이라고 읽으면 된다. 서비스가 뜰 때 등록하고 헬스체크로 죽은 것을 빼기 때문에 주소가 바뀌어도 부르는 쪽 코드는 그대로다.","kid":"큰 회사에서 사람들이 자리를 자주 옮기면 누가 어디 앉았는지 외울 수가 없지? 그래서 옮길 때마다 안내판에 적어 두고, 찾는 사람은 이름만 대고 안내판을 봐. 그만두고 나간 사람은 안내판에서 지워지니까 헛걸음도 안 하게 돼.","check":[{"q":"결제 서비스를 재시작해 IP가 바뀌었는데 주문 서비스 코드를 안 고쳐도 되는 이유는","at":"해결하는 문제"},{"q":"서버가 갑자기 죽었을 때 명단에서 빠지는 것은 무엇 덕분인가","at":"작동 원리"},{"q":"주소를 여러 개 받아온 다음 그중 어디로 보낼지 정하는 것은 어디가 하는 일인가","at":"흔한 오해"}],"myths":[{"wrong":"디스커버리가 부하도 나눠준다","right":"어디 있는지 알려주는 데까지가 일이다. 받은 주소가 여럿일 때 어디로 보낼지 고르는 것은 로드 밸런싱이고, 붙어 다닐 뿐 같은 일은 아니다."},{"wrong":"한 번 등록해두면 명단은 알아서 맞는다","right":"서버가 갑자기 죽으면 스스로 해지하지 못한다. 레지스트리가 주기적으로 물어보고 답이 없는 것을 빼기 때문에 명단이 실제와 맞는 것이다."},{"wrong":"서비스가 몇 개 안 되면 안 써도 된다","right":"개수가 아니라 주소가 바뀌느냐의 문제다. 컨테이너는 재시작할 때마다 주소가 달라져서 서비스가 둘이어도 필요해진다."}],"cases":[{"label":"대수 늘리기","note":"부하가 늘어 인스턴스가 세 대 더 떠도 각자 등록하니 부르는 쪽은 고칠 게 없다."},{"label":"배포","note":"새 버전을 띄워 등록한 뒤 옛 인스턴스를 명단에서 빼면 요청이 그쪽으로 옮겨간다."},{"label":"장애 격리","note":"헬스체크에 답하지 않는 인스턴스는 명단에서 빠져 요청을 받지 않는다."}],"dia":{"shape":"흐름","title":"주소가 계속 바뀌는 서비스를 어떻게 찾아 부르나","rows":[{"who":"결제","what":"뜨자마자 이름과 주소를 등록한다"},{"who":"레지스트리","what":"주기적으로 살아 있는지 물어 명단을 고친다"},{"who":"주문","what":"부르기 전에 \"결제 어디 있나\" 를 묻는다"},{"who":"레지스트리","what":"살아 있는 주소를 돌려준다. 주문은 그리로 부른다","back":true}],"sum":"부르는 쪽이 아는 것은 주소가 아니라 이름뿐이다"}},"arch--service-mesh":{"definition":"Azure 문서는 이 층이 트래픽 관리·복원력·정책·보안·신원·관측을 맡고, 애플리케이션은 그 일에서 분리된다고 적는다. 얻는 것은 \"코드를 안 고치고 통신 규칙을 바꿀 수 있다\" 하나이고, 내는 것은 프록시가 먹는 자원과 호출마다 붙는 지연이다.","name":"Service :: 서비스 하나하나\nMesh :: 그물망\n= 붙여 읽으면 \"서비스들이 이룬 그물망\". 그 그물의 매듭마다 대리인을 세워 통신을 맡긴 것이다","analogy":"건물 입구마다 서 있는 지킴이. 드나드는 사람은 모두 그 앞을 지나가고, 출입 규칙을 바꿀 때는 사무실이 아니라 지킴이들에게만 알린다.","example":"앱 코드는 한 줄도 안 고쳤는데 서비스 사이 호출이 전부 암호화되고 호출 지도까지 그려지던 그 상태다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"두 부분으로 나뉜다. Istio 문서는 데이터 평면을 \"사이드카로 배포된 똑똑한 프록시들의 모음\" 이라 적고, 이 프록시들이 마이크로서비스 사이의 모든 통신을 중개하고 통제한다고 설명한다. 제어 평면은 그 프록시들을 관리하고 설정해 트래픽을 어디로 보낼지 정한다. 데이터 평면 트래픽에 실제로 손을 대는 것은 프록시뿐이다.\n\n프록시가 자리를 잡고 있으니 거기서 할 수 있는 일이 많아진다. 서비스 찾기와 부하 분산, 상태 확인, TLS 종료, 차단기와 결함 주입, 비율을 나눠 조금씩 넘기는 단계적 출시, 접근 통제와 요청량 제한, 그리고 촘촘한 지표 수집이 전부 같은 자리에서 나온다. Istio 문서는 이 덕분에 기존 배포에 구조를 다시 짜거나 코드를 다시 쓰지 않고 기능을 더할 수 있다고 적는다.\n\n붙이는 방식은 하나가 아니다. Istio는 전통적인 사이드카 방식과, 운영을 단순하게 하려는 앰비언트 방식을 함께 제공한다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **클러스터 안 전면 암호화** — 지정한 서비스 사이에 mTLS를 켠다. 애플리케이션 코드와 인프라를 고치지 않고 기본이 암호화인 상태로 만든다.\n- **카나리 배포** — 조건에 맞는 일부 호출만 새 버전으로 보내고, 시험이 성공하면 비율을 점점 올려 결국 전부 넘긴다.\n- **장애 주입 시험** — 시험 환경에서 서비스 사이에 일부러 결함을 넣어, 한쪽이 무너졌을 때 나머지가 버티는지 본다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **마이크로서비스면 메시는 당연히 깔아야 한다** — 아니다. Azure 문서는 먼저 \"인그레스 컨트롤러만으로 충분한가\" 를 물으라고 한다. A/B 시험이나 트래픽 분할이 입구에서 되는 정도면 거기서 끝내라는 것이고, 얻는 것 없이 복잡도만 올리지 말라고 적혀 있다.\n- **앱을 안 고치니 공짜다** — 아니다. 메시를 떠받치는 부품들이 CPU와 메모리를 먹고, 프록시와 정책 검사가 호출마다 지연을 더한다. 지연에 예민하거나 여유 자원이 없는 업무라면 도입을 다시 생각하라고 문서가 적는다.\n- **메시를 깔면 장애가 줄어든다** — 메시는 재시도·차단·관측을 대신 걸어 줄 뿐 고장 난 서비스를 고치지 않는다. 부품이 늘어난 만큼 새로 관리해야 할 것도 같이 는다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **한꺼번에 다 깔지 않는다.** Azure 문서는 필요한 부품만 골라 점진적으로 들이라고 적는다. 처음부터 전부 설치하고 싶은 충동을 참으라는 문장이 그대로 들어 있다.\n- **업무에 중요하지 않은 기능 하나 때문에 들이지 않는다.** 설치·유지·설정에 드는 복잡도가 그 기능값보다 큰지 먼저 잰다.\n- **입구와 안쪽을 구분한다.** 밖에서 들어오는 길목의 문제는 게이트웨이가, 안쪽 서비스끼리의 문제는 메시가 맡는 자리다."}],"figure":"```도해\n층: 서비스끼리 주고받는 일은 어느 층에서 처리되나\n앱 코드 :: 업무만 한다. 상대를 부르되 통신 규칙은 모른다\n데이터 평면 :: 서비스마다 붙은 프록시. 드나드는 호출이 전부 여기를 지난다\n제어 평면 :: 프록시 전부에게 같은 규칙과 신분증을 내려보낸다\n= 통신에 관한 일이 앱에서 빠져나와 그 아래 인프라 층으로 내려간 것이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 재시도·암호화·추적을 서비스마다 넣으면 어떻게 되나\n서비스 안에 넣으면 || 메시에 맡기면\n규칙 바꾸기 :: 전부 다시 배포 || 설정 한 번\n언어가 여럿 :: 언어마다 만든다 || 한 벌로 끝난다\n누가 누굴 부르나 :: 알 길이 없다 || 지도가 그려진다\n= 통신에 관한 일을 앱 밖으로 꺼내면 한 곳에서 바꾸고 한 곳에서 볼 수 있다\n```\n\n서비스가 수십 개로 갈라지면 그 사이를 오가는 호출에 붙어야 할 일이 늘어난다. 상대가 죽었을 때 몇 번 다시 부를지, 오가는 내용을 암호화할지, 누가 누구를 불렀는지 어떻게 남길지. 이걸 서비스마다 코드로 넣으면 규칙 하나를 바꿀 때 서비스를 전부 다시 배포해야 하고, 언어가 다르면 같은 규칙을 언어 수만큼 만들어 유지해야 한다.\n\n메시는 그 일을 서비스 옆에 세운 프록시로 옮긴다. 앱은 평소처럼 상대를 부르고, 실제로 나가고 들어오는 것은 프록시가 처리한다. 그래서 암호화를 켜거나 재시도 규칙을 바꾸는 일이 코드 수정이 아니라 설정 변경이 된다."},"recap":"**\"통신에 관한 일을 앱 밖으로 걷어낸 그 그물망\"** 이라고 읽으면 된다. 서비스마다 프록시를 세우고, 제어 평면이 그 프록시들에게 규칙을 한꺼번에 내려보낸다. 고를지 말지는 코드를 안 고치고 규칙을 바꿔 얻는 이득이 프록시가 먹는 자원과 호출마다 붙는 지연보다 큰가로 정한다.","kid":"교실마다 문 앞에 지킴이가 한 명씩 서 있다고 해 봐. 쪽지를 주고받을 때 꼭 지킴이 손을 거치니까, 누가 누구한테 몇 번 보냈는지 다 알아. 규칙을 바꿀 때도 선생님은 지킴이한테만 말하면 되고, 교실 안 애들은 하던 대로 하면 돼.","check":[{"q":"서비스가 셋뿐인 팀이 메시를 깔면 왜 손해일 수 있나","at":"흔한 오해"},{"q":"앱 코드를 안 고쳤는데 호출이 암호화되는 일이 어떻게 가능한가","at":"작동 원리"},{"q":"메시를 들일 때 필요한 부품만 골라 깔라고 하는 이유는 무엇인가","at":"주의사항"}],"myths":[{"wrong":"마이크로서비스면 메시는 당연히 깔아야 한다","right":"아니다. Azure 문서는 먼저 \"인그레스 컨트롤러만으로 충분한가\" 를 물으라고 한다. A/B 시험이나 트래픽 분할이 입구에서 되는 정도면 거기서 끝내라는 것이고, 얻는 것 없이 복잡도만 올리지 말라고 적혀 있다."},{"wrong":"앱을 안 고치니 공짜다","right":"아니다. 메시를 떠받치는 부품들이 CPU와 메모리를 먹고, 프록시와 정책 검사가 호출마다 지연을 더한다. 지연에 예민하거나 여유 자원이 없는 업무라면 도입을 다시 생각하라고 문서가 적는다."},{"wrong":"메시를 깔면 장애가 줄어든다","right":"메시는 재시도·차단·관측을 대신 걸어 줄 뿐 고장 난 서비스를 고치지 않는다. 부품이 늘어난 만큼 새로 관리해야 할 것도 같이 는다."}],"cases":[{"label":"클러스터 안 전면 암호화","note":"지정한 서비스 사이에 mTLS를 켠다. 애플리케이션 코드와 인프라를 고치지 않고 기본이 암호화인 상태로 만든다."},{"label":"카나리 배포","note":"조건에 맞는 일부 호출만 새 버전으로 보내고, 시험이 성공하면 비율을 점점 올려 결국 전부 넘긴다."},{"label":"장애 주입 시험","note":"시험 환경에서 서비스 사이에 일부러 결함을 넣어, 한쪽이 무너졌을 때 나머지가 버티는지 본다."}],"dia":{"shape":"층","title":"서비스끼리 주고받는 일은 어느 층에서 처리되나","rows":[{"who":"앱 코드","what":"업무만 한다. 상대를 부르되 통신 규칙은 모른다"},{"who":"데이터 평면","what":"서비스마다 붙은 프록시. 드나드는 호출이 전부 여기를 지난다"},{"who":"제어 평면","what":"프록시 전부에게 같은 규칙과 신분증을 내려보낸다"}],"sum":"통신에 관한 일이 앱에서 빠져나와 그 아래 인프라 층으로 내려간 것이다"}},"arch--sharding":{"definition":"사용자 1번부터 백만 번까지는 A 서버, 백만 한 번부터는 B 서버에 둔다. 각 서버는 전체의 일부만 갖고 있어서 그만큼 가볍다.","name":"= Shard 는 깨진 그릇의 조각 하나를 뜻하는 말이다. 그릇 하나를 조각으로 갈라 나눠 담는다는 그림이 이름에 그대로 들어 있다","analogy":"도서관의 분관. 장서가 백만 권이 되면 한 건물에 다 넣을 수 없다. ㄱ부터 ㅅ은 본관, ㅇ부터 ㅎ은 분관에 두면 각 건물은 감당할 만해진다. 대신 어느 책이 어디 있는지 아는 규칙이 있어야 한다.","example":"게임에 들어갈 때 서버를 먼저 고르게 하고 다른 서버 친구와는 못 만나는 그 구조와 같다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"어떤 기준으로 나눌지가 전부다. 이 기준을 샤드 키라고 한다.\n\n| 방식 | 어떻게 나누나 | 문제 |\n|---|---|---|\n| 범위 | ID 1~100만은 A, 그다음은 B | 새 데이터가 한쪽에 몰린다 |\n| 해시 | ID를 해시해서 나머지로 정한다 | 고르게 퍼지지만 범위 검색이 어렵다 |\n| 지역 | 한국 사용자는 A, 미국은 B | 지역별 크기 차이가 그대로 온다 |\n\n샤드 키를 잘못 고르면 한 서버에만 데이터와 요청이 몰린다. 이걸 핫스팟이라고 하고, 샤딩 실패의 대부분이 여기서 나온다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **대형 서비스의 사용자 테이블** — 수억 건을 사용자 ID 기준으로 수십 대에 나눈다.\n- **메신저 대화방** — 방 ID로 나눠서, 한 방의 메시지는 항상 같은 서버에 모이게 한다.\n- **지역 분리** — 데이터를 나라별로 두면 규제도 만족하고 응답도 빨라진다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **샤딩하면 무조건 빨라진다** — 여러 샤드를 뒤져야 하는 질의는 오히려 느려진다. 샤드 키로 찾는 질의만 빨라진다.\n- **나중에 샤드 키를 바꿀 수 있다** — 바꾸려면 전체 데이터를 다시 배치해야 한다. 서비스 중에 하기가 매우 어려워서 처음 결정이 사실상 마지막 결정이다.\n- **샤딩이 백업을 대신한다** — 나눠 담는 것과 복제해 두는 것은 다르다. 샤드 하나가 날아가면 그 몫의 데이터가 사라진다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **샤드를 넘는 조인과 트랜잭션을 피한다.** 서버가 다르면 한 번에 묶을 수 없다. 같이 읽는 데이터는 같은 샤드에 모이도록 키를 고른다.\n- **샤딩은 마지막 수단이다.** 인덱스, 캐시, 읽기 전용 복제본을 먼저 써본다. 샤딩은 되돌리기가 가장 어렵다."}],"figure":"```도해\n흐름: 사용자 정보를 찾을 때 어느 서버로 가나\n앱 :: 사용자 ID 8,451,203 번 정보를 찾는다\n샤드 규칙 :: ID 를 샤드 수로 나눈 나머지를 본다\n샤드 규칙 :: 나머지가 3 이다. 4번 서버 담당\n4번 서버 :: 자기가 가진 25만 건 안에서 찾는다\n< 앱 :: 결과를 받는다. 몇 번 서버였는지는 몰라도 된다\n= 어느 서버에 있는지 계산으로 알 수 있어야 샤딩이 성립한다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 데이터가 서버 한 대에 안 들어가면 어떻게 하나\n샤딩 없이 || 샤딩으로\n저장 한계 :: 서버 사양이 상한 || 서버를 늘리면 됨\n검색 범위 :: 전체를 뒤진다 || 자기 몫만 뒤진다\n장비 교체 :: 더 비싼 한 대 || 평범한 여러 대\n= 한 대를 키우는 데는 끝이 있지만 대수를 늘리는 데는 없다\n```\n\n데이터가 늘면 서버를 키우는 것으로 한동안 버틸 수 있다. 메모리를 늘리고 디스크를 늘리고 CPU를 늘린다. 하지만 그 방법에는 끝이 있고, 끝에 가까워질수록 값이 가파르게 오른다.\n\n샤딩은 방향을 바꾼다. 한 대를 키우는 대신 평범한 서버를 여러 대 두고 데이터를 나눈다. 각 서버가 다루는 양이 줄어드니 검색도 빨라진다."},"recap":"**\"한 대에 안 들어가서 나눠 담는 그 조각\"** 이라고 읽으면 된다. 데이터를 여러 서버에 나눠 담아 한 대의 한계를 넘는다. 샤드 키 선택이 성패를 가르고, 한 번 정하면 바꾸기가 매우 어렵다.","kid":"책이 백만 권이 되면 한 건물에 다 못 넣지? 그래서 ㄱ부터 ㅅ은 본관, ㅇ부터 ㅎ은 옆 건물에 나눠 둬. 대신 어느 글자가 어느 건물인지를 먼저 정해 둬야 하고, 한 번 정한 걸 바꾸려면 책을 전부 다시 옮겨야 해.","check":[{"q":"최근 가입자 조회가 유독 느리다면 어떤 샤드 키를 썼을 가능성이 큰가","at":"작동 원리"},{"q":"샤드 키로 찾지 않는 질의는 왜 느려지나","at":"흔한 오해"},{"q":"샤딩보다 먼저 시도해볼 것은 무엇이고 그 이유는","at":"주의사항"}],"myths":[{"wrong":"샤딩하면 무조건 빨라진다","right":"여러 샤드를 뒤져야 하는 질의는 오히려 느려진다. 샤드 키로 찾는 질의만 빨라진다."},{"wrong":"나중에 샤드 키를 바꿀 수 있다","right":"바꾸려면 전체 데이터를 다시 배치해야 한다. 서비스 중에 하기가 매우 어려워서 처음 결정이 사실상 마지막 결정이다."},{"wrong":"샤딩이 백업을 대신한다","right":"나눠 담는 것과 복제해 두는 것은 다르다. 샤드 하나가 날아가면 그 몫의 데이터가 사라진다."}],"cases":[{"label":"대형 서비스의 사용자 테이블","note":"수억 건을 사용자 ID 기준으로 수십 대에 나눈다."},{"label":"메신저 대화방","note":"방 ID로 나눠서, 한 방의 메시지는 항상 같은 서버에 모이게 한다."},{"label":"지역 분리","note":"데이터를 나라별로 두면 규제도 만족하고 응답도 빨라진다."}],"dia":{"shape":"흐름","title":"사용자 정보를 찾을 때 어느 서버로 가나","rows":[{"who":"앱","what":"사용자 ID 8,451,203 번 정보를 찾는다"},{"who":"샤드 규칙","what":"ID 를 샤드 수로 나눈 나머지를 본다"},{"who":"샤드 규칙","what":"나머지가 3 이다. 4번 서버 담당"},{"who":"4번 서버","what":"자기가 가진 25만 건 안에서 찾는다"},{"who":"앱","what":"결과를 받는다. 몇 번 서버였는지는 몰라도 된다","back":true}],"sum":"어느 서버에 있는지 계산으로 알 수 있어야 샤딩이 성립한다"}},"arch--sidecar":{"definition":"Azure 문서는 이것을 오토바이 옆칸에 빗대 설명한다. 본체와 함께 만들어지고 함께 내려간다는 점에서 붙어 있지만, 프로세스나 컨테이너가 따로여서 언어도 갱신 주기도 따로 간다. 가장 흔한 구현이 컨테이너를 하나 더 세우는 방식이고, 쿠버네티스에서는 그 컨테이너를 본체와 같은 파드에 넣는다.","name":"Side :: 옆\nCar :: 달린 수레\n= 붙여 읽으면 \"옆에 달린 수레\". 오토바이 옆칸처럼 본체에 붙어 같이 다니지만 바퀴는 따로다","analogy":"오토바이 옆에 붙은 한 사람 타는 수레. 혼자 굴러가지 않고 오토바이가 서면 같이 서지만, 그 칸에 무엇을 싣든 오토바이는 상관하지 않는다.","example":"쿠버네티스에서 파드 하나를 열어봤더니 내가 만든 적 없는 컨테이너가 하나 더 떠 있던 그 화면이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"쿠버네티스 문서는 사이드카를 \"같은 파드 안에서 주 애플리케이션 컨테이너와 함께 도는 보조 컨테이너\" 로 정의하고, 주 컨테이너 코드를 고치지 않고 기록·감시·보안·동기화 같은 기능을 더하는 데 쓴다고 적는다.\n\n수명을 다루는 방식이 중요하다. 사이드카는 파드가 사는 내내 주 컨테이너와 나란히 돌고, 본체를 건드리지 않고 따로 시작하거나 다시 띄울 수 있다. 파드가 내려갈 때는 kubelet이 주 애플리케이션 컨테이너가 완전히 멈출 때까지 사이드카 종료를 미룬다. 그리고 명세에 적힌 순서의 역순으로 내린다. 본체가 마지막 기록을 남기는 동안 기록을 받아 줄 옆칸이 먼저 사라지면 안 되기 때문이다.\n\n대신 종료 시간이 빠듯하면 사이드카는 정리할 틈 없이 강제로 끊길 수 있다. 그래서 파드가 내려갈 때 사이드카의 종료 코드가 0이 아닌 것은 정상이고, 바깥 도구는 대체로 그 값을 무시해야 한다고 문서가 적어 둔다.\n\n자원 계산도 같이 본다. 파드가 스케줄러에게 요구하는 양에는 앱 컨테이너 몫과 사이드카 몫이 함께 들어간다. 옆칸을 하나 붙이면 인스턴스 수만큼 그 몫이 늘어난다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **서비스 메시의 대리인** — 서비스마다 프록시를 옆칸으로 붙여 경로 지정·재시도·mTLS·정책·계측을 앱 코드 수정 없이 처리한다.\n- **계측 수집기** — OpenTelemetry Collector 같은 부품을 옆칸으로 띄워 지표와 추적을 다듬어 내보낸다. 앱은 그 형식을 몰라도 된다.\n- **의존성 감추기** — 설정 읽기, 서비스 찾기, 상태 확인 같은 일을 옆칸이 맡고, 앱은 언어와 상관없이 같은 방식으로 부른다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **공통 기능은 무조건 옆에 붙이는 게 낫다** — 아니다. Azure 문서는 라이브러리로 넣는 쪽이 더 깊게 붙고 네트워크 부담도 적다고 적는다. 플랫폼이 이미 그 기능을 준다면 옆칸은 복잡도만 늘린다.\n- **옆칸은 가볍다** — 인스턴스마다 하나씩 뜬다. 앱이 작으면 격리로 얻는 것보다 옆칸 몫으로 나가는 자원이 더 크다.\n- **옆칸만 따로 늘려서 처리량을 올릴 수 있다** — 못 한다. 본체와 수명이 묶여 있어서 본체를 늘려야 옆칸도 는다. 따로 늘려야 하는 기능이면 사이드카가 아니라 별도 서비스로 뗀다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **주고받는 횟수가 잦으면 다시 생각한다.** 프로세스 사이를 건너가는 비용이 붙는다. 부품끼리 아주 자주 부르는 구조에는 맞지 않는다.\n- **통신 방식은 언어를 안 타는 것으로 고른다.** 언어에 묶인 방식을 쓰면 사이드카를 쓰는 이유가 사라진다.\n- **넣기 전에 세 가지를 먼저 묻는다.** 라이브러리로 되는가, 그냥 별도 서비스가 나은가, 플랫폼이 이미 해 주는가. 셋 다 아니면 그때 옆칸을 단다."}],"figure":"```도해\n대조: 부가 기능을 본체에 넣는 것과 옆에 붙이는 것은 무엇이 다른가\n본체 안에 넣으면 |=| 옆에 붙이면\n쓰는 언어 :: 본체와 같아야 한다 || 아무 언어나 된다\n고장 :: 본체까지 같이 죽는다 || 그 칸만 죽는다\n갱신 :: 본체를 다시 빌드 || 옆만 따로 올린다\n호출 :: 같은 안에서 즉시 || 한 번 더 건너간다\n= 옆에 따로 띄우되 본체와 수명은 같이한다. 격리를 얻고 지연을 내준다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 서비스마다 언어가 다르면 공통 기능을 어떻게 넣나\n사이드카 없이 || 사이드카로\n로그·보안 :: 언어마다 만든다 || 한 번 만들어 붙인다\n새 언어 도입 :: 그만큼 또 만든다 || 그대로 붙인다\n고칠 때 :: 전부 다시 빌드 || 옆칸만 바꿔 단다\n= 공통으로 해야 할 일을 본체 밖으로 꺼내면 언어 수만큼 만들 필요가 없다\n```\n\n애플리케이션에는 업무와 상관없는 일이 늘 따라붙는다. 기록 남기기, 상태 알리기, 설정 읽기, 바깥과 연결하기 같은 것들이다. 이걸 본체 안에 넣으면 자원을 같이 써서 빠르지만 격리가 없다. 한 군데가 터지면 전체가 같이 내려가고, 반드시 본체와 같은 언어로 만들어야 한다. 서비스가 여러 언어로 되어 있으면 같은 기능을 언어 수만큼 만들어 유지해야 한다.\n\n그렇다고 별도 서비스로 떼어 놓으면 이번에는 네트워크를 건너가야 해서 지연이 붙는다. 사이드카는 그 사이에 있다. 프로세스는 나누되 같은 호스트에 붙여 두어, 언어에서는 풀려나고 거리에서는 크게 손해 보지 않는다. 본체 인스턴스마다 하나씩 따라붙고 수명을 함께한다."},"recap":"**\"본체 옆칸에 태워 같이 다니는 보조석\"** 이라고 읽으면 된다. 프로세스를 나눠 언어와 갱신 주기에서 풀려나고, 같은 호스트에 붙여 거리 손해를 줄인다. 붙일지 말지는 격리로 얻는 것이 인스턴스마다 드는 자원과 한 번 더 건너가는 지연보다 큰가로 정한다.","kid":"오토바이 옆에 사람 한 명 타는 작은 칸이 달린 거 봤지? 오토바이는 달리는 일만 하고, 짐 챙기고 지도 보는 일은 옆칸에 탄 애가 해. 옆칸 애가 넘어져도 오토바이는 계속 달리지만, 오토바이가 서면 옆칸도 같이 서.","check":[{"q":"앱이 작을수록 옆칸을 다는 것이 손해가 되는 이유는 무엇인가","at":"흔한 오해"},{"q":"파드가 내려갈 때 옆칸을 본체보다 나중에 내리는 이유는 무엇인가","at":"작동 원리"},{"q":"같은 기능을 라이브러리로 넣는 쪽이 나을 때는 언제인가","at":"주의사항"}],"myths":[{"wrong":"공통 기능은 무조건 옆에 붙이는 게 낫다","right":"아니다. Azure 문서는 라이브러리로 넣는 쪽이 더 깊게 붙고 네트워크 부담도 적다고 적는다. 플랫폼이 이미 그 기능을 준다면 옆칸은 복잡도만 늘린다."},{"wrong":"옆칸은 가볍다","right":"인스턴스마다 하나씩 뜬다. 앱이 작으면 격리로 얻는 것보다 옆칸 몫으로 나가는 자원이 더 크다."},{"wrong":"옆칸만 따로 늘려서 처리량을 올릴 수 있다","right":"못 한다. 본체와 수명이 묶여 있어서 본체를 늘려야 옆칸도 는다. 따로 늘려야 하는 기능이면 사이드카가 아니라 별도 서비스로 뗀다."}],"cases":[{"label":"서비스 메시의 대리인","note":"서비스마다 프록시를 옆칸으로 붙여 경로 지정·재시도·mTLS·정책·계측을 앱 코드 수정 없이 처리한다."},{"label":"계측 수집기","note":"OpenTelemetry Collector 같은 부품을 옆칸으로 띄워 지표와 추적을 다듬어 내보낸다. 앱은 그 형식을 몰라도 된다."},{"label":"의존성 감추기","note":"설정 읽기, 서비스 찾기, 상태 확인 같은 일을 옆칸이 맡고, 앱은 언어와 상관없이 같은 방식으로 부른다."}],"dia":{"shape":"대조","title":"부가 기능을 본체에 넣는 것과 옆에 붙이는 것은 무엇이 다른가","rows":[{"who":"","what":"본체 안에 넣으면 || 옆에 붙이면","left":"본체 안에 넣으면","right":"옆에 붙이면","even":true},{"who":"쓰는 언어","what":"본체와 같아야 한다 || 아무 언어나 된다","left":"본체와 같아야 한다","right":"아무 언어나 된다"},{"who":"고장","what":"본체까지 같이 죽는다 || 그 칸만 죽는다","left":"본체까지 같이 죽는다","right":"그 칸만 죽는다"},{"who":"갱신","what":"본체를 다시 빌드 || 옆만 따로 올린다","left":"본체를 다시 빌드","right":"옆만 따로 올린다"},{"who":"호출","what":"같은 안에서 즉시 || 한 번 더 건너간다","left":"같은 안에서 즉시","right":"한 번 더 건너간다"}],"sum":"옆에 따로 띄우되 본체와 수명은 같이한다. 격리를 얻고 지연을 내준다"}},"arch--stateless-workload":{"definition":"Twelve-Factor App 은 이것을 \"프로세스는 무상태이고 아무것도 공유하지 않는다\" 로 못 박고, 오래 남아야 하는 것은 전부 바깥의 저장소로 보내라고 적는다. 쿠버네티스도 같은 선으로 일감을 가른다 — 서로 바꿔 껴도 되는 것은 Deployment 로, 이름과 디스크를 붙들어야 하는 것은 StatefulSet 으로 돌린다.","name":"State :: 지금까지의 기억\nless :: 없는\nWorkload :: 돌려야 할 일감\n= 붙여 읽으면 \"기억을 안 쥔 일감\". 기억이 밖에 있으니 아무 대나 그 일을 받아도 된다","analogy":"손님 사정을 직원이 외우는 대신 번호표에 딸린 서류에 다 적어 두는 은행 창구다.","example":"새로고침 한 번에 장바구니가 통째로 비던 옛날 사이트가, 기억을 밖에 안 맡겼을 때 벌어지던 일이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"무상태는 기억이 없다는 뜻이 아니라 **기억을 딴 데 둔다**는 뜻이다. Twelve-Factor 는 오래 남아야 하는 것을 전부 \"상태를 지닌 뒷단 저장소, 대개는 데이터베이스\" 로 보내라고 적는다. 로그인 상태처럼 잠깐만 필요한 것은 시간이 지나면 스스로 사라지는 저장소에 둔다.\n\n안에 남겨도 되는 것은 딱 하나, 한 번의 처리 안에서만 쓰고 버리는 임시 사본이다. 같은 대가 다음 부탁도 받는다는 가정은 성립하지 않는다 — 여러 대가 번갈아 받고, 다시 켜지면 안의 것은 지워지기 때문이다. 그래서 자산을 미리 굽는 일 같은 것도 돌리는 중이 아니라 만드는 단계에서 끝내 둔다.\n\n판정법은 간단하다. **그 일감을 지웠다 다시 켰을 때 사라지는 것이 있으면 무상태가 아니다.** 사라지는 것이 있는데도 무상태인 척 여러 대로 늘리면, 고장은 나지 않고 대신 \"가끔 로그아웃되는\" 일이 벌어진다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 무엇을 안에 두고 무엇을 밖으로 내보내나","body":"| 남길 것 | 어디에 두나 | 그 대를 지웠다 켜면 |\n|---|---|---|\n| **한 번의 처리 중에만 쓰는 것** | 그 대의 안. 12요소가 허락하는 유일한 자리 | 사라져도 아무 일 없다 |\n| **로그인처럼 잠깐 쓰는 기억** | 시간이 지나면 스스로 지워지는 바깥 저장소 | 그대로 이어진다 |\n| **오래 남아야 하는 기록** | 상태를 지닌 뒷단 저장소 | 그대로 이어진다 |\n| **미리 구워 둘 자산** | 돌리는 중이 아니라 만드는 단계 | 다시 구울 것이 없다 |\n\n첫 줄만 안이고 나머지는 전부 밖이다. 그래서 이 성질은 공짜로 얻는 것이 아니다 — 내보낸 기억을 맡아 줄 자리가 밖에 하나 더 생기고, 그 자리가 죽으면 무상태로 만들어 둔 대들이 전부 같이 멈춘다. 안의 문제를 없앤 것이 아니라 한곳으로 모은 것이다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **자동으로 대수 늘리기** — 붐비면 켜고 한가하면 끄는 일이 성립하려면 켜자마자 아무 부탁이나 받을 수 있어야 한다.\n- **한 대씩 갈아 끼우는 배포** — 옛 대를 하나 내리고 새 대를 하나 올리는 동안 쓰던 사람이 안 끊긴다. 끊길 기억이 그 안에 없어서다.\n- **로그인 상태 옮기기** — 붙여 두기를 쓰던 자리를 바깥 저장소로 옮기면 앞단이 아무 대에나 보내도 된다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **무상태면 아무것도 기억 못 한다** — 기억은 그대로 있다. 다만 일감 안이 아니라 바깥 저장소에 있고, 일감은 표에 적힌 열쇠로 그때그때 꺼내 온다.\n- **붙여 두기를 켜면 같은 문제를 푼 것이다** — 그 대가 죽는 순간 거기 붙어 있던 사람들만 골라 잃는다. Twelve-Factor 는 붙여 두기를 규칙 위반으로 적는다.\n- **전부 무상태로 만들면 된다** — 이름과 디스크를 붙들어야 하는 일감이 있다. 쿠버네티스 문서는 그런 일감에 Deployment 대신 StatefulSet 을 쓰라고 적는다."}],"figure":"```도해\n흐름: 기억을 밖에 두면 한 번의 부탁은 어떻게 도나\n사람 :: 표 한 장을 들고 온다\n앞단 :: 아무 대에나 그냥 넘긴다\n일감 :: 제 안에 아무것도 없어 밖에 묻는다\n저장소 :: 표에 걸린 기억을 돌려준다\n< 일감 :: 처리해 답하고, 남긴 것 없이 끝낸다\n= 기억이 밖에 있으니 다음 부탁을 다른 대가 받아도 똑같다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 일감이 기억을 쥐고 있으면 무슨 일이 생기나\n쥐고 있으면 || 안 쥐면\n갑자기 몰릴 때 :: 늘려도 안 나뉜다 || 켜는 대로 나뉜다\n새 판 올릴 때 :: 쓰던 사람이 끊긴다 || 조용히 갈린다\n한 대가 죽으면 :: 그 기억이 사라진다 || 남은 대가 잇는다\n= 늘리기·갈아 끼우기·되살리기가 전부 \"아무 대나 된다\" 에 얹혀 있다\n```\n\n기억을 안에 쥐고 있으면 그 사람의 다음 부탁을 반드시 같은 대로 보내야 한다. 그 붙여 두기(sticky session)를 Twelve-Factor 는 대놓고 규칙 위반이라고 적는다. 대를 늘려도 짐이 고르게 안 나뉘고, 새 판을 올리려고 옛 대를 내리는 순간 그 안에 있던 것이 함께 사라지고, 그 대가 고장 나면 거기 붙어 있던 사람들만 골라 잃는다.\n\n기억을 밖의 저장소로 내보내면 대들은 서로 구분되지 않는 여벌이 된다. 애저 Well-Architected 문서가 계산 계층을 \"어떤 상태도 없이 깨끗하게 두라\" 고 적는 이유가 여기 있다 — 부탁을 받는 대는 언제든 지워지거나 고장 나거나 교체될 수 있어서다. 쿠버네티스 문서가 StatefulSet 의 파드를 두고 \"서로 바꿔 낄 수 없다\" 고 못 박는 것도 뒤집어 읽으면 같은 말이다. 바꿔 낄 수 없다는 말이 굳이 필요했다는 것은, Deployment 쪽 파드는 바꿔 낄 수 있다는 뜻이다."},"recap":"**\"기억을 밖에 맡겨서 아무나 대신할 수 있게 만든 일감\"** 이라고 읽으면 된다. 기억이 안에 없으니 대를 늘리거나 줄이거나 통째로 갈아 끼워도 쓰는 사람은 모르고, 대신 그 기억을 맡아 줄 저장소가 반드시 밖에 있어야 한다. 그러니 무상태인지 아닌지는 그 일감을 지웠다 다시 켰을 때 무엇이 사라지는지로 가른다.","kid":"은행에서 번호표를 뽑으면 어느 창구로 가도 되지? 직원이 네 사정을 머리로 외우는 게 아니라 번호표에 딸린 서류를 그때그때 꺼내 보기 때문이야. 그래서 직원이 교대해도, 창구를 하나 더 열어도 너는 아무 데나 가서 그대로 이어 하면 돼.","check":[{"q":"대를 두 배로 켰는데도 짐이 고르게 안 나뉘던 이유는","at":"해결하는 문제"},{"q":"기억을 안 쥔다면서 로그인 상태는 어떻게 이어지나","at":"작동 원리"},{"q":"기억을 밖으로 내보내면 대신 무엇을 떠안게 되나","at":"비교"}],"myths":[{"wrong":"무상태면 아무것도 기억 못 한다","right":"기억은 그대로 있다. 다만 일감 안이 아니라 바깥 저장소에 있고, 일감은 표에 적힌 열쇠로 그때그때 꺼내 온다."},{"wrong":"붙여 두기를 켜면 같은 문제를 푼 것이다","right":"그 대가 죽는 순간 거기 붙어 있던 사람들만 골라 잃는다. Twelve-Factor 는 붙여 두기를 규칙 위반으로 적는다."},{"wrong":"전부 무상태로 만들면 된다","right":"이름과 디스크를 붙들어야 하는 일감이 있다. 쿠버네티스 문서는 그런 일감에 Deployment 대신 StatefulSet 을 쓰라고 적는다."}],"cases":[{"label":"자동으로 대수 늘리기","note":"붐비면 켜고 한가하면 끄는 일이 성립하려면 켜자마자 아무 부탁이나 받을 수 있어야 한다."},{"label":"한 대씩 갈아 끼우는 배포","note":"옛 대를 하나 내리고 새 대를 하나 올리는 동안 쓰던 사람이 안 끊긴다. 끊길 기억이 그 안에 없어서다."},{"label":"로그인 상태 옮기기","note":"붙여 두기를 쓰던 자리를 바깥 저장소로 옮기면 앞단이 아무 대에나 보내도 된다."}],"dia":{"shape":"흐름","title":"기억을 밖에 두면 한 번의 부탁은 어떻게 도나","rows":[{"who":"사람","what":"표 한 장을 들고 온다"},{"who":"앞단","what":"아무 대에나 그냥 넘긴다"},{"who":"일감","what":"제 안에 아무것도 없어 밖에 묻는다"},{"who":"저장소","what":"표에 걸린 기억을 돌려준다"},{"who":"일감","what":"처리해 답하고, 남긴 것 없이 끝낸다","back":true}],"sum":"기억이 밖에 있으니 다음 부탁을 다른 대가 받아도 똑같다"}},"arch--strangler-fig":{"definition":"값은 위험을 잘게 나누는 데 있고, 대가는 두 시스템이 한동안 나란히 살아야 한다는 데 있다. 그 기간 동안 운영·비용·데이터 정합성을 두 벌로 감당한다. Azure 문서는 이것을 잠시 세우는 전환기 구조로 보고, 위험을 줄이는 이득과 임시 인프라 비용을 저울에 같이 올리라고 적는다.","name":"Strangler :: 목을 조르는 것\nFig :: 무화과나무\n= 붙여 읽으면 \"목 조르는 무화과\". 남의 나무를 타고 올라가 뿌리를 내리고, 끝에는 그 나무 자리를 대신 차지하는 식물이다","analogy":"문을 안 닫고 한 칸씩 고치는 가게. 오늘은 안쪽 주방만, 다음 달은 홀만 바꾸는데 손님은 늘 같은 문으로 들어와서 안이 바뀐 줄 모른다.","example":"한 사이트인데 어떤 화면만 옛날 디자인 그대로인 것을 본 적이 있을 것이다. 갈아 끼우는 중간에 있는 것이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"AWS 문서는 이 이주를 세 마디로 나눈다. **바꾼다** — 옛 애플리케이션이 도는 동안 옆에서 기능을 새로 만들거나 옮긴다. **같이 산다** — 되돌릴 자리로 옛 시스템을 그대로 두고, 앞단에 프록시를 놓아 바깥 호출을 가로채 새 쪽으로 돌린다. **없앤다** — 그 기능으로 가는 요청이 없어지면 옛쪽에서 그 기능을 걷어낸다.\n\n까다로운 것은 데이터다. Azure 문서가 든 예에서는 도메인별 테이블을 새 데이터베이스로 옮기고, 옮기는 동안 원본과 사본을 함께 굴린다. 처음 한 번은 ETL로 옮기고, 그 뒤로는 변경분을 계속 따라 붙인다. 양쪽이 같은 값을 갖는지 확인한 다음에야 새 쪽을 원본으로 삼는다. 옛 테이블을 지우기 전까지는 되돌릴 수 있고, 지운 다음에는 복원과 재적용이 필요해 위험이 크게 오른다. 그래서 지우는 일은 도메인마다 맨 마지막에 따로 한다.\n\n이주 도중에는 두 시스템이 서로를 부른다. 새 쪽이 아직 안 옮긴 기능을 부르기도 하고, 안 옮긴 옛 부품이 새 기능을 부르기도 한다. 이때 사이에 번역기를 하나 두는 것이 부패 방지 계층(Anti-corruption Layer)이다. 이게 없으면 새 시스템이 옛 시스템의 말투를 그대로 받아 쓰게 된다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **모놀리스 쪼개기** — 한 덩어리 애플리케이션에서 도메인 하나씩 떼어 서비스로 만들고, 앞단 프록시로 그 경로만 새 쪽에 넘긴다.\n- **덩치 큰 데이터베이스 분해** — 여러 도메인이 함께 쓰던 테이블을 도메인별 데이터베이스로 옮기고, 값이 맞는지 확인한 뒤에 전환한다.\n- **API 버전 올리기** — 옛 버전을 그대로 두고 새 버전을 옆에 세운 뒤, 창구에서 호출을 옮겨 간다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **작은 시스템도 이렇게 옮기는 게 안전하다** — 아니다. AWS 문서는 규모가 작고 복잡도가 낮은 시스템에는 맞지 않는다고 못 박는다. 통째로 바꾸면 될 것에 창구와 이중 운영을 얹으면 비용만 남는다.\n- **창구는 그냥 지나가는 길이라 위험이 없다** — 두 문서가 같은 경고를 한다. 창구가 단일 장애점이 되거나 성능 병목이 되면, 이주를 안전하게 하려고 세운 것이 가장 위험한 지점이 된다.\n- **옛 시스템 소스를 안 건드려도 된다** — 못 건드리면 이 패턴을 쓸 수 없다. 옮긴 기능을 옛쪽에서 꺼 두고 내부 호출을 새 쪽으로 돌리려면 옛 코드를 고쳐야 한다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **가로챌 수 없으면 시작할 수 없다.** 뒤쪽으로 가는 요청을 앞에서 가로채 라우팅할 수 없는 구조라면 후보에서 뺀다.\n- **빨리 끄고 싶으면 다른 방법을 본다.** 원래 시스템을 짧은 기간 안에 완전히 내려야 하는 상황에는 맞지 않는다. 이 방식은 옛것이 한동안 살아 있는 것을 전제로 한다.\n- **기능마다 되돌릴 계획을 같이 쓴다.** AWS 문서는 옮긴 서비스마다 빠르고 안전하게 옛 방식으로 돌아갈 계획이 필요하다고 적는다. 계획이 없으면 조각내서 얻은 이득이 사라진다."}],"figure":"```도해\n흐름: 낡은 시스템은 어떻게 통째로 멈추지 않고 사라지나\n창구 :: 옛 시스템 앞에 요청을 받아 넘기는 창구를 세운다\n옛 시스템 :: 처음에는 거의 모든 요청이 이쪽으로 간다\n새 서비스 :: 기능 하나를 새로 만들고 그 요청만 이쪽으로 돌린다\n창구 :: 옮긴 기능이 늘수록 옛쪽으로 가는 길이 줄어든다\n옛 시스템 :: 남길 기능이 없어지면 전원을 내린다\n창구 :: 창구도 걷어내고 쓰는 쪽이 새 시스템에 바로 붙는다\n= 통째로 바꾸는 대신 창구를 세워 한 조각씩 옮기면, 옛 시스템은 할 일이 없어져 저절로 말라 죽는다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 낡은 시스템을 한 번에 갈아엎으면 무엇이 달라지나\n한 번에 || 한 조각씩\n전환 시점 :: 하루에 몰린다 || 매주 조금씩\n사고가 나면 :: 통째로 되돌린다 || 그 기능만 되돌린다\n도중에 멈추면 :: 아무것도 못 쓴다 || 쓰던 대로 돈다\n= 위험을 한 날에 몰지 않고 여러 날로 잘게 나누는 것, 그것이 이 패턴이 파는 물건이다\n```\n\n오래된 시스템은 만들 때 쓰던 도구와 구조가 낡아가고, 기능이 쌓일수록 고치기도 늘리기도 어려워진다. 그렇다고 통째로 새로 짜서 어느 날 한꺼번에 바꾸면 그날 하루에 모든 위험이 몰린다. 잘못되면 되돌릴 것은 시스템 전체이고, 그동안 사업은 멈춘다.\n\nStrangler Fig는 앞에 창구를 하나 세워 그 선택을 없앤다. 창구가 요청을 가로채 옛쪽으로 보낼지 새쪽으로 보낼지 정하므로, 쓰는 사람은 이주가 진행 중인지도 모른 채 같은 곳으로 들어온다. 옮기는 단위가 기능 하나로 작아지면 되돌리는 단위도 기능 하나로 작아진다."},"recap":"**\"옛것을 감고 자라 그 자리를 대신하는 그 이주 방식\"** 이라고 읽으면 된다. 앞에 창구를 세워 요청을 옛쪽과 새쪽으로 나눠 보내고, 옮긴 기능이 늘면 옛 시스템은 할 일이 없어져 내려간다. 요청을 가로챌 수 있고 두 시스템이 한동안 같이 살아도 되면 고르고, 규모가 작거나 빨리 끝내야 하면 고르지 않는다.","kid":"동네 가게가 문을 안 닫고 고칠 때 있지? 오늘은 안쪽 주방만 새로 바꾸고, 다음 달엔 의자를 바꿔. 다 바꾸고 나면 낡은 건 하나도 안 남는데, 너는 그동안 늘 같은 문으로 들어가서 사 먹었어.","check":[{"q":"요청을 앞에서 가로챌 수 없는 시스템에 이 방식을 못 쓰는 이유는 무엇인가","at":"주의사항"},{"q":"옛 쪽과 새 쪽이 서로를 불러야 할 때 사이에 무엇을 두나","at":"작동 원리"},{"q":"이주 도중에 사고가 났을 때 되돌릴 범위가 왜 좁아지나","at":"해결하는 문제"}],"myths":[{"wrong":"작은 시스템도 이렇게 옮기는 게 안전하다","right":"아니다. AWS 문서는 규모가 작고 복잡도가 낮은 시스템에는 맞지 않는다고 못 박는다. 통째로 바꾸면 될 것에 창구와 이중 운영을 얹으면 비용만 남는다."},{"wrong":"창구는 그냥 지나가는 길이라 위험이 없다","right":"두 문서가 같은 경고를 한다. 창구가 단일 장애점이 되거나 성능 병목이 되면, 이주를 안전하게 하려고 세운 것이 가장 위험한 지점이 된다."},{"wrong":"옛 시스템 소스를 안 건드려도 된다","right":"못 건드리면 이 패턴을 쓸 수 없다. 옮긴 기능을 옛쪽에서 꺼 두고 내부 호출을 새 쪽으로 돌리려면 옛 코드를 고쳐야 한다."}],"cases":[{"label":"모놀리스 쪼개기","note":"한 덩어리 애플리케이션에서 도메인 하나씩 떼어 서비스로 만들고, 앞단 프록시로 그 경로만 새 쪽에 넘긴다."},{"label":"덩치 큰 데이터베이스 분해","note":"여러 도메인이 함께 쓰던 테이블을 도메인별 데이터베이스로 옮기고, 값이 맞는지 확인한 뒤에 전환한다."},{"label":"API 버전 올리기","note":"옛 버전을 그대로 두고 새 버전을 옆에 세운 뒤, 창구에서 호출을 옮겨 간다."}],"dia":{"shape":"흐름","title":"낡은 시스템은 어떻게 통째로 멈추지 않고 사라지나","rows":[{"who":"창구","what":"옛 시스템 앞에 요청을 받아 넘기는 창구를 세운다"},{"who":"옛 시스템","what":"처음에는 거의 모든 요청이 이쪽으로 간다"},{"who":"새 서비스","what":"기능 하나를 새로 만들고 그 요청만 이쪽으로 돌린다"},{"who":"창구","what":"옮긴 기능이 늘수록 옛쪽으로 가는 길이 줄어든다"},{"who":"옛 시스템","what":"남길 기능이 없어지면 전원을 내린다"},{"who":"창구","what":"창구도 걷어내고 쓰는 쪽이 새 시스템에 바로 붙는다"}],"sum":"통째로 바꾸는 대신 창구를 세워 한 조각씩 옮기면, 옛 시스템은 할 일이 없어져 저절로 말라 죽는다"}},"arch--timeout":{"definition":"부르는 쪽은 상대가 언제 답할지 모른다. 상대가 바쁜 것일 수도, 회선이 끊긴 것일 수도, 답이 영영 안 오는 것일 수도 있는데 기다리는 쪽에서는 셋이 똑같이 보인다. 그래서 \"여기까지\" 를 숫자로 적어 두고, 그 선을 넘으면 성공도 실패도 아닌 세 번째 결말로 끝낸다.","name":"Time :: 정해 둔 시간\nout :: 다 써 버렸다\n= 붙여 읽으면 \"시간을 다 썼다\". 다 쓴 다음에 무엇을 할지가 이 값의 나머지 절반이다","analogy":"약속 장소에서 \"30분까지만 기다리고 간다\" 고 나가기 전에 미리 정해 두는 일과 같다.","example":"화면의 동그라미가 한참 돌다가 \"요청 시간이 초과되었습니다\" 로 끝나는 그 순간이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n층: 같은 기다림에 상한이 어디부터 걸리나\n부르는 쪽 :: 이 일 전체가 몇 초 안에 끝나야 하는지 정한다\n그 아래 호출 :: 남은 시간을 물려받는다. 더 길게는 못 잡는다\n맨 아래 연결 :: 실제로 회선을 붙잡고 앉아 있는 자리\n= 위에서 정한 끝이 아래로 내려간다. 위가 끝나면 아래도 같이 끝난다\n```\n\n제한 시간은 보통 \"지금부터 몇 초\" 라는 상대 값으로 적지만, 안에서는 \"몇 시 몇 분까지\" 라는 마감 시각으로 바뀐다. 그 편이 아래로 물려주기 쉽기 때문이다. 위에서 3초를 걸고 1초를 쓴 뒤 아래를 부르면, 아래가 받는 것은 다시 3초가 아니라 남은 2초다. 아래에서 더 넉넉하게 잡으려 해도 위의 마감이 더 이르면 그쪽이 이긴다.\n\n마감이 지나면 그 일과 거기서 갈라져 나온 일이 한꺼번에 취소 신호를 받는다. 그래서 위에서 한 번 끊으면 아래에 흩어져 있던 일이 각자 멈춘다. 반대로 일이 제때 끝났는데 걸어 둔 시계를 꺼 주지 않으면, 그 시계와 딸린 자리가 부모가 끝날 때까지 남아 쌓인다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **결제 요청이 응답 없이 멈출 때** — 상한이 없으면 사용자는 돌아가는 동그라미만 본다. 상한이 있으면 몇 초 만에 \"다시 시도\" 를 띄울 수 있다.\n- **연결을 천천히 붙잡는 공격** — 요청 앞머리를 한 글자씩 보내며 자리만 차지하는 수법이다. 앞머리 받는 시간에 상한을 두면 그 자리에서 끊긴다.\n- **느린 뒷단 하나가 앞단을 잡아먹을 때** — 상한 없이 기다리면 앞단의 처리 자리가 하나씩 줄다가, 결국 전부 그 뒷단만 바라보고 서 있게 된다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **넉넉히 길게 잡아 두면 안전하다** — 30초짜리 상한은 사용자가 이미 포기한 뒤에야 끊는다. 상한은 \"여기까지는 기다릴 값어치가 있다\" 는 선이지 보험이 아니다.\n- **시간이 지났으면 상대도 그만뒀을 것이다** — 부르는 쪽이 기다림을 접었을 뿐이다. 취소가 아래까지 전해지지 않으면 받는 쪽은 아무도 안 받아 갈 답을 끝까지 만든다.\n- **상한에 걸리면 바로 다시 보내면 된다** — 이미 느려진 상대에게 요청이 더 몰린다. 얼마나 기다렸다 다시 보낼지는 [[Retry & Exponential Backoff]] 가 따로 다루는 문제다."}],"figure":"```도해\n흐름: 제한 시간을 건 기다림은 어떻게 끝나나\n부르는 쪽 :: 요청을 보내면서 시계를 함께 건다\n받는 쪽 :: 일을 한다. 얼마나 걸릴지는 아무도 모른다\n시계 :: 정해 둔 시간을 센다. 남은 시간이 줄어든다\n끝나는 자리 :: 답이 먼저면 그 답으로, 시계가 먼저면 오류로 끝난다\n= 기다림의 끝을 상대가 아니라 내가 미리 정해 두는 것이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 기다림에 상한이 없으면 무엇이 곤란한가\n상한 없이 || 상한을 두고\n느린 상대 :: 끝까지 붙잡힌다 || 정한 데서 끊는다\n붙잡힌 자원 :: 계속 쌓인다 || 제때 풀린다\n막힌 곳 하나 :: 앞단까지 멈춘다 || 여기서 멈춘다\n= 끝을 안 정하면 남의 느림이 그대로 내 고장이 된다\n```\n\n기본이 \"무한\" 인 자리가 생각보다 많다. 널리 쓰는 HTTP 클라이언트 중에는 제한 시간 값이 0이면 상한 없이 도는 것이 있고, 서버 쪽도 연결이 조용히 놀고 있을 때의 상한이 기본 0인 경우가 있다. 값을 안 적었다는 것은 \"얼마든 기다린다\" 고 적은 것과 같다.\n\n이게 그대로 공격 통로가 된다. 요청 앞머리를 아주 천천히 보내면서 연결만 붙잡고 있으면 상한 없는 서버는 그 연결을 놓지 못하고, 그런 연결이 쌓이면 멀쩡한 손님을 받을 자리가 없어진다. 그래서 요청 전체를 받는 시간과 앞머리를 받는 시간에 각각 0 아닌 값을 두라고 권하고, 한 서버 런타임은 아예 기본값을 \"없음\" 에서 5분으로 바꿨다. 넘기면 요청을 안쪽으로 넘기지 않고 408을 돌려준 뒤 연결을 닫는다."},"recap":"**\"여기까지만 기다린다고 미리 정해 둔 값\"** 이라고 읽으면 된다. 안 적어 두면 기본이 \"무한\" 인 자리가 많다는 것, 그리고 위에서 정한 마감이 아래로 내려간다는 것 둘을 기억하면 된다. 끊는 것은 내 기다림이지 상대가 하던 일이 아니다.","kid":"친구랑 놀이터에서 만나기로 했는데 친구가 안 오면 언제까지 기다릴래? 아무것도 안 정해 두면 해가 질 때까지 거기 서 있게 돼. 그래서 나가기 전에 \"30분만 기다리고 집에 간다\" 고 미리 정해 두는 거야.","check":[{"q":"값을 안 적어 두면 그 기다림은 언제 끝나나","at":"해결하는 문제"},{"q":"위에서 3초를 걸었는데 아래에서 5초를 잡으면 어느 쪽이 이기나","at":"작동 원리"},{"q":"시간이 다 됐을 때 부르는 쪽과 받는 쪽은 각각 어떻게 되나","at":"흔한 오해"}],"myths":[{"wrong":"넉넉히 길게 잡아 두면 안전하다","right":"30초짜리 상한은 사용자가 이미 포기한 뒤에야 끊는다. 상한은 \"여기까지는 기다릴 값어치가 있다\" 는 선이지 보험이 아니다."},{"wrong":"시간이 지났으면 상대도 그만뒀을 것이다","right":"부르는 쪽이 기다림을 접었을 뿐이다. 취소가 아래까지 전해지지 않으면 받는 쪽은 아무도 안 받아 갈 답을 끝까지 만든다."},{"wrong":"상한에 걸리면 바로 다시 보내면 된다","right":"이미 느려진 상대에게 요청이 더 몰린다. 얼마나 기다렸다 다시 보낼지는 [[Retry & Exponential Backoff]] 가 따로 다루는 문제다."}],"cases":[{"label":"결제 요청이 응답 없이 멈출 때","note":"상한이 없으면 사용자는 돌아가는 동그라미만 본다. 상한이 있으면 몇 초 만에 \"다시 시도\" 를 띄울 수 있다."},{"label":"연결을 천천히 붙잡는 공격","note":"요청 앞머리를 한 글자씩 보내며 자리만 차지하는 수법이다. 앞머리 받는 시간에 상한을 두면 그 자리에서 끊긴다."},{"label":"느린 뒷단 하나가 앞단을 잡아먹을 때","note":"상한 없이 기다리면 앞단의 처리 자리가 하나씩 줄다가, 결국 전부 그 뒷단만 바라보고 서 있게 된다."}],"dia":{"shape":"흐름","title":"제한 시간을 건 기다림은 어떻게 끝나나","rows":[{"who":"부르는 쪽","what":"요청을 보내면서 시계를 함께 건다"},{"who":"받는 쪽","what":"일을 한다. 얼마나 걸릴지는 아무도 모른다"},{"who":"시계","what":"정해 둔 시간을 센다. 남은 시간이 줄어든다"},{"who":"끝나는 자리","what":"답이 먼저면 그 답으로, 시계가 먼저면 오류로 끝난다"}],"sum":"기다림의 끝을 상대가 아니라 내가 미리 정해 두는 것이다"}},"arch--twelve-factor-app":{"definition":"앱 수백 개를 직접 만들어 올려 보고, 한 플랫폼 위에서 도는 앱 수십만 개를 곁에서 지켜본 사람들이 되풀이해서 본 문제를 목록으로 굳힌 것이다. 원문은 특히 세 가지를 눈여겨봤다고 적는다 — 앱이 시간을 두고 자랄 때 생기는 일, 만드는 사람들 사이의 협업, 그리고 소프트웨어가 삭아 가는 비용을 막는 것.","name":"Twelve :: 열둘\nFactor :: 지켜야 할 항목\nApp :: 서비스로 도는 앱\n= 붙여 읽으면 \"열두 항목짜리 앱\". 이름이 곧 목차이고, 항목마다 지킬 일이 하나씩이다","analogy":"수학여행 방 배정. 짐을 방에 못 박아 두지 않기로 미리 정해 두면 어느 방을 받아도 그날로 지낼 수 있다.","example":"설정 파일 하나를 안 옮겨서 새 환경에서만 앱이 안 뜨던 그 밤이 이 목록이 겨누는 장면이다.","tryit":"지금 쓰는 프로젝트 폴더에 접속 정보나 열쇠가 적힌 파일이 그대로 들어 있는지 열어 보라. 있으면 셋째 항목이 깨진 것이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"열두 항목은 이렇게 생겼다.\n\n| 항목 | 무엇을 하라는 것인가 |\n|---|---|\n| **I 코드베이스** | 코드는 한 벌만 두고 배포를 여럿으로 |\n| **II 의존성** | 의존성을 드러내 적고 따로 떼어 둔다 |\n| **III 설정** | 설정은 환경에 둔다 |\n| **IV 붙는 자원** | DB·캐시·메일을 붙였다 뗄 수 있는 자원으로 본다 |\n| **V 빌드·릴리스·실행** | 세 단계를 엄격히 가른다 |\n| **VI 프로세스** | 상태 없는 프로세스 하나 이상으로 돌린다 |\n| **VII 포트 바인딩** | 자기 포트를 열어 스스로 내놓는다 |\n| **VIII 동시성** | 늘릴 때는 프로세스를 옆으로 늘린다 |\n| **IX 폐기 가능** | 빨리 뜨고 얌전히 죽는다 |\n| **X 개발·운영 일치** | 개발·스테이징·운영을 되도록 닮게 둔다 |\n| **XI 로그** | 로그를 흘러가는 사건 줄기로 다룬다 |\n| **XII 관리 작업** | 관리 작업은 한 번짜리로 따로 돌린다 |\n\n세 항목이 서로 물려 있어서 나머지를 끌고 간다. **여섯째**가 상태를 밖으로 밀어낸다. 프로세스는 아무것도 안 들고 있어야 하고, 남겨야 할 것은 붙는 저장소에 둔다. 메모리나 디스크에 얹어 둔 것이 다음 번에도 있으리라 믿으면 안 된다 — 다음 차례는 대개 다른 프로세스가 받고, 한 벌뿐이어도 다시 뜨면 그 자리는 비어 있다. 사용자 세션을 프로세스 안에 붙들어 두는 방식이 이 항목에 정면으로 걸린다.\n\n그래서 **여덟째**가 가능해진다. 아무것도 안 들고 있으니 한 벌 더 띄우는 것만으로 처리량이 는다. 큰 기계 한 대로 키우는 대신 같은 것을 옆으로 늘린다.\n\n**다섯째**가 그 셋을 이어 준다. 빌드는 코드를 실행 꾸러미로 바꾸고, 릴리스는 그 꾸러미에 그 자리의 설정을 붙이며, 실행은 고른 릴리스를 띄운다. 릴리스에는 시각이나 증가하는 번호로 고유한 표를 달고, 한 번 만든 릴리스는 고치지 않는다. 고칠 일이 생기면 새 릴리스를 만든다. 되돌리기가 쉬운 이유가 여기 있다 — 앞 번호를 다시 띄우면 된다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 어디까지 이 열둘을 그대로 들이나","body":"```도해\n대조: 이 규칙을 어디까지 그대로 들이나\n그대로 따를 곳 |=| 다시 따져 볼 곳\n앱의 성격 :: 서비스로 돈다 || 손에 쥐고 쓴다\n상태 :: 밖에 둘 수 있다 || 큰 상태가 붙는다\n올릴 자리 :: 여럿이고 는다 || 한 대로 고정\n= 서비스로 돌고 상태를 밖에 둘 수 있을 때 이 열둘이 가장 값을 한다\n```\n\n원문은 읽는 사람을 **서비스로 돌아가는 앱**을 만드는 사람과 그것을 올리고 굴리는 사람으로 적는다. 언어는 가리지 않지만 성격은 가린다. 손에 쥐고 쓰는 프로그램, 큰 상태를 안고 도는 일감, 한 대에 고정된 장비 위의 소프트웨어에 열둘을 글자 그대로 들이대면 규칙이 값을 하기보다 걸리적거린다.\n\n값을 하는 자리에서도 대가는 있다. 상태를 밖에 두라는 말은 곧 저장소를 하나 더 세우고 그 지연과 장애를 감당하라는 말이다. 로그를 흘려보내라는 말은 모으고 보관하는 몫을 바깥 도구로 옮기라는 말이다. 열둘은 공짜로 얻는 성질이 아니라 **밖으로 옮겨서 얻는 성질**이다. 옮길 곳이 없는 환경이라면 항목별로 따져서 고른다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **설정 밖으로 빼기** — 접속 정보와 열쇠를 코드에서 떼어 환경 변수로 옮긴다. 같은 꾸러미가 개발과 운영에 그대로 올라간다.\n- **되돌리기** — 릴리스마다 고유한 번호를 달아 두면 사고가 난 날 그 앞 번호를 다시 띄우는 것으로 끝난다.\n- **로그 흘려보내기** — 앱은 표준 출력으로 한 줄씩 뱉기만 하고, 모으고 어디로 보낼지는 실행 환경이 맡는다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **열두 규칙은 어떤 앱에나 다 맞다** — 원문은 서비스로 돌아가는 앱을 겨눈 목록이라고 적는다. 손에 쥐고 쓰는 프로그램이나 큰 상태를 안고 도는 일감에 그대로 들이대면 규칙이 값을 못 한다.\n- **설정을 파일로 빼면 셋째 항목을 지킨 것이다** — 원문은 그 방식의 약점을 둘 적는다. 실수로 저장소에 같이 올라가기 쉽고, 흩어져서 전부를 한눈에 보기 어렵다. 그래서 환경 변수를 고른다.\n- **로그 파일을 잘 굴리는 것이 열한째 항목이다** — 반대다. 12요소 앱은 자기 출력이 어디로 가서 어떻게 쌓이는지 신경 쓰지 않고, 로그 파일을 쓰거나 관리하려 들지 않는다."}],"figure":"```도해\n흐름: 코드 한 벌이 어느 곳에서든 똑같이 돌기까지 무엇을 거치나\n코드 저장소 :: 한 벌만 둔다. 거기서 나가는 배포는 여럿이다\n빌드 :: 코드와 의존성을 실행 꾸러미 하나로 굳힌다\n릴리스 :: 그 꾸러미에 그 자리의 설정을 붙이고 번호를 단다\n실행 :: 상태 없는 프로세스로 띄운다. 모자라면 한 벌 더\n@ 다시 코드로 :: 고칠 것이 생기면 새 릴리스를 만든다. 도는 것은 안 고친다\n= 코드 한 벌에 자리마다 다른 설정만 붙인다. 그래서 어디에 올려도 같은 것이 돈다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 이 규칙 없이 앱을 옮기면 무슨 일이 생기나\n규칙 없이 || 열두 규칙으로\n설정 :: 코드 안에 박힌다 || 환경에서 읽는다\n새 환경 :: 손으로 맞춘다 || 같은 꾸러미를 쓴다\n한 대 늘리기 :: 상태가 갈린다 || 한 벌 더 띄운다\n= 옮길 때마다 손이 가던 자리를 규칙 하나씩으로 없앤 것이다\n```\n\n옮길 때 사고가 나는 이유는 대개 하나다. 그 자리에서만 참인 것이 코드 안에 박혀 있어서다. 접속 주소, 열쇠, 파일이 놓인 경로, 지난번에 손으로 만져 둔 설정. 원문은 설정을 가르는 기준을 아주 간단한 시험으로 준다 — **지금 이 코드를 그대로 공개해도 아무 열쇠가 새지 않는가.** 새면 그건 설정인데 코드 안에 있는 것이다.\n\n설정 파일로 빼는 것만으로는 부족하다고도 적는다. 실수로 저장소에 같이 올라가기 쉽고, 여기저기 다른 모양으로 흩어져서 전부를 한눈에 보기 어렵다. 그래서 환경 변수를 고른다. 배포마다 코드를 안 고치고 바꿀 수 있고, 언어와 운영체제를 안 가리기 때문이다."},"recap":"**\"어디에 올려도 같은 것이 도는 앱의 조건표\"** 라고 읽으면 된다. 뼈대는 셋이다 — 상태를 밖으로 밀어내고, 설정을 환경에 두고, 빌드와 릴리스와 실행을 엄격히 가른다. 나머지 아홉은 그 셋을 지키려고 붙는 조건에 가깝다.","kid":"수학여행 가서 짐을 방에 못 박아 두면 방을 옮길 때마다 다 뜯어야 하잖아. 그래서 짐은 가방에 넣고 방에는 아무것도 남기지 않기로 미리 정해 두는 거야. 그러면 어느 방을 받아도 그날 바로 잘 수 있어.","check":[{"q":"같은 꾸러미를 개발과 운영에 그대로 올릴 수 있는 까닭은 무엇인가","at":"그림"},{"q":"앱을 한 벌 더 띄우기만 해도 처리량이 느는 까닭은 무엇인가","at":"작동 원리"},{"q":"손에 쥐고 쓰는 프로그램에 이 열둘을 그대로 들이대면 무엇이 어긋나나","at":"비교"}],"myths":[{"wrong":"열두 규칙은 어떤 앱에나 다 맞다","right":"원문은 서비스로 돌아가는 앱을 겨눈 목록이라고 적는다. 손에 쥐고 쓰는 프로그램이나 큰 상태를 안고 도는 일감에 그대로 들이대면 규칙이 값을 못 한다."},{"wrong":"설정을 파일로 빼면 셋째 항목을 지킨 것이다","right":"원문은 그 방식의 약점을 둘 적는다. 실수로 저장소에 같이 올라가기 쉽고, 흩어져서 전부를 한눈에 보기 어렵다. 그래서 환경 변수를 고른다."},{"wrong":"로그 파일을 잘 굴리는 것이 열한째 항목이다","right":"반대다. 12요소 앱은 자기 출력이 어디로 가서 어떻게 쌓이는지 신경 쓰지 않고, 로그 파일을 쓰거나 관리하려 들지 않는다."}],"cases":[{"label":"설정 밖으로 빼기","note":"접속 정보와 열쇠를 코드에서 떼어 환경 변수로 옮긴다. 같은 꾸러미가 개발과 운영에 그대로 올라간다."},{"label":"되돌리기","note":"릴리스마다 고유한 번호를 달아 두면 사고가 난 날 그 앞 번호를 다시 띄우는 것으로 끝난다."},{"label":"로그 흘려보내기","note":"앱은 표준 출력으로 한 줄씩 뱉기만 하고, 모으고 어디로 보낼지는 실행 환경이 맡는다."}],"dia":{"shape":"흐름","title":"코드 한 벌이 어느 곳에서든 똑같이 돌기까지 무엇을 거치나","rows":[{"who":"코드 저장소","what":"한 벌만 둔다. 거기서 나가는 배포는 여럿이다"},{"who":"빌드","what":"코드와 의존성을 실행 꾸러미 하나로 굳힌다"},{"who":"릴리스","what":"그 꾸러미에 그 자리의 설정을 붙이고 번호를 단다"},{"who":"실행","what":"상태 없는 프로세스로 띄운다. 모자라면 한 벌 더"}],"sum":"코드 한 벌에 자리마다 다른 설정만 붙인다. 그래서 어디에 올려도 같은 것이 돈다","loop":{"who":"다시 코드로","what":"고칠 것이 생기면 새 릴리스를 만든다. 도는 것은 안 고친다"}}},"arch--two-phase-commit":{"definition":"여러 저장소에 차례로 확정하면 중간에 하나가 실패했을 때 앞의 것만 남는다. 그래서 확정을 두 번에 나눈다. 준비 단계에서 참여자 모두가 \"할 수 있다\" 고 답한 뒤에야 확정 단계로 넘어가고, 하나라도 아니라고 하면 전부 취소한다. MySQL은 XA라는 규격으로, PostgreSQL은 `PREPARE TRANSACTION` 으로 이 절차를 연다.","name":"Two-Phase :: 두 단계\nCommit :: 확정\n= 붙여 읽으면 \"두 단계로 확정하기\". 묻는 단계와 확정하는 단계가 나뉘어 있다는 뜻이다","analogy":"반 아이들이 전부 갈 수 있다고 손을 든 다음에야 소풍 날짜를 못 박는 담임 선생님.","example":"장애 다음 날 아침, 준비까지만 끝난 거래가 잠금을 쥔 채 남아 있어 그 자료를 아무도 못 건드리는 그 상황이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"가운데에 조정자가 있고 참여자마다 자기 저장소가 있다. MySQL의 XA에서는 조정자를 거래 관리자, 참여자를 자원 관리자라 부르고, 하나의 큰 거래가 관리자마다 하나씩 가지를 친다.\n\n핵심은 준비 단계다. 참여자는 확정에 필요한 것을 안정된 저장 장치에 먼저 기록한다. PostgreSQL 문서는 이 상태를 두고, 준비를 마친 거래는 세션에서 떨어져 나와 상태가 통째로 디스크에 남으므로 확정을 지시받기 전에 데이터베이스가 죽어도 확정에 성공할 가능성이 매우 높다고 적는다. 그래서 준비 뒤에는 다른 세션에서도 확정하거나 취소할 수 있다.\n\n여기에 이 절차의 대가가 붙어 있다. 준비를 마친 참여자는 스스로 결정하지 못하고 조정자의 지시를 기다린다. 그동안 쥔 잠금을 놓지 않는다. PostgreSQL 문서는 준비 상태를 오래 두는 것이 현명하지 않다고 적으며, 저장 공간 회수를 방해하고 그 거래가 쥐고 있던 잠금을 계속 쥐고 있다는 점을 든다. 조정자가 그 사이에 죽으면 참여자는 잠금을 쥔 채 남는다. 밖에서 누가 확정이나 취소를 내려 주기 전까지 그 자리는 그대로다.\n\n그래서 이 기능은 감시할 주체가 있을 때만 켠다. PostgreSQL 문서는 준비된 거래를 추적하고 제때 닫아 줄 외부 거래 관리자를 두지 않았다면 이 기능을 아예 꺼 두는 편이 낫다고 적는다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 두 단계 커밋과 사가","body":"```도해\n대조: 두 단계 커밋과 사가 중 무엇을 고르나\n두 단계 커밋 |=| 사가\n경계 :: 내가 쥔 저장소들 || 남이 쥔 서비스들\n중간 상태 :: 밖에서 안 보인다 || 잠깐 보인다\n되돌리기 :: 규약이 해 준다 || 보상을 내가 짠다\n= 짧게 잠그고 정합을 얻을 수 있으면 두 단계, 오래 걸리는 일이면 사가다\n```\n\n고르는 기준은 잠금을 쥐고 있어도 되는 시간이다. 참여하는 저장소를 내가 다 쥐고 있고 거래가 밀리초 단위로 끝난다면 두 단계 커밋이 간단하다. 되돌리는 코드를 짤 필요가 없고 중간 상태가 밖으로 새지 않는다.\n\n반대쪽이면 [[Saga]]다. 서비스마다 주인이 다르고 한 단계가 몇 분씩 걸리는 흐름에서 잠금을 그만큼 쥐고 있으면 그 시간 내내 다른 일이 막힌다. Microsoft 문서도 여러 저장소가 독립적으로 관리되는 곳에는 데이터베이스가 주던 보장이 그대로 적용되지 않는다고 적고, 그 자리의 답으로 사가를 든다. 대신 되돌리는 일과 어긋난 중간 상태를 내가 떠안는다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **한 조직 안 여러 데이터베이스** — 주문 표와 회계 표가 서로 다른 인스턴스에 있을 때, 응용 프로그램이 거래 관리자 노릇을 하고 두 저장소가 자원 관리자로 참여해 한 묶음으로 확정한다.\n- **끊긴 세션을 넘어 마무리하기** — 준비를 마친 거래는 그 세션에서 떨어져 나와 디스크에 남는다. 그래서 확정과 취소를 원래 세션이 아닌 다른 세션에서 내릴 수 있다.\n- **남은 거래 치우기** — 조정자가 죽으면 준비 상태 거래가 남는다. 밖에서 누가 확정할지 취소할지 정해 주지 않으면 잠금이 그대로 남아 다른 작업을 막는다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **두 단계 커밋을 쓰면 어떤 실패에도 안전하다** — 준비까지 끝난 뒤 조정자가 죽으면 참여자는 결정을 기다리며 멈춘다. PostgreSQL 문서는 준비 상태의 거래가 쥐고 있던 잠금을 계속 쥔다고 적는다.\n- **마이크로서비스에서도 이걸로 묶으면 된다** — 서비스마다 주인이 다르고 한 단계가 오래 걸리는 곳에서는 잠금 시간이 그만큼 길어진다. 그 자리의 답으로 나온 것이 사가다.\n- **이제 안 쓰는 옛날 기술이다** — 지금도 데이터베이스가 문서로 지원한다. MySQL은 XA로, PostgreSQL은 `PREPARE TRANSACTION` 으로 이 절차를 열어 둔다."}],"figure":"```도해\n흐름: 여러 저장소를 한꺼번에 확정하려면 무엇을 하나\n조정자 :: \"확정할 수 있나\" 를 모두에게 묻는다\n참여자 :: 할 일을 안전한 곳에 적어 두고 답한다\n조정자 :: 답을 모아 확정할지 취소할지 정한다\n조정자 :: 정한 것을 참여자 전부에게 내려보낸다\n참여자 :: 그때 실제로 확정하거나 되돌린다\n= 묻는 단계와 확정하는 단계를 갈라서, 전부 되거나 전부 안 되게 만든다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 두 저장소에 차례로 확정하면 무슨 일이 생기나\n차례로 확정 || 두 단계로\n중간 실패 :: 한쪽만 반영된다 || 전부 없던 일 된다\n확인 :: 해 보고 나서 안다 || 미리 물어본다\n수습 :: 사람이 맞춰야 한다 || 규약이 맞춘다\n= 따로 확정하면 반만 남는다. 먼저 물어보는 단계가 그걸 막는다\n```\n\n한 저장소 안에서는 확정이 통째로 되거나 통째로 안 된다. 그런데 계좌 표와 회계 표가 서로 다른 저장소에 있으면 그 보장이 끊긴다. 앞에 확정하고 뒤에서 실패하는 순간 반쪽 상태가 남고, 어느 쪽이 맞는지는 시스템이 모른다.\n\n두 단계 커밋은 그 반쪽 상태를 없앤다. 준비 단계에서 각 참여자는 할 일을 안정된 저장 장치에 적어 두고 자기가 확정할 수 있는지를 답한다. MySQL 문서는 그다음 단계를 이렇게 적는다 — 전원이 할 수 있다고 답했으면 전부에게 확정을 지시하고, 하나라도 못 한다고 했으면 전부에게 취소를 지시한다."},"recap":"**\"전원이 준비됐다고 답한 뒤에만 확정하는 절차\"** 라고 읽으면 된다. 준비 단계 덕에 반쪽 상태가 사라지지만, 준비와 확정 사이에서 참여자는 잠금을 쥔 채 조정자를 기다린다. 그 기다림이 짧게 끝나는 곳에서만 고르고, 길어질 곳에는 사가를 쓴다.","kid":"소풍 갈 날을 정할 때 선생님이 먼저 \"그날 다 올 수 있어?\" 하고 물어보시지? 한 명이라도 손을 못 들면 그날은 아예 안 잡아. 다들 손을 들면 그때야 \"그날로 정한다\" 하고 못을 박는 거야.","check":[{"q":"두 곳에 차례로 확정했는데 반만 남는 일이 왜 생기나","at":"해결하는 문제"},{"q":"준비 단계까지 끝난 뒤에 조정자가 죽으면 참여자는 무엇을 하고 있나","at":"작동 원리"},{"q":"서비스마다 주인이 다른 곳에서 이 절차를 피하는 이유는 무엇인가","at":"비교"}],"myths":[{"wrong":"두 단계 커밋을 쓰면 어떤 실패에도 안전하다","right":"준비까지 끝난 뒤 조정자가 죽으면 참여자는 결정을 기다리며 멈춘다. PostgreSQL 문서는 준비 상태의 거래가 쥐고 있던 잠금을 계속 쥔다고 적는다."},{"wrong":"마이크로서비스에서도 이걸로 묶으면 된다","right":"서비스마다 주인이 다르고 한 단계가 오래 걸리는 곳에서는 잠금 시간이 그만큼 길어진다. 그 자리의 답으로 나온 것이 사가다."},{"wrong":"이제 안 쓰는 옛날 기술이다","right":"지금도 데이터베이스가 문서로 지원한다. MySQL은 XA로, PostgreSQL은 `PREPARE TRANSACTION` 으로 이 절차를 열어 둔다."}],"cases":[{"label":"한 조직 안 여러 데이터베이스","note":"주문 표와 회계 표가 서로 다른 인스턴스에 있을 때, 응용 프로그램이 거래 관리자 노릇을 하고 두 저장소가 자원 관리자로 참여해 한 묶음으로 확정한다."},{"label":"끊긴 세션을 넘어 마무리하기","note":"준비를 마친 거래는 그 세션에서 떨어져 나와 디스크에 남는다. 그래서 확정과 취소를 원래 세션이 아닌 다른 세션에서 내릴 수 있다."},{"label":"남은 거래 치우기","note":"조정자가 죽으면 준비 상태 거래가 남는다. 밖에서 누가 확정할지 취소할지 정해 주지 않으면 잠금이 그대로 남아 다른 작업을 막는다."}],"dia":{"shape":"흐름","title":"여러 저장소를 한꺼번에 확정하려면 무엇을 하나","rows":[{"who":"조정자","what":"\"확정할 수 있나\" 를 모두에게 묻는다"},{"who":"참여자","what":"할 일을 안전한 곳에 적어 두고 답한다"},{"who":"조정자","what":"답을 모아 확정할지 취소할지 정한다"},{"who":"조정자","what":"정한 것을 참여자 전부에게 내려보낸다"},{"who":"참여자","what":"그때 실제로 확정하거나 되돌린다"}],"sum":"묻는 단계와 확정하는 단계를 갈라서, 전부 되거나 전부 안 되게 만든다"}},"arch--trpc":{"definition":"TypeScript로 서버와 클라이언트를 함께 만들 때, 주고받는 값의 모양을 양쪽에 따로 적어두지 않아도 클라이언트가 서버 타입을 알아본다. 이름의 RPC는 원격 함수 호출을 뜻한다.","name":"t :: 타입 언어의 머리글자\nRPC :: 멀리 있는 함수 부르기\n= 붙여 읽으면 \"타입이 따라오는 원격 함수 호출\". 앞에 붙은 t 하나가 이 도구의 전부다","analogy":"같은 회사 안의 두 부서. 양식을 새로 만들어 주고받지 않고 원본 문서를 그대로 돌려 본다.","example":"서버에서 필드 이름 하나를 바꿨더니 그 자리를 쓰던 화면 코드에 곧바로 빨간 줄이 그어진다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"프로시저에는 받을 값의 모양을 함께 적는다. 이 검사는 실행할 때도 돌아서, 모양이 안 맞는 값이 들어오면 함수 안까지 가지 않고 그 앞에서 막힌다.\n\n클라이언트가 가져가는 것은 타입뿐이고 서버 코드를 실행하지는 않는다. 호출 자체는 여느 API처럼 네트워크를 탄다. 그래서 서버와 클라이언트가 같은 저장소에 있고 둘 다 TypeScript일 때 쓸 수 있다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **한 저장소에 화면과 서버가 같이 있는 프로젝트** — 서버 함수 이름을 바꾸면 부르는 쪽에서 곧바로 오류가 뜬다.\n- **응답 필드 삭제** — 서버에서 필드를 지우면 그 필드를 쓰던 화면 코드가 컴파일되지 않아 배포 전에 걸린다.\n- **자동 완성** — 호출할 때 어떤 값을 넣어야 하는지 편집기가 목록으로 띄워준다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **tRPC를 쓰면 REST나 GraphQL을 안 써도 된다** — TypeScript로 양쪽을 다 만들 때에 한한다. 다른 언어로 만든 클라이언트나 밖에 공개하는 API에는 쓸 수 없다.\n- **클라이언트가 서버 코드를 가져다 실행한다** — 가져가는 것은 타입뿐이다. 실제 호출은 여느 API처럼 네트워크를 탄다.\n- **타입이 맞으면 값도 맞다** — 타입은 코드를 쓸 때 확인하는 것이다. 밖에서 들어오는 값은 실행 시점의 검사를 따로 붙여야 한다."}],"figure":"```도해\n흐름: 서버 함수 하나가 클라이언트에서 어떻게 불리나\n서버 :: `getUser` 라는 프로시저를 만든다\n입력 :: 받을 값의 모양을 함께 적어둔다\n타입 :: 라우터 전체의 타입이 하나로 모인다\n클라이언트 :: 그 타입을 가져다 붙인다\n호출 :: `trpc.getUser.query({ id })` 를 부른다\n< 결과 :: 돌아온 값의 모양을 편집기가 이미 안다\n= 타입을 옮겨 적는 자리가 없어서 어긋날 자리도 없다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 서버가 응답 모양을 바꾸면 무엇이 달라지나\nREST 로 || tRPC 로\n클라이언트 코드 :: 그대로 통과됨 || 컴파일이 막힘\n오류를 아는 때 :: 실행 중에 || 코드 쓸 때\n타입 정의 :: 양쪽에 따로 || 한 군데만\n= 어긋남을 사람이 찾는 대신 컴파일러가 찾게 만드는 것이다\n```\n\nREST로 API를 만들면 서버가 내려주는 값의 모양과 클라이언트가 기대하는 모양이 각각 따로 적힌다. 서버에서 나이를 숫자로 바꿨는데 클라이언트가 여전히 문자열로 알고 있으면 코드는 멀쩡히 컴파일되고, 그 화면을 실제로 열었을 때 깨진다.\n\ntRPC는 서버에서 정의한 타입을 클라이언트가 그대로 가져다 쓴다. 옮겨 적는 자리가 없으니 어긋날 자리도 없다. 서버 쪽 모양이 바뀌면 부르는 코드가 그 자리에서 컴파일 오류를 낸다."},"compose":{"label":"무엇으로 되어 있나","head":"🧱 구성","body":"```도해\n층: tRPC 는 무엇을 쌓아 만드나\n프로시저 :: 함수 하나. 입력 모양과 하는 일을 적는다\n라우터 :: 프로시저들을 모아둔 것\n타입 :: 라우터에서 뽑아낸 전체 모양\n= 클라이언트가 가져가는 것은 코드가 아니라 이 타입 하나다\n```"},"recap":"**\"서버 타입이 화면까지 따라오는 그 도구\"** 라고 읽으면 된다. 값의 모양을 양쪽에 따로 적지 않으므로 어긋날 자리가 없고, 서버가 바뀌면 클라이언트 코드가 컴파일 단계에서 막힌다. 서버와 클라이언트가 둘 다 TypeScript일 때만 쓸 수 있다.","kid":"같은 회사 두 부서가 서류를 각자 자기 양식에 옮겨 적으면, 한쪽이 칸 이름을 바꿨을 때 딴소리가 되지? 그래서 옮겨 적지 않고 원본 한 장을 그대로 돌려 봐. 그러면 한쪽이 칸을 고치는 순간 다른 쪽에서 바로 티가 나서, 한참 뒤에야 어긋난 걸 알아채는 일이 없어.","check":[{"q":"서버가 응답 필드 하나를 지웠을 때 REST와 tRPC에서 문제가 드러나는 시점이 어떻게 다른가","at":"해결하는 문제"},{"q":"파이썬으로 만든 서버에는 tRPC를 붙일 수 없다. 왜 그런가","at":"작동 원리"},{"q":"타입이 맞는데도 실행 시점 검사를 따로 두는 이유는","at":"흔한 오해"}],"myths":[{"wrong":"tRPC를 쓰면 REST나 GraphQL을 안 써도 된다","right":"TypeScript로 양쪽을 다 만들 때에 한한다. 다른 언어로 만든 클라이언트나 밖에 공개하는 API에는 쓸 수 없다."},{"wrong":"클라이언트가 서버 코드를 가져다 실행한다","right":"가져가는 것은 타입뿐이다. 실제 호출은 여느 API처럼 네트워크를 탄다."},{"wrong":"타입이 맞으면 값도 맞다","right":"타입은 코드를 쓸 때 확인하는 것이다. 밖에서 들어오는 값은 실행 시점의 검사를 따로 붙여야 한다."}],"cases":[{"label":"한 저장소에 화면과 서버가 같이 있는 프로젝트","note":"서버 함수 이름을 바꾸면 부르는 쪽에서 곧바로 오류가 뜬다."},{"label":"응답 필드 삭제","note":"서버에서 필드를 지우면 그 필드를 쓰던 화면 코드가 컴파일되지 않아 배포 전에 걸린다."},{"label":"자동 완성","note":"호출할 때 어떤 값을 넣어야 하는지 편집기가 목록으로 띄워준다."}],"dia":{"shape":"흐름","title":"서버 함수 하나가 클라이언트에서 어떻게 불리나","rows":[{"who":"서버","what":"`getUser` 라는 프로시저를 만든다"},{"who":"입력","what":"받을 값의 모양을 함께 적어둔다"},{"who":"타입","what":"라우터 전체의 타입이 하나로 모인다"},{"who":"클라이언트","what":"그 타입을 가져다 붙인다"},{"who":"호출","what":"`trpc.getUser.query({ id })` 를 부른다"},{"who":"결과","what":"돌아온 값의 모양을 편집기가 이미 안다","back":true}],"sum":"타입을 옮겨 적는 자리가 없어서 어긋날 자리도 없다"}},"arch--vs":{"definition":"모놀리스는 모든 기능이 한 코드베이스에서 돌고 한 번에 배포된다. 마이크로서비스는 기능마다 서비스와 데이터베이스를 따로 두고 각각 배포한다.","name":"Mono :: 하나\nlith :: 돌덩이\nMicro :: 아주 작은\nService :: 제 몫 하는 한 가지 일\n= 앞은 \"통돌 하나\", 뒤는 \"아주 작게 나눈 일들\". 이름이 곧 한 덩어리냐 여러 조각이냐다","analogy":"백화점과 상가. 백화점은 한 건물에서 중앙이 관리하고, 상가는 가게마다 따로 열고 닫는 대신 오가려면 밖으로 나와야 한다.","example":"앱이 통째로 점검 중인 날과 결제만 막히고 검색과 장바구니는 되는 날의 차이가 여기서 갈린다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n흐름: 주문 하나가 마이크로서비스에서 어떻게 처리되나\n클라이언트 :: 상품 구매를 요청한다\n게이트웨이 :: 요청을 받아 각 서비스로 나눠 보낸다\n상품 서비스 :: 재고를 확인하고 자기 DB 에 적는다\n결제 서비스 :: 결제를 처리하고 자기 DB 에 적는다\n배송 서비스 :: 배송을 잡고 자기 DB 에 적는다\n< 게이트웨이 :: 응답을 모아 하나로 돌려준다\n= 모놀리스에서 함수 호출이던 자리가 여기서는 네트워크 통신이다\n```\n\n나누는 기준은 코드가 아니라 데이터다. 결제 서비스가 상품 테이블을 직접 읽고 있으면 둘은 여전히 붙어 있는 것이고, 한쪽 스키마를 바꿀 때 다른 쪽이 깨진다. 그래서 남의 데이터가 필요하면 API로 물어본다.\n\n가장 까다로운 자리는 트랜잭션이다. 한 데이터베이스 안에서는 결제 기록과 재고 차감이 함께 성공하거나 함께 취소된다. 서비스가 나뉘면 결제는 됐는데 재고 차감이 실패한 상태가 생길 수 있어서, 되돌리는 절차를 따로 만들어야 한다.\n\n서비스 앞에는 대개 게이트웨이를 둔다. 클라이언트가 서비스 주소를 하나하나 알 필요가 없어지고, 인증이나 요청 제한처럼 공통으로 할 일을 한자리에서 처리한다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교","body":"| 항목 | 모놀리스 | 마이크로서비스 |\n|---|---|---|\n| 배포 | 전체를 한 번에 | 서비스마다 따로 |\n| 기술 선택 | 하나로 통일 | 서비스마다 다르게 |\n| 확장 | 전체를 늘린다 | 필요한 것만 |\n| 데이터 처리 | 한 DB 안에서 끝난다 | 여러 서비스에 걸친다 |\n| 초기 운영 비용 | 낮다 | 높다 |\n| 장애 범위 | 전체 | 그 서비스 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **처음 시작할 때** — 사용자가 적은 동안은 모놀리스로 빨리 내놓는 편이 낫다. 나누는 데 드는 인프라가 얻는 것보다 크다.\n- **한 기능에 몰리는 부하** — 결제나 검색처럼 요청이 집중되는 기능만 떼어내 그 부분만 따로 늘린다.\n- **팀이 늘어날 때** — 한 코드베이스에 여러 팀이 붙으면 배포 순서를 맞추느라 서로 기다린다. 나누면 각 팀이 자기 것만 배포한다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **마이크로서비스가 모놀리스보다 발전한 방식이다** — 나중에 나온 것이지 더 나은 것이 아니다. 사람도 기능도 적을 때는 나누는 값이 얻는 것보다 크다.\n- **서비스를 잘게 쪼개면 마이크로서비스다** — 서비스는 나뉘었는데 데이터베이스를 함께 쓰면 배포도 함께 해야 한다. 나뉜 척하는 모놀리스가 된다.\n- **나누기만 하면 장애가 안 번진다** — 저절로 되지 않는다. 응답 없는 서비스를 계속 부르면 부르는 쪽도 같이 멈춘다. 타임아웃과 차단기를 따로 붙여야 격리가 생긴다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **나눌 준비가 됐는지 먼저 본다.** 배포 자동화와 모니터링이 없으면 서비스 수만큼 손이 늘어난다.\n- **경계는 데이터로 긋는다.** 두 서비스가 같은 데이터를 고쳐야 한다면 그 경계는 잘못 그은 것이다."}],"figure":"```도해\n대조: 기능을 한 덩어리로 둘 때와 쪼갤 때는 무엇이 다른가\n모놀리스 |=| 마이크로서비스\n코드와 DB :: 한 곳에 모인다 || 서비스마다 따로\n기능 사이 호출 :: 함수 호출 || 네트워크 통신\n배포 :: 한 번에 전체 || 서비스마다 따로\n초기 운영 비용 :: 낮다 || 높다\n= 어느 쪽이 옳은 게 아니라 무엇을 맞바꿀지의 문제다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 결제에만 트래픽이 몰리면 어떻게 되나\n모놀리스 || 마이크로서비스\n확장 :: 전체를 늘린다 || 결제만 늘린다\n배포 :: 전부 다시 올림 || 그 서비스만\n장애 :: 전체가 내려감 || 그 기능만 막힘\n= 나누면 늘릴 때도 고칠 때도 필요한 부분만 건드린다\n```\n\n모놀리스에서는 결제 코드 한 줄을 고쳐도 전체를 다시 배포한다. 결제에만 부하가 몰려도 서버 전체를 늘려야 하고, 어느 한 곳에서 난 오류가 프로세스를 내리면 나머지 기능도 같이 멈춘다. 코드가 커지고 팀이 늘수록 이 대가가 커진다.\n\n마이크로서비스는 그 대가를 다른 대가와 맞바꾼다. 필요한 부분만 늘리고 배포하는 대신, 함수 호출이던 것이 네트워크 통신이 되고 한 데이터베이스에서 끝나던 처리가 여러 서비스에 걸치게 된다."},"recap":"**\"한 덩어리로 둘지 쪼갤지의 그 갈림길\"** 이라고 읽으면 된다. 쪼개면 필요한 것만 늘리고 배포할 수 있지만 함수 호출이 네트워크 통신이 되고 처리가 여러 곳에 걸친다. 어느 쪽이 옳은 게 아니라 지금 무엇이 더 아픈지를 보고 고르는 것이다.","kid":"큰 백화점은 문 하나로 들어가 안에서 다 돌아다닐 수 있지만, 공사하는 날은 통째로 못 들어가지? 골목 상가는 가게마다 문이 따로라 한 집이 쉬어도 옆집은 그대로 열려 있어. 대신 옆 가게에 가려면 한 번 밖으로 나갔다 들어와야 해.","check":[{"q":"결제 코드 한 줄만 고쳤는데 서비스 전체를 다시 배포해야 한다면 어느 구조인가","at":"해결하는 문제"},{"q":"서비스를 나눴는데도 배포를 늘 같이 해야 한다면 무엇을 잘못한 건가","at":"흔한 오해"},{"q":"결제는 됐는데 재고 차감이 실패하는 일이 모놀리스에서는 왜 잘 안 생기나","at":"작동 원리"}],"myths":[{"wrong":"마이크로서비스가 모놀리스보다 발전한 방식이다","right":"나중에 나온 것이지 더 나은 것이 아니다. 사람도 기능도 적을 때는 나누는 값이 얻는 것보다 크다."},{"wrong":"서비스를 잘게 쪼개면 마이크로서비스다","right":"서비스는 나뉘었는데 데이터베이스를 함께 쓰면 배포도 함께 해야 한다. 나뉜 척하는 모놀리스가 된다."},{"wrong":"나누기만 하면 장애가 안 번진다","right":"저절로 되지 않는다. 응답 없는 서비스를 계속 부르면 부르는 쪽도 같이 멈춘다. 타임아웃과 차단기를 따로 붙여야 격리가 생긴다."}],"cases":[{"label":"처음 시작할 때","note":"사용자가 적은 동안은 모놀리스로 빨리 내놓는 편이 낫다. 나누는 데 드는 인프라가 얻는 것보다 크다."},{"label":"한 기능에 몰리는 부하","note":"결제나 검색처럼 요청이 집중되는 기능만 떼어내 그 부분만 따로 늘린다."},{"label":"팀이 늘어날 때","note":"한 코드베이스에 여러 팀이 붙으면 배포 순서를 맞추느라 서로 기다린다. 나누면 각 팀이 자기 것만 배포한다."}],"dia":{"shape":"대조","title":"기능을 한 덩어리로 둘 때와 쪼갤 때는 무엇이 다른가","rows":[{"who":"","what":"모놀리스 || 마이크로서비스","left":"모놀리스","right":"마이크로서비스","even":true},{"who":"코드와 DB","what":"한 곳에 모인다 || 서비스마다 따로","left":"한 곳에 모인다","right":"서비스마다 따로"},{"who":"기능 사이 호출","what":"함수 호출 || 네트워크 통신","left":"함수 호출","right":"네트워크 통신"},{"who":"배포","what":"한 번에 전체 || 서비스마다 따로","left":"한 번에 전체","right":"서비스마다 따로"},{"who":"초기 운영 비용","what":"낮다 || 높다","left":"낮다","right":"높다"}],"sum":"어느 쪽이 옳은 게 아니라 무엇을 맞바꿀지의 문제다"}},"arch--term-f4ea9317":{"definition":"서비스가 서로를 직접 부르면 부르는 쪽이 받는 쪽을 전부 알아야 한다. 이벤트로 바꾸면 알리는 쪽은 누가 받는지 모르고, 받는 쪽은 누가 보냈는지 모른 채로 각자 일한다.","name":"Event :: 일어난 일\nDriven :: 그것에 끌려 움직임\nArchitecture :: 짜임새\n= 붙여 읽으면 \"일어난 일에 끌려 움직이는 짜임새\". 시키는 쪽이 아니라 일어난 일이 다음을 끌어당긴다","analogy":"신문. 신문사는 누가 어느 면을 읽는지 모르고, 독자는 기사를 누가 썼는지 몰라도 읽는다.","example":"결제는 끝났다는데 주문 내역에는 한참 뒤에야 뜨는 것이 이 구조에서 흔히 겪는 일이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"브로커는 사건을 받아 저장해두고, 구독한 쪽이 가져갈 때까지 들고 있다. 받는 쪽이 잠시 죽어 있어도 살아난 뒤에 밀린 것부터 처리한다.\n\n대신 같은 사건을 두 번 받는 일이 생긴다. 브로커가 보냈는데 처리했다는 응답을 못 받으면 다시 보내기 때문이다. 그래서 받는 쪽은 같은 사건을 두 번 처리해도 결과가 같아지도록 짜야 한다.\n\n도착 순서도 보장되지 않는다. 결제 완료가 주문 생성보다 먼저 도착하는 경우까지 감안해서 짜지 않으면, 평소에는 잘 돌다가 부하가 몰릴 때만 어긋난다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교","body":"| | 이벤트 기반 | 직접 호출 |\n|---|---|---|\n| 응답 | 발행하고 바로 끝 | 상대가 답할 때까지 기다림 |\n| 받는 쪽을 아는가 | 모른다 | 알아야 한다 |\n| 한 곳이 죽으면 | 나머지는 계속 | 부른 쪽도 막힌다 |\n| 흐름 추적 | 어렵다 | 쉽다 |\n| 데이터 일치 | 잠시 어긋난다 | 그 자리에서 맞는다 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **주문 처리** — 주문 하나가 결제, 재고, 배송, 알림으로 각각 흘러가고 한 곳이 실패해도 나머지는 진행된다.\n- **댓글 알림** — 댓글이 달렸다는 사건 하나로 푸시와 이메일과 추천 갱신이 각자 돌고, 쓴 사람은 기다리지 않는다.\n- **센서 데이터** — 온도가 바뀌었다는 사건을 제어, 기록, 경고가 따로 구독해 처리한다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **이벤트를 쓰면 빨라진다** — 응답이 빨리 돌아오는 것뿐이고 전체 처리는 오히려 늦게 끝난다. 짧아지는 건 사용자가 기다리는 구간이다.\n- **발행했으니 처리된 것이다** — 발행은 알렸다는 데까지다. 받는 쪽이 실패해도 발행한 쪽은 모르므로 실패를 따로 감시해야 한다.\n- **보낸 순서대로 도착한다** — 보장되지 않는다. 나중 사건이 먼저 도착하는 경우를 감안하지 않으면 부하가 몰릴 때 어긋난다."}],"figure":"```도해\n흐름: 주문 한 건이 들어오면 어디까지 퍼지나\n주문 서비스 :: \"주문 생성됨\" 을 발행하고 곧바로 끝낸다\n브로커 :: 그 사건을 받아 쌓아둔다\n구독자들 :: 결제·재고·알림이 저마다 꺼내 간다. 순서도 없고 서로 모른다\n각자 처리 :: 한 곳이 느리거나 죽어도 나머지는 그대로 간다\n= 주문 서비스는 셋이 있다는 것도 모른다. 넷째가 생겨도 고칠 게 없다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 서비스 하나를 새로 붙이면 무엇을 고쳐야 하나\n직접 호출로 || 이벤트로\n새 기능 추가 :: 부르는 쪽 수정 || 구독만 추가\n한 곳이 느리면 :: 전부 같이 기다림 || 각자 진행\n받는 쪽 목록 :: 부르는 쪽이 앎 || 알 필요 없음\n= 누가 받는지 모르게 만들어두면, 받는 쪽이 늘어도 보내는 쪽은 그대로다\n```\n\n주문이 끝나면 결제도 하고 재고도 줄이고 문자도 보내야 한다. 주문 서비스가 이 셋을 직접 부르면 셋의 주소와 형식을 전부 알아야 하고, 넷째가 생길 때마다 주문 서비스를 고치게 된다. 셋 중 하나가 느리면 주문 응답도 그만큼 늦어진다.\n\n이벤트로 바꾸면 주문 서비스는 \"주문이 생겼다\" 만 남기고 끝낸다. 받는 쪽이 몇이든, 얼마나 느리든 주문 응답 시간은 달라지지 않는다."},"recap":"**\"부르지 않고 알리기만 하는 그 짜임새\"** 라고 읽으면 된다. 서비스가 서로를 부르는 대신 일어난 일을 브로커에 남기고 넘어가니, 받는 쪽이 늘어도 보내는 쪽을 고칠 일이 없고 한 곳의 장애가 옆으로 번지지 않는다. 대신 흐름을 추적하기 어렵고 데이터가 잠시 어긋난다.","kid":"신문사는 오늘 신문을 누가 읽을지 모르고 그냥 찍어서 내놓지? 어떤 사람은 아침에 읽고 어떤 사람은 밤에 읽는데, 신문사는 그걸 기다리지 않아. 읽는 사람이 하나 늘어도 신문사는 하던 대로 찍기만 하면 돼.","check":[{"q":"주문 서비스를 하나도 안 고치고 알림 기능을 붙일 수 있는 이유는","at":"해결하는 문제"},{"q":"같은 결제 완료 처리가 두 번 실행될 수 있는 이유는","at":"작동 원리"},{"q":"발행은 성공했는데 사용자에게 문자가 안 갔다면 어디를 봐야 하나","at":"흔한 오해"}],"myths":[{"wrong":"이벤트를 쓰면 빨라진다","right":"응답이 빨리 돌아오는 것뿐이고 전체 처리는 오히려 늦게 끝난다. 짧아지는 건 사용자가 기다리는 구간이다."},{"wrong":"발행했으니 처리된 것이다","right":"발행은 알렸다는 데까지다. 받는 쪽이 실패해도 발행한 쪽은 모르므로 실패를 따로 감시해야 한다."},{"wrong":"보낸 순서대로 도착한다","right":"보장되지 않는다. 나중 사건이 먼저 도착하는 경우를 감안하지 않으면 부하가 몰릴 때 어긋난다."}],"cases":[{"label":"주문 처리","note":"주문 하나가 결제, 재고, 배송, 알림으로 각각 흘러가고 한 곳이 실패해도 나머지는 진행된다."},{"label":"댓글 알림","note":"댓글이 달렸다는 사건 하나로 푸시와 이메일과 추천 갱신이 각자 돌고, 쓴 사람은 기다리지 않는다."},{"label":"센서 데이터","note":"온도가 바뀌었다는 사건을 제어, 기록, 경고가 따로 구독해 처리한다."}],"dia":{"shape":"흐름","title":"주문 한 건이 들어오면 어디까지 퍼지나","rows":[{"who":"주문 서비스","what":"\"주문 생성됨\" 을 발행하고 곧바로 끝낸다"},{"who":"브로커","what":"그 사건을 받아 쌓아둔다"},{"who":"구독자들","what":"결제·재고·알림이 저마다 꺼내 간다. 순서도 없고 서로 모른다"},{"who":"각자 처리","what":"한 곳이 느리거나 죽어도 나머지는 그대로 간다"}],"sum":"주문 서비스는 셋이 있다는 것도 모른다. 넷째가 생겨도 고칠 게 없다"}}};
